/**
 * Molecular biology intros for every curated gene, one paragraph per locus.
 * Voice: PI facing, pathway specific, allele design oriented. No em or en dashes.
 */

export const curatedGeneIntros: Record<string, string> = {
  Acvr1:
    'Acvr1, the mouse ortholog of human ACVR1, encodes ALK2, a type I BMP receptor serine/threonine kinase whose glycine-serine rich juxtamembrane box is held in check by FKBP12 until a type II receptor phosphorylates it, releasing kinase activity toward SMAD1, SMAD5 and SMAD8. Recurrent residue changes such as R206H and G328E destabilize the GS domain and confer neomorphic responsiveness to activin A, converting a normally antagonist ligand into an agonist, the mechanism underlying fibrodysplasia ossificans progressiva and diffuse midline glioma. Allele strategy therefore splits cleanly: conditional null alleles interrogate requirement for BMP flux in a given lineage, while conditional knockin of the human disease codon reproduces heterotopic ossification and permits testing of ALK2 kinase inhibitors and activin A blocking antibodies. Germline deletion arrests development at gastrulation, so floxed exons plus an inducible Cre remain mandatory. Paralogous Acvr1b, Bmpr1a and Bmpr1b buffer single-locus loss, making compound conditional genetics worth planning before phenotyping begins.',
  Acvr2a:
    'Encoding the activin type IIA receptor, Acvr2a is the mouse ortholog of human ACVR2A and produces a constitutively active serine/threonine kinase that captures activin A and activin B, plus myostatin, GDF11 and several BMPs, then transphosphorylates the GS box of ALK4, ALK5 or ALK7 to launch SMAD2 and SMAD3 signaling. Ligand affinity is tuned by follistatin sequestration and by the accessory coreceptor cripto, so ligand trap experiments and receptor genetics report different layers of the same axis. Conditional null alleles resolve tissue-autonomous requirements in gonadotropes, where loss blunts FSH synthesis, and in craniofacial mesenchyme, whereas extracellular domain humanization supports pharmacokinetic testing of receptor Fc decoys that are notoriously cross-reactive. Because Acvr2b binds an overlapping ligand set and largely compensates in muscle and skeleton, single knockouts underreport phenotype severity. Match the allele to the endpoint: null alleles for lineage requirement, humanized ectodomains for biologic engagement, and double conditional stocks for ligand flux.',
  Acvr2b:
    'Acvr2b, mouse ortholog of human ACVR2B, encodes the type IIB activin receptor, the highest affinity receptor for myostatin and GDF11 and a principal node controlling skeletal muscle mass, axial patterning and left-right asymmetry. Ligand capture drives constitutive kinase activity that phosphorylates ALK4 or ALK5, mobilizing SMAD2 and SMAD3, and dominant negative or Fc soluble ectodomain versions produce profound muscle hypertrophy, which is why this receptor anchors so much cachexia and muscular dystrophy pharmacology. Null animals die perinatally with cardiac and situs defects, so conditional deletion is required for adult muscle and metabolic questions, while ectodomain humanization gives an honest platform for testing bimagrumab class antibodies and engineered ligand traps against the human binding interface. Acvr2a shares ligands and compensates substantially, so interpret single-locus data cautiously. Choose conditional null alleles for lineage requirement, kinase-dead knockins for signaling dissection, and humanized ectodomains for biologic engagement, always with a validated tissue-restricted Cre.',
  Adipoq:
    'Adipoq is the mouse ortholog of human ADIPOQ and encodes adiponectin, an adipocyte-secreted protein built from an amino-terminal collagen-like stalk and a carboxy-terminal C1q-like globular head that assembles into trimers, hexamers and high molecular weight oligomers, with the high molecular weight species carrying most insulin-sensitizing activity through Adipor1, Adipor2 and T-cadherin, activating AMPK and ceramidase pathways. Because bioactivity depends on oligomeric state rather than total protein, assays that measure only bulk levels can miss the relevant defect. Null mice show diet-induced insulin resistance with a modest chow phenotype, while knockins that block multimerization separate assembly from secretion, and humanized alleles support agonist and antibody pharmacology. Note that the widely used Adipoq-Cre driver is a knockin at this locus, so verify whether your line perturbs adiponectin dosage before attributing phenotypes to the floxed gene. Read out high molecular weight ELISA, hyperinsulinemic euglycemic clamp, and hepatic lipid content.',
  Aim2:
    'Aim2, the mouse ortholog of human AIM2, encodes an interferon-inducible HIN-200 family sensor that pairs an N-terminal pyrin domain with a C-terminal HIN200 domain gripping the sugar-phosphate backbone of cytosolic double-stranded DNA in sequence-independent fashion. DNA binding relieves intramolecular autoinhibition, allowing pyrin domain filaments to nucleate ASC (Pycard) into a caspase-1 activating platform that matures pro-IL-1beta and pro-IL-18 and cleaves gasdermin D to drive pyroptosis, the core response to Francisella, cytomegalovirus, and self DNA released after genotoxic stress. Conditional nulls isolate cell-intrinsic sensing in macrophages, dendritic cells, or intestinal epithelium, whereas HIN200 point mutants that abolish DNA binding without removing protein separate sensing from scaffolding, and humanization supports inhibitor programs. Bear in mind the murine Ifi200 cluster contains Ifi202b, Ifi203, and Ifi204, which share HIN domains and can obscure phenotypes, while parallel Nlrp3 and Nlrc4 inflammasomes provide overlapping IL-1beta output, so pairing an allele with the right myeloid Cre and cytokine endpoint is essential.',
  Akt1:
    'As the dominant AGC kinase isoform in most tissues, Akt1 is the mouse ortholog of human AKT1 and encodes a PH domain kinase recruited to PIP3 generated by class I PI3K, activated by PDK1 phosphorylation of T308 in the activation loop and mTORC2 phosphorylation of S473 in the hydrophobic motif. Active AKT1 phosphorylates TSC2, PRAS40, GSK3 beta, BAD, and FOXO factors, coupling growth factor input to mTORC1 output, glycogen metabolism and apoptotic threshold. The recurrent E17K substitution in the PH domain locks the kinase at the membrane and drives Proteus syndrome and multiple carcinomas, so a conditional knockin of that codon addresses hyperactivation while a floxed null addresses requirement. Homozygous null mice are viable but growth restricted, and Akt2 and Akt3 compensate in muscle, liver and brain respectively, so isoform-specific conclusions demand compound alleles. Pair allele class to readout: null for dependency, E17K knockin for inhibitor pharmacodynamics.',
  Akt2:
    'Akt2 is the mouse ortholog of human AKT2 and encodes the insulin-responsive AKT isoform enriched in skeletal muscle, liver and adipose tissue, where PIP3 recruitment followed by PDK1 T309 and mTORC2 S474 phosphorylation licenses phosphorylation of AS160 and TBC1D1 to release GLUT4 vesicles, and of GSK3 beta and FOXO1 to suppress gluconeogenic transcription. Loss of function in humans produces severe insulin resistance with diabetes, and the corresponding mouse null recapitulates hyperglycemia, hyperinsulinemia and hepatic insulin resistance without embryonic lethality, making constitutive alleles usable while conditional alleles remain preferable for separating muscle, hepatocyte and adipocyte contributions. Activating E17K knockins model hypoinsulinemic hypoglycemia and provide a clean pharmacodynamic substrate for pan-AKT and isoform-selective inhibitors. Akt1 compensates broadly, so metabolic phenotypes sharpen considerably in compound heterozygous or double conditional backgrounds. Select nulls for metabolic dependency mapping, knockins for signaling gain, and tissue-restricted Cre lines matched to the insulin target organ under study.',
  Akt3:
    'Predominantly expressed in brain and testis, Akt3 is the mouse ortholog of human AKT3 and encodes the AKT isoform that governs neural progenitor proliferation and postnatal brain size through PI3K dependent PIP3 binding, PDK1 activation loop phosphorylation and mTORC2 hydrophobic motif phosphorylation, feeding mTORC1 and FOXO outputs in neurons and glia. Somatic mosaic activating changes, principally E17K, cause hemimegalencephaly and focal cortical dysplasia, while germline duplication contributes to megalencephaly capillary malformation spectrum, so conditional or mosaic knockin designs using inducible Cre or in utero electroporation reproduce the human lesion far better than global expression. Constitutive null mice are viable with a proportionally smaller brain, giving a tractable baseline for dependency studies. Akt1 is co-expressed and buffers loss, so double conditional alleles are advisable when scoring neuronal survival. Align allele class with endpoint, using nulls for developmental requirement and mosaic activating knockins for testing PI3K, AKT and mTOR inhibitors in epilepsy models.',
  Aldh1a1:
    'Aldh1a1, the mouse ortholog of human ALDH1A1, encodes the cytosolic NAD+-dependent retinaldehyde dehydrogenase RALDH1, which performs the irreversible oxidation of retinaldehyde to all-trans retinoic acid and thereby supplies ligand to nuclear RAR and RXR heterodimers in dorsal retina, liver, lung, and visceral adipose tissue. The same tetrameric active site detoxifies reactive lipid aldehydes such as 4-hydroxynonenal and metabolizes oxazaphosphorine chemotherapeutics, which is why high enzyme activity defines ALDEFLUOR-positive tumor populations and cyclophosphamide resistance. Since germline nulls are viable and fertile, constitutive deletion suits metabolic and adipose questions, whereas conditional floxed alleles isolate autonomous requirements in retina or tumor compartments, and catalytically dead point knockins separate enzymatic output from noncatalytic roles. Be aware that Aldh1a2, Aldh1a3, and Aldh8a1 generate retinoic acid in overlapping domains, so single-locus loss is often buffered. Humanized knockins are the correct substrate for isoform-selective inhibitor pharmacology, while compound Raldh genetics is required to collapse local retinoid signaling outright.',
  Aldh1a2:
    'Encoding RALDH2, Aldh1a2 is the mouse ortholog of human ALDH1A2 and the dominant source of embryonic all-trans retinoic acid, oxidizing retinaldehyde within paraxial and lateral plate mesoderm, epicardium, and meninges to establish the posterior-to-anterior retinoid gradient read by RAR and Hox targets. Loss of this single enzyme is not tolerated: germline nulls arrest around midgestation with unlooped heart tubes, absent forelimb buds, shortened trunks, and disrupted hindbrain segmentation, a lethality partially rescuable by maternal retinoic acid supplementation, so timed dietary rescue must be planned into any constitutive line. That embryonic requirement makes conditional floxed alleles the practical design for adult immunology, where dendritic cell and stromal RALDH2 drives gut homing and regulatory T cell induction. Paralogous Aldh1a1 and Aldh1a3 occupy largely nonoverlapping domains and do not rescue the early mesodermal deficit. Pair the flox with tissue-restricted Cre drivers such as Cd11c-Cre or Wt1-Cre when the endpoint is retinoid-dependent cell fate rather than gross morphogenesis.',
  Aldh1a3:
    'Aldh1a3, ortholog of human ALDH1A3, encodes RALDH3, the retinaldehyde dehydrogenase that supplies retinoic acid to ventral retina, olfactory and nasal epithelium, otic vesicle, and forebrain, complementing the dorsal RALDH1 domain to build the ocular retinoid gradient required for optic cup and choanal morphogenesis. Biallelic human loss-of-function variants cause autosomal recessive microphthalmia and anophthalmia, while amplified expression marks mesenchymal glioma and triple-negative breast tumor cells with elevated aldehyde detoxification capacity. Constitutive nulls die in the immediate neonatal period from obstructed nasal passages, so respiratory rescue or conditional floxed alleles are mandatory for postnatal retinal, metabolic, or tumor studies. Patient-derived missense knockins are preferable when the question concerns residual catalysis and dominant-negative tetramer poisoning rather than complete absence. Aldh1a1 and Aldh1a2 do not compensate in ventral retina or nasal epithelium, which is precisely why the eye phenotype is penetrant. Choose Six3-Cre or Rx-Cre for ocular questions and adipose or myeloid drivers for metabolic endpoints.',
  Aldoa:
    'Aldoa encodes the mouse ortholog of human ALDOA, the class I fructose-bisphosphate aldolase that assembles into a homotetramer and cleaves fructose-1,6-bisphosphate into dihydroxyacetone phosphate and glyceraldehyde-3-phosphate through a Schiff base intermediate formed on an active site lysine. Aldolase A carries most glycolytic flux in skeletal muscle and erythrocytes, and it also binds filamentous actin, WASP family proteins, and the V-ATPase, so loss perturbs cytoskeletal and vesicular biology alongside ATP supply. Recessive human variants produce nonspherocytic hemolytic anemia with rhabdomyolysis, which argues for point knockins rather than deletion when disease fidelity is the goal. Because Aldob and Aldoc are catalytically competent paralogs with overlapping tissue windows, single locus deletion can be buffered wherever they are co-expressed, so compound alleles belong in the plan early. Conditional floxed alleles crossed to Ckmm-Cre, Vav-Cre, or Rosa26-CreER assign glycolytic dependence to muscle, erythroid, or adult tissues while you read lactate output, ATP content, and myopathy endpoints.',
  Aldob:
    'Hereditary fructose intolerance is fundamentally a story about Aldob, the mouse ortholog of human ALDOB, whose product is the liver, kidney cortex, and intestinal aldolase isoform distinguished by high catalytic efficiency toward fructose-1-phosphate rather than fructose-1,6-bisphosphate alone. When aldolase B activity fails, ketohexokinase continues phosphorylating dietary fructose, fructose-1-phosphate accumulates, phosphate and adenine nucleotides are sequestered, and hypoglycemia, urate elevation, hepatomegaly, and proximal tubular injury follow. That mechanism makes allele choice sharp: a conditional null answers whether hepatocyte fructolysis drives steatosis and lipogenesis, whereas knockin of a catalytically crippled patient substitution such as A149P reproduces misfolding with residual activity closer to clinical biochemistry. Aldoa and Aldoc cannot substitute, since their fructose-1-phosphate kinetics are poor, so redundancy is not the usual confounder here. Pair Alb-Cre or Villin-Cre with defined fructose challenge protocols and read plasma glucose, hepatic ATP and phosphate, uric acid, and triglyceride flux.',
  Aldoc:
    'Aldoc, ortholog of human ALDOC, encodes aldolase C, the brain enriched class I aldolase known to neuroanatomists as zebrin II because its expression marks alternating parasagittal Purkinje cell stripes across the cerebellum. Catalysis follows the same lysine Schiff base chemistry used by aldolases A and B, splitting fructose-1,6-bisphosphate, but tissue distribution favors neurons and astrocytes, where glycolytic and shuttle flux support neurotransmission. Because aldolase C is a faithful compartment marker as well as an enzyme, a knockin reporter or Cre cassette at the locus buys lineage and stripe resolution that simple deletion cannot, while a conditional null asks whether neuronal glycolysis genuinely requires this isoform. Co-expressed Aldoa carries substantial flux in brain, so anticipate masked phenotypes and consider Aldoa Aldoc compound conditionals. Align the allele with the readout, whether cerebellar patterning, astrocyte lactate export, or glycolytic dependence in glioma models, and select an inducible Cre that spares developmental patterning.',
  Alk:
    'Anaplastic lymphoma kinase is encoded by Alk, the mouse ortholog of human ALK, a single-pass receptor tyrosine kinase of the insulin receptor superfamily whose extracellular MAM, LDLa, and glycine-rich domains bind the ALKAL1 and ALKAL2 ligands to drive dimerization and trans-autophosphorylation, feeding RAS/MAPK, PI3K/AKT, and JAK/STAT3 output. Oncogenic activation follows two distinct routes: chromosomal fusions such as EML4-ALK and NPM1-ALK that impose ligand-independent oligomerization, and kinase domain substitutions including F1174L and R1275Q found in neuroblastoma. Allele choice should follow the question, since an inducible fusion knockin at the Alk locus interrogates fusion-driven lung or lymphoid tumorigenesis, a point-mutant knockin reproduces neuroblastoma predisposition, and ectodomain humanization supports antibody, conjugate, and CAR-T pharmacology alongside resistance modeling for L1196M or G1202R. Because Alk null animals are viable with only subtle neurobehavioral changes, constitutive nulls suit ligand-axis studies, while tumor endpoints demand a tissue-restricted Cre or inducible expression matched to the target lineage.',
  Amh:
    'Amh, mouse ortholog of human AMH, encodes anti-Mullerian hormone, a disulfide-linked TGF-beta superfamily dimer secreted by fetal Sertoli cells and postnatal granulosa cells that must be furin-cleaved to release its bioactive C-terminal domain. Signaling proceeds through the dedicated type II receptor AMHR2 paired with type I receptors ALK2, ALK3, or ALK6 to phosphorylate SMAD1, SMAD5, and SMAD8, driving apoptotic regression of the Mullerian duct mesenchyme in males and restraining primordial follicle recruitment and FSH sensitivity in females. Human loss-of-function alleles in AMH or AMHR2 cause persistent Mullerian duct syndrome, and circulating levels index ovarian reserve. Null mice are viable, so conditional deletion is reserved for separating fetal duct regression from adult follicular restraint, while gain-of-function transgenics test ovarian suppression and Leydig differentiation. No other superfamily ligand engages AMHR2, so redundancy is minimal and single-locus phenotypes are interpretable. Humanized alleles matter most when assaying AMH immunoassays or AMHR2-directed biologics.',
  Ang:
    'Angiogenin, the product of mouse Ang and ortholog of human ANG (also called RNASE5), is a secreted RNase A superfamily ribonuclease whose His13, Lys40, His114 catalytic triad supports weak but obligatory cleavage of tRNA anticodon loops, generating stress-induced tiRNA fragments that displace eIF4G and reprogram translation initiation. Under basal conditions the enzyme is clamped by cytosolic RNH1, and during stress it is internalized by motor neurons through syndecan and neuropilin-1 before translocating to the nucleolus to sustain 45S rRNA transcription. Amyotrophic lateral sclerosis and frontotemporal dementia alleles such as K40I and C39W are catalytically hypomorphic, so a conditional null addresses cell-autonomous requirement while a patient point knockin tests whether diminished ribonucleolytic output alone drives motor neuron vulnerability, and humanization enables recombinant protein dosing work. Because the mouse locus is a tandem cluster spanning Ang2 through Ang6, single-gene deletion is buffered; pair Chat-Cre or Gfap-Cre conditionals with neuromuscular junction and survival endpoints.',
  Apc:
    'Apc, the mouse ortholog of human APC, encodes the large scaffold that nucleates the beta-catenin destruction complex, using 15 amino acid and 20 amino acid repeats to bind beta-catenin and SAMP repeats to bind AXIN1 and AXIN2, thereby positioning CK1 alpha and GSK3 beta for the priming and processive phosphorylations that create the beta-TrCP degron. Independently, the armadillo repeat region and C-terminal EB1 and DLG binding sites control microtubule plus end dynamics and mitotic spindle fidelity, so truncating alleles produce both Wnt hyperactivation and chromosomal instability. Mutation position matters enormously: the mutation cluster region retains some repeats and yields intermediate signaling, which is why allelic series such as Min, 1638N and 1322T give different tumor multiplicities. Homozygous null is embryonic lethal, mandating floxed exon 14 or 15 designs with tissue-restricted Cre for intestinal, hepatic or mammary work. Match truncation position to the desired Wnt setpoint rather than assuming all Apc alleles are equivalent.',
  Apoe:
    'Apoe is the mouse ortholog of human APOE and encodes a 299 residue exchangeable apolipoprotein whose amino-terminal four-helix bundle presents the receptor binding surface for LDLR, LRP1 and heparan sulfate proteoglycans, while the carboxy-terminal domain mediates lipid binding and self-association, together directing clearance of chylomicron remnants and VLDL and controlling brain lipid and amyloid beta handling. Mouse Apoe resembles human APOE4 at the domain interaction level and lacks the human isoform series, so targeted replacement knockins carrying human APOE2, APOE3 or APOE4 coding sequence under the endogenous promoter are the only honest platform for isoform-dependent questions in Alzheimer disease, and they are routinely crossed to amyloid or tau models. Conventional null mice develop marked hypercholesterolemia and spontaneous atherosclerosis on chow, which remains the workhorse cardiovascular readout. Because Apoe and Apoj partially overlap in glial lipid transport, interpret CNS phenotypes with that in mind, and select humanized alleles when testing isoform-selective or ASO based therapeutics.',
  App:
    'App encodes amyloid precursor protein, the mouse ortholog of human APP, a type I transmembrane glycoprotein with E1 and E2 ectodomain modules that is either cleaved by ADAM10 within the Aβ sequence, precluding amyloid, or processed sequentially by BACE1 and the presenilin-containing γ-secretase complex to liberate Aβ40, Aβ42 and the AICD transcriptional fragment. Familial Alzheimer alleles act by shifting that competition: Swedish KM670/671NL enhances BACE1 cleavage, London V717I raises the Aβ42 to Aβ40 ratio, Arctic E22G accelerates protofibril assembly, and Icelandic A673T is protective. Rodent Aβ differs from human at three residues (Arg5, Tyr10, His13) and aggregates poorly, so humanizing the Aβ-coding exons in place, rather than transgenic overexpression, is the design that preserves endogenous promoter control and copy number. Aplp1 and Aplp2 compensate broadly, and App with Aplp2 double nulls die perinatally, so plan compound genetics when synaptic and neuromuscular endpoints accompany plaque and cerebral amyloid angiopathy readouts.',
  Arid1a:
    'Arid1a encodes BAF250a, the mouse ortholog of human ARID1A and the largest accessory subunit of the canonical BAF chromatin remodeling complex, where its ARID domain contributes non-sequence-specific DNA contact and its C-terminal region docks onto the SMARCA4 ATPase to target enhancer nucleosome eviction. Tumor alleles are overwhelmingly nonsense or frameshift, collapsing accessibility at lineage and differentiation enhancers in ovarian clear cell carcinoma, endometrioid tumors, gastric adenocarcinoma, and hepatocellular carcinoma. Homozygous deletion causes gastrulation-stage embryonic lethality near E6.5, so useful models require conditional flox alleles with tissue-restricted Cre, frequently combined with Pten or Trp53 loss for penetrant tumors. The paralog Arid1b occupies the same BAF slot in mutually exclusive fashion and buffers single-locus loss, which is precisely why ARID1A mutant cells become selectively dependent on ARID1B, EZH2, and ATR. Choose heterozygous or mosaic loss for dosage questions and full conditional deletion when validating synthetic lethal targets.',
  Arnt:
    'Arnt, the mouse ortholog of human ARNT, encodes HIF1 beta, the obligate class II bHLH-PAS dimerization partner that licenses DNA binding by HIF1 alpha, EPAS1 and the aryl hydrocarbon receptor, contacting hypoxia response elements or xenobiotic response elements only as a heterodimer and recruiting p300 and CBP through partner transactivation domains. Because ARNT is constitutively expressed and not oxygen regulated, it functions as the shared limiting hub where hypoxic and xenobiotic transcriptional programs converge and compete. Germline deletion is embryonic lethal near midgestation from failed placental vascularization and yolk sac angiogenesis, so conditional alleles are essential for adult work in hepatocytes, pancreatic beta cells, keratinocytes and hematopoietic compartments. Because Arnt2 substitutes in neurons and some endocrine tissues, CNS phenotypes require compound conditional genetics to avoid false negatives. Deleting Arnt collapses the entire hypoxic and AHR axis simultaneously, so when isoform-specific questions matter, target Hif1a or Epas1 directly instead of this shared partner.',
  Asxl1:
    'Additional sex combs like 1, encoded by Asxl1 and orthologous to human ASXL1, scaffolds the polycomb repressive deubiquitinase complex by binding BAP1 through its ASXM region and stimulating removal of H2AK119 ubiquitin, while its PHD finger and HARE-HTH module direct chromatin engagement. Myeloid disease alleles cluster as frameshift and nonsense events in the final exon, producing a truncated protein that escapes degradation and behaves as a gain of function, enhancing BAP1 catalysis, depleting H3K27 trimethylation, and derepressing posterior HOXA genes in myelodysplastic syndrome, chronic myelomonocytic leukemia, and secondary AML. Design follows that distinction: a conditional null reports haploinsufficiency and steady-state hematopoiesis, whereas a knockin encoding the truncated mutant recapitulates clonal expansion and transformation that nulls miss entirely. Asxl2 and Asxl3 provide partial buffering in some tissues, so compound genetics may be warranted. Pair inducible Mx1-Cre or Vav-Cre with transplantation readouts when scoring stem cell self-renewal.',
  Atm:
    'Atm, the mouse ortholog of human ATM, encodes a PIKK family kinase held as an inactive dimer until the MRE11, RAD50 and NBS1 complex loads it at double strand breaks, where monomerization, autophosphorylation and acetylation by TIP60 activate phosphorylation of SQ and TQ motifs in KAP1, H2AX, CHK2 T68, p53 S15 and SMC1. This output enforces the G1/S and intra-S checkpoints, promotes heterochromatic break resection and couples oxidative stress to redox signaling. Null mice are viable but display thymic lymphoma, infertility, radiosensitivity and cerebellar signaling defects that only partially phenocopy ataxia telangiectasia, whereas kinase-dead knockin alleles are embryonic lethal because catalytically inert protein poisons break ends, a distinction that must inform allele choice. Conditional nulls are the right tool for tissue-restricted radiosensitization and synthetic lethality studies with ATR or PARP inhibitors, while patient-derived missense knockins address variant reclassification. Pair the allele with a Cre driver active in the lineage where checkpoint failure is being scored.',
  Atp13a2:
    'Atp13a2, ortholog of human ATP13A2 (PARK9), encodes a P5B-type transport ATPase resident in late endosomes and lysosomes that exports polyamines, principally spermine, from the lumen to the cytosol using an N-terminal lipid-binding domain that recognizes phosphatidic acid and phosphoinositides for membrane targeting. Recessive truncating and misfolding alleles cause Kufor-Rakeb juvenile parkinsonism and neuronal ceroid lipofuscinosis, with loss of function producing lysosomal alkalinization, impaired cathepsin maturation, spermine-driven lysosomal rupture, and secondary accumulation of α-synuclein and lipofuscin. Conditional nulls crossed to Dat-Cre or Slc6a3-Cre isolate dopaminergic cell-autonomous degeneration, whereas a patient missense knockin distinguishes catalytic failure from ER retention and degradation of misfolded protein, and humanization supports chaperone or antisense screening against the human coding sequence. The paralogs Atp13a3, Atp13a4 and Atp13a5 transport overlapping polyamine substrates in other compartments, so quantify them before interpreting a mild null; age animals well past twelve months for lipofuscin and gliosis endpoints.',
  Atp5f1a:
    'Oxidative phosphorylation stalls without Atp5f1a, the mouse ortholog of human ATP5F1A, which encodes the alpha subunit present in three copies within the alpha3beta3 hexamer forming the soluble F1 catalytic head of mitochondrial ATP synthase. Alpha subunits provide noncatalytic nucleotide sites and the structural walls against which the rotating gamma central stalk imposes sequential conformational changes on catalytic beta subunits, so alpha is indispensable for rotary coupling rather than merely accessory. De novo dominant and recessive human variants cause encephalopathy, hypotonia, and lactic acidosis with reduced complex V holoenzyme, phenotypes a targeted missense knockin reproduces far better than deletion. No nuclear paralog covers this function, and complete loss of complex V catalysis is incompatible with development, so conditional floxed alleles are mandatory for postnatal work. Combine Ckmm-Cre, Myh6-MerCreMer, or Nes-Cre with blue native PAGE, oligomycin sensitive respiration, and cristae ultrastructure as endpoints.',
  Atp5f1b:
    'Atp5f1b is the mouse ortholog of human ATP5F1B and encodes the beta subunit, the catalytic engine of the F1 sector, contributing Walker A and Walker B nucleotide binding motifs that bind ADP and phosphate and cycle through loose, tight, and open states as gamma rotation imposes the binding change mechanism. Three beta subunits alternate with alpha subunits, and inhibitors such as aurovertin and efrapeptin act on this head, distinguishing it pharmacologically from the oligomycin sensitive membrane sector. Dominant human ATP5F1B variants have been linked to dystonia with spasticity, so a heterozygous patient knockin models the dominant biochemical lesion whereas a conditional null tests absolute requirement in a chosen lineage. No functional nuclear paralog exists, and germline ablation abolishes ATP synthesis, so plan floxed alleles with inducible Cre. Match design to endpoint, whether ATP to ADP ratio biosensors, membrane potential, striatal circuit physiology, or complex V assembly intermediates.',
  Atp5f1c:
    'Rotary coupling in complex V depends on Atp5f1c, the mouse ortholog of human ATP5F1C, encoding the gamma subunit that forms the central stalk with delta and epsilon, inserts into the alpha3beta3 barrel, and converts torque generated by proton driven c-ring rotation into conformational cycling of the catalytic beta subunits. The transcript undergoes tissue specific alternative splicing that swaps carboxy terminal sequence between muscle and liver forms, a feature making isoform selective knockins uniquely informative here. Recessive human variants reduce holoenzyme assembly and present with mitochondrial encephalomyopathy and 3-methylglutaconic aciduria, so a patient substitution knockin captures partial function while a conditional null defines absolute tissue requirement. No redundant nuclear gene compensates, so lineage restricted floxed alleles with Ckmm-Cre, Alb-Cre, or Rosa26-CreER are the practical route. Choose readouts reporting coupling directly, including oligomycin sensitive oxygen consumption, ATP synthesis in permeabilized fibers, and blue native resolution of F1 subcomplexes.',
  Atp5f1d:
    'Atp5f1d, ortholog of human ATP5F1D, encodes the delta subunit of the F1 sector, a central stalk component equivalent to bacterial epsilon that packs against gamma and stabilizes the rotor interface with the catalytic hexamer, making it a structural requirement for productive rotary catalysis rather than a peripheral accessory. Biallelic human ATP5F1D variants cause an episodic metabolic crisis phenotype with 3-methylglutaconic aciduria, hyperammonemia, hypoglycemia, and reduced assembled complex V, a presentation dominated by destabilized holoenzyme rather than complete absence of protein. That distinction sets the design fork, since a missense knockin recreates crisis prone partial deficiency triggered by catabolic stress while a conditional null asks whether a given tissue tolerates complete rotor failure. No nuclear paralog substitutes for delta. Use inducible Rosa26-CreER or Alb-Cre with fasting and illness mimicking challenges, then read plasma organic acids, ammonia, hepatic ATP, and complex V versus subcomplex distribution.',
  Atp5f1e:
    'Assembly of the F1 head requires Atp5f1e, the mouse ortholog of human ATP5F1E, encoding the epsilon subunit, the smallest nuclear encoded component of complex V, which occupies the central stalk beneath gamma and delta and is needed for stable incorporation of the rotor into the catalytic hexamer. A homozygous human tyrosine to cysteine substitution near the amino terminus produces ATP synthase deficiency with 3-methylglutaconic aciduria, lactic acidosis, and peripheral neuropathy while preserving low residual activity, exactly the hypomorphic biochemistry a knockin reproduces and a deletion cannot. Because complete failure of rotor assembly eliminates ATP synthesis, a conditional floxed allele is the appropriate tool for postnatal tissue questions, and no nuclear paralog buffers loss. Select drivers by target tissue, such as Nes-Cre for neurons or Ckmm-Cre for muscle, and quantify holoenzyme by blue native PAGE alongside organic acid profiling and nerve conduction phenotyping.',
  Atp5md:
    'Atp5md corresponds to human ATP5MD, also catalogued as USMG5 and long described as DAPIT, the diabetes associated protein in insulin sensitive tissue, a small hydrophobic subunit of the membrane embedded Fo sector of mitochondrial ATP synthase. DAPIT associates with the c-ring periphery and is required for efficient accumulation of assembled complex V, and its depletion lowers holoenzyme content and oligomycin sensitive ATP synthesis without eliminating individual core subunits, indicating a role in stabilizing and oligomerizing the enzyme rather than in catalysis itself. Human loss of function through a splice altering variant causes Leigh syndrome with isolated complex V deficiency. Design accordingly: a conditional null tests whether a tissue tolerates reduced holoenzyme, while a splice site or missense knockin reproduces graded human deficiency. Because expression is highest in muscle, heart, and adipose, pair Ckmm-Cre, Myh6-MerCreMer, or Adipoq-Cre with respirometry, cristae ultrastructure, and glucose tolerance endpoints.',
  Atp5me:
    'Atp5me, the mouse ortholog of human ATP5ME, encodes subunit e of the membrane embedded Fo sector, a single pass hydrophobic protein that together with subunit g forms the dimerization interface joining ATP synthase monomers into the V shaped dimers that polymerize into rows along cristae ridges. Subunit e is therefore a determinant of inner membrane curvature and cristae architecture as much as of catalysis, and its loss flattens cristae, destabilizes dimers, and reduces coupled ATP synthesis while leaving the catalytic F1 head largely intact. This separates two questions cleanly: a conditional null interrogates whether dimer driven membrane shaping is required in a given tissue, whereas a missense knockin at the e to g contact surface probes dimerization without abolishing the subunit. Subunit g is an obligate partner rather than a substitute, so compensation is not expected. Read cristae by electron tomography, dimers by digitonin blue native PAGE, and coupling by respirometry using Myh6 or Ckmm drivers.',
  Atp5mf:
    'Subunit f of mitochondrial ATP synthase is encoded by Atp5mf, ortholog of human ATP5MF, a small membrane spanning component of the Fo sector positioned near subunits e and g and the mitochondrially encoded ATP6 proton channel, where it contributes to the lateral membrane domain supporting monomer stability and dimer formation. Because subunit f is built into late stage assembly intermediates, its absence yields subcomplexes and lowers oligomycin sensitive ATP synthesis rather than producing a discrete catalytic defect, a signature best captured biochemically rather than by activity assays alone. A conditional null therefore addresses tissue tolerance for destabilized holoenzyme, while a targeted substitution at membrane interfaces asks whether specific lipid or subunit contacts matter. No paralogous gene replaces this subunit. Use tissue restricted or tamoxifen inducible Cre lines to bypass developmental confounds, then profile complex V assembly by blue native PAGE, membrane potential with TMRM, and cristae ultrastructure by electron microscopy.',
  Atp5mg:
    'Atp5mg encodes the mouse counterpart of human ATP5MG, subunit g of the Fo membrane sector, which pairs with subunit e to create the dimerization interface that bends the inner membrane and organizes ATP synthase dimers into the ordered rows defining cristae rims. Loss of subunit g dissociates dimers, flattens cristae, and reduces coupled phosphorylation, phenotypes that reveal how tightly bioenergetic output and membrane topology are linked in mitochondria. Consequently, a conditional null tests the physiological cost of losing cristae shaping in a chosen tissue, while a knockin disrupting the e to g contact isolates dimerization from subunit presence, and neither question is answered by the other. Subunit e is an obligate partner, not a redundant backup, so functional compensation should not be assumed. Combine Myh6-MerCreMer, Ckmm-Cre, or Nes-Cre with electron tomography, digitonin blue native PAGE for dimer content, and respirometry to link architecture to ATP output.',
  Atp5mh:
    'Assigned by nomenclature to the membrane sector of mitochondrial ATP synthase, Atp5mh, ortholog of human ATP5MH, belongs to the ATP5M series of small hydrophobic Fo subunits that surround the c-ring and the mitochondrially encoded ATP6 subunit, whose two offset half channels admit protons from the intermembrane space and release them into the matrix. Torque generated by that protonation cycle rotates the c-ring and central stalk, so membrane sector subunits determine how faithfully proton motive force is converted into ATP rather than dissipated. A conditional null therefore reports coupling efficiency and holoenzyme stability in a defined tissue, whereas a transmembrane missense knockin probes packing against the rotor without eliminating the protein. Because each Fo subunit occupies a distinct position, paralogous rescue should not be assumed. Pair Ckmm-Cre or Rosa26-CreER with oligomycin sensitive oxygen consumption, ATP synthesis in permeabilized fibers, and blue native resolution of holoenzyme versus subcomplexes.',
  Atp5mj:
    'Atp5mj is the mouse ortholog of human ATP5MJ, previously catalogued as ATP5MPL and known biochemically as the 6.8 kDa mitochondrial proteolipid or MP68, a small hydrophobic subunit sitting within the membrane embedded Fo sector adjacent to the c-ring and the ATP6 proton pathway. This proteolipid is required for stable accumulation of assembled ATP synthase, and its depletion reduces holoenzyme levels and oligomycin sensitive ATP synthesis while sparing the isolated F1 catalytic head, marking it as an assembly and stability factor built into late intermediates. Design follows that logic: a conditional null asks whether a tissue tolerates reduced holoenzyme content, and a targeted substitution within the transmembrane span probes specific packing contacts with the rotor. No functional paralog exists. Deploy tamoxifen inducible Rosa26-CreER for adult onset questions or Ckmm-Cre for muscle, then quantify complex V by blue native PAGE, ATP synthesis in permeabilized fibers, and cristae morphology.',
  Atp5mk:
    'Atp5mk, ortholog of human ATP5MK, is the currently approved designation for the small proteolipid previously catalogued as USMG5 and ATP5MD and widely described as DAPIT, subunit k of the membrane embedded Fo sector of mitochondrial ATP synthase. This subunit is dispensable for catalysis in isolation yet required for efficient accumulation and oligomerization of the holoenzyme, so its loss lowers assembled complex V and oligomycin sensitive ATP synthesis while core subunits remain expressed. Expression is highest in insulin sensitive tissues including skeletal muscle, heart, and adipose, and human loss of function has been reported in Leigh syndrome with isolated complex V deficiency. Choose a conditional null to test tissue tolerance for reduced holoenzyme, or a splice altering knockin to reproduce graded human deficiency. Ckmm-Cre, Myh6-MerCreMer, or Adipoq-Cre combined with respirometry, cristae ultrastructure, indirect calorimetry, and blue native PAGE align allele class to endpoint.',
  Atp5ml:
    'Atp5ml, ortholog of human ATP5ML, is a member of the ATP5M family encoding small subunits of the membrane embedded sector of mitochondrial ATP synthase, the region anchoring the peripheral stalk. That stator arm, built around subunit b and capped by OSCP, must resist the torque generated during rotary catalysis, so membrane sector integrity determines whether rotation drives phosphorylation or simply strains the enzyme. Loss of a membrane sector subunit typically yields destabilized holoenzyme, accumulation of assembly intermediates, and reduced oligomycin sensitive ATP synthesis rather than clean loss of catalytic sites. A conditional null therefore measures tissue tolerance for a weakened stator, while a targeted substitution tests specific interfaces without removing the polypeptide. Since Fo subunits occupy nonequivalent positions, do not expect compensation from related subunits. Use Alb-Cre or Rosa26-CreER for hepatic and adult onset questions, reading blue native assembly profiles, respiratory control ratios, and hepatic ATP content.',
  Atp5mo:
    'Complex V biogenesis proceeds through discrete modules, and Atp5mo, ortholog of human ATP5MO, falls within the ATP5M series encoding small membrane sector subunits that join the enzyme late, after the F1 head and c-ring modules are united with help from chaperones including TMEM70. Because these subunits act where the membrane domain is completed, their loss characteristically produces isolated complex V deficiency with accumulated subcomplexes, a pattern shared with human neonatal presentations featuring lactic acidosis, hypertrophic cardiomyopathy, and 3-methylglutaconic aciduria. The design fork is therefore between a conditional null, which reports tissue specific tolerance for failed membrane domain assembly, and a hypomorphic knockin, which better mimics graded human deficiency and survival to phenotyping age. Related Fo subunits are not interchangeable, so compensation is unlikely. Nes-Cre, Myh6-MerCreMer, or inducible whole body Cre lines paired with blue native PAGE, echocardiography, and urine organic acid profiling connect allele class to endpoint.',
  Atp5mp:
    'Atp5mp, the mouse ortholog of human ATP5MP, is one of the ATP5M series encoding small hydrophobic subunits of the ATP synthase membrane sector, the domain whose dimerization drives inner membrane bending. ATP synthase dimers polymerize into rows at cristae rims and work alongside the MICOS complex, including Mic60 and Mic10 at crista junctions, to establish the folded topology that concentrates proton motive force near the enzyme. Losing membrane sector subunits therefore has structural consequences, flattening cristae and lowering coupled phosphorylation even when catalytic subunits remain present. A conditional null tests whether a tissue can operate with disordered cristae, whereas a transmembrane substitution isolates specific packing interactions from wholesale subunit loss. Because each Fo subunit sits in a unique position, related subunits do not substitute. Match the allele to structural readouts, using electron tomography, digitonin blue native PAGE for dimer content, and respirometry under Myh6-MerCreMer or Nes-Cre control.',
  Atp5mq:
    'During ischemia, mitochondrial ATP synthase can run backward, hydrolyzing glycolytic ATP to defend membrane potential, and that reversal is restrained by the inhibitory factor Atp5if1 acting on the F1 head while the membrane sector sets proton conductance. Atp5mq, ortholog of human ATP5MQ, belongs to the ATP5M series encoding small subunits of that membrane sector, so its status directly influences coupling and the balance between synthesis and hydrolysis. A conditional null therefore probes whether a tissue tolerates reduced holoenzyme when oxygen supply fluctuates, while a knockin altering a transmembrane interface asks a narrower structural question without removing the protein. Nonequivalent Fo positions mean related subunits should not be expected to compensate. For cardiac work, Myh6-MerCreMer with ischemia reperfusion protocols links allele class to infarct size, calcium retention capacity, and membrane potential, and blue native PAGE reports whether the lesion is assembly failure or catalytic loss.',
  Atp5mr:
    'Coupling efficiency is not fixed, and Atp5mr, ortholog of human ATP5MR, sits within the ATP5M series encoding small hydrophobic subunits of the ATP synthase membrane sector that determine how tightly proton flux is tied to phosphorylation. When membrane sector composition is perturbed, protons can traverse the inner membrane without productive rotation, shifting the balance between ATP output, heat production, and substrate oxidation, a distinction measurable as oligomycin insensitive respiration. A conditional null therefore quantifies the physiological cost of a leaky or destabilized enzyme in a chosen depot or tissue, while a transmembrane knockin isolates a defined structural contact. Related Fo subunits hold nonequivalent positions and should not be assumed to compensate. For metabolic phenotyping, cross floxed alleles to Adipoq-Cre, Ucp1-Cre, or Ckmm-Cre and read indirect calorimetry, cold tolerance, and glucose disposal alongside blue native complex V profiles and isolated mitochondrial proton leak kinetics.',
  Atp5ms:
    'Complex V is the only oxidative phosphorylation enzyme built from just two mitochondrially encoded proteins, Atp6 and Atp8, and Atp5ms, ortholog of human ATP5MS, belongs to the nuclear ATP5M series whose products complete the membrane sector around them. That bigenomic dependence means nuclear membrane sector subunits and mtDNA encoded partners must be stoichiometrically matched, and loss on either side yields stalled intermediates instead of a fully assembled, oligomycin sensitive enzyme. The allele fork follows: a conditional null defines the nuclear requirement in a tissue, while a hypomorphic knockin lets you titrate assembly and test interactions with mtDNA variants or heteroplasmy in mutator and conplastic strains. Fo subunits are positionally distinct, so paralogous rescue is not expected. Rosa26-CreER enables adult onset deletion that avoids developmental compensation, and blue native PAGE, in organello translation, and oligomycin sensitive ATP synthesis together separate assembly failure from catalytic loss.',
  Atp5mt:
    'Isolated complex V deficiency has a recognizable metabolic fingerprint, and Atp5mt, ortholog of human ATP5MT, belongs to the ATP5M series encoding small membrane sector subunits whose loss reproduces it. When ATP synthase content falls, the resulting redox and acetyl-CoA imbalance drives 3-methylglutaconic and 3-methylglutaric aciduria, lactate elevation, and episodic hyperammonemia, a pattern distinguishing complex V lesions from defects in complexes I through IV. Design choices should exploit that specificity: a hypomorphic knockin sustains viability while producing measurable organic acid abnormalities under catabolic stress, whereas a conditional null defines whether a tissue can function at all without the subunit. Related Fo subunits occupy distinct positions and are unlikely to compensate. Combine Alb-Cre or tamoxifen inducible Rosa26-CreER with fasting and high fat challenge, then track urine organic acids, plasma lactate and ammonia, hepatic ATP, and complex V holoenzyme content by blue native PAGE.',
  Atp5mu:
    'Atp5mu, the mouse ortholog of human ATP5MU, is a member of the ATP5M series encoding small hydrophobic subunits of the ATP synthase membrane sector, the domain that consumes proton motive force and therefore sets inner membrane potential. Because membrane potential governs calcium uptake through the mitochondrial calcium uniporter and influences susceptibility to permeability transition, perturbing membrane sector composition changes far more than ATP output, altering matrix calcium buffering and cell death thresholds. A conditional null tests whether a tissue tolerates a destabilized enzyme under calcium stress, while a transmembrane knockin narrows the question to a specific structural contact without removing the polypeptide. Nonequivalent Fo positions argue against compensation by related subunits. In cardiomyocytes or neurons, Myh6-MerCreMer or Camk2a-Cre paired with TMRM potential measurements, calcium retention capacity assays, and blue native complex V profiling connect the allele directly to the physiological endpoint you intend to report.',
  Atp5mv:
    'Pharmacology gives Atp5mv, ortholog of human ATP5MV, a distinct design logic within the ATP5M series of small ATP synthase membrane sector subunits, because this domain hosts binding sites for classical and emerging complex V inhibitors. Oligomycin engages the c-ring interface, and small molecules such as Gboxin exploit ATP synthase dependence in tumor cells, so residue level species differences in the membrane sector can shift potency between mouse and human enzymes. Humanizing the coding sequence therefore creates a pharmacologically matched host for candidate inhibitors, while a conditional null establishes on target dependence and a transmembrane knockin defines resistance conferring positions. Positional uniqueness among Fo subunits makes compensation improbable. For target validation, combine humanized or floxed alleles with inducible Cre, autochthonous or transplanted tumor models, and readouts including oligomycin sensitive respiration, cellular ATP, and target engagement, keeping allele class matched to whether you are asking about biology or drug response.',
  Atp5mw:
    'Neurons run on tight local ATP budgets, and Atp5mw, ortholog of human ATP5MW, belongs to the ATP5M series encoding small hydrophobic subunits that complete the membrane sector of mitochondrial ATP synthase in those energy limited compartments. Presynaptic terminals depend on oxidative phosphorylation to fuel vesicle cycling and ion pumping, so reduced holoenzyme content lowers coupled ATP synthesis and produces activity dependent failure long before gross mitochondrial loss appears. That kinetic vulnerability shapes allele choice, since a conditional null asks whether a neuronal population survives and transmits without the subunit, while a hypomorphic knockin models graded deficiency closer to human mitochondrial encephalopathy. Related Fo subunits sit in nonequivalent positions and should not be expected to substitute. Use Nes-Cre, Syn1-Cre, or Camk2a-Cre with genetically encoded ATP and ATP to ADP ratio sensors, synaptic electrophysiology, cristae tomography, and blue native complex V profiling to link allele class to circuit endpoints.',
  Atp5mx:
    'Glucose stimulated insulin secretion is an ATP dependent process, which gives Atp5mx, ortholog of human ATP5MX, a defined physiological entry point among the ATP5M series encoding small subunits of the ATP synthase membrane sector. In beta cells, glycolytic and mitochondrial flux raise the cytosolic ATP to ADP ratio, close KATP channels, and trigger calcium influx and exocytosis, so any reduction in oligomycin sensitive ATP synthesis blunts secretion without necessarily altering islet mass. A conditional null therefore tests whether beta cells tolerate reduced holoenzyme, whereas a hypomorphic knockin produces graded deficiency resembling human mitochondrial diabetes more closely. Because Fo subunits occupy unique positions, related subunits should not be assumed to compensate. Cross floxed alleles to Ins1-Cre or inducible Pdx1-CreER to avoid developmental confounds, then read perifusion insulin secretion, ATP to ADP ratio biosensors, calcium imaging, glucose tolerance, and complex V assembly by blue native PAGE.',
  Atp5my:
    'Hematopoietic stem cells sit at a metabolic decision point, and Atp5my, ortholog of human ATP5MY, belongs to the ATP5M series encoding small hydrophobic subunits of the mitochondrial ATP synthase membrane sector that set coupled ATP output in those cells. Quiescent stem cells maintain low oxidative flux yet require intact membrane potential and cristae organization, while lineage commitment and proliferation impose sharply higher demand, so reduced holoenzyme content typically spares the resting pool and penalizes differentiation and stress response. That biology defines the fork: a conditional null asks whether a hematopoietic compartment can expand without the subunit, and a hypomorphic knockin tests graded deficiency during regenerative stress. Positional specificity among Fo subunits makes compensation unlikely. Use Vav-Cre for pan hematopoietic deletion or Rosa26-CreER for adult onset, then combine competitive transplantation, cell cycle and membrane potential flow cytometry, respirometry, and blue native complex V profiles.',
  Atp5mz:
    'Skeletal muscle exposes complex V defects with unusual clarity, making Atp5mz, ortholog of human ATP5MZ, a tractable member of the ATP5M series encoding small membrane sector subunits of mitochondrial ATP synthase. Contracting fibers demand rapid, sustained phosphorylation of ADP, so lowered holoenzyme content restricts oxidative capacity, accelerates phosphocreatine depletion, and shifts flux toward glycolysis and lactate accumulation during exercise. A conditional null answers whether muscle can maintain force and metabolic homeostasis without the subunit, while a hypomorphic knockin better reproduces the exercise intolerance and delayed recovery seen in human ATP synthase deficiency. Related Fo subunits hold nonequivalent structural positions, so compensation should not be assumed. Pair floxed alleles with Ckmm-Cre for developmental deletion or Pax7-CreER and HSA-MerCreMer for adult onset, then measure treadmill endurance, phosphocreatine recovery kinetics, permeabilized fiber respirometry, and complex V holoenzyme by blue native PAGE.',
  Atp5po:
    'Atp5po encodes the mouse ortholog of human ATP5PO, the oligomycin sensitivity conferring protein that caps the peripheral stalk and clamps it onto the top of the alpha3beta3 catalytic head, transmitting the stator function that lets c-ring rotation do useful work rather than spin freely. OSCP is also a regulatory hub, serving as the binding site for cyclophilin D and for small molecules such as Bz-423, and it is central to arguments linking ATP synthase conformation to permeability transition. Loss of OSCP uncouples F1 from Fo and destabilizes the holoenzyme, so a conditional null measures the cost of losing the stator crown, whereas targeted substitutions at the cyclophilin D interface separate coupling from permeability transition regulation. No nuclear paralog substitutes. Myh6-MerCreMer or Rosa26-CreER with calcium retention capacity assays, TMRM potential measurements, oligomycin sensitive respiration, and blue native holoenzyme profiling map each allele to a distinct mechanistic endpoint.',
  Atr:
    'Distinct from ATM in trigger and kinetics, Atr is the mouse ortholog of human ATR and encodes the PIKK that responds to RPA coated single stranded DNA at stalled forks and resected ends, recruited through its obligate partner ATRIP and activated allosterically by TOPBP1 or ETAA1 to phosphorylate CHK1 at S317 and S345, RPA32 and the 9-1-1 clamp, thereby suppressing origin firing, stabilizing forks and enforcing the replication checkpoint. Complete loss is cell lethal and embryonic lethal, so hypomorphic Seckel syndrome knockins and conditional floxed alleles with inducible Cre are the only workable designs for studying replication stress in vivo. Acute conditional deletion in adult tissue produces stem cell attrition and progeroid features, giving a mechanistic readout for ATR inhibitor toxicity. Chek1 sits immediately downstream and is not redundant, so do not expect ATM to substitute. Select hypomorphs for chronic replication stress biology and conditional nulls for acute dependency and inhibitor mechanism-of-action work in ATM deficient or oncogene driven tumors.',
  Atrx:
    'The X-linked Atrx locus, ortholog of human ATRX, encodes a SNF2-family ATPase whose ADD domain reads the combinatorial signal of unmethylated H3K4 with trimethylated H3K9, licensing recruitment to pericentromeric satellite repeats, telomeres, and imprinted loci. Acting as the obligate partner of DAXX, it deposits the replication-independent variant H3.3 into heterochromatin and resolves G-quadruplex structures during replication, so loss produces telomere dysfunction and the alternative lengthening of telomeres phenotype seen in pediatric glioblastoma, sarcoma, and pancreatic neuroendocrine tumors, alongside the developmental syndrome caused by hypomorphic missense alleles. Constitutive deletion is embryonic lethal, so exon-flanked conditional alleles combined with lineage Cre lines are standard, and hemizygous males versus heterozygous females demand explicit design decisions because of X inactivation mosaicism. No paralog substitutes for ADD-directed targeting. Select full conditional loss for telomere and genome instability endpoints, and point-mutant knockins when modeling syndromic missense biology.',
  Axin1:
    'Axin1, the mouse ortholog of human AXIN1, encodes the concentration limiting scaffold of the beta-catenin destruction complex, using an N-terminal RGS domain to dock APC, a central segment to bind GSK3 beta and CK1 alpha, and a C-terminal DIX domain to polymerize and to engage Dishevelled DIX domains at activated LRP6 signalosomes. Its abundance is set by tankyrase mediated PARsylation and RNF146 dependent degradation, which is exactly why tankyrase inhibitors raise AXIN1 levels and suppress Wnt output. Loss of function AXIN1 mutations occur in hepatocellular carcinoma and hepatoblastoma, producing ligand-independent signaling equivalent to APC truncation. Germline null causes embryonic lethality with axis duplication in the classic Fused mutant, so hepatocyte or intestinal conditional alleles are required for tumor work. Axin2 is transcriptionally induced by Wnt and partially compensates, so double conditional stocks reveal phenotypes single deletion hides. Choose nulls for dependency and tankyrase pharmacology, and stabilization-resistant knockins to interrogate degradation control.',
  Axin2:
    'Axin2, mouse ortholog of human AXIN2 and also called conductin, encodes a destruction complex scaffold structurally parallel to AXIN1, with RGS and DIX domains supporting APC and Dishevelled interactions, but distinguished by being a direct Wnt target gene, which makes it both a negative feedback brake and the field standard transcriptional reporter of pathway activity. Reporter knockin alleles such as Axin2-LacZ or Axin2-CreERT2 exploit that property to mark and lineage trace Wnt responsive stem cells in intestine, bone, liver and hair follicle, so allele choice here is frequently about readout rather than loss of function. Human truncating variants cause oligodontia with colorectal cancer predisposition, and null mice are viable with craniosynostosis and altered bone mass, allowing constitutive alleles. Because Axin1 is the more abundant scaffold and buffers loss, expect modest signaling change from Axin2 deletion alone. Match design to purpose: reporter or CreERT2 knockins for lineage tracing, conditional nulls layered onto Axin1 alleles for feedback dissection.',
  Bak1:
    'Bak1 encodes BAK, the mouse ortholog of human BAK1 and one of two obligate multidomain effectors of mitochondrial outer membrane permeabilization. Unlike BAX, BAK resides constitutively in the outer membrane anchored by its alpha9 transmembrane helix, and activation begins when a BH3-only ligand such as BID, BIM, or PUMA transiently engages the canonical hydrophobic groove, triggering separation of the core and latch domains, exposure of the alpha6 dimerization interface, and assembly of BH3-in-groove homodimers that oligomerize into lipidic pores releasing cytochrome c and SMAC. Because Bax provides near-complete functional overlap, single Bak1 nulls are viable and largely unremarkable, and only Bax Bak1 double deficiency reveals the full phenotype, including persistent interdigital webbing, imperforate vaginal closure, accumulated neurons, and frequent perinatal death. Design accordingly: conditional Bak1 flox alleles combined with Bax flox and a tissue-restricted Cre for apoptosis-resistance studies, or groove mutants when distinguishing activation from effector pore formation during BH3 mimetic pharmacology.',
  Bax:
    'Mouse Bax, ortholog of human BAX, encodes the cytosolic counterpart to BAK and executes mitochondrial outer membrane permeabilization once activated by upstream ligands. In healthy cells BAX cycles between cytosol and mitochondria, its alpha9 helix sequestered in its own hydrophobic groove and continuously retrotranslocated by BCL2L1 and MCL1, so commitment requires BH3-only activators (BID, BIM, PUMA) to engage either the canonical groove or the alpha1 to alpha6 rear site, driving conformational opening, membrane insertion, symmetric BH3-in-groove dimers, and pore formation upstream of APAF1 apoptosome assembly. Since BAK1 is largely redundant, informative genetics almost always requires compound alleles, and germline Bax Bak1 double nulls are frequently perinatal lethal with retained interdigital webs and expanded neural progenitors. Conditional Bax flox stocks paired with Bak1 flox and a lineage-restricted Cre are therefore the practical route, with non-functional point knockins reserved for questions about oligomerization mechanism rather than absolute apoptotic capacity.',
  Bbc3:
    'Bbc3, ortholog of human BBC3, encodes PUMA, a BH3-only protein that is among the most direct transcriptional outputs of p53 and therefore the principal transducer of DNA damage, oncogene stress, and glucocorticoid or cytokine withdrawal into mitochondrial apoptosis. PUMA is unusual among BH3-only members in binding all antiapoptotic relatives, BCL2, BCL2L1, BCL2L2, MCL1, and BCL2A1, with high affinity, so it both liberates and directly activates BAX and BAK; p53-independent induction via FOXO3A and CHOP extends its reach to trophic factor loss and ER stress. Nulls are viable and fertile but show marked resistance of thymocytes and hematopoietic progenitors to irradiation, and phenotypes are frequently blunted because Pmaip1 (NOXA), Bid, and Bcl2l11 cover overlapping stress inputs, making compound alleles necessary. Choose a conditional null when asking whether a tissue requires PUMA for damage-induced deletion, and pair it with p53 pathway alleles when tumor latency or therapy response is the endpoint.',
  Bcl2:
    'Bcl2 is the mouse ortholog of human BCL2 and encodes the founding antiapoptotic guardian of the mitochondrial pathway, a tail-anchored protein whose BH1, BH2, and BH3 helices form an elongated hydrophobic groove that captures the BH3 helices of activators and effectors, restraining BAX and BAK before permeabilization. Its oncogenic biology is dosage driven rather than mutational: the human t(14;18) translocation places BCL2 under immunoglobulin heavy chain control in follicular lymphoma, best recapitulated in mice by Emu-driven or conditionally activated overexpression rather than a point mutant. Nulls survive birth but develop polycystic kidneys, lymphoid involution, and hair greying. Because Bcl2l1, Mcl1, and Bcl2l2 buffer loss in most tissues, single deletion often looks silent. Epitope-matched humanization is the decisive design when venetoclax pharmacology is the endpoint, including engineered Gly101Val resistance, while conditional nulls and inducible overexpression alleles answer survival dependency and lymphomagenesis questions respectively.',
  Bcl2l1:
    'Encoding BCL-xL, Bcl2l1 is the ortholog of human BCL2L1 and provides the dominant antiapoptotic buffer in erythroid precursors, platelets, and neurons, sequestering BAK and BAX BH3 helices in its groove and additionally retrotranslocating BAX from mitochondria back to cytosol to raise the permeabilization threshold. Regulation runs through STAT5 and NF-kappaB dependent transcription, alternative splicing that yields the proapoptotic BCL-xS isoform, and deamidation or Ser62 phosphorylation that weakens ligand binding. Germline deletion is embryonic lethal near E13 with massive apoptosis of immature hematopoietic cells and postmitotic neurons, so conditional flox alleles with lineage-restricted Cre drivers are mandatory rather than optional. Platelet-specific deletion phenocopies the dose-limiting thrombocytopenia of navitoclax and remains the standard platform for interrogating that toxicity. Match allele to question: conditional null for dependency mapping, and humanized knockin when BH3 mimetic selectivity or acquired resistance mutations constitute the readout.',
  Bcl6:
    'B cell lymphoma 6, encoded by Bcl6 and orthologous to human BCL6, is a BTB/POZ zinc finger transcriptional repressor whose homodimer lateral groove recruits NCOR, SMRT, and BCOR corepressors while its RD2 region engages MTA3 and NuRD. As master regulator of the germinal center reaction it silences Trp53, Cdkn1a, Atr, and Prdm1, permitting tolerated DNA damage during somatic hypermutation and blocking plasma cell differentiation. Lymphoma activation arises from IGH or promoter substitution translocations and 5-prime regulatory mutations that prevent normal downregulation, yielding constitutive expression in diffuse large B cell lymphoma. Design accordingly: conditional deletion defines germinal center dependency, a knockin or promoter substitution allele driving sustained expression models lymphomagenesis, and BTB groove point mutants separate corepressor-dependent from independent functions for degrader and inhibitor programs. Germline nulls are viable but develop inflammatory myocarditis, so Cd19-Cre or Cgamma1-Cre restriction keeps phenotypes interpretable against B cell endpoints.',
  Bid:
    'Bid, ortholog of human BID, encodes the BH3-only protein that couples receptor-initiated to mitochondrial apoptosis. Full-length BID is a compact eight-helix protein held inactive until caspase-8, activated within the FAS or TNFR1 death-inducing complex, cleaves it at Asp59 to yield tBID, which becomes N-myristoylated, targets cardiolipin-rich mitochondrial membranes, and directly activates BAK and BAX; granzyme B, calpains, and cathepsins cut BID at nearby sites, extending the same logic to cytotoxic lymphocyte killing and lysosomal damage. BID is also an ATM substrate implicated in the S-phase checkpoint. Nulls are viable, resist FAS-driven hepatocyte apoptosis, and eventually develop myeloid expansion, but the extrinsic-to-intrinsic bridge is partly covered by Bcl2l11 and Bbc3, so compound genetics is often required. A non-cleavable Asp59 knockin is the sharpest tool for isolating caspase-8-dependent amplification, whereas conditional nulls with hepatocyte or myeloid Cre address tissue-specific death sensitivity.',
  Bmp1:
    'Despite its name, Bmp1, the mouse ortholog of human BMP1, encodes no SMAD-activating ligand but rather a secreted zinc-dependent astacin family metalloprotease with CUB and EGF domains that functions as procollagen C-proteinase, removing the C-terminal propeptides of procollagen I, II, and III to permit fibril assembly. The same catalytic activity matures prolysyl oxidase for crosslinking and cleaves chordin, thereby liberating BMP2 and BMP4 for receptor engagement, placing this protease simultaneously in matrix assembly and morphogen availability. Human biallelic mutations cause osteogenesis imperfecta type XIII with high bone mass fractures and dentinogenesis defects. Constitutive nulls die perinatally with a persistent ventral body wall closure defect, so conditional floxed alleles driven by Col1a1-Cre or Prrx1-Cre are the correct tool for adult bone and fibrosis endpoints. Critically, the tolloid paralogs Tll1 and Tll2 share substrate specificity and mask single-locus loss, so compound conditional genetics should be planned before interpreting matrix phenotypes.',
  Bmp10:
    'Bmp10, ortholog of human BMP10, encodes a BMP9-related ligand whose expression in the embryonic ventricular trabeculae and the adult right atrium makes it the most anatomically restricted member of the family. Processed dimers, including circulating BMP9 and BMP10 heterodimers, bind the type I receptor ALK1 with BMPR2 or ACVR2A and the endothelial coreceptor endoglin to phosphorylate SMAD1, SMAD5, and SMAD8, enforcing vascular quiescence and driving cardiomyocyte proliferation through Nkx2-5 and Mef2c. Germline nulls die near midgestation with hypoplastic trabeculae and arrested cardiac growth, so cardiac and endothelial conditional floxed alleles are required for any postnatal vascular malformation or pulmonary hypertension study. Loss-of-function logic here connects directly to hereditary hemorrhagic telangiectasia, where ALK1 and endoglin lesions phenocopy ligand deprivation. Because BMP9 encoded by Gdf2 substitutes substantially in circulation, compound Gdf2 and Bmp10 genetics is necessary to unmask ALK1 pathway collapse, and ligand-trap or antibody testing benefits from epitope-matched humanization.',
  Bmp15:
    'Oocyte-restricted expression distinguishes Bmp15, the mouse ortholog of human BMP15, whose product is a TGF-beta superfamily ligand secreted by growing oocytes, largely as a covalent heterodimer with GDF9 known as cumulin. That heterodimer signals to adjacent granulosa cells through BMPR1B and BMPR2 with SMAD1, SMAD5, and SMAD8 phosphorylation, coordinating cumulus expansion, glycolytic support of the oocyte, and suppression of premature luteinization. Human heterozygous variants cause primary ovarian insufficiency, and ovine FecX alleles produce dose-dependent hyperprolificacy then sterility, illustrating a steep genotype to ovulation-rate relationship. Mouse nulls are viable with only modest subfertility, so a simple knockout is a weak model; instead, patient-specific missense knockins that impair proprotein processing or heterodimer formation better recapitulate human disease logic. Because Gdf9 partners with and partially covers this ligand, compound or allelic-series designs are advisable. Humanized knockins are the right platform for recombinant cumulin or in vitro maturation reagent testing against defined ovulation endpoints.',
  Bmp2:
    'Bmp2, mouse ortholog of human BMP2, encodes a proteolytically processed homodimeric ligand that engages BMPR1A or BMPR1B with BMPR2 to phosphorylate SMAD1, SMAD5, and SMAD8, which complex with SMAD4 to activate Id1, Runx2, and Sp7 while also feeding noncanonical TAK1 and p38 output. It is the classical osteoinductive ligand of the family, driving mesenchymal condensation, chondrogenesis, and osteoblast commitment, and its recombinant human form is used clinically for spinal fusion where ectopic bone is a recognized liability. Germline deletion is embryonic lethal with amnion and chorion failure plus malpositioned hearts, so conditional floxed alleles with Prrx1-Cre, Col2a1-Cre, or Sp7-Cre are mandatory for skeletal work, and inducible overexpression or degradation-resistant knockins model heterotopic ossification. Extracellular antagonists noggin, gremlin, and chordin and the closely related ligand BMP4 buffer local loss, making compound Bmp2 and Bmp4 conditionals the honest design when the endpoint is complete osteogenic signaling collapse.',
  Bmp3:
    'Functionally inverted relative to its osteogenic relatives, Bmp3, the mouse ortholog of human BMP3 and historically called osteogenin, encodes an abundant bone matrix ligand that antagonizes bone formation by signaling through ACVR2B with ALK4 to phosphorylate SMAD2 and SMAD3, thereby competing with SMAD1, SMAD5, and SMAD8 output from BMP2, BMP4, and BMP7 and restraining osteoprogenitor commitment. Deletion in mice is viable and produces increased trabecular bone volume, establishing the gene as a negative regulator whose loss is an anabolic gain, while transgenic overexpression yields spontaneous rib fractures and reduced bone mass. That directionality dictates allele choice: constitutive nulls address bone accrual and fracture healing, conditional floxed alleles separate osteocyte-derived from marrow stromal ligand, and overexpression knockins model the osteopenic extreme. Its closest paralog Gdf10, also named BMP3B, shares SMAD2 and SMAD3 bias and can obscure single-locus effects in skeletal readouts. Align allele class with microCT, dynamic histomorphometry, or callus bridging endpoints accordingly.',
  Bmp4:
    'Bmp4, ortholog of human BMP4, encodes the principal dorsoventral patterning ligand of the mammalian embryo, a processed homodimer acting through BMPR1A with BMPR2 to drive SMAD1, SMAD5, and SMAD8 phosphorylation and Id gene induction during gastrulation, primordial germ cell allocation, limb and craniofacial mesenchyme patterning, and later hair follicle and hematopoietic niche signaling. Extracellular tuning by noggin, chordin, gremlin, and twisted gastrulation sets the effective gradient, and human heterozygous deletions cause microphthalmia with coloboma, orofacial clefting, and digit anomalies, matching a strict dosage requirement. Constitutive nulls fail at gastrulation with absent mesoderm, so conditional floxed alleles are obligatory, and hypomorphic or haploinsufficient models are better matched to human dosage disease than complete deletion. Because Bmp2 and Bmp7 overlap in most of these fields and heterodimers are physiologically relevant, compound conditionals are frequently necessary. Choose Cre drivers such as Wnt1-Cre, Prrx1-Cre, or Krt14-Cre according to whether the endpoint is craniofacial, appendicular, or epidermal.',
  Bmp5:
    'Bmp5, mouse ortholog of human BMP5, encodes a BMP6 and BMP7 subgroup ligand that signals via ALK2, ALK3, or ALK6 with BMPR2 into SMAD1, SMAD5, and SMAD8, and it is best known through the classical short ear mutation, a naturally occurring allelic series affecting external ear cartilage, sternebrae, vertebral processes, ribs, and lung septation. Because those spontaneous alleles range from regulatory deletions to protein nulls, the locus is an unusually clean example of enhancer-specific versus coding disruption yielding distinct anatomical subsets, which is an argument for enhancer-targeted deletions rather than whole-gene ablation when a specific skeletal element is the readout. Homozygous nulls are viable and fertile, so constitutive knockouts are tractable for cartilage, fracture repair, and dendrite arborization studies. Substantial redundancy with Bmp6 and Bmp7 in kidney, bone, and iron-related contexts means single-locus loss is often silent outside the short ear domains. Match compound conditionals to whichever endpoint, skeletal patterning or repair, is being scored.',
  Bmp6:
    'Bmp6, ortholog of human BMP6, encodes the physiological iron sensor ligand of the liver, produced by sinusoidal endothelial cells in proportion to hepatic iron and acting on hepatocyte ALK2 and ALK3 with ACVR2A and the coreceptor hemojuvelin to phosphorylate SMAD1, SMAD5, and SMAD8 and transactivate the Hamp promoter, thereby setting circulating hepcidin and ferroportin-mediated iron export. Human variants reduce hepcidin and contribute to non-HFE iron overload, while pathway blockade underlies anemia of inflammation therapeutics. Nulls are viable with marked hepatic and pancreatic iron loading, so constitutive deletion is informative, though endothelial conditional floxed alleles are needed to prove the cellular source and to avoid confounding skeletal effects. Point knockins disrupting the hemojuvelin-dependent interface separate iron sensing from generic osteogenic signaling. Because BMP2 encoded by Bmp2 also contributes hepatic hepcidin induction and Bmp5 and Bmp7 overlap elsewhere, compound genetics is advisable when the endpoint is complete hepcidin failure rather than partial derepression.',
  Bmp7:
    'Bmp7, mouse ortholog of human BMP7 and long known as osteogenic protein 1, encodes a ligand acting through ALK2 and ALK3 with BMPR2 and ACVR2A to phosphorylate SMAD1, SMAD5, and SMAD8, and it is indispensable for metanephric mesenchyme survival, nephron progenitor maintenance, lens and retina induction, and eye and skeletal patterning, while also promoting brown adipocyte commitment through PRDM16 and UCP1. Constitutive nulls die within the first day after birth from renal dysplasia with anophthalmia or microphthalmia, so any adult fibrosis, kidney injury, or thermogenesis study requires conditional floxed alleles paired with drivers such as Six2-Cre, Pax8-Cre, or Adipoq-Cre. Its antifibrotic counterbalance against TGF-beta and SMAD3 makes ligand delivery and receptor-selective agonist testing a common goal, which favors epitope-matched humanization. Overlap with BMP5 and BMP6 in bone and kidney means single-locus deletion can understate the pathway requirement, so compound alleles should be considered when scoring interstitial fibrosis or tubular repair endpoints.',
  Bmp8a:
    'Bmp8a, ortholog of human BMP8A, encodes one of two tandemly duplicated BMP8 ligands in mouse and belongs to the BMP5, BMP6, BMP7 subgroup, signaling through ALK2 and ALK3 with BMPR2 and ACVR2A into SMAD1, SMAD5, and SMAD8. Expression is concentrated in germ cells and epididymis, with additional signal in placenta and brown adipose tissue, consistent with roles in spermatogenic maintenance and thermogenic programming. The critical experimental caveat is genomic: Bmp8a and Bmp8b lie adjacent in a duplicated cluster with near-identical mature domains, so guide RNA and homology arm design must be verified against both loci to avoid unintended dual targeting or off-locus recombination. Nulls are viable, making constitutive deletion feasible, but a floxed allele that permits sequential recombination with a Bmp8b flox is the more informative investment. Interpret single-locus phenotypes conservatively given reciprocal compensation, and reserve compound conditionals for germ cell attrition or UCP1-dependent energy expenditure endpoints.',
  Bmp8b:
    'Bmp8b, the mouse ortholog of human BMP8B, encodes the better characterized of the duplicated BMP8 ligands, acting through ALK2 and ALK3 with BMPR2 and ACVR2A on SMAD1, SMAD5, and SMAD8 in two well-defined settings: primordial germ cell allocation and spermatogenic progression in the testis, and brown adipose thermogenesis, where locally induced ligand raises sympathetic tone and p38-dependent UCP1 output while also acting on hypothalamic circuits. Nulls show germ cell depletion with progressive infertility and blunted diet-induced thermogenesis, both viable phenotypes accessible without conditional rescue. Nevertheless, tissue-specific floxed alleles separate adipocyte-autonomous from central contributions, which matters because the metabolic phenotype has both peripheral and hypothalamic components. Because the adjacent paralog Bmp8a shares mature domain sequence and expression territory, targeting design must be locus-verified and compensation assumed. Choose constitutive deletion for fertility scoring, adipocyte or neuron-restricted Cre for energy expenditure, and overexpression models when the endpoint is pharmacological thermogenic gain.',
  Braf:
    'Braf, the mouse ortholog of human BRAF, encodes the RAF family serine/threonine kinase that couples RAS-GTP to MEK1 and MEK2 through an N-terminal RAS binding domain and cysteine rich domain, an autoinhibitory 14-3-3 clamped conformation, and an obligate side-to-side kinase dimer interface. The V600E substitution within the activation segment mimics phosphorylation and signals as a RAS-independent monomer, whereas class II and class III alleles retain dimer or RAS dependence, a distinction that fully determines response to vemurafenib class inhibitors and explains paradoxical MAPK activation. Kinase-impaired germline variants instead drive cardiofaciocutaneous syndrome through altered dimer allostery. Constitutive null is embryonic lethal from vascular and placental failure, so conditional Lox-Stop-Lox V600E knockins driven by lineage-restricted Cre remain the standard for melanoma, thyroid, lung and colon models. Araf and Raf1 dimerize with BRAF and mediate resistance, so consider compound alleles. Match allele class to the inhibitor question, since monomer and dimer alleles predict opposite pharmacology.',
  Brca1:
    'Brca1, mouse ortholog of human BRCA1, encodes a RING domain E3 ubiquitin ligase that heterodimerizes obligately with BARD1 and uses tandem BRCT repeats to read phosphopeptides on ABRAXAS, BACH1 and CTIP, assembling distinct complexes that antagonize 53BP1 and shieldin at break ends, license end resection, and promote RAD51 loading for homologous recombination. Loss produces the BRCAness state of HR deficiency, replication fork instability and PARP inhibitor sensitivity, with tumor spectra concentrated in mammary and ovarian epithelium. Homozygous null mice die during early embryogenesis, rescued partially by Trp53 loss, so conditional exon 11 or full null floxed alleles combined with mammary Cre drivers and a p53 allele constitute the canonical model. Separation-of-function knockins, notably RING-deficient and BRCT phospho-binding mutants, distinguish ligase activity from scaffolding and explain PARP inhibitor resistance through 53BP1 loss. Choose conditional nulls for tumorigenesis and drug response, and precise variant knockins for clinical variant reclassification, always pairing with a validated epithelial Cre.',
  Brca2:
    'Encoding the RAD51 loading factor, Brca2 is the mouse ortholog of human BRCA2 and produces a very large protein whose eight BRC repeats bind RAD51 monomers, whose DNA binding domain with the DSS1 partner engages single stranded and double stranded junctions, and whose C-terminal TR2 site stabilizes assembled filaments, together enabling strand invasion during homologous recombination and protecting stalled replication forks from MRE11 mediated degradation. Because fork protection and HR are genetically separable, allele design matters: full nulls are embryonic lethal, whereas hypomorphic truncation alleles and conditional floxed exon 11 designs permit viable tumor-prone cohorts, typically combined with Trp53 deletion and a mammary or pancreatic Cre. Biallelic hypomorphic human alleles cause Fanconi anemia subtype D1, providing a distinct developmental readout. Reversion and fork protection restoring mutations drive PARP inhibitor resistance in vivo, so knockins of specific patient variants are the right tool for resistance mechanism work rather than a generic null.',
  C1qa:
    'C1qa encodes the A chain of C1q, ortholog of human C1QA, contributing one of the three collagen-like stalks and globular gC1q heads that assemble with C1QB and C1QC into the hexameric bouquet recognizing IgG and IgM Fc, pentraxins, and exposed phosphatidylserine on apoptotic cells and synapses. Head engagement induces a conformational change in the collagenous arms that activates the associated C1r2C1s2 tetramer, cleaving C4 and C2 to build the classical pathway C3 convertase, while C1q deposited on synapses licenses CR3-dependent microglial pruning and drives complement-mediated synapse loss in neurodegeneration models. Critically, the three chains are not redundant: loss of C1qa destabilizes the entire molecule, producing functional C1q deficiency with impaired apoptotic clearance and lupus-like autoimmunity. Conditional deletion distinguishes microglial from hepatic and macrophage sources, and humanization is worth the effort only when an anti-C1q antibody or classical pathway inhibitor with human-restricted binding is the endpoint.',
  C1qb:
    'Mouse C1qb is the ortholog of human C1QB and encodes the B chain that, in strict one-to-one stoichiometry with the A and C chains, forms the ABC heterotrimeric subunits whose triple-helical collagen regions bundle into the stalk of the hexameric C1q molecule. The B chain gC1q head carries much of the charge pattern used for immune complex recognition, and correct chain assembly in the endoplasmic reticulum is a prerequisite for secretion, which is why disrupting C1qb abolishes circulating C1q entirely rather than reducing it proportionally. Downstream consequences include loss of classical pathway initiation, defective clearance of apoptotic debris, glomerular immune complex accumulation, and reduced complement-dependent synaptic pruning. Because no paralog substitutes, single-gene deletion is fully informative, but for cell-source questions a conditional flox allele combined with microglial (Cx3cr1-CreER) or myeloid Cre is preferable, and full-locus humanization suits classical pathway therapeutics whose epitopes are species restricted.',
  C1qc:
    'Encoding the C chain of C1q, mouse C1qc is the ortholog of human C1QC and completes the obligate ABC subunit whose globular head contributes to the recognition surface for IgG Fc, C-reactive protein, calreticulin, and apoptotic cell ligands, while its collagen-like domain participates in the interlocking stalk that transmits binding energy to the C1r2C1s2 protease tetramer. Human C1QC mutations cause hereditary C1q deficiency with severe early-onset systemic lupus erythematosus and recurrent encapsulated bacterial infection, a phenotype mapping directly onto complement-dependent handling of nucleosomal debris. Deletion in mouse removes assembled C1q rather than a single chain, so the null is a clean loss-of-function model, and because the three chains cannot compensate for one another, no compound genetics is needed. Point knockins of patient missense alleles are the right choice for studying assembly and secretion defects, while conditional nulls address whether locally synthesized C1q from microglia or tissue macrophages drives a given pathology.',
  C3:
    'C3, ortholog of human C3, encodes the pivotal complement component whose proteolytic activation by either the classical and lectin pathway C4b2a convertase or the alternative pathway C3bBb releases the C3a anaphylatoxin and exposes a reactive thioester in the C3b thioester-containing domain that covalently tags surfaces. Deposited C3b seeds further convertase assembly for amplification, is degraded by factor I to iC3b and C3dg for CR3, CR4, and CR2 dependent phagocytosis and B cell priming, and feeds C5 convertase formation. Loss produces pyogenic infection susceptibility, impaired immune complex clearance, and blunted antibody responses, while dysregulated turnover underlies C3 glomerulopathy and paroxysmal nocturnal hemoglobinuria pathology. No paralog compensates, making the null definitive. Humanization is the design of record for compstatin family peptides and pegcetacoplan, which bind human C3 and do not engage the mouse protein, whereas hepatocyte-conditional deletion resolves liver-derived versus local myeloid C3 contributions.',
  C3ar1:
    'The mouse C3ar1 locus encodes C3aR, ortholog of human C3AR1 and a class A rhodopsin-like G protein coupled receptor with an unusually large second extracellular loop that binds the carboxy-terminal arginine of the C3a anaphylatoxin. Signaling proceeds mainly through Galphai to inhibit adenylate cyclase and through Gbetagamma to PI3Kgamma and phospholipase Cbeta, mobilizing calcium and driving chemotaxis, degranulation, and inflammasome priming in mast cells, neutrophils, monocytes, and microglia, with additional roles in adipocyte and neural progenitor biology. Loss of C3aR protects in models of asthma, ischemia reperfusion injury, and complement-driven neuroinflammation while sparing opsonization, which makes it attractive for separating anaphylatoxin signaling from C3b effector function. Because C5ar1 responds to a related ligand and overlaps in myeloid distribution, single-receptor deletion can be buffered and compound C3ar1 C5ar1 alleles are frequently required. Conditional flox designs with myeloid or microglial Cre suit cell-of-action questions; humanization suits antagonist pharmacology.',
  C4a:
    'Mouse C4a maps to the murine H2 complement region and is the annotated counterpart of human C4A, but the murine gene corresponds to Slp, the sex-limited protein, an androgen-dependent duplicate that is secreted yet hemolytically inactive because it fails to build a functional C4b2a convertase; functional murine C4 activity resides in C4b instead. This asymmetry matters, since human C4A and C4B differ at the isotypic site controlling covalent transfer, with C4A biased toward amide bond formation on amino groups of immune complexes and C4B toward ester linkage on carbohydrate surfaces, and human C4A copy number loss is a strong lupus risk factor. Consequently a mouse C4a null is unlikely to phenocopy human C4A deficiency, and locus humanization or human C4A transgene addition on a C4-deficient background is the honest design. Reserve conditional alleles for tissue-source questions and pair any allele with immune complex clearance and autoantibody endpoints.',
  C4b:
    'Mouse C4b, despite its name, encodes the functionally dominant murine complement C4 and is the practical ortholog of human C4B. The secreted alpha, beta, and gamma chain protein is cleaved by C1s or MASP2 to release C4a and expose a thioester in C4b that binds hydroxyl or amino groups on target surfaces, then recruits C2 for cleavage into the C4b2a classical and lectin pathway C3 convertase, with regulation by C4BP, factor I, CR1, and CD46. Human C4B favors ester linkage to carbohydrate, and copy number variation across C4A and C4B, together with endogenous retroviral insertion length variants, drives schizophrenia and lupus association through complement-dependent synaptic pruning. Because murine C4a (Slp) is hemolytically inactive, C4b deletion effectively creates whole classical pathway C4 deficiency without compound alleles. Use the null for immune complex and pruning phenotypes, and humanized knockins when isotype-specific covalent chemistry or copy number dosage is the actual variable.',
  C5:
    'C5, historically Hc in mouse and ortholog of human C5, encodes the terminal pathway substrate cleaved by C5 convertases into the potent C5a anaphylatoxin and C5b, which nucleates C6, C7, C8, and polymerized C9 into the membrane attack complex. Unlike C3, C5 carries no thioester and acts through conformational recruitment, so blocking it preserves opsonization while eliminating lytic and C5a-driven inflammation, the therapeutic logic behind eculizumab and ravulizumab. Strain background is a genuine design constraint: DBA/2, A/J, and several related lines carry a two base pair deletion producing natural C5 deficiency, so congenic status must be confirmed before any complement phenotype is interpreted. Species restriction is equally decisive, since eculizumab engages human C5 and is sensitive to the Arg885 polymorphism, making epitope-matched humanization the required allele for antibody pharmacology. Hepatocyte-restricted conditional deletion, by contrast, resolves whether circulating liver-derived or locally produced C5 drives a given tissue injury.',
  C5ar1:
    'C5ar1 encodes C5aR1 (CD88), the mouse ortholog of human C5AR1, a Galphai-coupled seven-transmembrane receptor that engages the carboxy-terminal region and core of C5a through a two-site mechanism involving its acidic N-terminal segment and transmembrane pocket, then signals via PI3Kgamma, PLCbeta, and beta-arrestin to drive neutrophil chemotaxis, oxidative burst, granule release, tissue factor induction, and NLRP3 priming. Output is shaped by C5a desArg generated by carboxypeptidase N and by the decoy-like second receptor C5ar2, which lacks G protein coupling but modulates beta-arrestin dependent signaling; that pairing means C5ar1 deletion alone may not fully reproduce pharmacological blockade. Nulls are viable and protected in sepsis, ANCA vasculitis, and ischemia reperfusion models, the same axis targeted by avacopan. Choose conditional alleles with myeloid or endothelial Cre when cell of action is the question, and humanized knockins when antagonist potency or species-restricted binding governs the readout.',
  C9orf72:
    'Faithful ALS and frontotemporal dementia modeling begins at C9orf72 (historically annotated 3110043O21Rik), the mouse ortholog of human C9ORF72, which encodes a DENN-domain guanine nucleotide exchange factor that partners stoichiometrically with SMCR8 and WDR41 to govern RAB GTPase cycling, ULK1-dependent autophagy initiation, and lysosomal trafficking. Disease arises from a GGGGCC hexanucleotide repeat expansion in intron 1 acting through three intertwined routes: transcriptional silencing and haploinsufficiency, sequestration of RNA-binding proteins into sense and antisense foci, and repeat-associated non-AUG translation into dipeptide repeat species including poly(GA), poly(GR), and poly(PR). Allele choice therefore encodes the hypothesis. Germline or conditional nulls interrogate loss of function, which in mice yields myeloid and microglial lysosomal defects plus autoimmunity rather than frank motor neuron death, repeat-expansion knockin or BAC alleles test gain of function, and humanized locus replacement enables antisense oligonucleotide and RNA-targeting campaigns. Match allele class to endpoint, pairing neuronal or myeloid Cre drivers with cell-type-restricted questions.',
  Cacna1a:
    'Cacna1a is the mouse ortholog of human CACNA1A and encodes CaV2.1, the pore-forming α1A subunit of presynaptic P/Q-type calcium channels, built from four homologous repeats each contributing an S4 voltage sensor and a P-loop to the selectivity filter, with a cytoplasmic synprint motif that tethers syntaxin-1A and SNAP-25 for tight coupling of calcium entry to vesicle fusion. Three distinct human mutation classes map to different alleles: truncating loss of function causes episodic ataxia type 2, gain-of-function substitutions such as R192Q and S218L cause familial hemiplegic migraine type 1, and a C-terminal polyglutamine expansion causes spinocerebellar ataxia type 6. Constitutive nulls develop severe ataxia and dystonia and die around weaning, so cerebellar conditional deletion using Pcp2-Cre or granule cell drivers is required for adult physiology. CaV2.2 partially substitutes at some central terminals, so record paired-pulse and calcium imaging readouts rather than relying on transmitter release amplitude alone.',
  Cacna1b:
    'Encoding CaV2.2, the α1B pore subunit of N-type calcium channels, Cacna1b is the mouse ortholog of human CACNA1B and dominates transmitter release at nociceptive primary afferent terminals and sympathetic neurons, where it is inhibited voltage-dependently by Gβγ binding to the I-II linker downstream of opioid and GABA-B receptors and trafficked in complex with CRMP2 and collapsin response signaling. Mutually exclusive splicing of exon 37a versus 37b creates a dorsal root ganglion variant with enhanced tonic G protein modulation, and the channel is the target of the conopeptide ziconotide. Because global nulls are viable but hypoalgesic in neuropathic and inflammatory assays, the informative fork is a conditional null crossed to Advillin-Cre or Scn10a-Cre to establish afferent-specific contribution versus humanization of the outer pore and drug-binding regions for species-selective blocker pharmacology. CaV2.1 upregulates at central synapses after deletion, so include compensation controls when interpreting spinal transmission endpoints.',
  Cacna1c:
    'Cacna1c encodes CaV1.2, mouse ortholog of human CACNA1C and the dominant L-type α1C subunit in cardiomyocytes, smooth muscle, and neuronal somatodendritic membranes, where calmodulin bound to the C-terminal IQ motif mediates calcium-dependent inactivation and facilitation, and the channel drives excitation-transcription coupling through CaMKII and CREB. Its dihydropyridine and phenylalkylamine sites make it the principal antihypertensive target, and de novo G406R substitutions in mutually exclusive exon 8 or 8A impair voltage-dependent inactivation to cause Timothy syndrome, while common intronic variants are among the strongest psychiatric GWAS signals. Constitutive deletion is embryonic lethal by midgestation from cardiovascular failure, so conditional null alleles are obligatory and should be paired with tissue-restricted drivers such as Camk2a-Cre for forebrain behavior or Myh6-Cre for cardiac phenotyping, whereas a Timothy knockin models gain of function. CaV1.3 partially substitutes in pacemaker and neuronal tissue and must be measured directly.',
  Cacna1d:
    'Cacna1d, ortholog of human CACNA1D, encodes CaV1.3, an L-type α1D channel distinguished from CaV1.2 by activation at markedly more negative potentials and by weak dihydropyridine sensitivity, properties that make it the pacemaking current in sinoatrial and adrenal chromaffin cells and the sole channel gating tonic glutamate release at cochlear inner hair cell ribbon synapses. Extensive C-terminal alternative splicing and a modulatory C-terminal domain tune calcium-dependent inactivation, and human alleles split cleanly by direction: recessive loss of function produces sinoatrial node dysfunction with deafness, whereas somatic and germline gain-of-function substitutions such as A749G cause aldosterone-producing adenomas and primary aldosteronism with seizures and neurologic disability. Constitutive nulls are viable but deaf and bradycardic, giving a tractable model, while a gain-of-function knockin isolates the aldosterone and neurodevelopmental arm. CaV1.2 compensates in several tissues, so quantify Cacna1c transcript and current before attributing residual L-type conductance.',
  Cacna1e:
    'CaV2.3, encoded by Cacna1e as the ortholog of human CACNA1E, carries the pharmacologically resistant R-type calcium current defined by insensitivity to dihydropyridines and conotoxins and by partial block with the tarantula peptide SNX-482. It localizes to dendrites and somata rather than to classical active zones, where it supports calcium spikes, afterdepolarizations and burst firing in thalamic and hippocampal neurons and contributes to insulin granule exocytosis. Recurrent de novo substitutions clustering in the S4 to S5 linkers and pore-lining segments, notably G352R and A702T, slow inactivation and cause developmental and epileptic encephalopathy with congenital contractures and macrocephaly, a clear gain-of-function mechanism. Constitutive nulls are viable with altered nociception, absence-like rhythms and modified seizure thresholds, so a conditional null answers circuit-level necessity while a patient knockin is the design matched to encephalopathy endpoints. Pair either with EEG and interneuron-specific Cre drivers rather than gross behavior alone.',
  Cacnb1:
    'Cacnb1 encodes the CaVβ1 auxiliary subunit, ortholog of human CACNB1, a cytosolic MAGUK-like protein whose SH3 and guanylate kinase modules clamp the α-interaction domain in the I-II linker of the pore subunit, masking ER retention signals to drive surface trafficking while shifting activation voltage and slowing inactivation. The β1a splice variant is the skeletal muscle isoform that is structurally required for organizing CaV1.1 into the tetrad arrays that mechanically couple the transverse tubule to RyR1, whereas β1b and β1d serve neuronal and cardiac roles. Constitutive nulls die at birth from failed excitation-contraction coupling and asphyxia, so a conditional null with Myf5-Cre, Hsa-Cre or a neuronal driver is required for postnatal study, and a knockin disrupting the α-interaction domain interface separates trafficking from gating contributions. Cacnb2, Cacnb3 and Cacnb4 substitute promiscuously in brain, so isoform-swap or compound alleles are needed for interpretable central phenotypes.',
  Cacnb2:
    'The CaVβ2 subunit encoded by Cacnb2, ortholog of human CACNB2, is the principal β partner of CaV1.2 in cardiomyocytes and a widely expressed neuronal subunit, using its guanylate kinase domain to bind the α-interaction domain with nanomolar affinity and thereby increase channel open probability and surface density. Its five N-terminal splice variants determine behavior, with the palmitoylated β2a variant anchoring to the membrane and markedly slowing voltage-dependent inactivation, a difference that dominates current kinetics. Human loss-of-function and missense variants segregate with Brugada syndrome and short QT phenotypes, and the locus is a replicated GWAS signal for schizophrenia and bipolar disorder. Constitutive deletion is embryonic lethal around midgestation from cardiac failure, so conditional nulls are mandatory, with cardiomyocyte-restricted or forebrain Cre drivers selected according to endpoint. Because Cacnb1, Cacnb3 and Cacnb4 exchange freely on the same α1 subunits, verify residual β occupancy before attributing a modest phenotype to β2.',
  Cacnb3:
    'Cacnb3, the mouse ortholog of human CACNB3, encodes CaVβ3, a broadly expressed cytosolic auxiliary subunit that binds the I-II linker α-interaction domain through its guanylate kinase module, promotes forward trafficking of CaV1 and CaV2 pore subunits, and produces relatively rapid voltage-dependent inactivation compared with palmitoylated β2a. Beyond channel work, β3 restrains inositol trisphosphate receptor calcium release and interacts with signaling scaffolds, giving it functions partly separable from the channelosome. Constitutive nulls are viable and fertile with reduced N-type current in sympathetic neurons, altered baroreflex and insulin secretion, and mild changes in anxiety and nociception, so lethality is not a design constraint and a conditional null is useful chiefly for dissecting cell-autonomous contributions in defined circuits. The severe caveat is redundancy: Cacnb1, Cacnb2 and Cacnb4 occupy the same binding site and increase in expression after deletion, so pair a β3 allele with compound conditionals and direct current measurements rather than behavioral endpoints alone.',
  Cacnb4:
    'CaVβ4, encoded by Cacnb4 as the ortholog of human CACNB4, is the cerebellum-enriched β subunit that partners CaV2.1 at parallel and climbing fiber terminals, engaging the α-interaction domain through its guanylate kinase domain to control surface expression and inactivation kinetics; a short nuclear isoform additionally binds chromatin regulators and the phosphatase regulatory subunit B56δ, giving the gene a transcriptional arm independent of conductance. The spontaneous lethargic allele, a splice mutation that abolishes α1 binding, causes ataxia, absence-like spike-wave discharges and lymphocyte defects, and human variants segregate with juvenile myoclonic epilepsy and episodic ataxia. Because homozygous loss produces severe ataxia and seizures with poor postweaning survival, a conditional null crossed to Pcp2-Cre or a granule cell driver is the practical route to adult cerebellar physiology, while a patient missense knockin separates trafficking from nuclear signaling. Cacnb1, Cacnb2 and Cacnb3 partially substitute, so quantify β subunit stoichiometry directly.',
  Cacng1:
    'Cacng1 encodes γ-1, ortholog of human CACNG1 and the founding member of the calcium channel gamma family, a four-transmembrane skeletal muscle protein that assembles with the CaV1.1 complex at the transverse tubule and is the only family member with well-documented direct modulation of a calcium channel, shifting steady-state inactivation of the L-type current to more negative potentials and thereby limiting calcium entry during repetitive stimulation. Unlike the transmembrane AMPA receptor regulatory proteins encoded by its paralogs, γ-1 does not traffic glutamate receptors, so it should not be treated as a synaptic scaffold. Constitutive nulls are viable and fertile with increased L-type current density and altered calcium homeostasis but essentially normal force generation, indicating a modulatory rather than structural role. A conditional null with Hsa-Cre or Myf5-Cre isolates muscle-autonomous effects on fatigue and calcium handling, whereas a gating-site knockin tests inactivation directly; distinguish γ-1 from Cacng6 in any interpretation.',
  Cacng2:
    'Stargazin, encoded by Cacng2 as the ortholog of human CACNG2, is the prototypical type Ia transmembrane AMPA receptor regulatory protein, a four-pass claudin-like subunit whose first extracellular loop slows deactivation and desensitization and relieves polyamine block of AMPA receptors, while its cytoplasmic C-terminal TTPV motif binds PSD-95 PDZ domains to anchor receptors at the postsynaptic density; PKA and CaMKII phosphorylation of the adjacent serine-rich stretch gates that interaction during long-term potentiation. The spontaneous stargazer mutation, a transposon insertion, eliminates cerebellar granule cell AMPA currents and produces ataxia, head tossing and absence seizures with spike-wave discharges. A conditional null crossed to Gabra6-Cre or a forebrain driver separates cerebellar from cortical contributions, and a C-terminal phosphomimetic or PDZ-binding knockin isolates trafficking from gating. Cacng3, Cacng4 and Cacng8 are genuine functional substitutes in forebrain, so compound alleles are usually required outside the cerebellum.',
  Cacng3:
    'Cacng3 encodes the type Ia transmembrane AMPA receptor regulatory protein γ-3, ortholog of human CACNG3, a stargazin-like four-transmembrane subunit expressed most strongly in neocortex and hippocampus, where it binds the AMPA receptor extracellular ligand-binding domain to slow deactivation and desensitization, promotes forward trafficking from the endoplasmic reticulum, and uses its C-terminal PDZ ligand to engage PSD-95 family scaffolds at the postsynaptic density. Human variants at the locus have been reported in childhood absence epilepsy and obesity association studies, though the causal weight remains modest compared with CACNG2 and CACNG8. Constitutive nulls are viable with essentially normal gross synaptic transmission, which is the central design problem: γ-2, γ-4 and γ-8 occupy overlapping receptor populations and mask single-gene loss almost completely. Plan compound conditional genetics with Cacng2 and Cacng8 from the outset, use surface biotinylation and glutamate uncaging rather than field potentials, and reserve humanization for TARP-selective modulator pharmacology.',
  Cacng4:
    'Among the type Ib transmembrane AMPA receptor regulatory proteins, Cacng4 encodes γ-4, ortholog of human CACNG4, distinguished from stargazin by a longer cytoplasmic C-terminus and by conferring strong resensitization on AMPA receptors, a kinetic signature that sustains current during prolonged glutamate exposure. Expression peaks in striatum, early postnatal cortex and hypothalamus, where γ-4 governs receptor surface delivery and PSD-95 mediated anchoring before γ-8 and γ-2 become dominant, giving it a developmentally restricted window that shapes any phenotyping schedule. Constitutive nulls are viable with subtle changes in AMPA receptor kinetics and striatal transmission, so the informative allele is usually a conditional null crossed to Drd1-Cre or Adora2a-Cre to assign contributions to direct and indirect pathway neurons, or a C-terminal truncation knockin that removes scaffold binding while preserving gating. Because γ-2, γ-3 and γ-8 overlap in the same neurons, compound deletion and direct kinetic recordings are needed for interpretable results.',
  Cacng5:
    'Cacng5 encodes γ-5, ortholog of human CACNG5 and a type II member of the gamma family whose behavior departs sharply from classical transmembrane AMPA receptor regulatory proteins: it selectively modulates GluA2-lacking, calcium-permeable AMPA receptors, markedly slows deactivation and confers resensitization, yet it does not promote surface trafficking of GluA2-containing receptors the way stargazin does. Expression is enriched in Bergmann glia and selected forebrain populations, and its short cytoplasmic tail engages PDZ scaffolds weakly, so its influence is largely on channel kinetics rather than synaptic anchoring. The locus sits within schizophrenia and bipolar disorder association intervals on chromosome 17q24, though causal evidence remains genetic rather than mechanistic. Constitutive nulls show no gross neurological deficit, so pair a conditional null with calcium-permeable AMPA receptor readouts such as rectification index and philanthotoxin sensitivity in defined cell types, and expect γ-2, γ-4 and γ-7 to obscure loss unless deleted together.',
  Cacng6:
    'Unlike its transmembrane AMPA receptor regulatory protein paralogs, Cacng6, ortholog of human CACNG6, encodes γ-6, a four-pass subunit that does not modulate glutamate receptors but instead inhibits low-voltage-activated T-type calcium current carried by CaV3.1, acting through a GxxxA motif in its first transmembrane segment that mediates helix packing against the channel and suppresses current density. It is expressed in heart, sinoatrial node and selected neuronal populations, placing it in pacemaking and burst-firing contexts rather than at glutamatergic synapses, and the human gene sits in the chromosome 19q13 gamma cluster with CACNG7 and CACNG8. Because loss of γ-6 elevates rather than removes a current, a constitutive or conditional null is the appropriate design for testing T-type disinhibition in nodal or thalamic circuits, while a GxxxA-disrupting knockin isolates the interaction interface from any trafficking role. Verify CaV3.1 and CaV3.2 expression directly, and do not assume AMPA receptor phenotypes.',
  Cacng7:
    'Cacng7 encodes γ-7, ortholog of human CACNG7 and a type II transmembrane AMPA receptor regulatory protein that promotes surface delivery and synaptic incorporation of AMPA receptors while slowing deactivation, with particularly strong expression in cerebellar Purkinje cells, brainstem and selected forebrain neurons. In contrast to stargazin, γ-7 shows preferential association with GluA1 and GluA2 assemblies and has been reported to stabilize receptor pools by protecting them from degradation as well as by direct kinetic modulation, and its short C-terminal PDZ ligand couples it to PSD-95 family scaffolds. The gene lies in the chromosome 19q13 gamma cluster with CACNG6 and CACNG8. Because constitutive deletion produces only modest changes in transmission, use a conditional null with Pcp2-Cre for Purkinje cell autonomy and read out miniature excitatory postsynaptic current amplitude and receptor surface fraction rather than behavior. Expect γ-2 and γ-5 to substitute in the same neurons, so compound alleles are frequently necessary.',
  Cacng8:
    'Hippocampal AMPA receptor content depends heavily on γ-8, encoded by Cacng8 as the ortholog of human CACNG8, a type Ia transmembrane AMPA receptor regulatory protein with an extended cytoplasmic C-terminus that binds PSD-95 through a PDZ ligand and slows receptor deactivation and desensitization; γ-8 deletion reduces hippocampal GluA1 and extrasynaptic receptor pools more than any other single TARP, impairing long-term potentiation. Its distinctive pharmacology is the key design driver: negative allosteric modulators such as JNJ-55511118 and LY3130481 act selectively on γ-8-associated receptors and are being pursued as anticonvulsants that spare cerebellar and brainstem transmission, and their potency differs between species. Consequently, humanization of the γ-8 interaction surface is the allele matched to translational pharmacology, whereas a conditional null with Camk2a-Cre or Grik4-Cre assigns regional necessity and a C-terminal truncation isolates scaffolding from gating. Cacng2, Cacng3 and Cacng4 partially compensate outside hippocampus, so restrict inference accordingly.',
  Casp1:
    'Casp1, ortholog of human CASP1, encodes the prototypic inflammatory caspase, a CARD-containing zymogen recruited to ASC filaments within NLRP3, NLRC4, AIM2, or pyrin inflammasomes, where proximity-induced dimerization and autoprocessing generate p20 and p10 catalytic species that cleave pro-IL-1beta and pro-IL-18 to mature cytokines and cut gasdermin D to liberate its pore-forming N-terminal fragment, causing pyroptosis and cytokine release. A crucial technical caveat is that most legacy Casp1 null lines derive from 129 embryonic stem cells and carry a passenger loss-of-function Casp11 (human CASP4) allele, so apparent Casp1 phenotypes may reflect combined canonical and noncanonical inflammasome deficiency unless a Casp11-intact or independently generated conditional allele is used. Catalytically dead C284A knockins separate scaffolding from proteolysis, conditional flox alleles with LysM or Cx3cr1 Cre assign the responsible myeloid compartment, and humanization serves inhibitor programs where active site chemistry differs between species.',
  Casp3:
    'Casp3 is the mouse ortholog of human CASP3 and encodes the principal executioner caspase, a short-prodomain zymogen activated by caspase-9 within the APAF1 apoptosome or by caspase-8 downstream of death receptors, then cleaving several hundred substrates including PARP1, the ICAD inhibitor of DFF40 whose removal unleashes internucleosomal DNA fragmentation, gelsolin, ROCK1 for membrane blebbing, and pannexin-1 for find-me signal release. Beyond death it mediates non-apoptotic events such as myoblast and osteoblast differentiation and dendritic spine pruning. Phenotype is strongly background dependent: on 129 the null shows exencephaly and perinatal lethality with excess neural progenitors, whereas on C57BL/6 mice are largely viable, so congenic state must be reported. Casp7 provides partial redundancy for a subset of substrates and compound Casp3 Casp7 alleles are needed for complete blockade. Use conditional flox designs with tissue Cre for lineage-restricted death questions, and catalytic mutant knockins when scaffold versus protease function is at issue.',
  Casp8:
    'As the apical death receptor caspase, mouse Casp8 is the ortholog of human CASP8 and carries tandem death effector domains that dock onto FADD within FAS, TRAIL receptor, or TNFR1 complex II, where dimerization and cleavage at Asp387 yield an active protease that processes BID and caspases 3 and 7. Equally important is its non-apoptotic role: caspase-8 cleaves RIPK1 and CYLD to restrain RIPK3 and MLKL dependent necroptosis, and it participates in FADD dependent inflammasome regulation. Germline deletion is embryonic lethal around E10.5 with yolk sac vascular failure, and that lethality is rescued by concurrent Ripk3 or Mlkl loss, the standard genetic proof that unrestrained necroptosis rather than lost apoptosis kills the embryo. Conditional flox alleles with epithelial or myeloid Cre are therefore mandatory for adult work, catalytically inactive C362A knockins isolate scaffolding, and human CASP8 knockins support study of patient variants causing lymphoproliferation and immunodeficiency.',
  Casp9:
    'Casp9, ortholog of human CASP9, encodes the initiator caspase of the intrinsic pathway, whose CARD docks onto the CARD ring of APAF1 after cytochrome c and dATP driven apoptosome assembly, converting the monomeric zymogen into a holoenzyme that cleaves and activates caspases 3 and 7. Activity is set by dimerization rather than proteolysis alone and is restrained by XIAP BIR3 binding and by inhibitory phosphorylation from AKT and ERK, so apoptosome stoichiometry and IAP tone both shape the threshold. Germline nulls show markedly reduced neural progenitor apoptosis, exencephaly, and perinatal lethality on sensitive backgrounds, mirroring Apaf1 and Casp3 deficiency and placing the axis firmly in brain development. No other caspase substitutes for apoptosome coupling, so redundancy is minimal. Conditional flox alleles with lineage-restricted Cre are the practical route past lethality, while catalytically dead knockins or CARD mutants answer whether a phenotype requires proteolysis or merely platform occupancy.',
  Cbfb:
    'Cbfb, ortholog of human CBFB, encodes core binding factor beta, a non-DNA-binding subunit that heterodimerizes with the Runt domain of RUNX1, RUNX2, or RUNX3, allosterically increasing DNA affinity and protecting those factors from ubiquitin-mediated turnover. Loss of the heterodimer collapses definitive hematopoietic emergence from hemogenic endothelium, and homozygous deletion is embryonic lethal near E12.5 with central nervous system hemorrhage, so viable analysis requires conditional alleles or knockin rescue strategies. In leukemia the dominant lesion is the inversion 16 CBFB-MYH11 fusion, whose smooth muscle myosin tail sequesters RUNX1 into transcriptionally inert complexes, a dominant-negative mechanism no simple null reproduces. Model design therefore forks cleanly between conditional deletion for dosage and lineage specification questions and a Cre-inducible fusion knockin for core binding factor leukemia. Because all three RUNX paralogs share this beta subunit, Cbfb loss removes their activities simultaneously, so interpret compound phenotypes with that breadth in mind.',
  Ccnd1:
    'Ccnd1, the mouse ortholog of human CCND1, encodes cyclin D1, the mitogen-induced regulatory subunit that binds CDK4 and CDK6, is assembled and stabilized by p21 and p27, and directs partial RB phosphorylation to relieve E2F repression at the restriction point. Its abundance is controlled by threonine 286 phosphorylation, nuclear export and ubiquitin mediated turnover, and cyclin D1 also acts kinase-independently as a transcriptional cofactor for estrogen receptor and as a chromatin recruited factor at DNA damage sites. Overexpression from the t(11;14) translocation defines mantle cell lymphoma, and 11q13 amplification marks breast and squamous carcinomas. Null mice are viable with retinal hypoplasia and defective pregnancy-associated mammary proliferation, so constitutive alleles are usable, though Ccnd2 and Ccnd3 substitute extensively and mask requirement in most lineages. Use a T286A stabilized knockin to test degron control, a knockin of a CDK-binding deficient cyclin to separate kinase from transcriptional roles, and compound D-cyclin alleles for CDK4/6 inhibitor response studies.',
  Ccne1:
    'Ccne1, mouse ortholog of human CCNE1, encodes cyclin E1, the late G1 partner of CDK2 whose activity peaks at the G1/S transition and drives phosphorylation of RB, p27, NPAT for histone gene transcription, and CDC6 and components of the prereplication complex to license origin firing and centrosome duplication. Cyclin E1 is destroyed by FBXW7 mediated ubiquitination after CDK2 autophosphorylation at threonine 380, and loss of that degron or 19q12 amplification produces constitutive S phase entry with rereplication, replication stress and chromosomal instability, a state now targeted therapeutically by PKMYT1 and WEE1 inhibitors in ovarian and endometrial cancer. Single nulls are viable, but Ccne1 and Ccne2 double nulls die in midgestation with failed trophoblast endoreplication, so redundancy is genuine and compound alleles are needed for requirement questions. Deploy conditional overexpression or degron-resistant T380A knockins for replication stress and synthetic lethality studies, and conditional nulls for endoreduplication and hepatocyte polyploidy endpoints.',
  Cd14:
    'Cd14 encodes the mouse ortholog of human CD14, a leucine-rich repeat horseshoe glycoprotein present both as a GPI-anchored surface receptor on monocytes, macrophages, and neutrophils and as a soluble plasma form generated by shedding or direct secretion. Its function is ligand delivery rather than signaling: CD14 accepts lipopolysaccharide extracted from bacterial membranes by LBP and loads lipid A into the TLR4 and MD-2 (Ly96) complex, enabling both MyD88 dependent surface responses and CD14 dependent endocytosis that licenses TRIF and type I interferon output, and it similarly assists TLR2 lipopeptide recognition and nucleic acid sensing TLR trafficking. Nulls are viable and profoundly hyporesponsive to low-dose LPS while retaining responses to high-dose stimulation, a dose-dependent phenotype that must be built into endotoxemia study design. Humanization is correct for anti-CD14 antibody and sepsis therapeutic programs, whereas conditional deletion with myeloid or hepatocyte Cre partitions membrane and soluble CD14 contributions.',
  Cd163:
    'Cd163 is the mouse ortholog of human CD163, encoding a type I transmembrane scavenger receptor built from nine class B scavenger receptor cysteine-rich domains that mediates calcium-dependent endocytosis of haptoglobin-hemoglobin complexes, delivering heme to macrophage lysosomes where HMOX1 degradation yields biliverdin, carbon monoxide, and iron for ferroportin export. Expression is restricted to the monocyte and macrophage lineage and is driven up by IL-10, glucocorticoids, and heme itself, making it a canonical marker of alternatively activated and tumor-associated macrophages, while ADAM17 shedding releases soluble CD163 that serves as a clinical macrophage activation biomarker. Loss impairs hemoglobin clearance and iron recycling and alters macrophage polarization in tumor and atherosclerosis models. Related SRCR proteins including CD163L1, CD5L, and CD6 do not substitute for haptoglobin-hemoglobin uptake. Use conditional alleles with LysM or Cx3cr1 Cre to interrogate tissue macrophage subsets, and humanization when CD163-directed antibody drug conjugates or imaging agents are the endpoint.',
  Cd19:
    'Cd19, ortholog of human CD19, encodes a B lineage immunoglobulin superfamily coreceptor with two extracellular Ig-like domains that partners with Cr2, Cd81 and Cd225 to lower the B cell receptor activation threshold, recruiting PI3K to phosphorylated cytoplasmic tyrosines and amplifying Btk and Akt signaling. Its dominant translational role is as the antigen for CD19-directed CAR T cells and for blinatumomab, and because those biologics recognize human epitopes that murine Cd19 does not present, an epitope-matched humanized CD19 knockin is the only credible platform for efficacy, B cell aplasia and cytokine release studies. A conventional null instead answers a developmental question, yielding reduced marginal zone and B1 populations with blunted humoral responses. Investigators should also note that Cd19-Cre is a knockin driver, so the Cre allele itself is a functional null and heterozygosity must be controlled. Pair alleles with flow cytometric B cell subset analysis, antigen-specific titers, and CAR persistence readouts.',
  Cd274:
    'Cd274 encodes PD-L1 (B7-H1), the mouse ortholog of human CD274, a type I membrane protein with IgV and IgC2 domains whose IgV face engages PD-1 (Pdcd1) to recruit SHP-2 to the PD-1 ITSM, dephosphorylating CD28 and proximal TCR components and thereby raising the activation threshold of effector T cells. Surface abundance is controlled transcriptionally by IFN-gamma through JAK and STAT1 to IRF1, by MYC and NF-kappaB, by structural variants of the 3 prime untranslated region, and post-translationally by CMTM6 mediated recycling versus glycosylation-dependent degradation; PD-L1 also binds CD80 in cis and exists in exosomal and soluble forms. Nulls are viable but show exaggerated T cell responses and autoimmune susceptibility. Because atezolizumab and durvalumab do not cross-react, epitope-matched humanization is the decisive allele for checkpoint pharmacology and biomarker work, whereas conditional deletion with tumor cell, dendritic cell, or endothelial Cre resolves which compartment enforces suppression.',
  Cd28:
    'Mouse Cd28, ortholog of human CD28, encodes the dominant costimulatory receptor of naive T cells and forms a disulfide-linked homodimer whose single IgV domain uses the MYPPPY motif to bind CD80 and CD86. Ligation clusters CD28 in the immunological synapse where its cytoplasmic YMNM motif recruits PI3K p85 and GRB2 while a proline-rich PYAP motif binds LCK and ITK, amplifying PLCgamma1, NF-kappaB, and NFAT signaling to drive IL-2 transcription, BCL2L1 induction, glucose uptake, and clonal expansion, and to sustain regulatory T cell homeostasis. Nulls are viable with impaired T-dependent antibody responses, reduced germinal centers, and Treg deficits. CTLA4 competes for the same ligands but antagonizes rather than substitutes, so no true redundancy exists. Humanized CD28 knockins are essential for CD28 bispecific and superagonist safety work given the TGN1412 precedent, while conditional alleles with Cd4-Cre or Foxp3-Cre separate conventional from regulatory T cell requirements.',
  Cd80:
    'Cd80 encodes B7-1, the mouse ortholog of human CD80, a type I membrane glycoprotein with IgV and IgC domains expressed on activated dendritic cells, macrophages, and B cells that delivers costimulation by binding CD28 and is captured with higher affinity and slower off-rate by CTLA4. CD80 dimerizes at the cell surface, which favors CTLA4 bivalent engagement and transendocytic ligand removal, and it additionally forms a cis heterodimer with PD-L1 that sterically blocks PD-1 binding while preserving CD28 engagement, an interaction that reframes how checkpoint blockade shifts costimulatory balance. Nulls have mild phenotypes because Cd86 covers most priming functions with faster kinetics and broader constitutive expression, so Cd80 Cd86 double deficiency is generally required to abolish CD28 costimulation. Reach for conditional alleles with dendritic cell or B cell Cre when the presenting compartment is the question, and humanization when abatacept or belatacept binding and CD80 PD-L1 cis biology are the readout.',
  Cd86:
    'Mouse Cd86 encodes B7-2, ortholog of human CD86, and is the costimulatory ligand dominating early T cell priming because it sits constitutively at low levels on resting antigen presenting cells and is rapidly upregulated after TLR or CD40 signaling, well before CD80 accumulates. Its IgV domain engages CD28 as a monomer with lower affinity but faster association than CD80, and it is likewise a preferred target for CTLA4 mediated transendocytosis, tying it directly to peripheral tolerance. CD86 also signals reciprocally into the presenting cell, influencing IL-6 production and immunoglobulin class switching in B cells. Because Cd80 provides substantial functional overlap, single nulls show only partial defects in germinal center formation and Th2 responses, and compound Cd80 Cd86 alleles are needed for clean loss of CD28 costimulation. Conditional flox designs with Cd19-Cre or Itgax-Cre localize the relevant presenter, while humanized knockins support CTLA4-Ig and anti-CD86 pharmacology.',
  Cdh5:
    'Vascular endothelial cadherin is encoded by Cdh5, ortholog of human CDH5, a classical cadherin restricted to endothelium whose five extracellular repeats mediate calcium-dependent homophilic adhesion at adherens junctions while the cytoplasmic tail binds p120 catenin to block internalization and beta-catenin to link alpha-catenin and the actin cytoskeleton. VEGF-driven Src and Vav2 phosphorylation of specific tail tyrosines triggers junction disassembly and permeability, making this locus the molecular control point for vascular leak. Germline deletion is lethal near midgestation from failed vascular remodeling rather than failed vasculogenesis, so conditional alleles are mandatory, and phosphosite knockins that lock or mimic tyrosine modification separate adhesion from signaling far better than a null. Because Cdh5-CreERT2 is the field standard pan-endothelial driver, confirm that your floxed allele and driver are not competing at the same locus. Assess Evans blue extravasation, junction morphology by immunofluorescence, and retinal angiogenesis.',
  Cdk2:
    'Cdk2, the mouse ortholog of human CDK2, encodes the cyclin dependent kinase that partners cyclin E in late G1 and cyclin A in S phase, requiring CAK phosphorylation of threonine 160 in the activation loop and inhibition by p21 and p27, and phosphorylating RB, p27 itself, CDC6, NPAT and nucleophosmin to coordinate origin licensing, histone synthesis and centrosome duplication. Loss of function is surprisingly tolerated because CDK1 binds cyclin E and cyclin A and executes S phase entry, so null mice are viable and only sterile from meiotic prophase failure at the telomere attachment step, a phenotype that makes this a clean reproductive biology model. That redundancy sets the design logic: conditional nulls are best for germ cell and CCNE1 amplified synthetic lethality studies, whereas analog-sensitive gatekeeper knockins allow acute chemical genetic inhibition that outperforms genetic deletion. Combine with Ccne1 or Ccne2 alleles when the endpoint is replication stress rather than proliferation, and pair with a germline or tumor-restricted Cre.',
  Cdk4:
    'Cdk4, mouse ortholog of human CDK4, encodes the D-cyclin dependent kinase that initiates RB phosphorylation at the restriction point, is directly inhibited by the INK4 proteins p16, p15, p18 and p19 through an allosteric interface that distorts the ATP site, and requires assembly with p21 or p27 plus CAK activation to function. The R24C substitution abolishes INK4 binding and yields an INK4-insensitive kinase, and the homologous human R24C and R24H alleles cause familial melanoma, so an R24C knockin is the appropriate tool for testing whether tumors depend on INK4 restraint or on CDK4/6 inhibitor binding. Null mice are viable but diabetic from beta cell hypoplasia and infertile, making constitutive alleles usable while conditional designs isolate tissue requirement. Cdk6 substitutes broadly, particularly in hematopoietic lineages, so single deletion understates dependency and palbociclib class resistance studies need compound alleles. Select nulls for dependency mapping, R24C knockins for oncogenic drive, and pair conditional alleles with a lineage-matched Cre.',
  Cdk6:
    'Cdk6 is the mouse ortholog of human CDK6 and encodes the second D-cyclin dependent kinase, sharing RB directed catalytic function with CDK4 and INK4 sensitivity but distinguished by dominant expression in hematopoietic stem and progenitor cells and lymphocytes, and by a kinase-independent nuclear function in which CDK6 acts as a transcriptional cofactor with STAT3, AP-1 and NF-kB to induce VEGFA and to repress p16 and p53 outputs. Chromosomal rearrangements placing CDK6 under strong enhancers occur in lymphoid malignancy, and CDK6 upregulation is a recurrent mechanism of acquired resistance to CDK4/6 inhibitors in breast cancer. Null mice are viable with mild anemia and thymic hypoplasia, so constitutive alleles are workable, but Cdk4 compensates in most nonhematopoietic tissue and single deletions mislead. Kinase-dead knockin alleles are the decisive tool here because they separate catalytic from transcriptional function, a distinction no null can make, while conditional nulls layered on Cdk4 alleles serve inhibitor resistance and hematopoietic dependency studies.',
  Cdkn2a:
    'Cdkn2a, the mouse ortholog of human CDKN2A, is unusual because a single locus encodes two unrelated tumor suppressors from alternative reading frames: p16INK4a, an ankyrin repeat protein that allosterically inhibits CDK4 and CDK6 to keep RB hypophosphorylated, and p19ARF (human p14ARF) from an alternate first exon, which sequesters MDM2 in the nucleolus to stabilize p53. Deletion of the entire locus therefore disables the RB and p53 axes simultaneously, which is why bulk 9p21 loss is among the most common events in melanoma, glioma, pancreatic cancer and mesothelioma but is uninterpretable for mechanism. Allele design must be isoform-specific: exon 1 alpha targeted alleles remove p16 alone, exon 1 beta targeted alleles remove ARF alone, and only the combined deletion mimics the human co-deletion. Cdkn2b lies adjacent, is frequently co-deleted, and p15 partially compensates for p16 loss. Match allele to endpoint, using p16-specific alleles for CDK4/6 inhibitor sensitivity and ARF-specific alleles for p53 pathway questions.',
  Cdkn2b:
    'Cdkn2b, mouse ortholog of human CDKN2B, encodes p15INK4b, an ankyrin repeat INK4 family inhibitor that binds CDK4 and CDK6 monomers and prevents productive D-cyclin association, thereby holding RB hypophosphorylated. Unlike p16, p15 is strongly transcriptionally induced by TGF beta through SMAD3 and SMAD4 with FOXO cofactors, making it the principal effector of cytostatic TGF beta signaling in epithelial and hematopoietic cells, and it is also silenced by promoter hypermethylation in acute myeloid leukemia and myelodysplastic syndrome. Because CDKN2B sits immediately adjacent to CDKN2A within the 9p21 cluster, most human deletions remove both, so a mouse allele targeting p15 alone is the only way to assign phenotype to this gene. Null mice are viable and develop lymphoid hyperplasia and angiosarcoma at low penetrance, and p16 upregulation genuinely compensates for p15 loss, so compound Cdkn2a and Cdkn2b alleles are required for the human co-deletion state. Use isolated nulls for TGF beta cytostasis and compound deletions for 9p21 tumor modeling.',
  Cer1:
    'Cer1, mouse ortholog of human CER1, encodes Cerberus 1, a secreted cysteine-knot DAN family antagonist expressed in anterior visceral endoderm and anterior primitive streak that binds and sequesters Nodal, BMP4, and in some contexts Wnt ligands, sculpting the anterior signaling shield that permits head formation and restricts posteriorizing signals. Its Nodal-binding activity also contributes to left-right asymmetry and to the periodicity of Nodal expression during somite and node development, and human variants have been reported in laterality and cardiac malformation cohorts. Mouse nulls are viable and grossly normal, an instructive negative result attributable to overlapping antagonism from Lefty1, Lefty2, Dand5, Nog, and Chrd, so compound genetics rather than a single knockout is required to expose anterior patterning failure. Given viability, allele choice should favor either compound antagonist deletion for developmental endpoints or reporter and conditional alleles for lineage tracing of anterior endoderm. Humanization is warranted only when assaying human CER1 protein directly in differentiation or organoid readouts.',
  Cfb:
    'Cfb is the mouse ortholog of human CFB and encodes complement factor B, the catalytic engine of the alternative pathway. The zymogen comprises three complement control protein modules, a von Willebrand factor type A domain that coordinates magnesium, and a chymotrypsin-like serine protease domain; binding to surface-bound C3b or hydrolyzed C3 opens the molecule for factor D cleavage into Ba and Bb, leaving Bb as the proteolytic subunit of the C3bBb convertase that properdin stabilizes and factor H and decay accelerating factor dissociate. Gain-of-function variants such as human D279G and F286L create decay-resistant convertases and cause atypical hemolytic uremic syndrome and C3 glomerulopathy. Nulls are viable with an intact classical pathway, cleanly isolating amplification loop contributions. Introduce patient missense knockins when spontaneous complement-driven renal disease is the goal, hepatocyte-conditional deletion when the source of circulating factor B matters, and humanization when iptacopan class inhibitors are being profiled.',
  Cfd:
    'Complement factor D, also called adipsin, is encoded by mouse Cfd, ortholog of human CFD, and constitutes the rate-limiting protease of the alternative pathway. Factor D is unique among complement proteases in circulating as a mature enzyme rather than a zymogen, held in a self-inhibited conformation by a distorted active site and a blocking self-inhibitory loop that is relieved only upon docking to the exosite presented by factor B once factor B has engaged C3b, an elegant substrate-induced activation that prevents fluid phase proteolysis. It is secreted largely by adipocytes, linking metabolic tissue to complement amplification and insulin secretion biology. Human deficiency causes recurrent Neisseria infection, and mouse nulls lack alternative pathway activity while retaining classical function, with no paralog to compensate. Choose the null or an adipocyte-conditional allele to test tissue source and metabolic crosstalk, and humanized knockins when danicopan class molecules exploiting the self-inhibited pocket are the endpoint.',
  Cfh:
    'Cfh, ortholog of human CFH, encodes factor H, the principal soluble regulator restraining alternative pathway amplification on host surfaces. Its twenty complement control protein modules are functionally partitioned: CCP1 to CCP4 accelerate decay of C3bBb and serve as cofactor for factor I cleavage of C3b, while CCP19 and CCP20 read host surface markers, binding sialic acid, glycosaminoglycans, and C3d simultaneously to localize regulation. Loss of function causes uncontrolled fluid phase C3 consumption, and mouse Cfh nulls develop spontaneous C3 glomerulopathy with dense intramembranous deposits, making this one of few complement models with autonomous renal pathology. Human disease splits sharply by domain: CCP20 mutations and anti-factor H autoantibodies cause atypical hemolytic uremic syndrome, whereas the CCP7 Y402H variant drives age-related macular degeneration. Match allele to question using the null for C3 glomerulopathy, domain-specific knockins for surface recognition, and humanization or Y402H equivalents for ocular endpoints.',
  Cfhr1:
    'Cfhr1 is annotated as the mouse counterpart of human CFHR1 within the regulator of complement activation cluster syntenic to human 1q31, and encodes a secreted factor H related protein built from complement control protein modules that lack the CCP1 to CCP4 regulatory region of factor H while retaining C-terminal surface and C3b recognition modules, so it competes with factor H for host surface binding and modulates rather than executes convertase decay. Human CFHR1 also dimerizes through its N-terminal modules, and homozygous CFHR3 CFHR1 deletion associates strongly with anti-factor H autoantibody positive atypical hemolytic uremic syndrome yet is protective in age-related macular degeneration. Crucially, the murine Cfhr genes arose by independent duplication, so orthology to human CFHR1 is approximate and phenotypes rarely transfer. Full-locus humanization spanning CFH and the CFHR cluster is therefore the defensible design, with murine nulls reserved for questions about local surface competition on the mouse glomerulus.',
  Cfhr3:
    'Mouse Cfhr3 sits within the same murine factor H related expansion and is the nominal counterpart of human CFHR3, which encodes a five module protein binding C3b, heparin, and pentraxin 3 that competes with factor H for surface recognition while lacking intrinsic decay accelerating activity, thereby acting as a competitive deregulator of complement on host membranes. In humans the CFHR3 CFHR1 deletion polymorphism alters this competition and shows opposing associations across atypical hemolytic uremic syndrome and age-related macular degeneration, while CFHR gene conversion and hybrid alleles cause C3 glomerulopathy. Because the murine cluster expanded independently of the human one, gene number, dimerization behavior, and expression pattern differ, so a mouse Cfhr3 null should not be presumed to model human CFHR3 loss. The rigorous approach is humanization of the CFH and CFHR interval, or transgenic expression of individual human CFHR proteins on a Cfh deficient background, with C3 deposition and glomerular pathology as endpoints.',
  Cfi:
    'Cfi, ortholog of human CFI, encodes complement factor I, the sole protease that irreversibly inactivates deposited C3b and C4b. The secreted two-chain enzyme couples a heavy chain of FIMAC, SRCR, and two LDL receptor class A modules to a chymotrypsin-like serine protease light chain that is unusual in requiring an allosteric partner: catalysis proceeds only when C3b or C4b is engaged with a cofactor such as factor H, membrane cofactor protein CD46, C4b-binding protein, or CR1, which explains both its exceptional specificity and its sequential cleavage of C3b at two arginine sites to yield iC3b and then C3dg. Human deficiency causes secondary C3 depletion with pyogenic infection, and heterozygous mutations predispose to atypical hemolytic uremic syndrome and macular degeneration. Nulls consume C3 spontaneously and lack compensating proteases. Deploy the null for uncontrolled amplification phenotypes, hepatocyte-conditional alleles to test liver source, and humanization when factor I supplementation or cofactor-dependent activity is measured.',
  Cflar:
    'Cflar encodes cellular FLICE inhibitory protein, the mouse ortholog of human CFLAR, a death effector domain protein recruited to FADD within death-inducing signaling complexes where it heterodimerizes with procaspase-8. The long isoform retains a catalytically dead caspase-like domain that paradoxically stabilizes partial caspase-8 activity sufficient for RIPK1 and CYLD cleavage while blocking full processing and apoptosis, whereas short isoforms truncate after the death effector domains and inhibit outright; abundance is set by NF-kappaB dependent transcription and rapid ITCH and cullin-3 mediated turnover, making CFLAR a labile rheostat between survival, apoptosis, and necroptosis. Germline deletion is embryonic lethal around E10.5 with cardiac and vascular failure, phenocopying Casp8 and Fadd loss, and is rescued by concurrent Ripk3 or Mlkl deficiency. Conditional flox alleles with keratinocyte, intestinal epithelial, or myeloid Cre are therefore required, and isoform-selective knockins are the tool of choice for separating long from short isoform function.',
  Chchd10:
    'Chchd10, ortholog of human CHCHD10, encodes a small twin CX9C motif protein imported into the mitochondrial intermembrane space by the MIA40 and CHCHD4 disulfide relay, where it associates with the MICOS complex through MIC60 and helps maintain cristae junction architecture and respiratory chain organization. Dominant substitutions including S59L cause amyotrophic lateral sclerosis with frontotemporal dementia, and G66V causes late-onset spinal muscular atrophy Jokela type, but the decisive genetic observation is that constitutive nulls are essentially phenotype-free while S59L knockin animals develop cardiomyopathy, mitochondrial integrated stress response activation and motor neuron loss. That contrast makes the allele choice unambiguous: a knockout answers dispensability, whereas a point knockin is required to model the aggregation-driven toxic gain of function that underlies patient disease. CHCHD2 heterodimerizes with CHCHD10 and buffers its loss, so include compound alleles when interpreting null results and score OMA1, DELE1 and ATF4 axis activation alongside neuromuscular endpoints.',
  Chchd2:
    'Encoding a twin CX9C intermembrane space protein imported through the MIA40 relay, Chchd2 is the mouse ortholog of human CHCHD2 (PARK22), where it associates with cytochrome c oxidase subunits, contributes to cristae organization together with CHCHD10, and under hypoxia relocates to the nucleus to act on oxygen-responsive promoter elements, giving it both a bioenergetic and a transcriptional identity. Dominant T61I and R145Q substitutions cause autosomal dominant Parkinson disease with α-synuclein pathology, and the mutant protein aggregates and destabilizes the CHCHD2 and CHCHD10 heterodimer rather than simply losing activity. As with its paralog, constitutive nulls display mild or age-delayed phenotypes, so a T61I knockin is the design matched to dopaminergic degeneration endpoints, while a conditional null crossed to Dat-Cre tests whether reduced dosage alone compromises nigral neurons. Because Chchd10 compensates directly through heterodimer formation, plan compound conditional genetics early and quantify mitochondrial integrated stress response markers with nigral cell counts.',
  Chd4:
    'Chromodomain helicase DNA-binding protein 4, encoded by Chd4 and orthologous to human CHD4, supplies the Mi-2 beta ATPase motor of the nucleosome remodeling and deacetylase complex, partnering with HDAC1 and HDAC2, MTA1 through MTA3, MBD2 or MBD3, GATAD2, and RBBP4. Tandem PHD fingers read the H3 tail while paired chromodomains grip nucleosomal DNA, coupling remodeling to deacetylation for enhancer decommissioning and promoter silencing, and enabling rapid PARP-dependent recruitment to double-strand breaks. Recurrent missense mutations in the ATPase and chromodomain regions occur in endometrial and serous carcinoma, indicating separation of function rather than simple loss. Constitutive deletion is early embryonic lethal, so conditional alleles with tissue-restricted Cre are required, and ATPase-dead knockins distinguish catalytic from scaffolding roles. Chd3 and Chd5 form mutually exclusive NuRD variants and partially buffer loss, so consider compound alleles when a single deletion yields a muted chromatin phenotype.',
  Chek1:
    'Chek1, the mouse ortholog of human CHEK1, encodes CHK1, the effector kinase of the replication checkpoint, recruited to chromatin through CLASPIN and activated by ATR phosphorylation at serines 317 and 345, after which it phosphorylates CDC25A to trigger its degradation, inhibits CDK2 driven origin firing, restrains CDC45 loading, stabilizes stalled forks and enforces the G2/M transition through CDC25C and WEE1. Loss is cell lethal because unrestrained origin firing exhausts nucleotide and RPA pools, and homozygous null embryos die at the blastocyst stage, while heterozygotes show genuine haploinsufficiency with checkpoint defects, so this is a gene where conditional floxed alleles and inducible Cre are not optional. Acute deletion in adult intestine or hematopoietic compartments reproduces the on-target toxicity that limits CHK1 inhibitors clinically, making it the right platform for therapeutic window studies. Chek2 does not substitute, since it operates downstream of ATM on double strand breaks. Reserve hypomorphic alleles for chronic replication stress and conditional nulls for acute dependency work.',
  Chek2:
    'Chek2, mouse ortholog of human CHEK2, encodes CHK2, an ATM effector kinase built from an SQ/TQ cluster, an FHA phosphopeptide binding domain and a kinase domain, activated when ATM phosphorylates threonine 68 to promote FHA-mediated dimerization and trans-autophosphorylation at the activation loop. Active CHK2 phosphorylates p53 at serine 20 to disrupt MDM2 binding, targets CDC25A and CDC25C for degradation or 14-3-3 sequestration, and phosphorylates BRCA1 and E2F1, enforcing G1 arrest and apoptosis after double strand breaks. The truncating 1100delC and missense I157T alleles confer moderate breast and prostate cancer risk, making patient-variant knockins the appropriate tool for penetrance and variant reclassification studies. Null mice are viable and radioresistant in thymocytes with defective p53 stabilization, so constitutive alleles are entirely workable, unlike Chek1. Because CHK2 acts on breaks and CHK1 on replication stress, they are not redundant. Choose nulls for apoptotic threshold and radiation response, and knockins for allele-specific cancer risk modeling.',
  Chrd:
    'Chrd, the mouse ortholog of human CHRD, encodes chordin, a secreted protein built from four cysteine-rich CR domains that binds BMP2 and BMP4 with high affinity and blocks receptor engagement, establishing the extracellular gradient that patterns dorsoventral axis, pharyngeal apparatus, and inner ear. Its inhibitory activity is itself regulated proteolytically: BMP1 and the tolloid proteases TLL1 and TLL2 cleave chordin to release active ligand, while twisted gastrulation encoded by Twsg1 forms ternary complexes that can either strengthen or relieve inhibition depending on cleavage state. Nulls show strain-dependent pharyngeal, cardiovascular, and ear defects resembling DiGeorge phenotypes with variable perinatal lethality, so background control is as consequential as allele design. Domain-specific deletions removing individual CR modules or cleavage-site knockins are more informative than complete ablation when the question is gradient shape rather than presence. Overlapping antagonism from Nog, Grem1, and Cer1 means compound alleles are needed to fully derepress BMP signaling at a given endpoint.',
  Cntnap2:
    'Cntnap2, ortholog of human CNTNAP2, encodes CASPR2, a neurexin superfamily single-pass adhesion molecule whose ectodomain combines discoidin, laminin G, EGF and fibrinogen-like modules and whose short cytoplasmic tail binds protein 4.1B; at myelinated axon juxtaparanodes it forms a ternary complex with TAG-1 (Contactin-2) to cluster Kv1.1 and Kv1.2 channels and prevent aberrant reexcitation, and it also functions at cortical synapses and in interneuron migration. Recessive truncating alleles cause cortical dysplasia focal epilepsy syndrome, common variants associate with language and autism phenotypes, and the CASPR2 ectodomain is a major autoantigen in limbic encephalitis and Morvan syndrome. Constitutive nulls are viable and reproduce interneuron loss, abnormal ultrasonic vocalization and repetitive behavior, giving a workable model, while a humanized ectodomain allele uniquely supports patient autoantibody and immunotherapy studies. Note the extreme locus size, over two megabases, which constrains full-locus humanization and favors targeted domain replacement with careful conditional exon design.',
  Coq2:
    'Coq2 encodes 4-hydroxybenzoate polyprenyltransferase, the mouse ortholog of human COQ2, an inner mitochondrial membrane enzyme that performs the committed prenylation step of coenzyme Q biosynthesis by condensing 4-hydroxybenzoate with the polyisoprenoid tail supplied by PDSS1 and PDSS2, generating the lipophilic intermediate that all downstream complex Q enzymes then modify. Recessive human alleles cause primary coenzyme Q10 deficiency presenting as steroid-resistant nephrotic syndrome, infantile encephalomyopathy and retinopathy, and a disputed association with multiple system atrophy has driven interest in heterozygous carrier biology. Because complete loss removes the substrate for every subsequent step, constitutive deletion is severely compromising and conditional nulls are the practical design, with Pax8-Cre or podocin-Cre for renal phenotypes and Nes-Cre or Dat-Cre for neurologic endpoints. No paralog performs this prenylation, so compensation is not a concern, but residual dietary and supplemental coenzyme Q10 uptake confounds rescue experiments; measure tissue CoQ9 and CoQ10 species directly.',
  Coq3:
    'The O-methylation steps of coenzyme Q biosynthesis are catalyzed by the product of Coq3, ortholog of human COQ3, a S-adenosylmethionine-dependent class I methyltransferase that is peripherally associated with the matrix face of the inner mitochondrial membrane as part of the multienzyme complex Q assembly. Uniquely among the pathway enzymes it acts twice, methylating the 3-hydroxy group of an early intermediate and then the 6-hydroxy group of demethyl-demethoxyubiquinol at the penultimate step, so its loss truncates the pathway at two distinct points and produces a characteristic accumulation of unmethylated precursors useful as a biochemical readout. Human deficiency is rare relative to COQ2, COQ6 and COQ8B but follows the same recessive coenzyme Q10 deficiency spectrum. Conditional nulls with tissue-restricted Cre drivers are the appropriate design because complete pathway ablation is poorly tolerated, and because complex Q stability is cooperative, verify COQ4, COQ7 and COQ9 protein levels before ascribing phenotypes solely to lost methyltransferase activity.',
  Coq4:
    'Structural rather than catalytic in function, the Coq4 product, ortholog of human COQ4, is a zinc-binding component of complex Q that adopts a lipid-binding fold, holds a polyprenyl intermediate in a hydrophobic pocket, and physically nucleates assembly of the coenzyme Q biosynthetic complex on the matrix face of the inner mitochondrial membrane. Loss therefore destabilizes multiple COQ proteins simultaneously rather than blocking a single reaction, and recessive human variants cause a severe spectrum ranging from neonatal encephalomyopathy and hypertrophic cardiomyopathy to later-onset spastic ataxia, with heterozygous deletions reported in some families. Constitutive deletion is not tolerated, so a conditional null with cardiomyocyte, podocyte or neuronal Cre drivers is the correct design, whereas a patient missense knockin distinguishes destabilized assembly from complete absence and is the better substrate for testing CoQ10 or 4-hydroxybenzoate analog supplementation. There is no functional paralog, so interpret residual coenzyme Q as uptake rather than compensation.',
  Coq5:
    'Coq5 encodes the C-methyltransferase of coenzyme Q biosynthesis, ortholog of human COQ5, a class I S-adenosylmethionine-dependent enzyme that transfers a methyl group to the C2 position of demethoxyubiquinol within the membrane-associated complex Q assembly, a reaction distinct from the two O-methylations performed by COQ3. Beyond catalysis it contributes to the structural integrity of the complex, and its steady-state level is coupled to COQ4 and COQ9 abundance, so perturbation produces a coordinated rather than isolated defect. Human variants and copy number changes at the locus have been linked to coenzyme Q10 deficiency with cerebellar ataxia and developmental delay. Given the essentiality of the pathway, a conditional null is the design of choice, matched to Nes-Cre or Pcp2-Cre for cerebellar endpoints and podocyte drivers for renal readouts, while a catalytically dead knockin separates enzymatic from scaffolding contributions. Quantify demethoxyubiquinone accumulation directly, since it is the diagnostic intermediate for this step.',
  Coq6:
    'Hydroxylation at the C5 position of the coenzyme Q ring is performed by the flavin-dependent monooxygenase encoded by Coq6, ortholog of human COQ6, an inner membrane enzyme with a Rossmann FAD-binding fold that operates within complex Q and requires ferredoxin and ferredoxin reductase as electron donors. Recessive human alleles produce a distinctive phenotype of steroid-resistant nephrotic syndrome with sensorineural deafness, and because the enzymatic block sits upstream of ring hydroxylation, the bypass compound 2,4-dihydroxybenzoate can restore coenzyme Q synthesis in model systems, a therapeutic logic that makes this gene unusually attractive for intervention studies. Constitutive loss is severe, so podocin-Cre or Pax8-Cre conditional nulls are the practical design for glomerular endpoints, with inner ear drivers for auditory phenotyping, while a patient missense knockin preserves partial activity and better models human disease progression and bypass responsiveness. No paralog performs this reaction, so measure CoQ9 levels and proteinuria directly rather than assuming redundancy.',
  Coq7:
    'Coq7 encodes the di-iron carboxylate hydroxylase that converts demethoxyubiquinol to the C6-hydroxylated intermediate in the penultimate step of coenzyme Q biosynthesis, the mouse ortholog of human COQ7 and originally identified as Mclk1 in longevity genetics. Its activity is regulated by phosphorylation and by COQ9, which binds and presents the lipophilic substrate, making the two proteins an obligate functional pair. Constitutive nulls are embryonic lethal around midgestation, while heterozygotes show reduced respiratory chain function with paradoxically extended lifespan and altered stress signaling, and human recessive variants cause coenzyme Q10 deficiency with encephalopathy, hearing loss and renal involvement. Because the block lies downstream of ring hydroxylation, 2,4-dihydroxybenzoate bypass rescues COQ7 but not COQ6 deficiency, a distinction that should determine which allele is chosen for therapeutic testing. Use conditional nulls with tissue-restricted Cre drivers for adult phenotyping and a hypomorphic knockin when graded loss rather than ablation is the question.',
  Coq8a:
    'Coq8a, ortholog of human COQ8A (also known as ADCK3 and CABC1), encodes an atypical UbiB-family protein kinase-like ATPase that lacks canonical protein kinase activity but binds cardiolipin and coenzyme Q intermediates, uses ATP hydrolysis to support complex Q assembly and stability, and thereby acts as a regulator rather than a biosynthetic enzyme. Recessive human variants cause autosomal recessive cerebellar ataxia type 2 with Purkinje cell loss, exercise intolerance and variable seizures, and partial responsiveness to high-dose coenzyme Q10 supplementation is a defining clinical feature. Usefully for modeling, constitutive nulls are viable and develop cerebellar ataxia with Purkinje cell degeneration, so an unconditional allele is often sufficient, while Pcp2-Cre conditional deletion establishes cell autonomy and a patient missense knockin retains partial ATPase function for supplementation trials. The paralog Coq8b covers largely non-overlapping tissues, chiefly kidney, so it does not rescue cerebellar loss; confirm tissue-specific expression before invoking redundancy.',
  Coq8b:
    'Podocyte biology dominates Coq8b, ortholog of human COQ8B (ADCK4), which encodes a UbiB-family atypical kinase-like ATPase paralogous to COQ8A that binds membrane lipids and supports assembly and stability of the coenzyme Q biosynthetic complex rather than catalyzing a ring modification itself. Recessive human variants are among the more common causes of steroid-resistant nephrotic syndrome presenting in adolescence with focal segmental glomerulosclerosis, and the protein interacts with COQ6 and COQ7 as well as with the podocyte-specific machinery, which explains the renal-restricted presentation despite ubiquitous pathway requirements. Because whole-body deletion compromises multiple tissues, podocin-Cre or Nphs2-Cre conditional nulls are the design that reproduces the human glomerular phenotype, whereas a patient missense knockin preserves residual activity and supports testing of coenzyme Q10 and 2,4-dihydroxybenzoate supplementation. Coq8a is expressed in overlapping tissues but does not rescue podocyte loss, so measure glomerular coenzyme Q content and proteinuria as primary endpoints.',
  Coq9:
    'Coq9 functions as a lipid-binding partner rather than a catalyst, encoding the mouse ortholog of human COQ9, a protein with a START-like hydrophobic cavity that extracts coenzyme Q intermediates from the inner membrane bilayer and presents them to COQ7, forming a stable complex that is required for the C6-hydroxylation step and for overall stability of complex Q. Recessive human variants, including the well-studied R244X truncation modeled by the Coq9 R239X mouse, cause neonatal encephalomyopathy with demyelination, seizures and renal tubulopathy, accompanied by diagnostic accumulation of demethoxyubiquinone. The allele fork is clear: a knockin truncation reproduces the destabilized COQ7 interaction and progressive encephalopathy suitable for therapeutic testing with 2,4-dihydroxybenzoate, whereas a conditional null with Nes-Cre or renal drivers assigns tissue autonomy. No paralog substitutes for the lipid-binding function, so interpret residual coenzyme Q as dietary uptake, and quantify the demethoxyubiquinone to coenzyme Q ratio as the primary biochemical endpoint.',
  Cox10:
    'Heme A biosynthesis begins with Cox10, the mouse ortholog of human COX10, which encodes the inner membrane heme A farnesyltransferase that converts protoheme, or heme B, into heme O by farnesylating a vinyl side chain, the committed first step toward the heme A cofactors of cytochrome c oxidase. Without heme A, subunit MT-CO1 cannot mature, so complex IV assembly stalls and the enzyme is degraded, producing isolated cytochrome c oxidase deficiency. Human COX10 mutations cause Leigh syndrome, leukodystrophy with tubulopathy, and fatal infantile encephalomyopathy, and conditional mouse alleles have been used productively to generate muscle and neuron restricted complex IV deficiency. Design accordingly: a floxed conditional null builds tissue specific COX deficiency models, while hypomorphic knockins reproduce partial cofactor synthesis. No paralog performs this farnesylation. Pair Ckmm-Cre, Nes-Cre, or Camk2a-Cre with COX and SDH histochemistry, spectrophotometric complex IV activity, and blue native assembly analysis.',
  Cox11:
    'Cox11, ortholog of human COX11, encodes an inner membrane metallochaperone that receives copper from the intermembrane space carrier Cox17 through conserved cysteine thiols and inserts it into the CuB site of MT-CO1, the site that together with heme a3 forms the binuclear oxygen reduction center of cytochrome c oxidase. Because CuB delivery occurs as MT-CO1 is being inserted, loss of Cox11 arrests complex IV assembly at an early module and triggers turnover of unmetalated subunit 1, yielding isolated cytochrome c oxidase deficiency rather than a partial activity defect. That places the design fork between a conditional null, which produces tissue restricted COX deficiency, and cysteine substitution knockins, which test metal transfer chemistry specifically. Sco1, Sco2, and Cox19 act on the CuA site and do not substitute for CuB delivery. Use Ckmm-Cre or Nes-Cre with COX histochemistry, mitochondrial copper measurements, and blue native profiling of assembly intermediates.',
  Cox14:
    'Translation of the mitochondrial genome must be matched to assembly capacity, and Cox14, ortholog of human COX14 and formerly C12orf62, encodes the small inner membrane protein performing this coupling for cytochrome c oxidase. Acting with COA3 and other MITRAC components, Cox14 binds newly synthesized MT-CO1 and feeds back on its translation, so when downstream assembly is blocked, subunit 1 synthesis is downregulated rather than allowed to accumulate as an aggregation prone apoprotein. Human COX14 mutations cause fatal neonatal lactic acidosis with isolated complex IV deficiency and reduced MT-CO1 synthesis, exactly the signature this regulatory role predicts. A conditional null therefore models tissue specific translational uncoupling, while a missense knockin preserves the protein and probes the MT-CO1 interaction. No redundant factor performs this function. Combine Nes-Cre or Ckmm-Cre with in organello translation assays, COX histochemistry, and blue native detection of stalled MITRAC intermediates.',
  Cox15:
    'Cox15 encodes the mouse ortholog of human COX15, the inner membrane heme A synthase that completes cofactor maturation by hydroxylating and oxidizing a methyl group of heme O to yield heme A, the reaction immediately downstream of the farnesylation catalyzed by Cox10. Heme A is required for MT-CO1 maturation and for the heme a and heme a3 centers that drive electron transfer to oxygen, so blocking this step produces isolated cytochrome c oxidase deficiency with degradation of unassembled subunit 1. Human COX15 mutations cause fatal infantile hypertrophic cardiomyopathy and Leigh syndrome, phenotypes making cardiac and neuronal conditional alleles the most informative designs, while hypomorphic knockins model residual heme A synthesis. Cox10 works in the same pathway and cannot substitute for the synthase step. Use Myh6-MerCreMer or Nes-Cre with echocardiography, COX and SDH histochemistry, complex IV spectrophotometry, and blue native assembly profiling matched to the question.',
  Cox16:
    'Cox16, ortholog of human COX16, encodes a small inner membrane protein participating in copper delivery during cytochrome c oxidase biogenesis, interacting with the MT-CO2 module and with SCO1 to support formation of the binuclear CuA center. Because CuA in subunit 2 accepts electrons directly from reduced cytochrome c, failure of this maturation step yields catalytically incompetent complex IV and accumulation of assembly intermediates rather than a fully formed enzyme with merely reduced turnover. The design fork is therefore between a conditional null that establishes tissue specific complex IV deficiency and targeted substitutions that test the SCO1 and MT-CO2 interfaces while retaining the protein. Cox17, Cox19, Sco1, and Sco2 act at neighboring steps in the same copper relay and do not functionally replace Cox16. Match the allele to readouts including COX histochemistry, cytochrome c oxidase spectrophotometric activity, mitochondrial copper quantification, and blue native resolution of subassemblies under Nes-Cre or Ckmm-Cre control.',
  Cox17:
    'Copper trafficking into cytochrome c oxidase begins with Cox17, the mouse ortholog of human COX17, a small twin CX9C intermembrane space metallochaperone that binds copper through conserved cysteines and hands it to SCO1 for the CuA site in MT-CO2 and to COX11 for the CuB site in MT-CO1. Loss of this single relay point compromises both metal centers simultaneously, which is why germline deletion in mouse arrests development near implantation, an established lethality that makes conditional alleles mandatory for any postnatal or tissue specific question. A floxed null therefore defines tissue tolerance for complex IV loss, while cysteine to serine knockins dissect metal binding from protein interaction. Cox19 and Cox23 participate in related redox and copper signaling but do not substitute for Cox17. Pair Ckmm-Cre, Nes-Cre, or Rosa26-CreER with COX histochemistry, copper measurements, complex IV activity, and blue native assembly analysis.',
  Cox18:
    'Cox18, ortholog of human COX18, encodes an Oxa1 family inner membrane insertase dedicated to topogenesis of the mitochondrially encoded subunit MT-CO2, translocating its carboxy terminal domain across the membrane so the CuA site can be formed on the intermembrane space face. Working with COX20 and the SCO chaperones, Cox18 acts at the interface between membrane protein insertion and metal center assembly, and its loss leaves subunit 2 improperly exposed and rapidly degraded, producing isolated cytochrome c oxidase deficiency. A conditional null models tissue restricted complex IV failure, whereas substitutions in the conserved insertase core test translocation activity without removing the protein. Oxa1l serves other substrates and does not replace this specialized function. Choose drivers by target tissue, then quantify MT-CO2 stability by pulse labeling, complex IV by spectrophotometry and histochemistry, and assembly intermediates by blue native PAGE to keep allele class matched to mechanism.',
  Cox19:
    'Cox19 encodes the mouse ortholog of human COX19, a small twin CX9C protein that shuttles between the cytosol and the mitochondrial intermembrane space and functions in the copper and thiol redox relay supporting cytochrome c oxidase biogenesis, acting alongside COX17 and influencing the redox state of SCO1. Through that connection, Cox19 participates in signaling that couples complex IV assembly status to cellular copper handling, so its loss reduces cytochrome c oxidase activity and perturbs copper homeostasis rather than causing a simple structural deficit. Allele design should reflect this dual role: a conditional null tests tissue dependence on the relay, while cysteine substitution knockins separate metal and redox chemistry from scaffolding. Cox17 and Cox23 occupy adjacent steps and are not interchangeable with Cox19. Combine Nes-Cre, Ckmm-Cre, or Rosa26-CreER with complex IV activity, COX histochemistry, mitochondrial copper quantification, and blue native profiling of stalled intermediates.',
  Cox20:
    'Cox20, ortholog of human COX20, encodes an inner membrane chaperone that binds newly inserted MT-CO2 immediately after membrane integration, stabilizing it and handing it to SCO1 and SCO2 for CuA maturation while cooperating with the COX18 insertase. This makes Cox20 a substrate specific holdase in the complex IV assembly line, and its loss leaves subunit 2 unmetalated and degradation prone, producing isolated cytochrome c oxidase deficiency. Human COX20 mutations cause early onset ataxia with dystonia and sensory neuropathy, a neurological presentation arguing for neuron directed conditional alleles when clinical fidelity matters, whereas patient missense knockins reproduce residual activity better than deletion. No paralogous chaperone covers MT-CO2 in its place. Use Nes-Cre, Camk2a-Cre, or Pcp2-Cre depending on the circuit of interest, then read complex IV activity and histochemistry, MT-CO2 stability, motor phenotyping, and blue native assembly intermediates.',
  Cox4i1:
    'Cox4i1 is the mouse ortholog of human COX4I1 and encodes the ubiquitously expressed isoform of nuclear encoded subunit 4 of cytochrome c oxidase, a transmembrane subunit whose matrix facing domain binds ATP at a regulatory site mediating allosteric inhibition of the enzyme at high ATP to ADP ratios. Subunit 4 joins the MT-CO1 module early and is required for stable holoenzyme accumulation, so reduced levels lower assembled complex IV rather than simply altering kinetics. Under hypoxia, HIF1 alpha drives replacement of this isoform by COX4I2 with LONP1 mediated degradation of the constitutive subunit, an isoform switch a conditional null can test directly. Cox4i2 is expressed in restricted tissues and does not fully compensate in most cells. Combine floxed alleles with Ckmm-Cre, Nes-Cre, or Rosa26-CreER and read complex IV activity, ATP dependent allosteric inhibition, respirometry, and blue native holoenzyme content.',
  Cox4i2:
    'Cox4i2, ortholog of human COX4I2, encodes the alternative isoform of cytochrome c oxidase subunit 4 that predominates in lung, particularly in pulmonary artery smooth muscle, and lacks the ATP binding regulatory motif of the constitutive isoform, so complex IV containing it escapes allosteric inhibition by high ATP. Because this isoform is induced under hypoxia and has been implicated in hypoxic pulmonary vasoconstriction, it links oxygen sensing to contractile signaling as well as to electron transfer. Biallelic human variants cause exocrine pancreatic insufficiency with dyserythropoietic anemia and calvarial hyperostosis, so patient knockins address clinical fidelity while a conditional null tests the vasoconstriction hypothesis. Cox4i1 is co-expressed in many tissues and can partly substitute structurally, which may mask phenotypes, so consider compound designs. Use smooth muscle drivers such as Myh11-CreER with hypoxic pulmonary hypertension protocols, right heart hemodynamics, vasoreactivity, and complex IV activity as endpoints.',
  Cox5a:
    'Cox5a encodes the mouse ortholog of human COX5A, a nuclear encoded matrix side subunit of cytochrome c oxidase that packs against MT-CO1 and contributes to allosteric regulation of the enzyme, including the relief of ATP mediated inhibition by 3,5-diiodothyronine binding described for this subunit. Subunit 5A is incorporated during assembly of the catalytic core, so its loss destabilizes the holoenzyme and produces isolated complex IV deficiency, and human recessive variants cause failure to thrive with lactic acidosis and pulmonary hypertension. Design therefore separates two questions: a conditional null tests absolute tissue requirement, while a missense knockin preserves assembly and interrogates regulation, which is the more informative allele if hormonal or nucleotide control is your target. No paralogous subunit replaces 5A. Use Ckmm-Cre, Myh6-MerCreMer, or Nes-Cre with complex IV spectrophotometry, respirometry across ATP to ADP ratios, echocardiography, and blue native assembly profiling.',
  Cox5b:
    'Cox5b, ortholog of human COX5B, encodes a nuclear encoded matrix facing subunit of cytochrome c oxidase that carries a structural zinc site coordinated by conserved cysteines and sits adjacent to the catalytic core formed by the mitochondrially encoded subunits. Subunit 5B contributes to holoenzyme stability rather than to electron transfer chemistry itself, so its depletion reduces assembled complex IV and lowers cytochrome c oxidase activity while sparing the redox centers, a distinction visible when blue native PAGE and spectrophotometry are read together. That biology defines the fork between a conditional null, which measures tissue dependence on the subunit, and cysteine substitution knockins, which test the zinc site without removing the polypeptide. No isoform paralog substitutes for 5B in mouse. Deploy Ckmm-Cre, Alb-Cre, or Rosa26-CreER according to target tissue, then combine COX histochemistry, respirometry, mitochondrial zinc measurements, and assembly analysis to link allele class to a defined endpoint.',
  Cox6a1:
    'Charcot-Marie-Tooth disease provides the clearest disease logic for Cox6a1, the mouse ortholog of human COX6A1, which encodes the ubiquitously expressed isoform of cytochrome c oxidase subunit 6A, a transmembrane subunit contacting the MT-CO3 side of the enzyme and contributing to holoenzyme stability and dimer contacts. Biallelic loss of function variants in humans cause recessive intermediate Charcot-Marie-Tooth neuropathy type D with reduced complex IV activity, and reduced gene dosage in mouse has been used to model the peripheral nerve phenotype. Allele choice follows the endpoint: a conditional null defines tissue requirement and can be directed to Schwann cells or neurons, while hypomorphic or patient knockins reproduce partial deficiency and axonal pathology. The muscle restricted paralog Cox6a2 is co-expressed in heart and skeletal muscle and can blunt phenotypes there, so plan compound alleles for striated tissue. Use Dhh-Cre or Nes-Cre with nerve conduction studies, morphometry, and complex IV activity.',
  Cox6a2:
    'Cox6a2 encodes the mouse ortholog of human COX6A2, the heart and skeletal muscle restricted isoform of cytochrome c oxidase subunit 6A, a transmembrane subunit implicated in ADP dependent allosteric regulation of the enzyme and in tuning proton pumping efficiency in oxidative fibers. Tissue restricted expression means this is intrinsically striated muscle biology, and mouse deletion has been reported to alter cytochrome c oxidase kinetics and mitochondrial coupling without abolishing complex IV, consistent with a regulatory rather than obligatory structural role. That makes the design fork clear: a conditional null tests the regulatory contribution in a defined muscle compartment, whereas a knockin at the ADP responsive interface probes control specifically. The ubiquitous paralog Cox6a1 is co-expressed and can substitute structurally, so compound alleles are worth planning. Combine Ckmm-Cre or Myh6-MerCreMer with respirometry, proton to electron stoichiometry measurements, echocardiography, exercise testing, and blue native holoenzyme analysis.',
  Cox6b1:
    'Cox6b1, ortholog of human COX6B1, encodes a nuclear encoded subunit lying entirely on the intermembrane space face of cytochrome c oxidase, adopting a twin CX9C stabilized fold and sitting near the cytochrome c docking surface and the monomer to monomer interface of the dimeric enzyme. Because subunit 6B contributes to the electron entry region rather than to the catalytic metal centers, its loss reduces holoenzyme stability and turnover and yields isolated complex IV deficiency, and human recessive variants cause severe infantile encephalomyopathy. A conditional null therefore establishes tissue requirement, while patient missense knockins preserve assembly and better reproduce the partial activity relevant to human presentations. The testis enriched paralog Cox6b2 is not co-expressed in somatic tissues, so compensation should not be expected. Use Nes-Cre or Ckmm-Cre with cytochrome c oxidase activity, COX histochemistry, cytochrome c oxidation kinetics, and blue native monomer and dimer profiling.',
  Cox6c:
    'Cox6c is the mouse ortholog of human COX6C and encodes a small nuclear encoded transmembrane subunit of cytochrome c oxidase added during the later assembly module together with subunits 7C and 8A, completing the peripheral shell around the mitochondrially encoded catalytic core. Subunits of this class stabilize the holoenzyme and its lipid interactions rather than participating directly in electron transfer, so depletion lowers assembled complex IV and cytochrome c oxidase activity while the heme and copper centers of surviving enzyme remain functional. The design decision is therefore whether you need absolute tissue requirement, addressed by a floxed conditional null, or a structural interface question, addressed by transmembrane substitutions that retain the subunit. No isoform paralog substitutes for 6C in somatic tissues. Direct deletion with Ckmm-Cre, Alb-Cre, or Rosa26-CreER, then quantify complex IV by spectrophotometry and histochemistry, respirometry, and assembly intermediates by blue native PAGE.',
  Cox7a1:
    'Cox7a1, ortholog of human COX7A1, encodes the heart and skeletal muscle isoform of cytochrome c oxidase subunit 7A, a small transmembrane subunit positioned near the dimer interface and the cardiolipin binding region, where it stabilizes the holoenzyme and influences supramolecular organization within respiratory supercomplexes. Deletion in mouse is viable but produces dilated cardiomyopathy with reduced cytochrome c oxidase activity, an established phenotype making this locus useful for studying isoform specific contributions to cardiac bioenergetics rather than for modeling absolute complex IV loss. Consequently, a conditional null resolves whether the cardiomyopathy is cardiomyocyte autonomous or secondary, while a knockin swapping in the ubiquitous isoform sequence tests isoform specificity directly. The paralog Cox7a2 is co-expressed and partially compensates, which explains the graded phenotype and argues for compound alleles when full loss is required. Pair Myh6-MerCreMer or Ckmm-Cre with echocardiography, respirometry, supercomplex blue native analysis, and exercise testing.',
  Cox7a2:
    'Cox7a2 encodes the mouse ortholog of human COX7A2, the ubiquitously expressed liver type isoform of cytochrome c oxidase subunit 7A, a single pass transmembrane subunit that packs against the mitochondrially encoded core near the dimer interface and contributes to holoenzyme stability and cardiolipin dependent supercomplex organization. Because this isoform provides the default 7A function in most tissues, its depletion lowers assembled complex IV and respiratory capacity broadly rather than in a single organ, distinguishing it from the striated muscle restricted paralog. That difference sets the allele fork between a conditional null, which measures tissue specific dependence on the constitutive isoform, and an isoform swap knockin, which tests whether 7A sequences are functionally interchangeable. Cox7a1 is co-expressed in heart and skeletal muscle and can mask phenotypes there, so plan compound conditionals for striated tissue. Combine Alb-Cre, Nes-Cre, or Rosa26-CreER with complex IV spectrophotometry, respirometry, supercomplex profiling, and hepatic metabolic phenotyping.',
  Cox7b:
    'Cox7b, the mouse ortholog of human COX7B, encodes a small nuclear encoded transmembrane subunit of cytochrome c oxidase incorporated into the late assembly module that completes the shell surrounding the catalytic core, and the gene is X-linked in both species. Human COX7B mutations cause microphthalmia with linear skin defects, an X-linked dominant disorder with male lethality in which skewed X inactivation in females produces mosaic complex IV deficiency, biology that makes X-linked mosaicism itself the experimental variable. Design therefore differs from autosomal COX genes: heterozygous females model mosaic deficiency and developmental patterning defects, while conditional deletion in males tests absolute tissue requirement without whole embryo loss. No paralog substitutes for 7B in somatic tissues. Use Rosa26-CreER, Nes-Cre, or Krt14-Cre depending on whether skin, eye, or nervous system is the endpoint, then read COX histochemistry, clonal patch analysis, complex IV activity, and blue native assembly profiles.',
  Cox7c:
    'Cox7c, ortholog of human COX7C, encodes one of the smallest nuclear encoded subunits of cytochrome c oxidase, a single transmembrane helix added with subunits 6C and 8A during the final assembly module that seals the peripheral shell around the mitochondrially encoded catalytic core. Despite its size, this subunit is required for stable holoenzyme accumulation, so loss produces isolated complex IV deficiency with reduced cytochrome c oxidase activity and accumulated subassemblies, and de novo human variants have been reported in mitochondrial disease with encephalopathy. The design fork separates absolute requirement, tested by a floxed conditional null, from interface specific questions, tested by transmembrane substitutions that keep the subunit in place and better mimic patient alleles. No isoform paralog covers 7C in somatic tissues. Direct deletion with Nes-Cre, Ckmm-Cre, or inducible Rosa26-CreER, then combine COX histochemistry, spectrophotometric complex IV activity, respirometry, and blue native assembly analysis.',
  Cox8a:
    'Cox8a encodes the mouse ortholog of human COX8A, a small nuclear-encoded subunit of cytochrome c oxidase that packs against the mtDNA-encoded catalytic core (MT-CO1, MT-CO2, MT-CO3) and stabilizes the mature complex IV monomer during late assembly, supporting electron transfer from cytochrome c to oxygen and vectorial proton pumping. Because complex IV output is set by assembly efficiency rather than by transcript abundance of any accessory subunit, loss of Cox8a yields isolated complex IV deficiency with reduced respiratory reserve rather than global OXPHOS collapse. Allele choice follows the question: a conditional null with cardiac, skeletal muscle or neuronal Cre isolates cell-autonomous bioenergetic failure, whereas humanization supports testing of patient COX8A missense variants in situ. Note that Cox8b and Cox8c are expressed in restricted tissues, so confirm isoform usage before interpreting residual activity, and pair the allele with the endpoint, whether complex IV kinetics, BN-PAGE assembly intermediates, or organ stress physiology.',
  Cox8c:
    'Cox8c, ortholog of human COX8C, encodes a divergent, tissue-restricted paralog of the cytochrome c oxidase subunit 8 family whose expression is confined to a narrow set of tissues and is far lower than that of the ubiquitous Cox8a product, making it a candidate for isoform-specific tuning of complex IV rather than a core structural requirement. Where expressed, the protein is predicted to occupy the same peripheral position on the complex IV monomer as other subunit 8 isoforms, so functional consequences should appear as modest shifts in holoenzyme stability or assembly kinetics rather than as frank deficiency. A constitutive null is usually the correct first experiment here, since baseline phenotypes are poorly characterized and viability is not in question, while reporter-tagged alleles better define genuine expression domains. Given clear redundancy with Cox8a, plan compound alleles if an isoform-null respiratory readout is required, and restrict endpoints to high-resolution respirometry in tissues where Cox8c transcript is actually detectable.',
  Crebbp:
    'CREB binding protein, encoded by Crebbp and orthologous to human CREBBP, is a KAT3 family lysine acetyltransferase that deposits H3K18 and H3K27 acetylation at enhancers and, through KIX, TAZ1, TAZ2, bromodomain, and nuclear coactivator binding modules, bridges sequence-specific factors including CREB, TP53, MYB, and IRF proteins to the basal machinery. Lymphoma alleles are dominated by HAT domain missense substitutions such as R1446C and by truncations that reduce enhancer acetylation at MHC class II and BCL6 target loci, while germline heterozygous loss produces Rubinstein-Taybi syndrome. Homozygous deletion is embryonic lethal with hematopoietic and neural tube defects, making conditional deletion the practical route, and catalytically dead knockins separate acetyltransferase output from scaffolding. The paralog Ep300 shares substrates and buffers partial loss, which is exactly why CREBBP mutant tumors show heightened EP300 dependency. Use heterozygous conditional loss for immune evasion endpoints and compound Crebbp with Ep300 alleles for synthetic lethality validation.',
  Cstb:
    'Cstb is the mouse ortholog of human CSTB and encodes cystatin B (stefin B), a small monomeric cytosolic inhibitor of papain-family cysteine cathepsins that uses a wedge formed by its N-terminal glycine region and two hairpin loops to occlude the active sites of cathepsins B, L, S, and H, guarding against leaked lysosomal proteolysis. Loss produces oxidative stress, lysosomal instability, and cerebellar granule cell apoptosis, and mouse nulls develop progressive myoclonus, ataxia, and microglial activation reproducing human Unverricht-Lundborg disease, EPM1. Note a modeling constraint: most human EPM1 alleles are expansions of a dodecamer repeat in the CSTB promoter that reduce transcription, a mutation class that simple coding deletion cannot replicate, so promoter humanization or knockin of the repeat is required for expression-level fidelity. Related cystatins do not compensate in brain, so use the null for neurodegeneration endpoints and conditional alleles to test neuronal versus microglial origin.',
  Ctla4:
    'Ctla4, ortholog of human CTLA4, encodes CD152, an inhibitory CD28 family homodimer that shares the MYPPPY ligand motif but binds CD80 and CD86 with far higher avidity, outcompeting CD28 and physically stripping ligands from antigen presenting cells by transendocytosis, a cell-extrinsic mechanism central to regulatory T cell suppression. Surface residence is brief because the cytoplasmic YVKM motif recruits AP-2 for constitutive clathrin-mediated internalization and LRBA-dependent recycling, and the same motif engages PP2A and SHP-2. Germline deletion is catastrophic, with fatal lymphoproliferation, myocarditis, and pancreatitis by three to four weeks, so adult studies demand conditional flox alleles with Foxp3-Cre or Cd4-CreER to separate regulatory from conventional T cell requirements. No paralog compensates, since CD28 is the functional antagonist rather than a substitute. Humanized CTLA4 knockins are essential for ipilimumab and Fc-engineered antibody work, and haploinsufficient alleles suit human CTLA4 insufficiency and LRBA deficiency biology.',
  Ctnnb1:
    'To model Wnt signaling accurately, researchers must target Ctnnb1, the mouse ortholog of human CTNNB1, which encodes β-catenin, the central cytosolic pool and transcriptional effector of the canonical Wnt pathway. Upon pathway activation, β-catenin escapes destruction-complex phosphorylation, accumulates, and translocates to the nucleus to bind TCF/LEF factors, driving genes linked to stemness and oncogenesis. Consequently, model designs must explicitly separate absolute pathway collapse (via conditional null alleles) from hyperactivation (via exon 3 deletion or degron-evading mutations) or epitope-matched humanization for therapeutic antibody testing. Because homologous cadherin-associated or plakoglobin family members can functionally compensate for local loss, planning compound conditional genetics early prevents the discovery of masked phenotypes after a single-locus knockout. Ultimately, matching the specific Ctnnb1 allele class to your endpoint, whether assessing downstream signaling readouts, tumor latency in cooperation with partners like Apc, or drug response, is critical, as a trusted, validated Cre driver is just as vital as the flox design itself.',
  Ctsb:
    'Mouse Ctsb, ortholog of human CTSB, encodes cathepsin B, a papain-family lysosomal cysteine protease distinguished by an occluding loop that folds over the primed subsites, conferring carboxydipeptidase activity in addition to endopeptidase function. The proenzyme is trafficked by mannose-6-phosphate receptors and activated at acidic pH by autocatalysis or by cathepsin D and legumain, and its substrates span bulk lysosomal turnover, maturation of other proenzymes, extracellular matrix components after secretion, and inflammatory mediators, with lysosomal leakage of cathepsin B implicated in NLRP3 inflammasome activation, tumor invasion, and necrotic death. Nulls are viable and fertile, partly because cathepsins L, Z, and S share substrate space, so meaningful phenotypes often require compound Ctsb Ctsl or Ctsb Ctsz alleles. Use conditional deletion with myeloid or tumor cell Cre when localizing the relevant protease pool, and active site or occluding loop knockins when endopeptidase versus exopeptidase activity is the mechanistic question.',
  Ctsg:
    'Ctsg, ortholog of human CTSG, encodes cathepsin G, a chymotrypsin-family serine protease stored in mature form within neutrophil azurophilic granules alongside elastase and proteinase 3. Cathepsin G is unusual in possessing dual chymase-like and tryptase-like specificity, allowing it to process angiotensin, activate PAR4 on platelets, convert chemokines and cytokines, kill bacteria through combined catalytic and cationic antimicrobial activity, and decorate neutrophil extracellular traps. Maturation of cathepsin G, elastase, and proteinase 3 all requires dipeptidyl peptidase I (cathepsin C, Ctsc) removal of the activation dipeptide, so Ctsc deficiency phenocopies triple protease loss and offers a useful genetic shortcut. Because Elane and Prtn3 overlap substantially in substrate range and granule localization, single Ctsg nulls show only partial defects in bacterial killing and compound alleles are needed for clear phenotypes. Reserve humanization for inhibitor pharmacology where chymase pocket specificity differs by species, and use granulocyte-restricted conditional deletion for tissue injury endpoints.',
  Cx3cr1:
    'Cx3cr1, the mouse ortholog of human CX3CR1, encodes the Gi-coupled seven transmembrane receptor for fractalkine, the only CX3C chemokine, which is unusual in being tethered to the membrane by a mucin stalk so that it functions as an adhesion molecule until ADAM10 or ADAM17 shedding releases a soluble chemoattractant. The receptor marks microglia, patrolling monocytes and some natural killer and T cell subsets, and mediates neuron to microglia communication governing synaptic pruning. Allele design here carries a specific trap: the ubiquitous Cx3cr1-GFP and Cx3cr1-CreER tools are knockins that disrupt the coding sequence, so homozygous reporter animals are receptor nulls and heterozygous controls are essential. Humanized knockins additionally allow study of the human M280 variant associated with altered adhesion. Use tamoxifen-inducible deletion with appropriate chase periods to distinguish long-lived microglia from replenishing monocytes, then read process motility, synaptic engulfment, and lesion-associated recruitment.',
  Cyp26a1:
    'Cyp26a1, ortholog of human CYP26A1, encodes the principal retinoic acid catabolizing cytochrome P450, a microsomal enzyme that hydroxylates all-trans retinoic acid at carbon 4 and drives it toward oxo and polar metabolites, thereby carving retinoid-free zones adjacent to RALDH2-derived source domains and sharpening hindbrain, tailbud, and limb boundaries. The gene is itself a direct RAR target, forming a negative feedback loop that buffers retinoid excess, and its induction contributes to resistance against all-trans retinoic acid therapy in acute promyelocytic leukemia. Germline nulls die during gestation or shortly after birth with caudal truncation, spina bifida, and cervical vertebral transformations that phenocopy retinoid teratogenesis, so any postnatal or adult study requires conditional floxed alleles. Enzyme-dead knockins distinguish catalysis from expression, and humanized alleles are appropriate for testing CYP26 inhibitors such as talarozole. Because Cyp26b1 and Cyp26c1 clear retinoic acid in adjacent territories, compound conditionals are needed where domains abut, notably hindbrain rhombomeres.',
  Cyp26b1:
    'Encoding a second retinoic acid 4-hydroxylase, Cyp26b1 is the mouse ortholog of human CYP26B1 and shields specific tissues from retinoid exposure rather than shaping the trunk axis, most decisively in the fetal testis, where its expression in Sertoli and interstitial cells degrades retinoic acid to keep male germ cells from entering meiosis prematurely, and in skin, where it restrains epidermal retinoid tone. Germline deletion is lethal shortly after birth with a severe permeability barrier defect, limb and craniofacial abnormalities, and ectopic germ cell meiosis, while biallelic human variants cause craniosynostosis with radiohumeral fusion. That neonatal lethality makes conditional floxed alleles essential for adult skin, immune, and spermatogenic questions, and catalytically inactive knockins separate hydroxylase output from protein presence. Because Cyp26a1 and Cyp26c1 clear the same substrate in overlapping fields such as hindbrain, single-locus loss can be partially buffered. Match tissue-restricted Cre drivers, Krt14-Cre for barrier or Amh-Cre for Sertoli cells, to the specific retinoid threshold being tested.',
  Cyp26c1:
    'Cyp26c1, mouse ortholog of human CYP26C1, encodes the third retinoic acid hydroxylase of the family, distinguished by its ability to act on both all-trans and 9-cis retinoic acid and by a sharply restricted expression pattern in rhombomeres 2 and 4, first branchial arch, and inner ear, where it refines local retinoid clearance beyond what the other isoforms supply. Human variants combined with CYP26B1 lesions have been reported in focal facial dermal dysplasia, consistent with an additive retinoid-clearance requirement. Single nulls are viable and essentially normal, which is the central design fact: informative genetics requires compound deletion with Cyp26a1, where double mutants show markedly enhanced hindbrain and rostral patterning defects that neither allele produces alone. Accordingly, invest in a floxed allele that can be combined sequentially rather than a plain knockout, and consider enzyme-dead knockins when substrate preference between all-trans and 9-cis isomers is the question. Reserve humanization for inhibitor selectivity profiling against defined craniofacial or otic endpoints.',
  Dand5:
    'Dand5, the mouse ortholog of human DAND5 and also known as Cerl2 or Dante, encodes a secreted cysteine-knot DAN family antagonist that binds Nodal and restrains its activity specifically on the right side of the embryonic node, where leftward cilia-driven flow degrades its transcripts to break symmetry and permit left-sided Nodal, Lefty2, and Pitx2 expression. The gene therefore sits at the mechanotransduction to transcription interface of left-right patterning, downstream of Pkd2 and ciliary function and upstream of lateral plate asymmetry. Nulls are born with randomized cardiac looping, situs anomalies, and variable perinatal lethality, and human heterozygous variants segregate with laterality defects and congenital heart disease, so patient-matched missense knockins are often more faithful than complete deletion. Conditional alleles are less critical here than precise timing and node-restricted analysis, though floxed designs help dissect later cardiac roles. Related antagonists Cer1 and Lefty1 overlap partially, so compound genetics clarifies which Nodal pool is being controlled at each endpoint.',
  Daxx:
    'Death domain associated protein, encoded by Daxx and orthologous to human DAXX, is a dedicated histone chaperone that captures the H3.3 to H4 dimer through variant-specific recognition of alanine 87, isoleucine 89, and glycine 90, then hands it to ATRX for deposition at telomeres, pericentromeric repeats, and endogenous retroviral elements. SUMO-interacting motifs additionally localize it to PML nuclear bodies, where it sequesters transcription factors and modulates apoptotic signaling. Inactivating mutations co-occur with ATRX loss in pancreatic neuroendocrine tumors and drive alternative lengthening of telomeres through defective heterochromatin maintenance and replication stress at repeats. Constitutive deletion causes embryonic lethality near E9.5 with widespread apoptosis, so conditional alleles paired with lineage or tamoxifen-inducible Cre are essential for adult tumor work. ATRX cannot substitute for chaperone activity, making compound analysis informative rather than redundant. Align allele class with telomere maintenance, retroelement derepression, or tumor latency as the intended readout.',
  Deptor:
    'Deptor, mouse ortholog of human DEPTOR, encodes a naturally occurring inhibitor of both mTOR complexes, using tandem DEP domains and a C-terminal PDZ domain that binds the FAT domain of mTOR to suppress mTORC1 and mTORC2 catalytic output toward S6K1, 4E-BP1 and AKT serine 473. Regulation is largely post-translational: active mTORC1 and CK1 alpha phosphorylate DEPTOR to create a beta-TrCP degron, so growth factor stimulation degrades its own brake in a feedforward loop, while nutrient withdrawal restores it. Loss of DEPTOR relieves mTORC1 inhibition but also removes the negative feedback that normally suppresses PI3K and AKT, so overexpression in a subset of multiple myeloma paradoxically sustains AKT activity, a genuinely counterintuitive result that allele design must respect. Constitutive nulls are viable, permitting simple alleles, but conditional deletion or degron-resistant knockins are far more informative for dissecting feedback. Match allele to endpoint, using knockins when the question is loop architecture rather than net mTOR flux.',
  Dhh:
    'Dhh, mouse ortholog of human DHH, encodes Desert hedgehog, an autoprocessing morphogen that undergoes intramolecular cleavage with cholesterol modification and palmitoylation before binding PTCH1 to relieve inhibition of SMO, stabilizing GLI2 and GLI3 for target transcription. Unlike the broadly expressed SHH, its expression is restricted chiefly to Sertoli cells, where it acts on peritubular and Leydig progenitors to drive steroidogenic differentiation, and to Schwann cells, where it builds the perineurium and nerve-blood barrier. Human biallelic mutations cause 46,XY gonadal dysgenesis with or without minifascicular polyneuropathy, a phenotype well matched by patient-derived missense knockins that impair processing or receptor binding. Mouse nulls are viable but males show Leydig hypoplasia, infertility, and abnormal nerve sheaths, so constitutive deletion is workable while conditional floxed alleles with Amh-Cre or Dhh-Cre separate testicular from peripheral nerve requirements. Because Shh and Ihh signal through the same PTCH1 and SMO machinery, interpret pathway-level readouts with paralog expression documented for the tissue scored.',
  Dkk1:
    'Dkk1, the mouse ortholog of human DKK1, encodes a secreted glycoprotein with two cysteine rich domains that antagonizes canonical Wnt signaling by binding the third and fourth beta-propeller modules of LRP5 and LRP6 with high affinity, blocking Wnt induced LRP6 signalosome assembly with Frizzled, and in some contexts cooperating with Kremen1 and Kremen2 to internalize the coreceptor. Its function is strictly extracellular and dose dependent, which is why heterozygotes show measurable phenotype and why DKK1 neutralizing antibodies are tested in myeloma bone disease and osteoporosis. Germline null embryos die at birth lacking anterior head structures and with limb malformation because DKK1 is required for head organizer activity, so conditional deletion is necessary for adult bone and hematopoietic questions. Dkk2 and Dkk4 bind the same LRP sites, with DKK2 acting as agonist or antagonist depending on Kremen levels, so compound alleles matter. Use conditional nulls for tissue Wnt tone and humanized knockins when testing antibody epitope engagement.',
  Dlat:
    'Dlat is the mouse ortholog of human DLAT and encodes the E2 dihydrolipoamide S-acetyltransferase that forms the trimeric 60-subunit core of the pyruvate dehydrogenase complex, presenting lipoyl domains that swing acetyl groups from E1 to coenzyme A and thereby committing glycolytic pyruvate to acetyl-CoA and the TCA cycle. The lipoyl arm, installed by LIAS and LIPT1, also makes E2 the docking platform for E1, E3 and E3BP, so its loss removes the scaffold on which flux control by Pdk kinases and Pdp phosphatases operates. Complete deficiency produces congenital lactic acidosis, so conditional nulls with Alb-Cre, Ckmm-Cre or Nes-Cre are the practical route for isolating tissue-specific pyruvate oxidation defects, while patient missense knockins retain partial activity and model graded disease. Lipoylated E2 is also the dominant autoantigen of primary biliary cholangitis, making humanized alleles attractive for immunological endpoints; match allele to readout, whether carbon 13 pyruvate tracing, blood lactate, or PDH activity assays.',
  Dld:
    'Mouse Dld, ortholog of human DLD, specifies the FAD-dependent homodimeric E3 dihydrolipoamide dehydrogenase shared by four mitochondrial systems, pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, branched-chain ketoacid dehydrogenase and the glycine cleavage complex, where it reoxidizes reduced lipoamide and passes electrons to NAD+. This shared architecture explains why human DLD mutations cause combined E3 deficiency with simultaneous lactic acidemia, elevated alpha-ketoglutarate, branched-chain ketoaciduria and sometimes hyperglycinemia, and why the enzyme is itself a significant source of reactive oxygen species. Because a global null removes four dehydrogenase activities at once and is not survivable, conditional alleles are the workable design, with hepatocyte, neuronal or cardiomyocyte Cre lines separating hepatic decompensation from encephalopathy and cardiomyopathy. Patient variant knockins, particularly those at the dimer interface, better reproduce the partially active and temperature-sensitive human enzyme. Align allele to endpoint, whether organic acid profiling, complex-resolved dehydrogenase activity assays, or fasting and catabolic stress challenge.',
  Dlg1:
    'Dlg1, ortholog of human DLG1, encodes SAP97, a membrane-associated guanylate kinase built from three PDZ domains, an SH3 module and a catalytically inactive guanylate kinase domain, whose alternatively spliced N-terminal L27 or palmitoylated variants determine whether it acts in epithelial polarity with Scribble and Lgl or in neuronal receptor trafficking. In neurons it escorts GluA1 through the secretory pathway and binds Kv1.4 and the cardiac sodium channel Nav1.5, linking it to both synaptic delivery and excitability, while in epithelia it enforces basolateral identity and is a target of viral oncoproteins. Constitutive nulls die perinatally with cleft palate, urogenital and kidney defects, so a conditional null is mandatory for adult neural work; pair Camk2a-Cre for forebrain synapses or a cardiomyocyte driver for conduction endpoints. Dlg2, Dlg3 and Dlg4 share domain architecture and partially substitute at the postsynaptic density, so compound alleles and direct receptor surface measurements are advisable.',
  Dlg2:
    'Encoding PSD-93, also called chapsyn-110, Dlg2 is the mouse ortholog of human DLG2 and a palmitoylated membrane-associated guanylate kinase whose N-terminal cysteines drive raft targeting and whose PDZ1 and PDZ2 domains bind the ESDV motif of GluN2A and GluN2B, clustering NMDA receptors and Kv1 channels at the postsynaptic density while its guanylate kinase domain recruits GKAP and the Shank and Homer scaffold layer. It preferentially stabilizes GluN2A-containing receptors in mature synapses, giving it a developmental profile distinct from SAP102. Rare deletions and exonic copy number variants at the human locus are established risk factors for schizophrenia and intellectual disability, making dosage-sensitive alleles biologically relevant. Constitutive nulls are viable with mild synaptic phenotypes, so a heterozygous or conditional deletion better mirrors human haploinsufficiency, and Camk2a-Cre or interneuron drivers assign circuit contributions. Dlg1, Dlg3 and Dlg4 compensate substantially, so quantify all four paralogs after deletion.',
  Dlg3:
    'Dlg3 encodes SAP102, ortholog of human DLG3, a membrane-associated guanylate kinase distinguished from PSD-95 by the absence of N-terminal palmitoylation and by an alternatively spliced insert that binds mPins and exportin, features that make it the dominant NMDA receptor scaffold in immature synapses where it preferentially associates with GluN2B-containing receptors and supports their delivery before PSD-95 and PSD-93 take over. Its PDZ domains also engage GluA2 and the exocyst, giving it a role in receptor trafficking as well as anchoring. Truncating mutations in the X-linked human gene cause nonsyndromic intellectual disability, so hemizygous male mice provide a directly comparable dosage model. Constitutive nulls are viable with impaired learning and altered synaptic plasticity, though the developmental window matters: phenotypes are strongest early and are progressively masked as Dlg4 and Dlg2 expression rises. Plan conditional deletion with early drivers such as Nes-Cre and score juvenile plasticity rather than adult endpoints alone.',
  Dlg4:
    'PSD-95, encoded by Dlg4 as the ortholog of human DLG4, is the dominant scaffold of the excitatory postsynaptic density, anchored by palmitoylation of Cys3 and Cys5 and organizing receptors through PDZ1 and PDZ2 binding to the GluN2 ESDV motif and to transmembrane AMPA receptor regulatory protein C-termini including γ-8, while PDZ2 recruits nNOS and the guanylate kinase domain assembles the GKAP, Shank and Homer layers. Its abundance sets AMPA receptor content per synapse, and disruption of the nNOS interaction is an established stroke neuroprotection strategy. Constitutive nulls are viable but show markedly enhanced long-term potentiation, absent long-term depression and impaired spatial learning, so lethality is not a constraint; a conditional null with Camk2a-Cre isolates forebrain contributions and a palmitoylation-site or PDZ-binding knockin separates membrane anchoring from protein interaction. Because Dlg1, Dlg2 and Dlg3 upregulate and partly substitute, compound conditional genetics and quantitative postsynaptic density proteomics should be planned from the start.',
  Dll1:
    'Dll1, ortholog of human DLL1, encodes Delta-like 1, a single-pass transmembrane Notch ligand with an N-terminal MNNL and DSL domain plus tandem EGF repeats that engages NOTCH1 and NOTCH2 in trans, and whose activity depends on MIB1-mediated ubiquitination and endocytic pulling force to expose the S2 cleavage site for ADAM10 and gamma-secretase. Oscillatory expression in presomitic mesoderm couples the segmentation clock to somite boundary formation, and the ligand also governs neural progenitor lateral inhibition, muscle progenitor maintenance, and intestinal secretory fate. Germline nulls die at midgestation with disorganized somites and vascular defects, so conditional floxed alleles are required for adult neurogenesis, myogenesis, or intestinal work, and human haploinsufficiency causing neurodevelopmental disorder argues for heterozygous or hypomorphic designs. Since Dll4 and Jag1 activate the same receptors in overlapping fields, compound conditionals prevent misattributing residual signaling. Pair the flox with Sox2-Cre, Pax7-CreER, or Villin-CreER according to whether the endpoint is progenitor pool size, regeneration, or lineage allocation.',
  Dll3:
    'Dll3, the mouse ortholog of human DLL3, encodes a divergent Delta-like protein that lacks a functional DSL domain and fails to trans-activate Notch, instead accumulating in the Golgi and late endosomes where it acts as a cis-inhibitor by retaining NOTCH1 and DLL1 and preventing their surface presentation, thereby modulating the segmentation clock. Loss in mouse yields the pudgy phenotype with severely disorganized vertebrae and ribs, matching human biallelic mutations that cause spondylocostal dysostosis type 1, so constitutive nulls are directly informative for axial skeletal endpoints. The dominant contemporary interest is oncologic: aberrant surface expression in small cell lung cancer and neuroendocrine tumors makes the protein a target for antibody drug conjugates, bispecific T cell engagers such as tarlatamab, and CAR designs, none of which cross-react between species. Consequently, epitope-matched humanized knockins are the correct allele for efficacy and on-target toxicity studies, while floxed conditionals suit developmental questions. Related Dll1 partially overlaps in presomitic mesoderm but cannot substitute for cis-inhibition.',
  Dll4:
    'Dll4, mouse ortholog of human DLL4, encodes the arterial and tip cell restricted Notch ligand that engages NOTCH1 on adjacent endothelial cells, and its lateral inhibition of neighboring stalk cells, reinforced by VEGFA-driven induction and antagonized by JAG1, sets sprouting density during angiogenesis while specifying arterial identity and thymic T cell commitment. The locus is unusual in being haploinsufficient: heterozygous deletion is embryonic lethal on many backgrounds with severe vascular remodeling failure, which means even a well-designed conditional must be genotyped and monitored for allele dosage effects and the floxed allele validated as truly silent before recombination. Blockade produces nonproductive hypersprouting and, in preclinical and clinical work, vascular neoplasms and hepatic toxicity, so epitope-matched humanization is essential for antibody or ligand-trap testing. Use Cdh5-CreER for endothelial or Foxn1-Cre for thymic questions, and interpret partial phenotypes against Jag1 expression in the same field. Match allele class to whether the endpoint is vessel density, arterial marker expression, or tumor perfusion.',
  Dnmt1:
    'Maintenance of CpG methylation depends on Dnmt1, the mouse ortholog of human DNMT1, whose catalytic domain is held autoinhibited by CXXC and BAH modules until UHRF1 delivers hemimethylated DNA and ubiquitinates histone H3, while PCNA tethering couples the enzyme to the replication fork. Loss produces genome-wide hypomethylation, retroelement derepression, loss of imprinting, and chromosomal instability, and homozygous deletion is embryonic lethal around E9.5, whereas hypomorphic alleles that reduce activity to a fraction of normal survive and develop thymic lymphoma, demonstrating that graded dosage rather than binary loss drives tumor phenotypes. Design choices follow directly: hypomorphic and conditional alleles address graded hypomethylation and tumor susceptibility, catalytically dead knockins separate methyltransferase output from scaffolding, and knockins supporting hypomethylating agent studies address pharmacology. The de novo enzymes Dnmt3a and Dnmt3b cannot restore maintenance activity, so assume no compensation when interpreting conditional deletion in adult tissues.',
  Dnmt3a:
    'De novo methylation in hematopoiesis is dominated by Dnmt3a, ortholog of human DNMT3A, whose ADD domain is released from autoinhibition upon reading unmethylated H3K4, whose PWWP domain docks on H3K36 dimethylation to direct intergenic and heterochromatic targeting, and whose catalytic domain forms active tetramers with DNMT3L or DNMT3B. The leukemia hotspot R882H sits at the substrate binding interface and acts dominantly by poisoning tetramer formation, reducing methylation output well below simple haploinsufficiency and driving clonal hematopoiesis, AML, and T cell lymphoma. Design should therefore distinguish a conditional null, which reports stem cell self-renewal and differentiation blockade, from an inducible R882H knockin, which reproduces the dominant-negative epigenetic state seen in patients. Constitutive nulls survive gestation but die within weeks after birth, so conditional deletion with Mx1-Cre or Vav-Cre plus transplantation is standard. Dnmt3b overlaps only partially, and compound deletion collapses methylation far more severely than either allele alone.',
  Dnmt3b:
    'Dnmt3b, the mouse ortholog of human DNMT3B, encodes a de novo DNA methyltransferase whose PWWP domain preferentially engages H3K36 trimethylation across gene bodies and whose activity is required for methylation of pericentromeric minor satellite repeats, germline gene promoters, and inactive X chromosome CpG islands. Hypomorphic catalytic domain substitutions cause immunodeficiency, centromeric instability, and facial anomalies syndrome, while overexpression of catalytically active and inactive isoforms accompanies promoter hypermethylation in colorectal and hematologic malignancy. Homozygous deletion is lethal in mid to late gestation with neural tube and growth defects, so conditional alleles are the practical route to adult tissue analysis, and knockin of specific syndromic substitutions models graded catalytic loss rather than absence of protein. Dnmt3a covers overlapping but non-identical targets, and only compound deletion broadly collapses de novo methylation. Match allele class to whether the endpoint is repeat methylation, imprint establishment, or tumor promoter hypermethylation.',
  E2f1:
    'E2f1, mouse ortholog of human E2F1, encodes an activator E2F that heterodimerizes with DP1 or DP2 through its dimerization domain and binds TTTCCCGC consensus elements, driving the S phase transcriptional program including cyclin E, CDC6, MCM proteins and thymidine kinase. Its transactivation domain is masked by hypophosphorylated RB, and CDK4/6 and CDK2 mediated RB phosphorylation releases it at the restriction point. Uniquely among E2Fs, E2F1 is stabilized by ATM and CHK2 phosphorylation after DNA damage and induces apoptosis through ARF, TP73 and APAF1, giving it both oncogenic and tumor suppressive character, which is exactly why null mice develop tissue-specific tumors rather than being protected. Constitutive nulls are viable with thymic hyperplasia and testicular atrophy, so simple alleles work. Because E2f2 and E2f3 bind identical sites and compensate substantially, compound alleles are required for proliferation endpoints. Reserve single nulls for apoptotic threshold and damage response, and use conditional triple activator alleles for cell cycle exit studies.',
  E2f2:
    'Encoding a second activator E2F, E2f2 is the mouse ortholog of human E2F2 and produces a DP-heterodimerizing transcription factor with a winged helix DNA binding domain, a marked box domain mediating cofactor contacts, and a C-terminal transactivation and RB pocket binding region, occupying the same S phase promoters as E2F1 and E2F3 downstream of CDK dependent RB inactivation. Its distinguishing biology is immunological: E2F2 restrains T lymphocyte proliferation and null mice develop enhanced T cell activation with autoantibody production and a lupus-like autoimmune syndrome, and it also contributes to pancreatic beta cell mass. Because nulls are viable, constitutive alleles suffice for immunology work, while conditional alleles are preferable when separating lymphoid from stromal contributions. Redundancy within the activator subfamily is substantial, since E2f1 and E2f3 occupy overlapping targets, so proliferative phenotypes appear only in compound backgrounds. Match design to endpoint, using single nulls for autoimmunity and compound activator alleles when the readout is cell cycle entry or RB pathway dependency.',
  E2f3:
    'E2f3, the mouse ortholog of human E2F3, encodes the most proliferation-critical activator E2F and produces two isoforms from alternative promoters, E2F3a induced at the G1/S boundary and E2F3b expressed constitutively, both heterodimerizing with DP proteins and both repressed by RB pocket binding until CDK mediated phosphorylation. E2F3 loss reduces expression of the core replication program more severely than loss of E2F1 or E2F2, and E2F3 amplification at 6p22 drives bladder and small cell lung carcinoma, while E2F3 is also required for the proliferative burst that follows RB inactivation, making it the principal mediator of RB pathway dependency. Null viability is strongly strain dependent, with most nulls dying perinatally on inbred backgrounds, so conditional floxed alleles and isoform-specific knockins are the safer design. Given real redundancy with E2f1 and E2f2, compound conditional stocks are needed to expose requirement. Choose isoform-specific alleles when the question is RB pathway output versus constitutive housekeeping transcription.',
  Egf:
    'Egf, mouse ortholog of human EGF, encodes not a simple 53 residue peptide but a large transmembrane precursor containing nine EGF-like repeats, from which the mature ligand is liberated by ADAM10 and ADAM17 mediated ectodomain shedding, a regulated step that determines autocrine and paracrine availability. Mature EGF binds EGFR domains I and III with high affinity, stabilizing the extended conformation that exposes the dimerization arm and triggers asymmetric kinase dimer formation, and unlike TGF alpha it remains bound at endosomal pH and thereby routes receptor toward lysosomal degradation rather than recycling, a trafficking distinction with real signaling duration consequences. Null mice are viable with mild epithelial and renal phenotypes because Tgfa, Areg, Hbegf, Btc, Ereg and Epgn all engage the same receptor, so single deletion is nearly uninformative and compound ligand alleles are essential. Use conditional nulls when asking about a specific stromal or epithelial source, and reserve ligand humanization for antibody and ligand trap pharmacology.',
  Egfr:
    'Egfr, the mouse ortholog of human EGFR, encodes ERBB1, a receptor tyrosine kinase whose extracellular domains I through IV adopt a tethered autoinhibited conformation until ligand binding to domains I and III exposes the domain II dimerization arm, permitting formation of an asymmetric kinase dimer in which one lobe allosterically activates the other, with autophosphorylated C-terminal tyrosines recruiting GRB2, SHC and PLC gamma to fire RAS-MAPK and PI3K-AKT. Oncogenic exon 19 deletions and L858R destabilize the inactive kinase conformation and confer TKI sensitivity, T790M and C797S confer resistance, and the vIII extracellular truncation drives glioblastoma. Critically, mouse Egfr is not bound by cetuximab and differs in domain III epitopes, so ectodomain humanization is mandatory for antibody and antibody-drug conjugate testing, while inducible mutant knockins model TKI response. Germline nulls die perinatally with strain-dependent severity, so conditional alleles plus a lineage Cre are required for adult skin, intestinal or lung studies.',
  Eif4ebp1:
    'Eif4ebp1, mouse ortholog of human EIF4EBP1, encodes 4E-BP1, the principal translational repressor downstream of mTORC1, which binds eIF4E through a canonical YXXXXL phi motif plus a secondary elongated interface and thereby blocks eIF4G recruitment and cap-dependent initiation. RAPTOR docks the TOS motif and mTORC1 phosphorylates a hierarchical series beginning at threonines 37 and 46, then threonine 70 and serine 65, progressively releasing eIF4E and licensing translation of 5 prime TOP and eIF4E-sensitive mRNAs including cyclin D1, MCL1 and MYC. Because 4E-BP1 phosphorylation is rapamycin-resistant relative to S6K1, it is the readout that distinguishes true mTOR kinase inhibitors from rapalogs. Nonphosphorylatable knockin alleles carrying alanine substitutions at the four regulatory sites give constitutive repression and are far more informative than a null for testing whether a tumor depends on cap-dependent translation. Eif4ebp2 and Eif4ebp3 compensate, especially in brain, so compound alleles are needed before concluding requirement.',
  Elane:
    'Elane is the mouse ortholog of human ELANE and encodes neutrophil elastase, a chymotrypsin-fold serine protease packaged into azurophilic granules after cathepsin C dependent propeptide removal, where it degrades elastin, collagens, and bacterial outer membrane protein A, inactivates tissue factor pathway inhibitor, processes chemokines, and drives chromatin decondensation during neutrophil extracellular trap formation, restrained extracellularly by alpha-1 antitrypsin and SLPI. The disease logic here is misfolding rather than lost proteolysis: human ELANE mutations cause severe congenital and cyclic neutropenia through mistrafficking and unfolded protein response driven apoptosis of promyelocytes, so an Elane null does not phenocopy the human condition and knockin of specific patient alleles, ideally within a humanized locus, is the only faithful design. Cathepsin G and proteinase 3 overlap for extracellular substrate degradation, meaning compound alleles are needed for protease-driven tissue injury studies, while sivelestat class inhibitor programs require humanization for potency assessment.',
  Eno1:
    'Eno1, the mouse ortholog of human ENO1, encodes alpha-enolase, the magnesium-dependent dimeric lyase that dehydrates 2-phosphoglycerate to phosphoenolpyruvate in the payoff phase of glycolysis and supplies substrate to pyruvate kinase. Beyond catalysis the locus produces MBP-1 by alternative translation, a nuclear repressor acting at the MYC P2 promoter, and surface-displayed alpha-enolase serves as a plasminogen receptor on leukocytes and tumor cells, so phenotypes may be metabolic, transcriptional or proteolytic. Rare human ENO1 loss causes hemolytic anemia, while ENO1 deletion in glioma creates collateral lethality with ENO2 dependence. Allele strategy divides sharply: a conditional null tests glycolytic dependence within a defined lineage, a catalytically dead knockin separates enzymatic from moonlighting functions, and humanization enables evaluation of enolase inhibitors with human-selective pharmacology. Because Eno2 and Eno3 substitute in neurons and muscle respectively, confine conclusions to tissues where alpha-enolase dominates, and prioritize flux measurements over transcript abundance as endpoints.',
  Eno2:
    'Neuronal glycolysis depends on Eno2, the mouse ortholog of human ENO2, which encodes gamma-enolase (neuron-specific enolase), the isoform that replaces alpha-enolase during neuronal maturation and converts 2-phosphoglycerate to phosphoenolpyruvate; its release into serum underlies the NSE biomarker used in neuroendocrine and small cell lung tumors. Gamma-enolase additionally carries a neurotrophic, plasminogen-binding activity at the neuronal surface that promotes axonal growth, a function separable from catalysis. Design decisions hinge on which activity is under test: a conditional null with Syn1-Cre or Nes-Cre probes neuronal glycolytic reserve and synaptic energetics, a catalytically dead knockin isolates the extracellular neurotrophic role, and a humanized allele supports biomarker and inhibitor work, including glioma studies that exploit ENO1-deleted, ENO2-dependent tumors. Because Eno1 persists in glia and immature neurons, interpret residual enolase activity cautiously, and align allele with endpoints such as regional lactate flux, electrophysiology, and axon regeneration after injury.',
  Eno3:
    'Skeletal muscle relies on Eno3, ortholog of human ENO3, which encodes beta-enolase, the isoform that accumulates during myogenesis and carries most 2-phosphoglycerate to phosphoenolpyruvate conversion in fast glycolytic fibers, coupling glycogenolytic flux to ATP supply during burst contraction. Recessive ENO3 mutations cause glycogen storage disease type XIII, with exercise intolerance, myalgia and elevated creatine kinase but no fixed weakness, a presentation that reflects partial rather than absolute loss of glycolytic capacity. That disease logic favors knockin of patient missense alleles over a clean null, since residual activity produces the exertional, load-dependent phenotype, whereas a muscle-restricted conditional null with Ckmm-Cre or Myf5-Cre defines the ceiling of glycolytic dependence and consequent fiber-type remodeling. Eno1 persists in muscle and partially compensates, so quantify isoform ratios before attributing any phenotype to beta-enolase. Match allele to endpoint, whether treadmill and grip performance, phosphorus 31 magnetic resonance spectroscopy of phosphocreatine recovery, or single-fiber metabolic profiling.',
  Ep300:
    'Ep300 encodes p300, the mouse ortholog of human EP300 and the second KAT3 family acetyltransferase, which deposits H3K27 acetylation to mark active enhancers, requires autoacetylation of its activation loop for full catalysis, and uses TAZ1, TAZ2, KIX, and bromodomain modules to nucleate coactivator assemblies with HIF1A, TP53, MYB, and nuclear receptors. Cancer alleles include truncations and HAT domain missense mutations in bladder carcinoma, lymphoma, and colorectal tumors, and the paralog relationship is asymmetric enough that CREBBP mutant tumors become dependent on residual p300, an actionable synthetic lethality now targeted by catalytic and bromodomain inhibitors. Homozygous deletion causes embryonic lethality with cardiac and neural defects, so conditional alleles are mandatory for adult studies, and HAT-dead knockins separate enzymatic from scaffolding contributions. Because Crebbp compensates at many enhancers, single conditional deletion often yields muted transcriptional phenotypes, so plan compound genetics with Cre drivers matched to the tumor lineage.',
  Epas1:
    'Epas1, the mouse ortholog of human EPAS1, encodes HIF2 alpha, a bHLH-PAS transcription factor that dimerizes with ARNT and, in normoxia, is hydroxylated at prolines 405 and 531 by EGLN1 and related prolyl hydroxylases, creating the VHL recognition site for proteasomal destruction, while FIH hydroxylation of an asparagine blocks p300 recruitment. HIF2 alpha drives a target set biased toward erythropoietin, VEGFA and the endothelial and renal programs, distinct from the glycolytic bias of HIF1 alpha. Gain of function mutations at the hydroxylation sites cause erythrocytosis with paraganglioma and pheochromocytoma, and the druggable PAS-B cavity is the basis of belzutifan, so a knockin of a hydroxylation-resistant allele such as the human P531 variant is the appropriate tool for testing HIF2 alpha selective inhibitors. Null mice show strain-dependent embryonic and perinatal lethality from catecholamine and vascular defects, so conditional deletion is preferable. Hif1a occupies overlapping HREs, making double conditional alleles necessary for isoform assignment.',
  Erbb2:
    'Erbb2, mouse ortholog of human ERBB2 and historically called Neu, encodes the ERBB family member that binds no known ligand because its extracellular region is constitutively fixed in the extended, dimerization-competent conformation, making it the preferred heterodimerization partner for ligand-bound EGFR, ERBB3 and ERBB4 and the most potent signaling partner in the family. Amplification at 17q12 drives breast and gastric carcinoma, whereas the rat transmembrane V664E substitution and human extracellular and kinase domain missense variants act through enhanced dimerization. Trastuzumab and pertuzumab recognize subdomain IV and subdomain II epitopes that differ between mouse and human, so ectodomain humanized knockins are the only rigorous platform for antibody and antibody-drug conjugate efficacy and cardiotoxicity work. Germline null embryos die from failed cardiac trabeculation and cranial neural crest defects, requiring conditional alleles. Because ERBB2 signals only as a heterodimer, Erbb3 is functionally obligate for PI3K output, so pair alleles accordingly and select a mammary-restricted Cre for tumor studies.',
  Erbb3:
    'Erbb3, the mouse ortholog of human ERBB3, encodes a pseudokinase family member that binds neuregulin 1 and neuregulin 2 through extracellular domains I and III but carries substitutions in the catalytic loop that render it essentially kinase dead, so it functions as an allosteric activator of a partner kinase and, critically, as the ERBB family member with six YXXM motifs in its C-terminal tail that directly recruit the p85 subunit of PI3K. This makes ERBB3 the dominant conduit to AKT for ERBB2 amplified tumors and the principal mechanism of adaptive resistance to EGFR and ERBB2 targeted agents, since relief of feedback rapidly upregulates ERBB3. Null embryos die at midgestation with cardiac cushion and Schwann cell precursor defects, so conditional alleles are needed for adult work. Humanized ectodomain knockins support testing of ERBB3 antibodies and bispecifics whose epitopes do not cross-react. Choose conditional nulls for PI3K dependency and resistance studies, paired with an epithelial or Schwann cell Cre.',
  Erbb4:
    'Erbb4, mouse ortholog of human ERBB4, encodes the only ERBB member that is both a fully active tyrosine kinase and a regulated intramembrane proteolysis substrate, binding neuregulins 1 through 4 and heparin binding EGF. Alternative splicing generates JM-a isoforms that contain a TACE and ADAM17 cleavage site permitting ectodomain shedding followed by gamma-secretase release of a soluble intracellular domain that translocates to the nucleus and partners with YAP, STAT5A and ETO2, versus JM-b isoforms that are not cleavable, and CYT-1 isoforms that carry a PI3K p85 binding site versus CYT-2 isoforms that do not. This isoform architecture means a conventional null conflates four biologically distinct receptors, so isoform-selective knockins are the correct design for neurodevelopmental, cardiac and mammary questions. Null mice die at midgestation from cardiac trabeculation failure and cranial ganglion defects, requiring conditional alleles. Erbb2 is the obligate heterodimer partner, so pair alleles when testing whether phenotypes reflect receptor loss or dimer loss.',
  Esr1:
    'Esr1, the mouse ortholog of human ESR1, encodes estrogen receptor alpha, a nuclear receptor with a ligand-independent AF-1 region, a zinc finger DNA binding domain that recognizes palindromic estrogen response elements as a homodimer, and a ligand binding domain whose helix 12 repositioning creates the AF-2 surface for NCOA coactivators, with additional membrane-initiated signaling from a palmitoylated pool. Acquired ligand binding domain mutations Y537S and D538G stabilize the agonist conformation and drive endocrine therapy resistance, whereas ESR1 fusions and amplification act by other routes, so a conditional knockin of Y537S is the right tool for resistance pharmacology and a floxed null answers lineage requirement in mammary epithelium, uterus, bone, hypothalamus and vasculature. Separation-of-function knockins that disable DNA binding or AF-2 distinguish genomic from nongenomic signaling. Null mice are viable but infertile with uterine hypoplasia, so constitutive alleles are usable, though Esr2 mediates distinct ovarian functions rather than compensating. Pair conditional alleles with a tissue-matched Cre.',
  Ezh2:
    'Ezh2, ortholog of human EZH2, encodes the SET domain catalytic subunit of polycomb repressive complex 2, which requires EED and SUZ12 for activity and is allosterically stimulated when the EED aromatic cage binds preexisting H3K27 trimethylation, generating the spreading repressive domains that silence developmental and tumor suppressor loci. Disease alleles run in opposite directions: Y646 substitutions in the SET domain shift substrate preference toward the final trimethylation step and hyperactivate the enzyme in germinal center lymphoma, whereas nonsense and missense loss-of-function mutations occur in myelodysplastic syndrome and T cell leukemia. Model design must reflect this, using a conditional inducible Y646 knockin for lymphoma and inhibitor response work and a conditional null for myeloid loss-of-function questions. Constitutive deletion is embryonic lethal near gastrulation, so Cre-dependent alleles are required, and the paralog Ezh1 sustains residual H3K27 methylation in quiescent and postmitotic tissues, meaning compound Ezh1 deletion may be needed to unmask phenotypes.',
  F10:
    'F10 encodes coagulation factor X, the mouse ortholog of human F10 and the convergence point of the intrinsic and extrinsic cascades. The vitamin K dependent zymogen carries an amino-terminal Gla domain whose gamma-carboxyglutamate residues mediate calcium-dependent phospholipid binding, two EGF-like modules, and a trypsin-like protease domain; activation by the tissue factor and factor VIIa complex or by the factor IXa and factor VIIIa intrinsic tenase generates factor Xa, which assembles with factor Va on activated platelet membranes into prothrombinase to convert prothrombin to thrombin, and is checked by antithrombin and tissue factor pathway inhibitor. Complete deficiency is not survivable in mouse, causing embryonic and perinatal lethality from hemorrhage, so hypomorphic or conditional alleles are required for adult phenotyping. Low-expressing knockins that titrate factor X to a few percent of normal are the established route for bleeding and thrombosis endpoints, whereas humanized knockins suit direct oral anticoagulant and reversal agent pharmacology.',
  F11:
    'Mouse F11, ortholog of human F11, encodes coagulation factor XI, a disulfide-linked homodimer in which each subunit contributes four apple domains and a trypsin-like catalytic domain; the apple modules dock high molecular weight kininogen, platelet GPIb, heparin, and the substrate factor IX. Factor XI is activated by factor XIIa during contact activation or, more relevant in vivo, by thrombin feedback on polyanionic surfaces, and factor XIa then cleaves factor IX to sustain intrinsic tenase and thrombin amplification. The therapeutic appeal is asymmetry: human factor XI deficiency causes only injury-related bleeding while mouse nulls are protected from arterial and venous thrombosis, uncoupling hemostasis from pathological clotting and underpinning abelacimab and milvexian development. Nulls are viable, so a conditional allele is not strictly required, though hepatocyte-restricted deletion clarifies the source. Humanized knockins are the appropriate design when antibodies or small molecules targeting human apple domains or the catalytic pocket are being tested.',
  F12:
    'F12 encodes factor XII (Hageman factor), the mouse ortholog of human F12, a zymogen with fibronectin type I and II, EGF, and kringle domains plus a proline-rich region that autoactivates upon contact with polyanionic surfaces including polyphosphate, misfolded protein aggregates, collagen, and artificial materials. Factor XIIa then cleaves prekallikrein to plasma kallikrein, which reciprocally amplifies factor XII activation and liberates bradykinin from high molecular weight kininogen, and it activates factor XI to feed intrinsic coagulation. This dual output makes F12 the entry point for both contact-driven thrombosis and kinin-mediated vascular permeability, with human gain-of-function variants such as Thr309Lys causing hereditary angioedema despite normal C1 inhibitor. Nulls display normal hemostasis yet are protected in arterial thrombosis and stroke models, precisely the dissociation of interest. Knockins of angioedema-associated alleles are the design for permeability and attack-driven endpoints, whereas humanization supports antibody and antisense programs directed at human factor XII.',
  F13a1:
    'F13a1 is the mouse ortholog of human F13A1 and encodes the catalytic A subunit of factor XIII, a calcium-dependent transglutaminase circulating as an A2B2 heterotetramer and present intracellularly as cytoplasmic A2. Thrombin cleavage of the activation peptide plus calcium-driven dissociation from the B subunit exposes the cysteine active site, which forms gamma-glutamyl-epsilon-lysyl isopeptide crosslinks between fibrin gamma and alpha chains and incorporates alpha-2 antiplasmin, conferring mechanical strength and fibrinolysis resistance on the clot; additional substrates include factor V, von Willebrand factor, and matrix proteins, while macrophage and platelet A subunit contributes to wound healing and phagocytosis. Human A subunit deficiency causes severe bleeding with umbilical hemorrhage and poor healing, and mouse nulls are viable but bleed and show impaired uterine and cardiac repair. The B subunit cannot substitute catalytically. Use nulls or patient knockins for clot stability endpoints and conditional alleles to separate hepatic from myeloid A subunit pools.',
  F13b:
    'The carrier B subunit of factor XIII is encoded by mouse F13b, ortholog of human F13B, a plasma glycoprotein composed of ten sushi domains, also called complement control protein modules, that binds the catalytic A2 dimer to form the circulating A2B2 heterotetramer. The B subunit has no transglutaminase activity of its own; its role is to stabilize A2 in plasma, extend its half-life several fold, prevent premature calcium-dependent activation, and modulate presentation of factor XIII to fibrin, dissociating once thrombin cleaves the A subunit activation peptide so catalysis can proceed. Human F13B deficiency therefore produces a secondary reduction in circulating A subunit and a milder bleeding phenotype than A subunit deficiency, an informative dissociation between availability and catalysis. No paralog performs this carrier function. Choose the null when factor XIII stability, clearance, and plasma reservoir biology is the question, hepatocyte-conditional alleles to confirm liver source, and humanization for concentrate replacement pharmacokinetics.',
  F2:
    'F2, ortholog of human F2, encodes prothrombin, the vitamin K dependent precursor of thrombin and the central protease of hemostasis. Prothrombinase, comprising factor Xa and factor Va on an anionic phospholipid surface, cleaves prothrombin at two sites to release the Gla and kringle containing fragment 1.2 and generate alpha-thrombin, whose substrate selection is governed by two electropositive exosites: exosite I engages fibrinogen, PAR1, and thrombomodulin, while exosite II binds heparin and GPIb alpha. Thrombin converts fibrinogen to fibrin, activates factors V, VIII, XI, and XIII along with platelet PAR1 and PAR4, and when bound to thrombomodulin switches specificity to activate protein C. Complete deficiency is lethal in mouse, with embryonic loss and neonatal hemorrhage, so hypomorphic or conditional alleles are mandatory. Note that the common human G20210A thrombophilia allele lies in the 3 prime untranslated region and raises expression rather than altering sequence, so dosage-increasing designs, not missense knockins, are the faithful mimic.',
  F5:
    'Mouse F5 is the ortholog of human F5 and encodes factor V, the nonenzymatic cofactor that raises factor Xa catalytic efficiency toward prothrombin by several orders of magnitude. Synthesized with A1, A2, B, A3, C1, and C2 domains, factor V is activated by thrombin or factor Xa cleavage that releases the large inhibitory B domain, allowing heterodimeric factor Va to bind membrane phosphatidylserine through its C2 discoidin domain and assemble prothrombinase. Downregulation occurs by activated protein C cleavage at Arg306, Arg506, and Arg679, and the human Leiden variant substituting Arg506 with glutamine confers APC resistance and thrombophilia, a mutation class best modeled by homologous knockin rather than null. Complete deficiency is lethal in mouse from embryonic and perinatal hemorrhage, so hypomorphic or conditional alleles are required, while the East Texas splice variant illustrates additional TFPI-related regulatory function. Pair Leiden knockins with thrombosis challenge endpoints and conditional alleles with platelet versus hepatic source questions.',
  F7:
    'F7 encodes coagulation factor VII, the mouse ortholog of human F7 and the trigger protease of the extrinsic pathway. This vitamin K dependent zymogen combines a Gla domain, two EGF-like modules, and a trypsin-like catalytic domain, and a small circulating fraction already exists as factor VIIa that remains essentially inactive until it binds tissue factor exposed by vascular injury or expressed by tumor and myeloid cells; the tissue factor complex allosterically completes the factor VIIa active site, enabling cleavage of factors IX and X and initiation of thrombin generation, with tissue factor pathway inhibitor as the principal check. Complete deficiency permits normal embryogenesis but causes fatal perinatal hemorrhage, so hypomorphic low-expression alleles or conditional deletion with hepatocyte Cre are necessary for adult studies. Patient missense knockins suit factor VII deficiency and bypass therapy questions, while humanized F7 alleles are the correct platform for recombinant factor VIIa and tissue factor directed agent pharmacology.',
  F9:
    'F9, ortholog of human F9, encodes coagulation factor IX and sits on the X chromosome, making hemizygous males the natural genetic configuration for hemophilia B modeling. The vitamin K dependent zymogen presents a Gla domain, two EGF modules, an activation peptide, and a protease domain; cleavage by factor XIa or by the tissue factor and factor VIIa complex yields factor IXa, which assembles with factor VIIIa on activated platelet membranes into intrinsic tenase to activate factor X, with the EGF1 and Gla surfaces mediating cofactor and membrane contacts. Mouse nulls reproduce the coagulopathy and remain the standard preclinical hemophilia B platform. Two allele designs answer different questions: patient-specific missense knockins interrogate residual activity, inhibitor development, and immune tolerance, whereas the hyperfunctional Padua substitution at Arg338 underpins gene therapy potency studies. Humanized F9 knockins are required when human factor IX directed antibody, Fc or albumin fusion pharmacokinetics, or mimetic bispecific activity is the readout.',
  Fahn:
    'Fahn is a clinical designation, fatty acid hydroxylase-associated neurodegeneration, rather than a distinct locus, and the gene to target in mouse is Fa2h, ortholog of human FA2H, which encodes an endoplasmic reticulum membrane enzyme combining an N-terminal cytochrome b5 heme domain with a di-iron sterol desaturase-like catalytic domain that introduces a 2-hydroxyl group into very long chain fatty acids destined for 2-hydroxy galactosylceramide and sulfatide in myelin. Recessive human variants produce an allelic spectrum spanning hereditary spastic paraplegia SPG35, leukodystrophy with dystonia, and neurodegeneration with brain iron accumulation, reflecting graded loss of hydroxylated sphingolipid. Nulls are viable and initially myelinate normally but develop late sheath splitting, demyelination and axon loss, making them suitable for aging studies rather than developmental screens. A conditional null with Cnp-Cre or Plp-CreER assigns oligodendrocyte autonomy, while a patient missense knockin preserves partial activity; quantify 2-hydroxylated galactosylceramide species by mass spectrometry as the primary readout.',
  Fanca:
    'Fanca, mouse ortholog of human FANCA, encodes the most frequently mutated Fanconi anemia gene product, a scaffolding subunit of the multiprotein FA core complex that, with FANCB, FANCC, FANCE, FANCF, FANCG, FANCL and FAAP proteins, functions as the E3 ubiquitin ligase that monoubiquitinates FANCD2 and FANCI after the FANCM and FAAP24 sensor detects a stalled replication fork at an interstrand crosslink. Loss abolishes ID2 activation, blocking recruitment of SLX4, XPF and the translesion machinery, producing the diagnostic hypersensitivity to mitomycin C and diepoxybutane and progressive bone marrow failure. Null mice reproduce the cellular crosslinker sensitivity and germ cell attrition but only develop overt marrow failure when combined with aldehyde detoxification alleles such as Aldh2 or Adh5, which is the key design insight for building a faithful hematopoietic model. Because the core complex is nonredundant, single nulls are informative. Use constitutive nulls for crosslink repair biology and compound aldehyde-stress backgrounds for marrow failure endpoints.',
  Fancd2:
    'Fancd2, the mouse ortholog of human FANCD2, encodes the central effector of the Fanconi anemia pathway, forming an obligate heterodimer with FANCI that clamps around double stranded DNA at stalled forks and is monoubiquitinated at lysine 561 by the FANCL RING subunit of the core complex, a modification that locks the ID2 clamp on chromatin and recruits SLX4 with the XPF and MUS81 nucleases to unhook interstrand crosslinks, after which USP1 and UAF1 remove the mark to allow release. FANCD2 also protects nascent strands at stalled forks from MRE11 degradation independently of crosslink unhooking. That functional split dictates allele design: a non-ubiquitinatable K559R knockin isolates the ubiquitin-dependent repair arm while preserving protein, whereas a null removes both activities, and USP1 alleles test the release step. Null mice show crosslinker sensitivity, germ cell loss and epithelial cancers, are viable, and become marrow failure models on aldehyde-sensitized backgrounds. Choose the knockin when mechanism, not dependency, is the question.',
  Fas:
    'Fas encodes CD95 (APO-1, TNFRSF6), the mouse ortholog of human FAS, a type I membrane death receptor whose three cysteine-rich extracellular domains bind trimeric FAS ligand and whose cytoplasmic death domain, after ligand-driven higher-order clustering, recruits FADD and procaspase-8 into the death-inducing signaling complex to initiate apoptosis directly and through BID cleavage. Outcome depends on receptor palmitoylation, lipid raft clustering, and CFLAR abundance, while non-apoptotic FAS signaling through NF-kappaB and ERK contributes to inflammation and proliferation. Mouse genetics here is historically rich: the lpr allele is a retrotransposon insertion causing aberrant splicing and near-complete loss, lprcg is a death domain point mutation, and both drive lymphadenopathy, autoantibodies, and background-dependent nephritis modeling human autoimmune lymphoproliferative syndrome. Faslg (gld) mutation phenocopies from the ligand side, so the axis is nonredundant. Use conditional flox alleles with T cell, B cell, or hepatocyte Cre for compartment questions and humanization for agonist or antagonist antibody programs.',
  Faslg:
    'Faslg is the mouse ortholog of human FASLG and encodes FAS ligand, a type II transmembrane member of the TNF superfamily whose extracellular TNF homology domain assembles into a trimer that clusters CD95 and triggers death-inducing complex formation. Expression is tightly restricted, induced on activated T cells and constitutive within cytotoxic lymphocyte secretory lysosomes from which it is delivered to the immune synapse, and activity is set by processing: ADAM10 and MMP7 shedding releases a soluble trimer that is poorly apoptotic and can act as a competitive antagonist, so membrane-bound ligand is the physiologically cytotoxic species. The spontaneous gld mutation is a single substitution in the trimerization interface that abolishes receptor binding and produces lymphoproliferation and autoantibodies indistinguishable in kind from lpr. A cleavage-resistant knockin is the definitive tool for separating membrane from soluble ligand function, while conditional deletion with Cd4-Cre or Gzmb-Cre assigns the killer population and humanization serves antibody pharmacology.',
  Fbp1:
    'Fbp1 encodes the mouse ortholog of human FBP1, the liver and kidney fructose-1,6-bisphosphatase that hydrolyzes fructose-1,6-bisphosphate to fructose-6-phosphate and, with Pck1 and G6pc1, sets gluconeogenic flux. The tetrameric enzyme is allosterically inhibited by AMP at a site distinct from the active site and synergistically by fructose-2,6-bisphosphate, making it the node where cellular energy charge and insulin signaling veto hepatic glucose output. Human FBP1 deficiency presents as fasting hypoglycemia with lactic acidosis and ketosis, typically unmasked by intercurrent illness rather than at baseline. Allele planning follows that logic: a hepatocyte conditional null with Alb-Cre interrogates fasting glucose production directly, AMP-site mutant knockins create a constitutively active enzyme to probe flux control, and humanization supports variant and inhibitor studies. Because Fbp2 covers skeletal muscle, a liver-restricted null leaves systemic FBPase activity intact. Pair alleles with fasting and pyruvate tolerance testing plus glycerol tracing rather than steady-state glycemia alone.',
  Fbp2:
    'The muscle-predominant fructose-1,6-bisphosphatase is encoded by Fbp2, ortholog of human FBP2, which hydrolyzes fructose-1,6-bisphosphate during glyconeogenesis, allowing lactate carbon to be resynthesized into glycogen after intense contraction. The Fbp2 protein is markedly more AMP sensitive than the liver isoform and additionally associates with aldolase, mitochondria and nuclei, where it has been reported to stabilize mitochondrial membrane potential and restrain apoptosis, activities separable from gluconeogenic catalysis. The allele fork therefore matters: a conditional null in skeletal muscle or cardiomyocytes tests glycogen resynthesis and recovery kinetics, whereas point mutants that break either the AMP site or the aldolase interaction dissociate catalysis from the reported protective role. Because Fbp1 covers liver and kidney, whole-body glucose homeostasis will often look normal, so avoid systemic glycemia as a primary readout. Instead match allele to muscle glycogen repletion, mitochondrial respirometry and postexercise recovery, using tamoxifen-inducible Cre to bypass developmental adaptation.',
  Fcer1a:
    'Fcer1a encodes the alpha chain of the high-affinity IgE receptor, mouse ortholog of human FCER1A, providing the ligand-binding subunit of FcepsilonRI, a tetramer completed by the beta chain MS4A2 and a disulfide-linked FCER1G gamma dimer on mast cells and basophils. Two extracellular Ig-like domains grip the Cepsilon2 to Cepsilon3 region of IgE Fc with picomolar affinity and slow dissociation, so receptors remain chronically occupied; antigen-driven crosslinking of bound IgE aggregates receptors, triggering LYN and FYN phosphorylation of the gamma chain ITAMs, SYK recruitment, LAT and PLCgamma signaling, calcium flux, degranulation of histamine and proteases, eicosanoid generation, and cytokine transcription. Species specificity is the dominant design constraint, since human IgE does not bind mouse FcepsilonRI alpha, which is why humanized FCER1A knockins are required for omalizumab, ligelizumab, and human IgE dependent anaphylaxis studies, whereas conditional deletion with mast cell restricted Cre resolves which effector population drives an allergic endpoint.',
  Fcer1g:
    'Fcer1g, the mouse ortholog of human FCER1G, encodes the FcR gamma chain, a compact ITAM-bearing transmembrane subunit that supplies signaling competence to ligand-binding alpha chains including FcgammaRI, FcgammaRIII, FcgammaRIV, FcepsilonRI, and several PIR and OSCAR family receptors. Receptor crosslinking by immune complexes drives Src family phosphorylation of the ITAM tyrosines, Syk recruitment through tandem SH2 domains, and downstream PLCgamma2, PI3K, and Vav signaling that produces degranulation, phagocytosis, and antibody dependent cytotoxicity. Because the gamma chain is also required for surface assembly and stability of its partner alpha chains, a germline null collapses essentially all activating Fc receptor output at once, which is powerful for asking whether a phenotype is Fc dependent but useless for resolving which individual receptor carries it. Conditional deletion in myeloid or NK compartments, or reconstitution on a null background with single humanized alpha chains, keeps interpretation clean, and note that Tyrobp supplies parallel ITAM coupling for a distinct receptor set.',
  Fcgr1a:
    'Encoding the high-affinity IgG receptor CD64, Fcgr1a corresponds to human FCGR1A and presents three extracellular Ig-like domains that capture monomeric IgG with nanomolar affinity, unlike low-affinity family members that require immune complex avidity. Signaling requires the associated FcR gamma chain, so CD64 ligation on monocytes, macrophages, and interferon gamma primed neutrophils triggers Syk dependent phagocytosis, oxidative burst, and presentation of internalized complexes. Mouse and human receptors differ substantially in IgG subclass preference and expression control, which means a wild type mouse cannot faithfully predict how a therapeutic antibody Fc will be captured, cleared, or cross-presented in patients. That divergence makes epitope-matched humanization, ideally on an Fcgr null background, the informative allele for effector function and pharmacokinetic work, while a conditional null suits questions about macrophage clearance of opsonized cells. Because Fcgr3 and Fcgr4 overlap functionally in mouse myeloid cells, single-locus deletion routinely understates the aggregate contribution of activating receptors.',
  Fcgr2a:
    'Human FCGR2A encodes CD32a, a low-affinity activating IgG receptor whose cytoplasmic ITAM distinguishes it from the inhibitory CD32b product of FCGR2B, and the mouse genome carries no direct counterpart, since murine Fcgr2b is exclusively an ITIM-bearing inhibitory receptor. CD32a dominates immune complex capture and Syk dependent activation on human neutrophils, monocytes, and platelets, and the common H131R polymorphism alters IgG2 engagement strongly enough to shift clinical responses to rituximab and to shape immune thrombocytopenia and heparin induced thrombocytopenia biology. Any Fcgr2a project is therefore a humanization project rather than a knockout, typically a targeted knockin or transgene expressing the human receptor under myeloid control, ideally on a background lacking murine activating Fc receptors so mouse and human receptors do not compete for the same antibody. Match the allotype you install to the clinical hypothesis, because H131 and R131 knockins answer different questions about antibody potency and immune complex clearance.',
  Fcgr3a:
    'CD16a, encoded by human FCGR3A, is the low-affinity IgG receptor that arms NK cells for antibody dependent cellular cytotoxicity, pairing with the FcR gamma chain for ITAM signaling and also expressed on macrophage subsets. Its V158F polymorphism changes IgG1 affinity enough to stratify clinical responses to rituximab, trastuzumab, and cetuximab, and afucosylated Fc glycoforms exploit the same interface for enhanced binding. The mouse counterparts Fcgr3 and Fcgr4 differ in cellular distribution and subclass preference, so murine NK cells report antibody effector potency poorly. Consequently the productive design is humanization, usually knockin of human FCGR3A as part of a combined human FCGR locus replacement on a murine Fcgr null background, with allotype choice matched to the potency question. Conditional deletion of the murine loci remains useful for asking whether tumor control in a given model is cytotoxicity dependent, and NK restricted drivers such as Ncr1-Cre keep that assignment cell intrinsic.',
  Fcgr3b:
    'FCGR3B specifies CD16b, a glycosylphosphatidylinositol anchored, neutrophil restricted low-affinity IgG receptor with no transmembrane or cytoplasmic signaling module, and no murine ortholog exists, which makes this locus a humanization target rather than a deletion target. Lacking an ITAM, CD16b works largely through immune complex capture, cooperation with CD11b and CD32a, and shedding of a soluble ectodomain that buffers circulating complexes, and it carries the human neutrophil antigen system whose NA1 and NA2 allotypes underlie alloimmune neonatal neutropenia and transfusion related acute lung injury. A knockin expressing human FCGR3B with faithful granulocyte restricted expression enables antibody clearance, complex trapping, and alloantibody studies that cannot otherwise be modeled, and allotype selection should follow the serologic hypothesis. Since CD16b operates alongside human CD32a and CD11b within the same neutrophil, single-receptor humanization understates complex handling, so composite humanized Fc receptor backgrounds are usually the endpoint-matched choice for translational work.',
  Fgf1:
    'Fgf1, mouse ortholog of human FGF1 and historically acidic FGF, encodes the most promiscuous ligand of the family, capable of activating all seven principal FGFR splice variants when presented with heparan sulfate, which drives FRS2 recruitment, RAS to ERK signaling, PI3K, and PLCgamma output. It carries no signal peptide and exits cells by a nonclassical copper-dependent route involving S100A13 and synaptotagmin, and its intracellular pool binds FIBP and can traffic to the nucleus. Nulls are viable with only subtle vascular and wound phenotypes, making constitutive deletion straightforward, so most designs instead pursue knockins of engineered variants: thermostable or heparin-binding-deficient mutants, or receptor-biased forms that retain glucose lowering without mitogenicity, since central administration produces sustained diabetes remission. Extensive redundancy with FGF2 and other paracrine ligands at shared receptors means single-locus loss rarely produces a clean readout. Choose conditional alleles when the endpoint is tissue-autonomous repair, and humanized knockins when profiling therapeutic FGF1 analogs.',
  Fgf10:
    'Fgf10, ortholog of human FGF10, encodes a mesenchymally expressed paracrine ligand with strong heparan sulfate affinity that signals with high selectivity through the FGFR2b splice variant on adjacent epithelium, driving FRS2 to ERK output and constituting the reciprocal mesenchymal arm of the FGF10 to FGFR2b to SHH loop that governs branching morphogenesis. It is required for lung bud initiation and outgrowth, limb bud induction, and development of salivary, lacrimal, mammary, and pancreatic epithelium, and it maintains adult alveolar and airway progenitors. Germline nulls die at birth with complete lung agenesis and absent limbs, so conditional floxed alleles are mandatory for postnatal regeneration studies. Human heterozygous loss causes lacrimo-auriculo-dento-digital syndrome and aplasia of lacrimal and salivary glands, making hypomorphic or heterozygous designs the closer disease match. The related ligand FGF7 shares FGFR2b and can partially substitute in glandular epithelium, so compound alleles clarify attribution. Pair the flox with Tbx4-rtTA or Dermo1-Cre depending on the tissue endpoint.',
  Fgf11:
    'Fgf11, the mouse ortholog of human FGF11, belongs to the intracellular FGF homologous factor subfamily and, despite the name, encodes no secreted mitogen: the protein lacks a signal peptide, does not engage FGFR ectodomains, and instead functions within the cytosol through a beta-trefoil core that docks onto the C-terminal tails of voltage-gated sodium channels and interacts with hypoxia-responsive machinery, having been described as a HIF-1alpha modulator in T cells and tumor contexts. This intracellular mechanism dictates allele strategy: secreted-ligand logic such as ligand traps or neutralizing antibodies is inapplicable, and interpretation should center on channel gating, cytoskeletal, and transcriptional readouts. Nulls are viable, so constitutive deletion is feasible, while domain-swap or interaction-surface point knockins are far more informative than whole-gene ablation for separating channel binding from other partners. The closely related paralogs Fgf12, Fgf13, and Fgf14 occupy overlapping neuronal and cardiac territory, so compound genetics is often required before assigning an excitability or arrhythmia endpoint to this locus.',
  Fgf12:
    'Fgf12, ortholog of human FGF12, encodes an intracellular FGF homologous factor, formerly FHF1, that is not secreted and does not activate FGFRs; instead its beta-trefoil core binds the C-terminal tail of voltage-gated sodium channels including NaV1.5 in heart and NaV1.2 and NaV1.6 in neurons, tuning fast inactivation kinetics, promoting long-term inactivation, and shifting availability, with an alternative N-terminal isoform determining the strength of that block. Human recurrent gain-of-function variants such as the arginine to histidine substitution in the core cause developmental and epileptic encephalopathy, while other variants associate with Brugada-type conduction phenotypes, so patient-specific missense knockins are the disease-relevant allele rather than a null. Constitutive deletion is viable and yields modest excitability changes, reflecting substantial redundancy with Fgf11, Fgf13, and Fgf14 in the same compartments, so compound genetics should be planned before interpreting seizure thresholds. Match allele class to endpoint: knockin for channel biophysics and EEG phenotypes, conditional flox with neuron or cardiomyocyte Cre for compartment attribution.',
  Fgf13:
    'Fgf13, mouse ortholog of human FGF13, encodes an intracellular FGF homologous factor whose multiple N-terminal splice isoforms are generated from an X-linked locus and which acts through two distinct nonreceptor mechanisms: docking on the C-terminal tails of voltage-gated sodium channels including NaV1.6 to control inactivation and availability, and direct microtubule binding that stabilizes polymers during neuronal polarization and axon branching. It is also a thermal nociception regulator in sensory neurons and contributes to cardiomyocyte excitability. Human hemizygous loss-of-function variants cause X-linked intellectual disability with epilepsy and febrile seizure susceptibility, which makes patient-derived truncating or missense knockins, together with isoform-specific targeting, more informative than whole-gene deletion. Nulls are viable, permitting conditional floxed alleles with Nestin-Cre, Advillin-Cre, or Myh6-Cre to separate cortical, sensory, and cardiac contributions, and X-linkage requires careful hemizygous versus mosaic female design. Paralogs Fgf11, Fgf12, and Fgf14 share channel partners, so compound alleles clarify which factor sets the excitability endpoint being measured.',
  Fgf14:
    'Fgf14, the mouse ortholog of human FGF14, encodes intracellular FGF homologous factor 4, a nonsecreted beta-trefoil protein that binds the C-terminal tails of NaV1.1, NaV1.2, and NaV1.6 and physically associates with CaV2.1 and scaffolding partners at the axon initial segment of cerebellar granule and Purkinje neurons, where it sets sodium channel availability, resurgent current, and the fidelity of high-frequency firing. Human heterozygous missense and truncating variants cause spinocerebellar ataxia 27A, and a dominantly inherited intronic GAA repeat expansion causes the common late-onset ataxia SCA27B, giving two mechanistically distinct disease classes, loss of protein function versus repeat-driven transcriptional silencing. Allele design should therefore fork explicitly: patient missense knockins for channel-interaction deficits, humanized repeat-containing knockins for expansion biology and antisense or small-molecule correction, and floxed conditionals for cell-type attribution using Pcp2-Cre or Atoh1-Cre. Nulls are viable with ataxia and paroxysmal dyskinesia, and paralogs Fgf12 and Fgf13 only partially overlap in cerebellum.',
  Fgf16:
    'Fgf16, ortholog of human FGF16, encodes a secreted FGF9 subfamily ligand that, unlike most paracrine members, dimerizes in a way that limits heparan sulfate binding and diffusion, and it signals preferentially through FGFR1c, FGFR2c, FGFR3c, and FGFR4 with FRS2 to ERK output. Expression concentrates in embryonic and adult cardiomyocytes and brown adipose tissue, where it supports cardiomyocyte proliferation during ventricular growth and modulates hypertrophic and injury responses, and additional signal in developing limb correlates with human phenotypes. Hemizygous human loss-of-function variants cause X-linked metacarpal 4 and 5 fusion, and the mouse locus is likewise X-linked, so hemizygous male, homozygous female, and mosaic heterozygous female comparisons must be built into the design. Nulls are viable, making constitutive deletion tractable for cardiac stress testing, while conditional floxed alleles with Myh6-Cre or Adipoq-Cre attribute effects to muscle versus fat. Substantial overlap with Fgf9 and Fgf20 at shared c-isoform receptors argues for compound alleles when scoring proliferation endpoints.',
  Fgf17:
    'Fgf17, mouse ortholog of human FGF17, is a member of the FGF8 subfamily and encodes a secreted ligand with strong preference for the c-splice receptors FGFR1c, FGFR2c, FGFR3c, and FGFR4, acting alongside FGF8 at the midbrain-hindbrain isthmic organizer and in the anterior neural ridge to pattern frontal cortex, cerebellar vermis, and rostral telencephalon. Nulls are viable but show hypoplasia of the cerebellar vermis, reduced dorsomedial frontal cortex, and altered social behavior, phenotypes that map cleanly onto region-specific FGF dosage. In humans, heterozygous variants have been reported in Kallmann syndrome and normosmic hypogonadotropic hypogonadism, consistent with GnRH neuron and olfactory placode requirements shared with FGF8 and FGFR1. Because viability permits constitutive deletion, the informative designs are hypomorphic allelic series and compound Fgf8 and Fgf17 alleles that titrate isthmic signal, since these two ligands substantially overlap. Reserve conditional floxed alleles with En1-Cre or Emx1-Cre for questions that separate organizer patterning from later cortical growth endpoints.',
  Fgf18:
    'Fgf18, ortholog of human FGF18, encodes a secreted FGF8 subfamily ligand that signals principally through FGFR3c and FGFR4, with additional FGFR1c and FGFR2c engagement, and functions as a positive regulator of chondrocyte proliferation, matrix production, and growth plate hypertrophic transition while simultaneously restraining osteoblast differentiation timing, thereby coordinating endochondral ossification and cranial suture closure. It is the basis of the intra-articular cartilage anabolic agent sprifermin, which makes species-matched receptor engagement a practical concern. Germline nulls die in the perinatal period with delayed ossification, expanded proliferative zones, and craniosynostosis-like suture abnormalities, so conditional floxed alleles combined with Col2a1-Cre, Prrx1-Cre, or Sp7-Cre are the appropriate tool for postnatal joint and skeletal work. Overlapping activity from Fgf9 at the same c-isoform receptors means compound conditionals are advisable when the endpoint is complete growth plate FGF input. Align allele class to readout: humanized knockins for sprifermin-type pharmacology, conditional deletion for cartilage homeostasis and osteoarthritis progression.',
  Fgf19:
    'Fgf19, represented in mouse by the Fgf15 locus that is the accepted rodent ortholog of human FGF19, encodes an endocrine FGF with a degenerate heparan sulfate binding surface, allowing it to leave the tissue of origin and circulate. It is transcribed in ileal enterocytes under direct control of the bile acid receptor FXR, travels through portal blood, and engages hepatocyte FGFR4 together with the obligate coreceptor beta-Klotho to activate ERK and repress Cyp7a1, closing the enterohepatic feedback loop on bile acid synthesis while also promoting hepatocyte proliferation and glycogen storage. Amplification of the human gene drives FGFR4-dependent hepatocellular carcinoma, motivating selective inhibitors, and engineered nonmitogenic analogs are used in cholestasis and steatohepatitis. Nulls are viable with elevated bile acid synthesis and impaired gallbladder filling, so constitutive deletion suits metabolic endpoints, whereas humanized FGF19 knockins are required for testing human-specific analogs or FGFR4 inhibitors. Note that rodent and human sequences differ substantially, so cross-species pharmacology must be validated before interpretation.',
  Fgf2:
    'Fgf2, mouse ortholog of human FGF2 and long called basic FGF, encodes a heparin-dependent ligand that activates FGFR1c and FGFR2c to drive FRS2, ERK, PI3K, and PLCgamma signaling, and it is stored bound to heparan sulfate proteoglycans in extracellular matrix, forming a mobilizable reservoir released by heparanase or injury. Translation from alternative CUG start codons yields high molecular weight isoforms that bear nuclear localization signals and act intracellularly, distinct from the classical 18 kDa form that is exported by a nonclassical, signal peptide independent route. Nulls are viable with reduced vascular tone, delayed wound healing, and neocortical neuron deficits, so constitutive deletion is feasible, but isoform-specific knockins that ablate only high molecular weight forms are far more revealing given their opposing roles in cardiac hypertrophy. Redundancy with FGF1 and other c-isoform ligands buffers single-locus loss. Use conditional alleles with Cdh5-CreER or Nestin-Cre when the endpoint is angiogenesis or neural progenitor expansion rather than systemic phenotype.',
  Fgf20:
    'Fgf20, ortholog of human FGF20, encodes a secreted FGF9 subfamily ligand that dimerizes to limit heparan sulfate engagement, signals through FGFR1c and FGFR2c, and sits downstream of canonical Wnt as a direct beta-catenin and TCF target, making it a key relay that converts Wnt input into FGF output during placode and progenitor decisions. It is required for cochlear sensory epithelium and outer hair cell development, nephron progenitor maintenance in cooperation with FGF9, and hair follicle placode induction, and human biallelic variants cause autosomal recessive nonsyndromic deafness. Nulls are viable with profound sensorineural hearing loss and altered follicle patterning, so constitutive deletion supports auditory phenotyping, while conditional floxed alleles paired with Six2-Cre or Krt14-Cre separate kidney and skin requirements. Because Fgf9 shares receptors and expression territory, particularly in nephron progenitors, compound conditionals are necessary before attributing progenitor exhaustion to this locus. Reserve humanization for reagent or antibody studies and match allele class to auditory brainstem response, nephron endowment, or follicle density endpoints.',
  Fgf21:
    'Fgf21, the mouse ortholog of human FGF21, encodes an endocrine FGF whose weak heparan sulfate affinity permits circulation and whose activity requires the coreceptor beta-Klotho paired with FGFR1c on adipocytes, or FGFR1c in hypothalamus and hindbrain. Hepatic transcription is induced by PPARalpha during fasting and ketogenesis and by ATF4 during amino acid restriction and integrated stress response, and the protein raises adipose glucose uptake and adiponectin, promotes energy expenditure, and centrally suppresses sweet and alcohol preference while stimulating water intake. Circulating levels are limited by fibroblast activation protein cleavage, a fact exploited by protease-resistant analogs including efruxifermin and pegozafermin. Nulls are viable, so constitutive deletion suits metabolic challenge protocols, while conditional floxed alleles distinguish hepatocyte-derived from adipose or muscle sources and Klb conditionals localize the responsive tissue. No paralog substitutes because beta-Klotho dependence is specific, though FGF15 and FGF19 share the coreceptor with FGFR4. Humanized knockins are the appropriate platform for analog pharmacokinetics and receptor-selectivity endpoints.',
  Fgf22:
    'Fgf22, ortholog of human FGF22, encodes an FGF7 subfamily ligand that binds heparan sulfate tightly and signals through the FGFR2b splice variant, and its defining role is as a target-derived presynaptic organizer: released from CA3 pyramidal dendrites, it acts retrogradely on incoming axons to promote excitatory presynaptic terminal differentiation and vesicle clustering, complementing FGF7, which performs the analogous function for inhibitory terminals. Deletion in mouse reduces excitatory synapse number, produces resistance to epileptogenesis in kindling models, and yields depression-like behavior, establishing an excitatory to inhibitory balance phenotype rather than a gross developmental defect. Because nulls are viable, constitutive knockouts are usable, but conditional floxed alleles with Grik4-Cre or Camk2a-CreER are preferable for separating developmental synapse formation from adult plasticity, and the ligand also functions in skin and hair follicle epithelium. Its close paralogs Fgf7 and Fgf10 share FGFR2b, so compound alleles are advisable. Match allele class to whether the endpoint is synaptic density, seizure threshold, or behavioral output.',
  Fgf23:
    'Fgf23, mouse ortholog of human FGF23, encodes the osteocyte and osteoblast derived endocrine regulator of phosphate homeostasis, a ligand with weak heparan sulfate binding that requires alpha-Klotho as coreceptor with FGFR1c on renal proximal tubule and parathyroid cells to suppress the sodium phosphate cotransporters NPT2a and NPT2c and to downregulate CYP27B1 while inducing CYP24A1, thereby lowering serum phosphate and active vitamin D. Bioactivity is set by furin-family cleavage at an RXXR motif that is itself blocked by GALNT3-dependent O-glycosylation, so autosomal dominant hypophosphatemic rickets arises from cleavage-resistant arginine substitutions while familial tumoral calcinosis arises from failed glycosylation or loss of function. Nulls are viable but hyperphosphatemic with ectopic calcification and short lifespan. Allele choice follows disease logic precisely: cleavage-resistant knockins model excess and reproduce XLH-like phenotypes seen with Phex loss, floxed conditionals localize the osteocyte source, and humanized knockins are required for burosumab and other antibody testing against phosphate, ALP, and rickets scoring endpoints.',
  Fgf3:
    'Fgf3, ortholog of human FGF3 and originally identified as the int-2 proviral integration site in mouse mammary tumor virus induced tumors, encodes a secreted FGF7 subfamily ligand with FGFR1b and FGFR2b preference that is expressed in hindbrain rhombomeres 5 and 6 and in periotic mesenchyme, where it acts with FGF10 to induce the otic placode and drive inner ear morphogenesis, and additionally in tooth and pharyngeal development. Human biallelic mutations cause the congenital deafness syndrome with labyrinthine aplasia, microtia, and microdontia, matching the mouse otic requirement closely. Single nulls display inner ear dysmorphology and tail abnormalities with variable severity, whereas the sharpest phenotypes emerge in compound Fgf3 and Fgf10 mutants that fail otic induction outright, so plan combinatorial alleles from the start. Constitutive deletion supports auditory and vestibular phenotyping; conditional floxed alleles with Hoxb1-Cre or Foxg1-Cre separate hindbrain-derived from mesenchymal ligand. Match allele class to auditory brainstem response, labyrinth imaging, or dental patterning endpoints.',
  Fgf4:
    'Fgf4, the mouse ortholog of human FGF4, encodes a secreted ligand signaling through FGFR1c, FGFR2c, FGFR3c, and FGFR4 that occupies an unusually pivotal position in early development: it is expressed by inner cell mass and epiblast cells and is the paracrine input that specifies trophoblast stem cell maintenance and, within the blastocyst, drives the ERK-dependent segregation of primitive endoderm from epiblast, which is why exogenous ligand plus heparin is standard in trophoblast stem cell culture. Later expression in the limb apical ectodermal ridge and somites sustains outgrowth alongside FGF8. Germline nulls die shortly after implantation with inner cell mass failure, so any postimplantation question demands conditional floxed alleles, and hypomorphic or inducible designs are preferable for dose-sensitive lineage studies. Substantial overlap with Fgf8 and Fgf17 in the ridge means compound conditionals are needed for limb endpoints. Note also the retrogene expansion underlying canine chondrodysplasia, a reminder that copy number, not only coding sequence, changes skeletal outcome.',
  Fgf5:
    'Fgf5, ortholog of human FGF5, encodes a secreted ligand acting through FGFR1c and FGFR2c whose best-defined function is as a negative regulator of the hair cycle: expressed in the outer root sheath at the end of anagen, it signals to the dermal papilla to trigger catagen entry, so loss of function extends anagen and produces the classical angora long-hair mouse phenotype, and homologous human variants cause familial trichomegaly with elongated eyelashes. Loss-of-function alleles are similarly the basis of long-haired breeds across many mammals, making this locus an unusually clean example of a single ligand setting an organ-level timing switch. Nulls are viable and healthy, so constitutive deletion is fully adequate for hair cycle and follicle biology, while conditional floxed alleles are worth the investment only when separating follicular from reported neural or muscle contributions. Redundancy is limited in the follicle context, which is why the phenotype is penetrant. Match allele class to anagen duration, hair shaft length, or follicle histology endpoints.',
  Fgf6:
    'Fgf6, mouse ortholog of human FGF6, encodes an FGF4 subfamily secreted ligand with FGFR1c and FGFR4 preference whose expression is essentially confined to skeletal muscle lineages, where it is induced in satellite cells and regenerating myofibers and modulates the balance between myoblast proliferation and MyoD-dependent differentiation during repair. Deletion is viable and fertile with normal gross myogenesis, and reported regeneration deficits, delayed myotube formation, and increased fibrosis after injury are background-dependent, which makes injury challenge rather than baseline histology the necessary readout for this allele. Consequently, constitutive nulls are adequate and conditional alleles add value chiefly when distinguishing satellite cell autonomous from myofiber-derived ligand using Pax7-CreER versus Myf5-Cre. Because Fgf2, Fgf4, and Fgf9 act on the same c-isoform receptors in muscle and can substitute, compound alleles are advisable before attributing regenerative failure to this locus. Overexpression knockins test the hypothesis that supplemental ligand accelerates repair. Align allele class to cardiotoxin or dystrophic model endpoints such as centronuclear fiber counts and fibrotic area.',
  Fgf7:
    'Fgf7, the mouse ortholog of human FGF7 and known as keratinocyte growth factor, encodes a heparan sulfate dependent ligand with strict specificity for the FGFR2b splice variant, secreted by dermal fibroblasts, submucosal stroma, and other mesenchymal cells to act exclusively on adjacent epithelium, driving keratinocyte proliferation, migration, and cytoprotective gene expression, and its recombinant truncated form palifermin is used to prevent chemoradiation-induced oral mucositis. In the nervous system it acts as a target-derived organizer of inhibitory presynaptic terminals, complementing FGF22 at excitatory terminals. Nulls are viable with only mild hair follicle and kidney phenotypes, so constitutive deletion is tractable but rarely dramatic, reflecting compensation from Fgf10 and Fgf22 at the shared FGFR2b receptor. Accordingly, compound alleles or epithelial Fgfr2b conditional deletion is the more decisive design for mucosal repair questions. Humanized knockins are appropriate when profiling palifermin-like biologics, and overexpression models address epithelial hyperplasia risk against wound closure and mucositis scoring endpoints.',
  Fgf8:
    'Fgf8, ortholog of human FGF8, encodes a secreted ligand with multiple N-terminal splice isoforms of differing potency that signals through FGFR1c, FGFR2c, FGFR3c, and FGFR4 and functions as the organizing signal at the midbrain-hindbrain isthmus, the limb apical ectodermal ridge, the pharyngeal ectoderm, and the anterior neural ridge, coupling to ERK output that sustains progenitor proliferation and positional identity. Its biology is famously dosage dependent, which is why the hypomorphic neo-insertion allelic series remains the reference tool for producing graded craniofacial, cardiac outflow, and cerebellar phenotypes that complete nulls, lethal at gastrulation, cannot deliver. Human heterozygous variants cause Kallmann syndrome and normosmic hypogonadotropic hypogonadism through GnRH neuron deficits, and holoprosencephaly-spectrum defects also occur. Conditional floxed alleles with En1-Cre, Msx2-Cre, or Nkx2-5-Cre are essential for tissue attribution, and Fgf17 and Fgf18 overlap at c-isoform receptors in isthmus and limb. Match hypomorph, conditional, or humanized allele to whether the endpoint is patterning gradient, organ morphology, or ligand pharmacology.',
  Fgf9:
    'Fgf9, mouse ortholog of human FGF9, encodes a secreted ligand that homodimerizes through an N-terminal interface, which occludes part of its heparan sulfate binding surface and thereby extends diffusion range, and it activates FGFR2c, FGFR3c, and FGFR1c with ERK output. Its most decisive role is in gonadal sex determination, where it forms a feedforward loop with SOX9 that antagonizes WNT4 and RSPO1, such that XY nulls undergo male-to-female sex reversal, and it further drives lung mesenchymal proliferation, cerebellar and inner ear development, and intestinal mesenchyme growth. Germline deletion is lethal at birth from lung hypoplasia, so conditional floxed alleles are required for postnatal work, while human heterozygous missense variants that increase dimerization cause multiple synostoses syndrome 3 with elbow and knee fusion, making gain-of-function knockins the correct model for that disease class. Overlap with Fgf16 and Fgf20 at shared c-isoform receptors warrants compound alleles. Match allele to gonadal fate, alveolarization, or joint fusion endpoints.',
  Fgfr1:
    'Fgfr1, mouse ortholog of human FGFR1, encodes a receptor tyrosine kinase with three immunoglobulin-like extracellular domains, an acid box, and a split intracellular kinase domain, requiring heparan sulfate proteoglycan as a ternary coreceptor for FGF binding and, for endocrine FGFs, klotho proteins. Alternative splicing of the second half of the third Ig domain generates IIIb and IIIc variants with divergent ligand specificity, and activated receptor recruits FRS2 alpha and PLC gamma to drive RAS-MAPK, PI3K and PKC output. Loss of function alleles cause Kallmann syndrome and hypogonadotropic hypogonadism, while activating P252R causes Pfeiffer syndrome and 8p11 fusions such as ZMYM2-FGFR1 drive myeloid neoplasms. Germline nulls die at gastrulation from failed mesodermal migration, so conditional floxed kinase domain alleles with lineage Cre are required. Fgfr2 and Fgfr3 overlap in ligand response and compensate in limb and skeleton, so compound alleles matter. Use isoform-restricted or point knockins when splice-specific or inhibitor questions drive the study.',
  Fgfr2:
    'Fgfr2, the mouse ortholog of human FGFR2, encodes an FGF receptor whose biology is dominated by mutually exclusive splicing of exons encoding the second half of Ig domain III, producing FGFR2 IIIb in epithelium, which responds to FGF7 and FGF10 from mesenchyme, and FGFR2 IIIc in mesenchyme, which responds to epithelial FGF2, FGF8 and FGF9, establishing the reciprocal epithelial-mesenchymal loop that patterns limb, lung and craniofacial structures. Craniosynostosis alleles including S252W and P253W in Apert syndrome and cysteine substitutions in Crouzon syndrome act by broadening ligand specificity or promoting ligand-independent disulfide dimerization, while FGFR2 amplification and fusions drive gastric and intrahepatic cholangiocarcinoma. Because a conventional null is embryonic lethal from limb bud and placental failure, and because isoform-specific alleles produce entirely different phenotypes, splice-restricted alleles are the sharpest tool available. Fgfr1 and Fgfr3 compensate in skeletal contexts. Choose isoform-specific nulls for developmental patterning and conditional activating knockins for FGFR inhibitor response and resistance studies.',
  Fgfr3:
    'Unlike its paralogs, Fgfr3 acts predominantly as a negative regulator of endochondral bone growth, and the mouse ortholog of human FGFR3 encodes a receptor whose activation in growth plate chondrocytes suppresses proliferation and hypertrophic differentiation through STAT1 and MAPK, which is why gain of function alleles cause dwarfism rather than overgrowth. The transmembrane G380R substitution causes achondroplasia, K650E and K650M in the activation loop cause thanatophoric dysplasia type II and SADDAN, and null mice are viable with skeletal overgrowth and inner ear defects, exactly inverting the human mutant phenotype. In cancer, S249C and Y375C drive urothelial carcinoma through ligand-independent disulfide dimerization and FGFR3-TACC3 fusions drive glioma, both targets for erdafitinib class inhibitors. Allele logic is therefore unusually clean: knockin the specific human activating codon for skeletal dysplasia and inhibitor testing, and use nulls only when asking about growth restraint. Fgfr1 and Fgfr2 do not substitute for this inhibitory function, so single-locus knockins are interpretable.',
  Fgfr4:
    'Fgfr4, mouse ortholog of human FGFR4, encodes the FGF receptor most distinguished by its endocrine ligand relationship, forming a complex with beta-klotho to serve as the hepatic receptor for FGF19 (mouse Fgf15), which represses CYP7A1 transcription and thereby closes the bile acid feedback loop from ileum to liver. Unlike other family members, FGFR4 undergoes limited receptor internalization and lacks IIIb and IIIc alternative splicing, simplifying allele design. The germline G388R polymorphism enhances STAT3 signaling and associates with cancer progression, FGF19 amplification with FGFR4 dependency defines a hepatocellular carcinoma subset targeted by covalent inhibitors such as fisogatinib and roblitinib, and FGFR4 sustains rhabdomyosarcoma. Null mice are viable with elevated bile acid pool and depleted gallbladder, and only show skeletal phenotypes when combined with Fgfr3 alleles, indicating real but limited redundancy. Use conditional hepatocyte nulls for bile acid and hepatocarcinogenesis questions, and humanized kinase domain knockins when covalent inhibitor cysteine reactivity must translate.',
  Flt1:
    'Flt1, ortholog of human FLT1, encodes VEGFR1, a receptor tyrosine kinase whose seven immunoglobulin-like extracellular domains bind VEGFA with roughly an order of magnitude higher affinity than VEGFR2 while its kinase domain signals only weakly, making it primarily a decoy that restrains VEGF availability. Alternative processing yields soluble sFLT1, which sequesters circulating VEGF and placental growth factor and is a central mediator of preeclampsia. The genetics resolve this elegantly and should guide design: null embryos die from endothelial overgrowth and disorganized vessels, whereas kinase-dead knockin animals are viable and largely normal, demonstrating that ligand sequestration rather than catalysis is the essential function. Conditional deletion therefore addresses tissue-specific VEGF buffering, isoform-selective alleles isolate the soluble species, and humanized ectodomains support testing of VEGF traps such as aflibercept. Read out vascular density and branching, permeability, proteinuria and blood pressure in pregnancy models, and free VEGF levels.',
  Flt3:
    'FMS-like tyrosine kinase 3, encoded by Flt3 and orthologous to human FLT3, is a class III receptor tyrosine kinase with five immunoglobulin-like extracellular domains, a juxtamembrane autoinhibitory segment, and a split kinase domain, driving STAT5, RAS/MAPK, and PI3K signaling upon FLT3 ligand binding on multipotent and lymphoid progenitors. Internal tandem duplications within the juxtamembrane region relieve autoinhibition and impose constitutive, mislocalized STAT5 activation, while tyrosine kinase domain substitutions at D835 confer a distinct active conformation and differing sensitivity to type I versus type II inhibitors. Because a straightforward null is viable with only modest progenitor deficits, informative cancer models use knockin ITD alleles, which produce myeloproliferative disease and cooperate with Npm1 or Dnmt3a mutations to yield frank leukemia. Ectodomain humanization supports antibody, bispecific, and CAR-T evaluation. Select allele class according to whether the endpoint is inhibitor resistance, cooperating mutation genetics, or immunotherapy targeting.',
  Foxo1:
    'Foxo1, the mouse ortholog of human FOXO1, encodes a forkhead box O transcription factor that binds the DAF-16 family consensus element through a winged helix domain and activates gluconeogenic, autophagy, cell cycle arrest and stress resistance programs including G6pc, Pck1, Cdkn1b, Gadd45a and Sod2. Insulin and growth factor signaling suppress it directly, since AKT phosphorylates threonine 24, serine 253 and serine 316 to create 14-3-3 binding sites that drive nuclear exclusion and SKP2 dependent degradation, while SIRT1 deacetylation and JNK phosphorylation reverse that control under stress. PAX3-FOXO1 and PAX7-FOXO1 fusions from the t(2;13) and t(1;13) translocations define alveolar rhabdomyosarcoma, a distinct oncogenic use of this locus. Null embryos die at midgestation from vascular remodeling failure, so conditional alleles are required, and a triple alanine knockin that resists AKT phosphorylation gives constitutive nuclear activity for insulin resistance studies. Foxo3 and Foxo4 compensate substantially, so compound conditional alleles are needed for hematopoietic and metabolic endpoints.',
  Foxo3:
    'Foxo3 is the mouse ortholog of human FOXO3 and encodes the forkhead factor most closely tied to oxidative stress resistance, quiescence and longevity, binding the same consensus element as FOXO1 and inducing Sod2, Cat, Gadd45a, Bcl2l11 encoding BIM, and Cdkn1b, thereby setting apoptotic threshold and stem cell reserve. Regulation mirrors the family, with AKT and SGK phosphorylation creating 14-3-3 docking sites for nuclear export, AMPK phosphorylation enhancing activity under energy stress, and IKK and ERK driving degradation. FOXO3 intronic haplotypes are among the most reproducible human longevity associations, and the gene is essential for primordial follicle quiescence, since null females exhaust the ovarian reserve and develop premature ovarian failure. Nulls are viable, so constitutive alleles support aging, hematopoietic stem cell and fertility studies directly. Because Foxo1 and Foxo4 occupy overlapping targets, single deletion underestimates requirement and compound conditional alleles are the standard for hematopoietic and neural stem cell work. Use phospho-resistant knockins to force nuclear retention.',
  Foxp3:
    'Foxp3, the mouse ortholog of human FOXP3, encodes a forkhead-box transcription factor whose FKH DNA-binding domain, leucine zipper dimerization region, and N-terminal repressor module nucleate large complexes with Runx1/CBFβ, NFAT, Eos, and the NuRD and CoREST corepressors to enforce the regulatory T cell program, repressing Il2 while sustaining Il2ra, Ctla4, and Ikzf2. Lineage specification requires sustained TCR signaling plus demethylation of conserved noncoding sequence 2, which locks heritable expression; loss produces the scurfy phenotype, an X-linked fatal lymphoproliferative wasting syndrome in hemizygous males that mirrors human IPEX. Design decisions follow directly. Null and conditional alleles ask whether Treg identity is required in a given tissue or temporal window, Cre and reporter knockins (including inducible Foxp3-CreERT2 for fate mapping or diphtheria-toxin ablation) resolve lineage stability, and IPEX point-mutation or humanized alleles interrogate patient variants. No paralog substitutes for Foxp3, so deletion timing and driver fidelity, not redundancy, dominate interpretation.',
  Fst:
    'Fst, ortholog of human FST, encodes follistatin, a secreted glycoprotein built from an N-terminal domain and three follistatin domains that neutralizes TGF-beta superfamily ligands by wrapping two molecules of activin A in a ring that buries both type I and type II receptor interfaces, an irreversible steric block rather than competitive inhibition. The same architecture binds myostatin encoded by Mstn, GDF11, and several BMPs, and heparan sulfate affinity distinguishes the tissue-retained FST288 isoform from the circulating FST315 form generated by alternative splicing. Nulls die within hours of birth with growth retardation, taut skin, rib and palate defects, so conditional floxed alleles are mandatory for adult muscle, reproductive, or metabolic studies. Isoform-selective knockins are uniquely informative here because retention versus circulation determines whether inhibition is local or systemic, and overexpression or AAV delivery models test muscle hypertrophy directly. The related genes Fstl3 and Inhba-binding partners modulate the same ligand pool, so document them when scoring muscle mass or folliculogenesis endpoints.',
  Fus:
    'Fus encodes the FET family RNA-binding protein FUS, ortholog of human FUS, organized as an N-terminal QGSY-rich low complexity prion-like domain, an RGG-flanked RRM, a zinc finger, and a C-terminal PY nuclear localization signal recognized by Transportin-1; it binds nascent transcripts, regulates splicing and transcription elongation, and undergoes liquid-liquid phase separation that is normally restrained by nuclear import and arginine methylation. Amyotrophic lateral sclerosis mutations cluster in the PY-NLS, notably R521C and P525L, weakening Transportin binding and driving cytoplasmic mislocalization, stress granule partitioning and progressive aggregation, a toxic gain-of-function mechanism distinct from the nuclear loss seen in FTLD-FUS. Because constitutive nulls show perinatal lethality on C57BL/6 backgrounds and only partial recovery on outbred backgrounds, NLS-mutant knockins and Δ14 frameshift alleles are the designs that reproduce motor neuron degeneration at endogenous expression. Ewsr1 and Taf15 share domain architecture and buffer nuclear functions, so score cytoplasmic mislocalization directly.',
  Fyn:
    'Fyn, mouse ortholog of human FYN, encodes a Src family nonreceptor tyrosine kinase organized as a myristoylated and palmitoylated N-terminal membrane anchor followed by SH3, SH2 and kinase domains, held closed by CSK phosphorylation of the C-terminal tyrosine 531 and opened by CD45 or PTPN22 mediated dephosphorylation with activation loop autophosphorylation. In T cells FYN and LCK phosphorylate CD3 and zeta chain ITAMs to recruit ZAP70, while in neurons the FynB splice isoform phosphorylates NR2B to control NMDA receptor gating and phosphorylates tau at tyrosine 18, placing it downstream of amyloid beta and cellular prion protein signaling in Alzheimer disease models. Nulls are viable with impaired hippocampal long term potentiation and defective thymocyte selection, so constitutive alleles are workable. Src, Yes, Lck and Lyn are genuinely redundant in most lineages, so compound alleles are needed before claiming requirement. Choose conditional nulls for neuronal versus immune assignment and analog-sensitive knockins for acute chemical genetic inhibition.',
  Fzd1:
    'Fzd1, the mouse ortholog of human FZD1, encodes a seven transmembrane Frizzled receptor whose extracellular cysteine rich domain binds the palmitoleate-modified thumb of Wnt ligands, and whose intracellular KTXXXW motif recruits Dishevelled to nucleate the signalosome that, together with LRP5 or LRP6, inhibits the beta-catenin destruction complex. Receptor abundance is set post-translationally by the E3 ligases RNF43 and ZNRF3, which ubiquitinate the intracellular loops for internalization and are themselves antagonized by RSPO ligands acting through LGR4, LGR5 and LGR6, the axis exploited by porcupine and anti-FZD therapeutics. FZD1 participates in canonical signaling in kidney, lung and bone and contributes to injury responses in fibrosis. Null mice are essentially normal because ten Frizzled paralogs share ligands, with Fzd2 and Fzd7 being the closest functional relatives, so single deletion is nearly uninformative and compound conditional alleles are mandatory. Use humanized CRD knockins when the goal is testing Frizzled selective antibodies whose epitopes do not cross-react with mouse receptor.',
  Fzd2:
    'Fzd2, mouse ortholog of human FZD2, encodes a class F seven transmembrane receptor closely related to FZD1 and FZD7, binding Wnt ligands through its cysteine rich domain and coupling to both canonical beta-catenin signaling via LRP5 and LRP6 and to planar cell polarity signaling through Dishevelled, DAAM1 and RHOA with ROCK and JNK output. Heterozygous truncating variants near the C-terminal KTXXXW and PDZ binding region cause autosomal dominant Robinow syndrome and omodysplasia, and these act as dominant alleles rather than simple loss of function, which means a conventional null will not reproduce the human disease and a targeted truncation knockin is required. FZD2 is also induced during epithelial to mesenchymal transition and supports STAT3 dependent invasion in carcinoma. Single nulls are viable with cleft palate at low penetrance, but combined Fzd1 and Fzd2 deletion produces highly penetrant palatal clefting, confirming real redundancy. Match design to question, using truncation knockins for skeletal dysplasia and compound conditional alleles for developmental requirement.',
  Fzd7:
    'Fzd7, the mouse ortholog of human FZD7, encodes a seven-pass transmembrane Frizzled receptor whose extracellular cysteine-rich domain captures Wnt lipid-modified ligands and, together with Lrp5 or Lrp6, nucleates the signalosome that recruits Dishevelled through the intracellular KTXXXW motif. Because Fzd7 is enriched in intestinal and hepatic progenitors and is upregulated in triple-negative breast and hepatocellular tumors, it is a favored target for CRD-directed antibodies and decoy receptors, which makes the allele decision consequential: a conditional null asks whether a tissue depends on Fzd7-specific Wnt reception, a CRD humanization asks whether a clinical antibody engages its epitope and blocks ligand capture in vivo, and a signaling-dead tail mutant separates canonical output from planar cell polarity roles. Given that Fzd1, Fzd2, and Fzd5 bind overlapping Wnts and buffer single-receptor loss, compound conditional designs are prudent. Pair the chosen allele with a validated lineage driver such as Villin-Cre or Alb-Cre so the readout reflects the intended compartment.',
  G6pc:
    'Encoding the catalytic subunit of glucose-6-phosphatase, G6pc is the mouse ortholog of human G6PC and completes both gluconeogenesis and glycogenolysis by hydrolyzing glucose-6-phosphate within the endoplasmic reticulum lumen, working obligately with the Slc37a4 transporter that delivers substrate across the membrane. Loss-of-function mutations cause glycogen storage disease type Ia, with fasting hypoglycemia, hepatomegaly, lactic acidemia, and nephropathy, and whole-body nulls in mouse suffer severe neonatal hypoglycemia and high early mortality, so survivable studies generally require a floxed allele deleted postnatally in liver or kidney using Alb-Cre or AAV8-delivered Cre. Patient-mutation knockins such as R83C preserve residual biology for enzyme-correction studies, whereas humanization of the locus is the design that supports gene therapy, base editing, and mRNA replacement testing against the actual human sequence. Note that G6pc2 and G6pc3 do not substitute for hepatic output, so redundancy is not a rescue here; match allele and Cre timing to the metabolic endpoint you intend to measure.',
  G6pc2:
    'G6pc2 is the mouse ortholog of human G6PC2 and encodes the islet-specific glucose-6-phosphatase catalytic subunit related protein, an endoplasmic reticulum membrane enzyme of beta cells that hydrolyzes glucose-6-phosphate and thereby opposes glucokinase, creating a futile cycle that raises the glucose threshold for insulin secretion. Human variants at G6PC2 are among the strongest fasting plasma glucose signals in GWAS, with loss-of-function alleles lowering fasting glucose without increasing diabetes risk, and mouse deletion reproduces this leftward shift in the glucose dose response for insulin release. The same protein is the IGRP antigen recognized by pathogenic CD8 T cells in NOD mice, giving the locus a second, immunological identity. Consequently a straight null suits secretion threshold studies, humanized knockins are the right tool for validating human coding variants and epitope-matched T cell work, and conditional alleles with Ins1-Cre confirm beta cell autonomy. Match allele to endpoint, whether hyperglycemic clamp, islet perifusion, or tetramer-based autoreactive T cell assays.',
  Gabra1:
    'Gabra1 encodes the α1 subunit of the GABA-A receptor, ortholog of human GABRA1, and is the most abundant α isoform in brain, assembling predominantly as α1β2γ2 pentamers at synapses where the benzodiazepine site is formed at the α1 and γ2 interface and requires His101 for high-affinity diazepam binding. Dominant human variants including A322D and pore-lining substitutions cause juvenile myoclonic epilepsy and developmental and epileptic encephalopathy through dominant negative assembly failure and reduced surface receptor rather than simple haploinsufficiency. The classic knockin H101R, which renders α1 diazepam-insensitive, remains the definitive demonstration that this subunit mediates the sedative and amnestic components of benzodiazepine action, and it exemplifies the point-mutation strategy for dissecting pharmacology. Constitutive nulls are viable with tremor and near-total loss of brain benzodiazepine binding, so choose a conditional null for circuit assignment, a patient knockin for encephalopathy modeling, and pair either with EEG and interneuron-specific Cre drivers.',
  Gabra2:
    'The α2 subunit encoded by Gabra2, ortholog of human GABRA2, assembles chiefly as α2β3γ2 receptors concentrated at axon initial segment synapses formed by chandelier cells and in amygdala, striatum and spinal dorsal horn, where it contributes a slower deactivating inhibitory current than α1-containing receptors and anchors through gephyrin and collybistin. Human variation at the locus is a replicated association signal for alcohol dependence and externalizing traits, and rare de novo variants cause developmental and epileptic encephalopathy. Point knockin work established the subunit-specific pharmacology: an H101R equivalent substitution that renders α2 diazepam-insensitive abolishes benzodiazepine anxiolysis and spinal antihyperalgesia while sparing sedation, which is the mechanistic basis for α2-selective positive allosteric modulators. That result dictates the design fork, with a benzodiazepine-insensitive knockin for pharmacology, a conditional null with Nkx2-1-Cre or Advillin-Cre for circuit assignment, and humanization when testing subtype-selective compounds whose potency differs across species.',
  Gabra3:
    'Located on the X chromosome within a cluster with Gabrq and Gabre, Gabra3 encodes the α3 GABA-A receptor subunit, ortholog of human GABRA3, which assembles with β and γ2 subunits into receptors enriched in the thalamic reticular nucleus, monoaminergic brainstem nuclei, amygdala and neonatal cortex, where they generate slowly deactivating inhibitory currents that shape burst firing and oscillatory output. Expression is highest perinatally and declines as α1 rises, so developmental timing governs any phenotype. Diazepam-insensitive knockin analysis assigned α3 no essential role in classical sedation or anxiolysis but implicated it in antipsychotic-relevant sensorimotor gating and in spinal nociception, motivating α3-selective positive allosteric modulators as nonsedating analgesics. Human missense variants cause X-linked intellectual disability with epilepsy. Choose a conditional null crossed to a thalamic reticular or serotonergic driver for circuit questions, a benzodiazepine-insensitive knockin for subtype pharmacology, and remember that hemizygous males give the cleanest dosage comparison to patients.',
  Gabra4:
    'Gabra4 encodes the α4 subunit, ortholog of human GABRA4, which partners preferentially with δ rather than γ2 and localizes to extrasynaptic and perisynaptic membranes of dentate granule cells, thalamus and striatum, where α4βδ receptors mediate high-affinity tonic GABA current rather than phasic inhibition. These receptors carry an arginine at the position equivalent to α1 His101, rendering them benzodiazepine-insensitive, while remaining exquisitely sensitive to neurosteroids such as allopregnanolone, to low-dose ethanol, and to the superagonist gaboxadol, which is the pharmacological signature that defines the subunit. Expression is plastic, rising sharply after stress, ethanol withdrawal and across the ovarian cycle, so phenotyping must control for hormonal state. Constitutive nulls are viable and lose gaboxadol-sensitive tonic current, so a conditional null with Pomc-Cre or a dentate driver localizes the contribution, whereas δ subunit deletion produces overlapping phenotypes; measure tonic current amplitude directly rather than inferring from behavior.',
  Gabra5:
    'Extrasynaptic inhibition in hippocampus depends heavily on the α5 subunit encoded by Gabra5, ortholog of human GABRA5, which assembles as α5βγ2 receptors anchored perisynaptically on CA1 pyramidal cell dendrites by radixin and generates a substantial component of tonic conductance that raises the threshold for dendritic integration and long-term potentiation. Because α5 receptors retain benzodiazepine site sensitivity, α5-selective inverse agonists enhance learning in rodents and have been pursued for cognitive deficits in Down syndrome, schizophrenia and post-stroke recovery, while α5 mediates part of the persistent memory impairment following etomidate and other general anesthetics. The gene lies in the imprinted 15q11 to q13 cluster with GABRB3 and GABRG3, adjacent to the Angelman and Prader-Willi interval. Constitutive nulls are viable with improved spatial learning, so a conditional null with Camk2a-Cre or Grik4-Cre assigns regional contribution, and a benzodiazepine-insensitive knockin is the allele matched to inverse agonist pharmacology.',
  Gabrb1:
    'Gabrb1 encodes the β1 GABA-A receptor subunit, ortholog of human GABRB1, one of three β isoforms that contribute the principal side of the orthosteric GABA binding site at the β and α interface and that carry the transmembrane residues determining sensitivity to etomidate, propofol and loreclezole. Relative to β2 and β3 it is the least abundant, with expression concentrated in hippocampus, septum and specific hypothalamic and brainstem nuclei, and it is the sole β subunit in the imprinted-adjacent chromosome 4p12 cluster with GABRA2, GABRA4 and GABRG1. De novo missense variants in the M2 pore-lining segment cause developmental and epileptic encephalopathy by increasing spontaneous channel opening, a gain-of-function mechanism that argues for a patient knockin rather than a null. Because β2 and β3 substitute broadly during assembly, a single Gabrb1 deletion is frequently silent; plan compound conditional alleles, quantify pentamer composition biochemically, and read out anesthetic sensitivity alongside EEG.',
  Gabrb2:
    'As the most abundant β isoform in brain, the subunit encoded by Gabrb2, ortholog of human GABRB2, contributes the principal face of the GABA binding site in the canonical α1β2γ2 pentamer and carries the transmembrane asparagine, Asn265, that forms part of the etomidate and propofol binding pocket. The knockin substitution β2 N265S, which renders these receptors anesthetic-insensitive, showed that β2-containing receptors mediate the sedative and hypnotic component of etomidate action while β3 receptors mediate immobility and respiratory depression, a dissociation that remains the cleanest example of subunit-resolved anesthetic pharmacology. Human variants cause developmental and epileptic encephalopathy and the locus carries schizophrenia association signals. Because β1 and β3 assemble with the same α and γ partners and buffer deletion, a straight null is often uninformative; select an anesthetic-insensitive knockin for pharmacology, a conditional null with forebrain Cre for circuit assignment, and verify pentamer stoichiometry after any manipulation.',
  Gabrb3:
    'Gabrb3 encodes the β3 GABA-A receptor subunit, ortholog of human GABRB3, situated within the imprinted 15q11 to q13 interval alongside GABRA5 and GABRG3 and therefore implicated in Angelman syndrome and 15q duplication autism phenotypes. β3 contributes the principal side of the GABA site and carries Asn265, whose substitution to methionine in the β3 N265M knockin abolished the immobilizing and respiratory-depressant actions of etomidate and propofol while sparing sedation, definitively separating anesthetic endpoints by subunit. De novo missense variants across the extracellular and pore domains cause Lennox-Gastaut and infantile epileptic encephalopathies through altered gating rather than simple loss. Constitutive nulls display cleft palate with high neonatal lethality, epilepsy, hyperactivity and abnormal social behavior, so a conditional null with Nes-Cre or Camk2a-Cre is preferable for adult work, while a patient knockin models gain-of-function gating. β2 partially substitutes in forebrain, so quantify subunit composition rather than assuming specificity.',
  Gabrd:
    'The δ subunit encoded by Gabrd, ortholog of human GABRD, never occupies synapses; it replaces γ2 in extrasynaptic α4βδ and cerebellar α6βδ pentamers that mediate tonic inhibitory conductance, showing high GABA affinity, minimal desensitization, insensitivity to benzodiazepines and exceptional sensitivity to neurosteroids including allopregnanolone and to the superagonist gaboxadol. Expression is dynamically regulated across the ovarian cycle, pregnancy and the postpartum period, providing the mechanistic basis for catamenial and postpartum seizure susceptibility and for the therapeutic action of brexanolone and ganaxolone. Human variants including E177A and R220H associate with generalized epilepsy with febrile seizures plus and juvenile myoclonic epilepsy through reduced surface expression and channel open time. Constitutive nulls are viable with attenuated neurosteroid responses and altered seizure thresholds, making them directly useful; add a conditional null with a dentate or thalamic driver for circuit resolution, and note that Gabra4 deletion produces overlapping loss of tonic current.',
  Gabre:
    'Gabre encodes the ε subunit, ortholog of human GABRE, an unusual GABA-A receptor subunit that substitutes for γ2 in pentamers expressed in locus coeruleus, dorsal raphe, hypothalamus and selected brainstem autonomic nuclei, situated in the X-linked cluster with Gabra3 and Gabrq. Its defining property is that ε-containing receptors display prominent spontaneous, agonist-independent channel opening and are largely insensitive to benzodiazepines and to the potentiating effects of anesthetics and neurosteroids, so they set a constitutive chloride leak in monoaminergic neurons rather than transducing phasic synaptic input. This makes them a plausible substrate for the differential anesthetic sensitivity of arousal circuits. Because loss removes a tonic conductance rather than a synaptic current, a conditional null crossed to Dbh-Cre or Slc6a4-Cre paired with whole-cell recording of holding current is the informative design, while humanization supports pharmacology on a subunit whose properties diverge across species. Verify ε expression by in situ before phenotyping.',
  Gabrg2:
    'Gabrg2 encodes the γ2 subunit, ortholog of human GABRG2, present in the large majority of synaptic GABA-A receptors, where it completes the α1β2γ2 pentamer, forms the complementary face of the benzodiazepine binding site with α, and is strictly required for clustering at inhibitory postsynaptic sites through gephyrin, collybistin and neuroligin-2 interactions. Human dominant variants map cleanly to mechanism: R43Q in the benzodiazepine site causes febrile seizures and childhood absence epilepsy by impairing trafficking, K289M in the extracellular M2 to M3 loop causes generalized epilepsy with febrile seizures plus by accelerating deactivation, and truncations cause Dravet-like encephalopathy through dominant negative retention. Constitutive nulls die within the first postnatal days with loss of synaptic receptor clustering, so a conditional null with Camk2a-Cre or an interneuron driver is required for adult circuit work, while patient knockins reproduce specific seizure phenotypes. No other γ isoform substitutes appreciably in forebrain synapses.',
  Gabrp:
    'Gabrp encodes the π subunit, ortholog of human GABRP, and stands apart from the neuronal subunits because its expression is overwhelmingly peripheral and epithelial, concentrated in uterine myometrium and endometrium, lung, breast and pancreatic ductal tissue rather than in brain. When incorporated into pentamers with α and β subunits it alters the pharmacology of the receptor, notably shifting sensitivity to pregnanolone and other neuroactive steroids, which has been proposed to contribute to steroid-dependent regulation of uterine quiescence during pregnancy. Independently, the gene is a robust marker of basal-like breast carcinoma and pancreatic ductal adenocarcinoma, where it has been linked to proliferative and migratory signaling, giving it an oncology as well as a reproductive identity. A constitutive null is viable and appropriate for reproductive phenotyping, while a conditional null with Pgr-Cre or Krt5-Cre isolates tissue-autonomous roles; do not assume central nervous system phenotypes without direct expression evidence.',
  Gabrq:
    'Gabrq, the mouse ortholog of human GABRQ, encodes the theta subunit of the GABA-A receptor, an atypical subunit that assembles with epsilon and alpha3 rather than the canonical alpha1/beta2/gamma2 arrangement, and it sits in the X-linked cluster alongside Gabra3 and Gabre. Theta-containing pentamers concentrate in monoaminergic and hypothalamic circuits, including locus coeruleus, dorsal raphe, and preoptic area, where they confer reduced benzodiazepine sensitivity, altered anesthetic and neurosteroid responses, and in some configurations agonist-independent spontaneous opening. Because the subunit tunes gating rather than forming a receptor by itself, conditional null alleles ask whether removing theta shifts tonic inhibition and arousal state, while epitope-matched humanization supports subunit-selective positive allosteric modulators whose pockets diverge between species. Epsilon subunits occupy overlapping pentamer positions, so plan compound Gabre genetics early, and pair the allele with monoamine-restricted drivers such as Dbh-Cre or Slc6a4-Cre when circuit-level endpoints are the goal.',
  Gapdh:
    'Cytosolic NAD+ turnover is set by Gapdh, the mouse ortholog of human GAPDH, which encodes the homotetrameric glyceraldehyde-3-phosphate dehydrogenase that oxidizes and phosphorylates glyceraldehyde-3-phosphate to 1,3-bisphosphoglycerate while reducing NAD+, the step that gates the payoff phase of glycolysis and feeds substrate-level phosphorylation. Its active site cysteine makes the enzyme a redox sensor, since oxidation or S-nitrosylation redirects the protein toward nuclear functions including SIAH1-dependent degradation cascades, OCA-S-linked histone gene transcription and mRNA binding, and the same residue underlies inhibition by koningic acid and adduction by methylglyoxal. Because glycolytic flux is essential in nearly every lineage, germline deletion is not a viable design, and even partial manipulation perturbs the housekeeping standard commonly used for normalization. Practical alleles are conditional nulls with tamoxifen-inducible Cre for acute flux collapse, active site cysteine knockins to separate moonlighting from catalysis, and epitope-tagged or humanized knockins for pharmacology. Align allele with endpoint, whether extracellular acidification, NAD+ to NADH ratio, or in vivo glucose tracing.',
  Gba:
    'Gba, the mouse ortholog of human GBA1, encodes lysosomal acid beta-glucocerebrosidase, a retaining glycosidase that cleaves glucosylceramide into ceramide and glucose, depends on saposin C for activity, and reaches the lysosome via LIMP2 (Scarb2) rather than the mannose-6-phosphate route. Biallelic loss causes Gaucher disease with glucosylsphingosine accumulation, whereas single variant alleles such as N370S and L444P are the strongest common genetic risk factors for Parkinson disease, acting through impaired lysosomal flux and a reciprocal loop between reduced enzyme activity and alpha-synuclein aggregation. Constitutive nulls die within a day of birth from a defective epidermal permeability barrier, so conditional deletion with nestin-Cre or microglial drivers is required for adult neuropathology, while point knockins preserve residual activity and model heterozygous risk. The non-lysosomal paralog Gba2 hydrolyzes the same substrate elsewhere, so interpret lipid panels accordingly and match allele class to storage, chaperone response, or synucleinopathy endpoints.',
  Gck:
    'Glucokinase, encoded by Gck as the mouse ortholog of human GCK, is hexokinase IV, a monomeric enzyme with low glucose affinity, sigmoidal kinetics, no product inhibition by glucose-6-phosphate, and an allosteric activator site distinct from the catalytic cleft, properties that let it act as the glucose sensor of pancreatic beta cells and hepatocytes, where Gckr-encoded regulatory protein sequesters it in the nucleus until fructose-1-phosphate releases it. Heterozygous inactivating mutations produce GCK-MODY with a raised glucose threshold for insulin release, while activating mutations cause congenital hyperinsulinism, and homozygous null mice die perinatally from severe diabetes, so heterozygous or tissue-restricted conditional alleles are the workable designs. Beta-cell deletion using Ins1-Cre interrogates secretion thresholds, hepatocyte deletion using Alb-Cre interrogates glucose disposal and glycogen synthesis, activating knockins model hyperinsulinism, and humanization enables glucokinase activator pharmacology. Hexokinases 1 through 3 have far lower Km and cannot reconstitute sensing, so compensation is not a confound.',
  Gckr:
    'Gckr, the mouse ortholog of human GCKR, encodes glucokinase regulatory protein, a sugar isomerase fold protein that binds hepatic glucokinase and sequesters it in the nucleus, releasing it to the cytosol when fructose-1-phosphate rises and retaining it when fructose-6-phosphate accumulates, so hepatic glucose phosphorylation reports fructose and glycolytic intermediates rather than glucose alone. The common human P446L variant weakens this restraint, lowering fasting glucose and insulin while raising triglycerides, one of the clearest examples of an allele with divergent cardiometabolic consequences. That biology argues for a humanized knockin carrying the P446L substitution when the goal is to reproduce the human tradeoff, whereas a hepatocyte conditional null models complete loss of glucokinase sequestration and unrestrained lipogenic flux. No paralog substitutes for GKRP, so residual regulation depends on glucokinase expression itself. Match allele to endpoint, whether glucokinase translocation imaging, de novo lipogenesis tracing, or fructose challenge with paired lipid and glucose profiling.',
  Gdf1:
    'Gdf1, the mouse ortholog of human GDF1, encodes a TGF-beta superfamily ligand most closely related to Vg1 that functions as a Nodal-like signal in left-right patterning, requiring the coreceptor CRIPTO, encoded by Tdgf1, to engage ACVR1B or ACVR1C with ACVR2A or ACVR2B and phosphorylate SMAD2 and SMAD3 for FOXH1-dependent transcription of Lefty2 and Pitx2. Proprotein processing is inefficient on its own, and heterodimer formation with NODAL markedly increases secretion and potency, a biochemical detail that makes cis-acting processing mutations informative. Nulls display randomized situs, right isomerism, and cardiac outflow and looping defects with substantial lethality, and human heterozygous and biallelic variants cause transposition of the great arteries, double outlet right ventricle, and heterotaxy, so patient-matched missense knockins are the disease-relevant allele. Conditional floxed alleles matter chiefly for later cardiac roles, since the critical window is at the node. The paralog Gdf3 shares CRIPTO dependence, so compound designs clarify laterality and cardiac morphology endpoints.',
  Gdf10:
    'Gdf10, mouse ortholog of human GDF10 and also designated BMP3B, encodes a TGF-beta superfamily ligand that, like its closest paralog BMP3, signals through activin-type receptors ACVR2B with ALK4 to phosphorylate SMAD2 and SMAD3 rather than the SMAD1, SMAD5, and SMAD8 branch, positioning it as a counterweight to osteogenic BMP output in bone and as a TGF-beta-like input elsewhere. Expression is high in cerebellar Purkinje neurons, and after cortical stroke it is induced in peri-infarct layer 5 neurons, where it drives axonal sprouting and functional recovery by modulating PTEN, mTOR, and growth-associated transcriptional programs, making it a plasticity effector rather than a developmental patterning ligand. Nulls are viable with subtle skeletal and neurological phenotypes, so constitutive deletion is workable, while conditional floxed alleles with Pcp2-Cre or Rbp4-Cre attribute recovery effects to specific neuron classes and overexpression or AAV delivery tests therapeutic sprouting. Given overlap with Bmp3 in SMAD2 and SMAD3 signaling, compound alleles clarify bone mass endpoints.',
  Gdf11:
    'Gdf11, the mouse ortholog of human GDF11, encodes a TGF-beta superfamily ligand secreted as a proprotein whose furin-cleaved mature dimer remains latent in a noncovalent complex with its own prodomain until BMP1 and tolloid proteases liberate it. Active GDF11 engages ActRIIA and ActRIIB with ALK4 or ALK5 to phosphorylate SMAD2 and SMAD3, and its mature domain is roughly 90 percent identical to myostatin, so the two ligands share receptors and the antagonist follistatin. Loss of Gdf11 shifts anterior Hox boundaries, producing extra thoracic vertebrae, kidney agenesis, and perinatal lethality, which makes conditional nulls rather than germline deletion the practical route to adult physiology. Prodomain or cleavage-site knockins interrogate latency and proteolytic activation separately from total ligand loss, while humanizing the mature domain supports selectivity testing of antibodies meant to spare myostatin. Because Mstn compensates functionally, pair the allele with a tissue-restricted Cre and consider compound Mstn genetics before interpreting muscle endpoints.',
  Gdf15:
    'As the most divergent member of the TGF-beta superfamily, the mouse ortholog of human GDF15, Gdf15, produces a circulating hormone that signals not through canonical type II receptors but through GFRAL, a GDNF-receptor-family protein restricted to the area postrema and nucleus tractus solitarius, using RET as its signaling coreceptor. Transcription is driven by the integrated stress response through ATF4 and CHOP, and by p53, which is why plasma levels track mitochondrial disease, metformin exposure, and tumor burden, and why the ligand produces anorexia, nausea-like behavior, and cachexia. Germline nulls are viable, so straight knockouts remain informative, but tissue-restricted conditional deletion is needed to assign hepatic, placental, or tumor sources of the circulating pool. Alternatively, hepatocyte-directed overexpression or humanized knockins allow direct testing of blocking antibodies and long-acting agonists. No close paralog substitutes for this ligand, so single-locus loss is interpretable, and pairing it with Gfral alleles cleanly separates ligand supply from central reception.',
  Gdf2:
    'Gdf2 is the mouse ortholog of human GDF2 and encodes BMP9, a circulating BMP produced largely by hepatic stellate cells that binds ALK1 with subnanomolar affinity, partners with BMPR2 or ActRIIA, and requires endoglin as coreceptor to phosphorylate SMAD1, SMAD5, and SMAD8 in endothelium, where it enforces quiescence and restrains angiogenic sprouting. Human loss-of-function alleles cause hereditary hemorrhagic telangiectasia type 5 and predispose to pulmonary arterial hypertension, mirroring the ALK1 and endoglin arm of the same axis. Conditional deletion in hepatocytes or stellate cells tests whether the liver is the obligate source of ligand, patient missense knockins probe prodomain processing and receptor engagement, and epitope humanization enables pharmacology of ALK1 pathway biologics. Redundancy here is genuine, since BMP10 signals through the same receptor set and circulates as a BMP9 and BMP10 heterodimer, so plan compound Gdf2 and Bmp10 alleles before concluding that single-gene loss is phenotypically silent.',
  Gdf3:
    'Gdf3, ortholog of human GDF3, encodes a divergent TGF-beta ligand expressed in the inner cell mass, embryonic stem cells, and adipose tissue that behaves context-dependently, either signaling like Nodal through ActRIIB and ALK4 with an EGF-CFC coreceptor, or acting as an extracellular BMP antagonist that sequesters BMP4. This dual character explains why loss produces partially penetrant defects in anterior visceral endoderm positioning and mesoderm patterning rather than one clean phenotype, and why human variants segregate with microphthalmia, coloboma, and Klippel-Feil vertebral fusion. Conditional nulls address tissue-specific requirements in visceral endoderm versus adipocytes, knocking in patient missense alleles distinguishes a hypomorphic ligand from a true antimorph, and humanization supports biochemical assays of receptor and BMP binding. Because Gdf1 is the closest paralog and both ligands feed Nodal-type signaling, interpret single-locus phenotypes cautiously and build compound Gdf1 alleles whenever laterality or axial patterning is the endpoint.',
  Gdf5:
    'Known biochemically as cartilage-derived morphogenetic protein 1, Gdf5 is the mouse ortholog of human GDF5 and produces a BMP-family ligand with unusual selectivity for BMPR1B (ALK6) over ALK3, which it uses with BMPR2 or ActRIIA to drive SMAD1, SMAD5, and SMAD8 phosphorylation in the joint interzone, articular surface, tendon, and ligament. The spontaneous brachypodism allele is a Gdf5 null that shortens limb segments and eliminates specific joints, and human mutations span brachydactyly type C, Grebe and Hunter-Thompson chondrodysplasia, and gain-of-function symphalangism, with the common regulatory variant rs143383 in the R2 and R3 elements conferring osteoarthritis risk. Nulls are viable, so allele choice follows the question: conditional deletion for adult articular maintenance, coding knockins for chondrodysplasia mechanism, and enhancer knockins for the human osteoarthritis risk haplotype. Gdf6 and Gdf7 overlap in joint and tendon programs, so compound alleles and a joint-restricted Gdf5-Cre driver sharpen skeletal endpoints considerably.',
  Gdf6:
    'Gdf6 is the mouse ortholog of human GDF6 and encodes BMP13, a ligand that signals through ALK3 and ALK6 with BMPR2 to activate SMAD1, SMAD5, and SMAD8, and that heterodimerizes with GDF5 to alter receptor preference and antagonist sensitivity. Its dominant requirement is ocular morphogenesis, where dosage controls optic fissure closure and retinal specification, explaining human microphthalmia with coloboma, Leber congenital amaurosis, and Klippel-Feil presentations, alongside segment-specific roles in wrist, ankle, and vertebral joint formation. Since nulls survive with restricted joint fusions and variable eye defects, conditional deletion is most useful for separating optic vesicle from periocular mesenchyme requirements, patient missense knockins test whether variants are hypomorphic or dominant negative through heterodimer poisoning, and humanization enables ligand trap and antibody pharmacology. Because Gdf5 and Gdf7 buffer overlapping skeletal domains, design compound conditional genetics early rather than reading a single-locus knockout as definitive.',
  Gdf7:
    'Gdf7, the mouse ortholog of human GDF7, encodes BMP12, a BMP-family ligand secreted by the roof plate of the developing spinal cord that signals through ALK3 and ALK6 with BMPR2 onto SMAD1, SMAD5, and SMAD8 to specify dorsal commissural interneuron identity, with additional requirements in tendon and ligament matrix programs and a human association with Barrett esophagus risk. Nulls are viable and lose a defined dorsal interneuron population without gross axial malformation, which makes the locus attractive for knockin engineering: Cre or reporter cassettes at Gdf7 provide clean roof plate lineage access, conditional nulls dissect ligand requirement after neural tube closure, and humanization supports tendon-directed biologic testing. Gdf5, Gdf6, and BMP7 supply overlapping activity in tendon and dorsal neural tube, so anticipate masked phenotypes and consider compound alleles when interneuron subtype output or tendon mechanical properties is the primary endpoint.',
  Gdf9:
    'Gdf9, ortholog of human GDF9, encodes an oocyte-restricted TGF-beta ligand that is unusual in signaling through BMPR2 paired with ALK5 to phosphorylate SMAD2 and SMAD3 in granulosa cells, and that forms the potent cumulin heterodimer with BMP15 to amplify cumulus expansion and metabolic support of the oocyte. Follicles arrest at the primary stage without it, so nulls are viable yet female sterile, and human variants cause premature ovarian insufficiency and influence dizygotic twinning rates. Because germline deletion already terminates folliculogenesis, oocyte-specific conditional deletion using Zp3-Cre or Gdf9-Cre is the way to interrogate later antral and periovulatory functions, patient missense knockins separate reduced secretion from impaired heterodimer assembly, and humanization enables recombinant cumulin and antibody assays. Bmp15 is the functional partner rather than a simple backup, and its dosage strongly modifies Gdf9 phenotypes, so compound allelic series are essential for meaningful fertility endpoints.',
  Gli1:
    'As the mouse ortholog of human GLI1, Gli1 encodes a five-finger C2H2 zinc finger transcription factor that binds the GACCACCCA consensus and functions almost purely as an activator, lacking the strong amino-terminal repressor module of Gli3; it is itself a direct Hedgehog target gene, so its expression amplifies rather than initiates the pathway downstream of Ptch1 relief of Smoothened, with Sufu restraining nuclear entry. Because homozygous Gli1 nulls are viable and largely normal, the locus is exceptionally useful as a readout and lineage tool, and Gli1-LacZ or Gli1-CreER knockins report pathway activity and mark Hedgehog-responsive stroma, perivascular, and progenitor populations. Conditional nulls test tissue-autonomous requirements, while Rosa26-based activator expression asks whether forced GLI output suffices for transformation. Gli2 supplies most activator function and readily compensates, so single-gene loss frequently looks silent; compound Gli1 and Gli2 genetics, paired with a tamoxifen-controlled driver, keeps allele class matched to the endpoint.',
  Gli2:
    'Gli2, the mouse ortholog of human GLI2, encodes the principal transcriptional activator of Hedgehog signaling, a zinc finger protein bearing an amino-terminal repressor domain, a Sufu-binding region, and carboxy-terminal transactivation sequences; unlike Gli3, it is only inefficiently processed into a repressor form, and its activity is set by PKA-primed GSK3 and CK1 phosphorylation, Spop-directed degradation, and Kif7-dependent trafficking within the primary cilium. Homozygous nulls die perinatally with cleft palate, skeletal and vertebral defects, and lung and foregut abnormalities, so tissue-restricted floxed alleles are the practical route for postnatal or organ-specific questions. A conditional null asks whether a lineage requires activator output, an amino-terminally truncated constitutively active knockin asks whether GLI2 output alone drives proliferation or tumor initiation, and degron-resistant variants isolate turnover from transcription. Gli1 and Gli3 partially buffer loss, arguing for compound alleles, and a well-characterized Cre with confirmed recombination efficiency matters as much as the flox itself.',
  Gli3:
    'Functioning chiefly as a repressor, Gli3 is the mouse ortholog of human GLI3 and encodes a zinc finger protein that, in the absence of Hedgehog ligand, undergoes PKA-primed, GSK3 and CK1 mediated phosphorylation followed by limited proteasomal processing into a truncated Gli3R that occupies target promoters and silences them, a step requiring intact ciliary trafficking through Kif7 and restraint by Sufu. Human GLI3 lesions produce Greig cephalopolysyndactyly and, with specific mid-protein truncations, Pallister-Hall syndrome, while the classic mouse extra-toes allele causes preaxial polydactyly and perinatal lethality in homozygotes, so conditional deletion is preferable for limb, neural tube, and craniofacial work beyond birth. A repressor-only knockin that constitutively yields Gli3R distinguishes loss of repression from loss of activator capacity, and patient-matched frameshift knockins model Pallister-Hall directly. Gli2 supplies activator output that shapes the Gli3 phenotype, so compound genetics and precise driver selection determine interpretability.',
  Glp1r:
    'Glp1r is the mouse ortholog of human GLP1R and encodes a class B1 secretin-family G protein-coupled receptor that engages GLP-1 by a two-domain mechanism, with the large extracellular domain capturing the peptide carboxy terminus before the peptide amino terminus inserts into the transmembrane bundle to trigger Gs coupling, cyclic AMP production and PKA and Epac2 signaling that potentiates glucose-dependent insulin secretion. Beyond beta cells, hindbrain and hypothalamic receptor populations mediate satiety and gastric emptying, so circuit-level and islet-level questions demand different tools. Because incretin mimetics including semaglutide were optimized against the human receptor and species differences in the extracellular domain alter potency, humanized GLP1R knockins are the honest platform for pharmacology, while conditional nulls with a validated tissue-restricted or neuron-specific Cre assign efficacy to a compartment. Glp1r-Cre lines are knockins, so check dosage. Endpoints include glucose tolerance, insulin secretion, food intake and body weight.',
  Grb2:
    'Grb2, the mouse ortholog of human GRB2, encodes a compact adaptor built from a central SH2 domain flanked by two SH3 domains, with no catalytic activity of its own; the SH2 domain reads phosphotyrosine in pYXNX motifs on activated receptors such as Egfr and on Shc, while the SH3 domains bind proline-rich sequences in Sos1 and Gab1, thereby converting receptor autophosphorylation into Ras nucleotide exchange and, through Gab1, into PI3K activation. Homozygous deletion causes early embryonic lethality around gastrulation, so conditional alleles are required for any postnatal or tissue-specific study, and separation-of-function knockins are particularly informative here: an SH2-binding-dead substitution uncouples receptor docking, while selective disruption of the Sos1-binding or Gab1-binding SH3 surfaces splits Erk from Akt output within the same receptor. The related adaptors Grap and Grap2 overlap in hematopoietic lineages and can mask loss, so consider compound designs and a driver validated in the lineage under study.',
  Grem1:
    'Grem1 is the mouse ortholog of human GREM1 and encodes gremlin 1, a secreted DAN-family cysteine-knot protein that dimerizes and clamps BMP2, BMP4, and BMP7 to prevent type I and type II receptor engagement, thereby sustaining the BMP, SHH, and FGF feedback loop that maintains limb bud outgrowth, with additional reported engagement of VEGFR2 independent of BMP. Nulls die neonatally with failed lung septation and renal agenesis, making conditional deletion the only practical route to adult fibrosis and tumor stroma questions. The human disease logic is ectopic expression rather than loss, since duplication of an upstream enhancer region drives GREM1 in intestinal crypt epithelium and causes hereditary mixed polyposis, so an enhancer duplication or epithelium-restricted overexpression knockin models the disease far better than a null. Grem2, noggin, and chordin overlap as BMP antagonists, so pair a validated stromal or epithelial Cre with compound alleles when scoring BMP tone directly.',
  Grem2:
    'Grem2, the mouse ortholog of human GREM2, encodes the DAN-family antagonist PRDC, a secreted dimer that binds BMP2 and BMP4 with high affinity to block receptor assembly and lower SMAD1, SMAD5, and SMAD8 output in dental mesenchyme, bone remodeling compartments, atrial myocardium, and ovarian follicles. Human heterozygous variants cause autosomal dominant tooth agenesis, and locus variation associates with atrial fibrillation, consistent with BMP tone shaping both odontogenic placode signaling and atrial electrical remodeling. Nulls are viable, so germline deletion is usable, yet conditional alleles are preferable for distinguishing developmental tooth patterning from adult bone turnover and atrial conduction phenotypes. Knocking in patient missense alleles tests whether variants impair secretion, dimerization, or BMP capture, while humanization supports antagonist-directed biologics. Grem1 and noggin cover overlapping BMP-buffering roles in bone and dental mesenchyme, so compound conditional genetics protects against dismissing a real requirement after single-locus knockout.',
  Gria1:
    'Encoding the GluA1 subunit of AMPA-type glutamate receptors, Gria1 is the mouse ortholog of human GRIA1 and contributes the activity-regulated, long cytoplasmic tail arm of tetrameric receptors whose trafficking underlies hippocampal long-term potentiation. GluA1 remains unedited at the Q/R site, so GluA2-lacking assemblies are calcium permeable and inwardly rectifying, and its tail carries the S831 CaMKII/PKC and S845 PKA phosphosites plus PDZ binding for SAP97, while TARP auxiliary subunits such as Cacng8 and stargazin govern surface delivery and channel kinetics. Null mice are viable and fertile but show loss of extrasynaptic AMPA current, deficient CA1 LTP, working memory impairment, and altered locomotor sensitization, making germline deletion informative. Conditional alleles isolate circuit contributions, phosphosite knockins test whether specific residues are required for plasticity, and humanization supports antibody or modulator work. Because Gria2 through Gria4 form heteromers that partially buffer subunit loss, plan compound crosses before attributing phenotypes to a single locus.',
  Gria2:
    'Gria2, the mouse ortholog of human GRIA2, encodes GluA2, the subunit that dictates the biophysical identity of most AMPA receptors because ADAR2-mediated editing at the Q/R site within the pore loop converts a glutamine to arginine, rendering receptors calcium impermeable and linearly rectifying. Editing is essentially complete in wild-type brain, and mice engineered to express unedited GluA2 develop severe seizures and die early, whereas conventional Gria2 nulls survive with markedly increased calcium influx, altered rectification, and impaired plasticity. Additional regulation comes from R/G editing, flip and flop splicing that set desensitization kinetics, and PDZ interactions with GRIP1, GRIP2, and PICK1 that control receptor cycling. Allele choice follows the question directly: conditional nulls address subunit requirement in defined circuits, editing-site or splice-site knockins test biophysical mechanism, and humanization serves biologics. Because Gria1, Gria3, and Gria4 assemble in its absence, quantify subunit composition rather than assuming simple loss of current.',
  Gria3:
    'Gria3 is X-linked in both species and, as the ortholog of human GRIA3, encodes GluA3, an AMPA receptor subunit with a short cytoplasmic tail that supports constitutive, activity-independent receptor cycling through PICK1 and GRIP interactions, in contrast with the regulated insertion driven by GluA1. GluA3-containing receptors are abundant in hippocampus, cortex, and auditory brainstem, and their fast kinetics depend on flip and flop splicing plus TARP association. Human GRIA3 missense variants produce X-linked intellectual disability with both loss-of-function and gain-of-function gating changes, including slowed deactivation and shifted agonist potency, which is why patient-specific knockin alleles are usually more informative than deletion. Constitutive nulls are viable with subtle synaptic phenotypes, so conditional alleles are reserved for cell-type attribution rather than for bypassing lethality. Because Gria1 and Gria2 readily substitute in heteromers, score subunit-resolved currents and rectification, and use humanized alleles when testing modulators with species-divergent binding sites.',
  Gria4:
    'Gria4, the mouse ortholog of human GRIA4, encodes GluA4, the AMPA receptor subunit that dominates fast, high-fidelity transmission in parvalbumin-positive interneurons, cerebellar Bergmann glia, and auditory brainstem synapses such as the calyx of Held, where flop-splice, TARP-associated GluA4 receptors deactivate and desensitize on a submillisecond timescale. Its long cytoplasmic tail resembles that of GluA1 and supports PKA-dependent, activity-driven insertion, and GluA4 expression peaks early in postnatal development before ceding ground to GluA2 and GluA3. Human GRIA4 variants are linked to intellectual disability and absence-like seizures, with gain-of-function changes slowing deactivation. Conditional nulls are the right tool for asking whether interneuron feedforward inhibition or auditory temporal precision depends on this subunit, whereas gating knockins model disease directly. Given robust heteromerization with Gria1 through Gria3, expect partial compensation, and pair alleles with Pvalb-Cre or auditory-restricted drivers so the electrophysiological endpoint matches the circuit under study.',
  Grin1:
    'Grin1, the mouse ortholog of human GRIN1, encodes GluN1, the obligatory subunit present in every NMDA receptor tetramer, contributing the glycine and D-serine binding S1S2 clamshell that must be co-occupied with glutamate on GluN2 subunits for channel opening. Eight GluN1 splice variants generated by cassette exon 5 and the C1, C2, and C2 prime tails control proton sensitivity, PKC modulation, and PDZ-dependent trafficking, while the M2 asparagine sets magnesium block and calcium permeability. Constitutive nulls die within hours of birth from respiratory failure, so viable models rely on hypomorphic knockdown alleles that reduce receptor number, floxed exons paired with CaMKIIa-Cre, Gad2-Cre, or Nex-Cre for regional deletion, or point knockins at the glycine site and magnesium block residue that dissect specific channel properties. No paralog substitutes for GluN1, so deletion is absolute. Match allele class to whether the endpoint is developmental survival, circuit plasticity, or pharmacological occupancy in a humanized ligand-binding domain.',
  Grin2a:
    'Grin2a is the mouse ortholog of human GRIN2A and encodes GluN2A, the glutamate-binding NMDA receptor subunit whose expression rises sharply after the second postnatal week and progressively replaces GluN2B at mature cortical and hippocampal synapses, conferring faster deactivation, higher open probability, and stronger sensitivity to extracellular zinc through its amino-terminal domain. Its shorter C-terminal tail binds PSD-95 and shifts downstream coupling away from the CaMKII-dominated signaling of GluN2B. Human variants populate the epilepsy-aphasia spectrum and developmental encephalopathies, and critically they split into loss-of-function and gain-of-function classes with opposite therapeutic implications, so patient knockins usually outperform simple deletion. Constitutive nulls are viable with impaired LTP and altered fear learning, making conditional alleles a tool for cell-type attribution rather than lethality rescue. Because Grin2b, Grin2c, and Grin2d can occupy the same tetramer position, quantify subunit-resolved kinetics and zinc sensitivity, and use humanized ligand-binding domains for subunit-selective modulator campaigns.',
  Grin2b:
    'GluN2B, encoded by Grin2b, the mouse ortholog of human GRIN2B, is the dominant NMDA receptor GluN2 subunit in embryonic and early postnatal brain, generating currents with slow deactivation and high charge transfer, and it is uniquely blocked by ifenprodil and related amino-terminal domain antagonists. Its exceptionally long cytoplasmic tail binds CaMKII with high affinity and scaffolds PSD-95 and SynGAP, so GluN2B is not merely a pore component but a signaling hub for synaptic plasticity and spine maturation. Constitutive nulls die perinatally with failed suckling and absent hippocampal long-term depression, which mandates floxed alleles combined with CaMKIIa-Cre or Emx1-Cre for adult work. Human GRIN2B variants cause intellectual disability and epileptic encephalopathy through both reduced current and gating gain of function, favoring targeted knockins, while tail-swap alleles separate ion flux from CaMKII recruitment. GluN2A upregulation partially masks loss, so measure ifenprodil-sensitive current directly rather than inferring composition.',
  Grin2c:
    'Grin2c, the mouse ortholog of human GRIN2C, encodes GluN2C, an NMDA receptor subunit whose expression is concentrated in cerebellar granule cells, thalamic relay nuclei, oligodendrocyte lineage cells, and some astrocytes, appearing after the second postnatal week. GluN2C-containing receptors are biophysically distinctive: low open probability, weak magnesium block relative to GluN2A and GluN2B, low single-channel conductance, and slow deactivation, which lets them pass current near resting potential and act as tonic rather than coincidence-detecting conductances. Nulls are viable with mild cerebellar motor learning deficits, so conditional alleles serve cell-type attribution in thalamocortical or glial compartments rather than lethality rescue. Because GluN2A and GluN2B dominate most forebrain synapses and can populate triheteromeric receptors with GluN2C, interpret loss-of-function data with subunit-resolved pharmacology. Positive allosteric modulators selective for GluN2C and GluN2D have species-divergent sites, making humanized ligand-binding or amino-terminal domain knockins the right choice for translational pharmacology endpoints.',
  Grin2d:
    'Encoding GluN2D, Grin2d is the mouse ortholog of human GRIN2D and produces the NMDA receptor subunit with the slowest deactivation kinetics of the family, generating currents that decay over seconds and remain relatively resistant to magnesium block, properties that suit its enrichment in GABAergic interneurons, subthalamic nucleus, substantia nigra, and midbrain circuits. Expression peaks embryonically and in early postnatal life, then persists in defined inhibitory populations, where GluN2D-containing triheteromers shape sustained depolarization rather than brief coincidence detection. De novo GRIN2D variants such as V667I cause severe developmental and epileptic encephalopathy through gain of function, prolonging current and increasing agonist potency, so knockin alleles model the disease far better than deletion, which yields viable mice with modest behavioral change. Grin2c overlaps functionally in some populations and GluN2A or GluN2B substitutes elsewhere, so combine subunit-resolved recordings with interneuron-restricted Cre drivers and reserve humanized alleles for GluN2D-preferring modulator testing.',
  Grn:
    'Grn, the mouse ortholog of human GRN, encodes progranulin, a secreted cysteine-rich glycoprotein composed of seven and a half granulin repeats that is delivered to lysosomes through sortilin (Sort1) and prosaposin, then proteolytically processed by cathepsins and elastase into individual granulin peptides with activities distinct from the intact precursor. Progranulin regulates lysosomal enzyme function, including glucocerebrosidase and cathepsin D, and restrains microglial activation and complement-driven synaptic pruning. Human genetics defines a dosage logic that should drive allele choice: heterozygous nonsense and frameshift mutations cause frontotemporal dementia with TDP-43 pathology through haploinsufficiency, whereas complete biallelic loss causes neuronal ceroid lipofuscinosis type 11. Null mice are viable and accumulate lipofuscin with age-dependent microgliosis, so germline heterozygotes test haploinsufficiency, full nulls test lysosomal storage, and humanized knockins support progranulin-raising biologics and sortilin-blocking antibodies. No paralog compensates, making dose titration rather than redundancy the central experimental variable.',
  Gsdmd:
    'Gsdmd is the mouse ortholog of human GSDMD and encodes gasdermin D, a two-domain protein in which an autoinhibitory C-terminal domain restrains an N-terminal pore-forming module. Inflammatory caspase-1 and caspase-11, and in some settings caspase-8 or neutrophil elastase, cleave the interdomain linker at Asp276 in mouse, liberating the p30 fragment that binds acidic membrane lipids, oligomerizes into large beta-barrel pores, and provides the conduit for mature interleukin 1 beta and interleukin 18 export before NINJ1 dependent membrane rupture completes pyroptosis. Allele choice maps onto mechanism directly: a conditional null removes both cytokine release and lytic death, a D276A noncleavable knockin isolates processing from expression, and pore-dead point mutants separate lysis from unconventional secretion. Gsdme and the Gsdma cluster execute overlapping lytic programs downstream of caspase-3 or bacterial proteases, so pyroptosis-resistant phenotypes may require compound alleles, and myeloid restricted Cre lines assign the death to the intended lineage.',
  Gsk3b:
    'Encoding a constitutively active serine and threonine kinase that prefers substrates pre-phosphorylated four residues carboxy-terminal to its site, Gsk3b is the mouse ortholog of human GSK3B and is inhibited by Akt phosphorylation of Ser9 as well as by Wnt-driven sequestration; within the Axin and Apc destruction complex it phosphorylates beta-catenin at Ser33, Ser37, and Thr41 to license betaTrCP-mediated degradation, and it also targets tau, Snai1, Mcl1, Nfatc, and glycogen synthase. Homozygous nulls die at mid-gestation with hepatocyte apoptosis reflecting defective NF-kB survival signaling, so conditional deletion is standard, while a Ser9-to-alanine knockin creates an Akt-resistant kinase that tests whether inhibitory phosphorylation is required in vivo and a kinase-dead allele distinguishes scaffolding from catalysis. Critically, Gsk3a is a genuine paralog with overlapping substrate specificity, and many phenotypes emerge only in double conditional animals, so plan the compound cross and driver together with the primary flox.',
  H3f3a:
    'H3f3a, ortholog of human H3F3A, encodes histone variant H3.3, which differs from replication-coupled H3.1 at serine 31 and across the alanine 87, isoleucine 89, glycine 90 patch that dictates chaperone selection, permitting HIRA-mediated deposition at transcribed gene bodies and regulatory elements and ATRX with DAXX deposition at telomeres and heterochromatin outside S phase. Its oncohistone alleles are dominant and lesion specific: lysine 27 to methionine sequesters and inhibits the EZH2 active site, collapsing global H3K27 trimethylation in diffuse midline glioma, while glycine 34 to arginine or valine acts in cis by impairing SETD2 and KDM4 activity on the same tail in hemispheric pediatric glioblastoma. Use conditional Lox-Stop-Lox knockin of the specific substitution at the endogenous locus with a spatially restricted Cre, since one mutant copy among many histone genes suffices. The identical protein from H3f3b buffers null alleles, so loss-of-function work requires compound targeting.',
  H3f3b:
    'Although H3f3b, the mouse ortholog of human H3F3B, encodes a protein identical to that of H3f3a, its distinct promoter and untranslated regions give different expression kinetics and it supplies the majority of H3.3 in several lineages. The variant is loaded outside S phase by HIRA at active chromatin and by ATRX with DAXX at repeats, and it carries serine 31, phosphorylated at mitotic pericentromeres and at stimulus-responsive enhancers. Disease alleles differ from those of H3f3a: glycine 34 to tryptophan or leucine defines giant cell tumor of bone, and lysine 36 to methionine inhibits NSD2 and SETD2 in chondroblastoma, each acting dominantly from a single allele. Model designs therefore favor conditional knockin of the precise substitution in the relevant mesenchymal lineage rather than deletion. Null animals show growth and fertility defects with partial compensation by H3f3a, so interpret single-gene deletion cautiously and consider compound alleles for variant dosage questions.',
  Havcr2:
    'Havcr2 encodes TIM-3, the mouse ortholog of human HAVCR2, an immunoglobulin V-type domain plus mucin stalk receptor expressed on exhausted CD8 T cells, Th1 cells, NK cells, and myeloid populations, with reported ligands including galectin 9, phosphatidylserine, CEACAM1, and HMGB1. Unlike PD-1 it carries no ITIM or ITSM, and instead its cytoplasmic tyrosines Y256 and Y263 are phosphorylated to displace HLA-B associated transcript 3 and permit Fyn dependent inhibitory signaling, which is why TIM-3 behaves as a context dependent regulator rather than a simple brake. Germline loss-of-function HAVCR2 variants cause subcutaneous panniculitis-like T cell lymphoma with hemophagocytic syndrome, giving a genuine disease knockin rationale distinct from a null. Because clinical antibodies do not cross-react, humanization is the allele for pharmacology, while conditional nulls with Cd4-Cre or Lyz2-Cre separate lymphoid from myeloid contributions, and combining with Pdcd1 loss is usually required before checkpoint phenotypes become measurable.',
  Hes1:
    'Hes1, the mouse ortholog of human HES1, encodes a basic helix-loop-helix repressor with an Orange domain and a carboxy-terminal WRPW motif that recruits Tle and Groucho corepressors; it is a direct Notch target activated by the NICD and Rbpj complex, binds N-box and class C sites, and represses proneural genes including Ascl1 as well as Cdkn1b, while autorepression of its own promoter combined with rapid protein and mRNA turnover generates two-hour oscillations that time neural progenitor and somite decisions. Homozygous nulls die during embryogenesis with severe neural tube, eye, and pancreatic defects, making conditional alleles essential for postnatal work, and fluorescent or luciferase fusion knockins are the design of choice when the question concerns oscillation dynamics rather than presence or absence. Because Hes5, Hes3, Hey1, and Hey2 provide overlapping repression, single deletions often appear buffered; compound alleles combined with an inducible, lineage-restricted Cre keep the readout aligned with the biology.',
  Hey1:
    'Belonging to the HESR family, Hey1 is the mouse ortholog of human HEY1 and encodes a basic helix-loop-helix Orange domain repressor that is a direct Rbpj-dependent Notch target; it homodimerizes and heterodimerizes with Hey2 and Hes1, binds class B and class C sites, and represses cardiogenic and chondrogenic programs including Gata4-dependent transcription, contributing to arterial versus venous endothelial specification and cardiac cushion development. In humans, the recurrent HEY1 to NCOA2 fusion defines mesenchymal chondrosarcoma, which makes a fusion knockin a distinct and highly informative allele class from simple loss: the fusion asks whether a chimeric transcriptional activator initiates cartilage-lineage tumors, whereas a conditional null asks whether endogenous repression is required for vascular and valvular patterning. Single Hey1 nulls are viable because Hey2 and Hes1 compensate, and double Hey1 and Hey2 animals show the cardiovascular lethality, so plan compound genetics and an endothelial or mesenchymal driver alongside the primary allele.',
  Hif1a:
    'Hif1a, the mouse ortholog of human HIF1A, encodes the oxygen-labile alpha subunit of hypoxia-inducible factor 1, a basic helix-loop-helix PAS protein that dimerizes with Arnt and binds RCGTG hypoxia response elements to induce glycolytic enzymes, Slc2a1, Vegfa, and Pdk1. Regulation is post-translational: in normoxia the Egln prolyl hydroxylases modify Pro402 and Pro564 in the oxygen-dependent degradation domain, creating the binding site for the Vhl E3 ligase, while factor inhibiting HIF hydroxylates Asn803 to block p300 recruitment. Homozygous nulls die near E10.5 with vascular and cardiac defects, so conditional deletion is standard for tumor, immunometabolism, and renal studies, whereas a triple knockin substituting both prolines and the asparagine yields an oxygen-insensitive, constitutively active factor that tests whether HIF output alone drives a phenotype. Epas1 encodes Hif2a with overlapping and sometimes antagonistic targets, so isoform-specific compound alleles and a validated driver determine what the readout actually measures.',
  Hist1h3b:
    'Among the replication-dependent histone genes, Hist1h3b, ortholog of human HIST1H3B, is the most clinically consequential, encoding canonical histone H3.1 within the Hist1 cluster and producing a non-polyadenylated transcript that terminates in a stem-loop bound by SLBP and cleaved by the U7 small nuclear ribonucleoprotein, restricting expression to S phase under NPAT and CDK2 control at histone locus bodies. New H3.1 with H4 reaches chromatin through ASF1 and the PCNA-tethered CAF-1 complex. The lysine 27 to methionine substitution at this locus defines a large subset of diffuse midline glioma, where the mutant tail occupies and inhibits the EZH2 active site, erasing H3K27 trimethylation genome wide despite representing a small fraction of total H3. Model this with a conditional Lox-Stop-Lox K27M knockin driven in pontine or thalamic progenitors, because deletion of any single cluster gene is silently buffered by the many identical paralogs.',
  Hist1h3c:
    'Hist1h3c, ortholog of human HIST1H3C, is a second major source of the K27M oncohistone in diffuse midline glioma and encodes canonical histone H3.1, which carries cysteine 96 in place of the serine found in H3.2 and whose serine 87, valine 89, methionine 90 patch routes it to CAF-1 rather than HIRA. Its transcript lacks a poly(A) tail, ending instead in the conserved stem-loop that SLBP stabilizes only while replication proceeds, so expression collapses when forks stall. Mutant protein incorporated from this locus poisons PRC2 in trans, and the resulting loss of H3K27 trimethylation is accompanied by redistribution of H3K27 acetylation to active enhancers. Because roughly a dozen genes encode identical H3.1, conditional knockin of the mutant residue is far more informative than deletion, which is buffered. Pair the knockin with a developmentally timed, region-restricted Cre to reproduce the anatomic specificity of the human disease.',
  Hist1h3d:
    'Within the Hist1 cluster, Hist1h3d, ortholog of human HIST1H3D, contributes canonical histone H3.1 to the bulk nucleosome pool assembled behind the replication fork. Its regulation is transcript based rather than promoter based alone: the messenger RNA ends in a conserved stem-loop instead of a poly(A) tail, is bound by the stem-loop binding protein, is matured by U7 small nuclear ribonucleoprotein cleavage, and is degraded through oligouridylation and the LSM1 to LSM7 pathway once S phase ends or replication is inhibited, which enforces tight coupling of histone supply to DNA synthesis. Because every H3.1 gene in the locus encodes an identical protein, a single-gene null yields essentially no chromatin phenotype, so meaningful engineering means either knockin of a defined tail substitution that acts dominantly or multiplexed deletion across the cluster. Choose the dominant knockin route when the endpoint is a chromatin mark, and reserve multiplex deletion for histone dosage questions.',
  Hist1h3e:
    'S-phase transcription of Hist1h3e, ortholog of human HIST1H3E, is driven from within the histone locus body, a nuclear compartment nucleated by NPAT after CDK2 with cyclin E phosphorylation, which concentrates FLASH, the U7 machinery, and the processing factors that generate the stem-loop terminated messenger RNA encoding canonical histone H3.1. The protein product is indistinguishable from that of its cluster neighbors and is chaperoned by ASF1A or ASF1B to CAF-1 for replication-coupled deposition, where it acquires the marks that define constitutive and facultative heterochromatin. Because the coding sequence is invariant between mouse and human, epitope humanization is not a meaningful design option here. Single-locus deletion is compensated by the remaining H3.1 genes, so useful alleles are point-mutant knockins that act dominantly on writers or readers of the H3 tail. Match Cre timing to a proliferative compartment, since replication-dependent histone expression is absent from quiescent cells.',
  Hist1h3f:
    'Newly synthesized H3.1 encoded by Hist1h3f, ortholog of human HIST1H3F, enters chromatin through a defined relay: cytoplasmic folding with NASP and the HAT1 with RBBP7 complex, transfer to importin, handoff to ASF1A or ASF1B in the nucleus, and delivery to the CAF-1 heterotrimer, which is tethered to PCNA at the replication fork for deposition of an H3 to H4 tetramer behind the polymerase. That route distinguishes canonical H3.1 from the HIRA-dependent loading of H3.3 and explains why cluster histones accumulate only during DNA synthesis. Since all cluster members produce identical protein, deletion of this single gene is buffered and generates no measurable mark change, so productive designs use knockin substitutions at tail residues that dominantly inhibit specific methyltransferases or demethylases. Choose the substitution to match the pathway under test, and use an inducible Cre in a cycling lineage so mutant histone is actually incorporated.',
  Hist1h3g:
    'Heterochromatin maintenance depends on the lysine 9 residue of the histone H3 tail supplied in bulk by cluster genes including Hist1h3g, ortholog of human HIST1H3G, which encodes canonical replication-coupled H3.1. SUV39H1 and SUV39H2 trimethylate that residue at pericentromeric major satellite repeats, creating the binding site for the HP1 chromodomain and a self-propagating loop that silences repeats, retroelements, and lineage-inappropriate genes, while KDM4 family demethylases oppose it. Loss of this compartment produces chromosome missegregation and derepression of transposable elements in tumors. Because the cluster encodes many identical copies of the protein, single-gene knockout is functionally invisible, and the informative alleles are dominant tail substitutions such as lysine 9 to methionine, which titrates SUV39 enzymes and collapses the mark from a minority of nucleosomes. Deploy such a knockin as a conditional Lox-Stop-Lox allele with a proliferating-tissue Cre and score heterochromatin integrity directly.',
  Hist1h3h:
    'Promoter-proximal chromatin states are written on the same H3 tail supplied by Hist1h3h, ortholog of human HIST1H3H, one of the replication-dependent genes encoding canonical histone H3.1. Trimethylation of lysine 4 by the SETD1A, SETD1B, and MLL family complexes, assembled with WDR5, RBBP5, ASH2L, and DPY30, marks active and poised promoters and is read by TAF3, CHD1, and the ING PHD fingers, while unmethylated lysine 4 is required for DNMT3A ADD domain engagement, coupling this residue directly to de novo DNA methylation. MLL rearranged leukemia and NSD-driven tumors both distort this axis. Single-gene deletion within the cluster is buffered by identical paralogous copies, so the productive engineering choice is a conditional knockin of a dominant tail substitution such as lysine 4 to methionine that inhibits the writer complexes. Select a lineage Cre appropriate to the malignancy and read out promoter methylation and transcriptional output together.',
  Hist1h3i:
    'Co-transcriptional chromatin marking uses the H3 tail contributed by genes such as Hist1h3i, ortholog of human HIST1H3I, which encodes replication-coupled canonical histone H3.1. SETD2, recruited through the phosphorylated C-terminal domain of elongating RNA polymerase II, trimethylates lysine 36 across gene bodies, and that mark recruits the MSH2 with MSH6 mismatch repair complex, the DNMT3B PWWP domain, and the RPD3S deacetylase module to suppress cryptic intragenic initiation. NSD1 and NSD2 generate the dimethyl state at enhancers and intergenic regions. Oncohistone substitutions of lysine 36 to methionine dominantly inhibit these enzymes, showing that a minority of mutant nucleosomes reshapes the entire genome. Because identical protein is produced by all cluster genes, plain deletion of this locus is compensated and uninformative. Build a conditional K36M knockin instead, choose a mesenchymal or hematopoietic Cre matched to the tumor context, and score SETD2 output and cryptic transcription.',
  Hist1h3j:
    'Methylation of lysine 79, which lies in the globular core rather than the tail of the histone H3 encoded by Hist1h3j, ortholog of human HIST1H3J, is deposited by DOT1L and requires prior H2B lysine 120 ubiquitination by RNF20 with RNF40, a textbook trans-histone crosstalk. This mark is essential to the transcriptional program of MLL rearranged leukemia, where fusion partners recruit DOT1L to HOXA9 and MEIS1, motivating clinical DOT1L inhibition. The gene itself is one of many replication-dependent loci producing identical canonical H3.1, transcribed in S phase from stem-loop terminated messages and deposited by CAF-1. Consequently a single-gene null is buffered and yields no chromatin readout, while a conditional knockin substituting lysine 79 or an adjacent core residue provides a dominant, interpretable perturbation. Pair such an allele with an inducible hematopoietic Cre and measure H3K79 dimethylation together with HOXA cluster expression as the endpoint.',
  Hist1h3k:
    'Mitotic chromosome behavior is governed in part by phosphorylation of serine 10 on the histone H3 tail encoded by cluster genes including Hist1h3k, a mouse locus corresponding to the human HIST1H3K designation and producing canonical replication-coupled H3.1. Aurora B, as the enzymatic core of the chromosomal passenger complex with INCENP, survivin, and borealin, phosphorylates this residue from late G2 through anaphase, ejecting HP1 from methylated lysine 9 by a phospho-methyl switch and coupling condensation to error correction at kinetochores. MSK1 and MSK2 place the same mark at immediate early gene promoters during interphase signaling. Because the cluster provides many identical protein copies, deletion of one gene changes nothing measurable, so dominant knockins that block or mimic modification of this residue are the informative design. Use a conditional allele with a proliferative Cre and read out mitotic fidelity, aneuploidy, and passenger complex localization rather than bulk expression.',
  Hist1h3l:
    'Threonine 3 phosphorylation of histone H3, supplied in bulk by replication-dependent genes such as Hist1h3l, a locus corresponding to the human HIST1H3L designation, is catalyzed by haspin during mitosis and creates the docking site that positions survivin and the chromosomal passenger complex at inner centromeres, working together with Bub1-dependent H2A threonine 120 phosphorylation to license Aurora B error correction. The gene follows canonical cluster rules, with S phase restricted transcription, a stem-loop terminated transcript stabilized by SLBP, and CAF-1 mediated deposition coupled to the replication fork. Since every H3.1 gene encodes the same protein, knocking out this one locus is compensated immediately and produces no phenotype worth measuring. Informative models instead introduce dominant substitutions at the modified residue through a conditional knockin, or delete multiple cluster genes together to probe histone dosage. Match Cre expression to a cycling tissue and score centromeric passenger complex recruitment and segregation fidelity.',
  Hist1h3m:
    'Nucleosome core stability, not just tail signaling, depends on residues within the histone fold of the H3.1 protein encoded by Hist1h3m, a locus corresponding to the human HIST1H3M designation. Acetylation of lysine 56 near the DNA entry and exit site loosens histone to DNA contacts and promotes chaperone-mediated assembly during replication and repair, while acetylation of lysine 122 within the dyad destabilizes the particle and facilitates eviction during transcription. These lateral surface modifications are removed by sirtuins and HDAC complexes to restore compaction. The gene itself is replication dependent, transcribed only in S phase from a stem-loop terminated message and loaded by ASF1 with CAF-1. With many identical copies across the cluster, single-locus deletion is buffered and phenotypically silent, so use conditional knockins of core substitutions when interrogating nucleosome turnover, and reserve multiplexed cluster deletion for questions about total histone supply during replication stress.',
  Hist1h3n:
    'Polycomb repression writes on the same substrate produced by Hist1h3n, a locus corresponding to the human HIST1H3N designation and encoding canonical replication-coupled histone H3.1. PRC2, through its EZH2 catalytic subunit with EED and SUZ12, trimethylates lysine 27 to establish facultative heterochromatin over developmental regulators, a mark read by the CBX chromodomains of PRC1 and erased by KDM6A and KDM6B, while the same residue is acetylated by CBP and p300 at active enhancers, making lysine 27 a direct switch between silencing and activation. Oncohistone substitution to methionine at this position dominantly inhibits PRC2 across the genome. Because the cluster contains many genes encoding identical protein, a single knockout provides no readout, so conditional knockin of the mutant residue is the design that reproduces disease biology. Select a Cre matched to the developmental window and lineage of interest and quantify H3K27 trimethylation and acetylation redistribution.',
  Hist1h3o:
    'Balanced supply of canonical histone H3.1, contributed by cluster loci including Hist1h3o, a gene corresponding to the human HIST1H3O designation, is itself a genome stability variable. Excess free histone is toxic and is cleared by chaperone buffering and proteasomal degradation, while insufficient supply during S phase produces nascent chromatin with reduced nucleosome density, exposed single-stranded DNA, fork slowing, and ATR-dependent checkpoint activation. This is why transcription of every cluster gene is confined to S phase by NPAT and CDK2 and why the stem-loop transcript is destroyed within minutes of replication arrest. Deletion of one gene from a family encoding identical protein is absorbed by the remainder, so dosage questions require multiplexed deletion across the locus rather than a single flox allele, whereas mark-specific questions require dominant tail knockins. Define which of those two endpoints you need before designing, and use a proliferative Cre so the allele is expressed at all.',
  Hist1h3p:
    'Cluster architecture dictates what is feasible at Hist1h3p, a locus corresponding to the human HIST1H3P designation within the tightly packed replication-dependent histone array where H3, H4, H2A, H2B, and H1 genes are interleaved, share bidirectional promoters, and are coordinately activated in S phase from histone locus bodies. Each produces a stem-loop terminated, non-polyadenylated transcript processed by the U7 small nuclear ribonucleoprotein and stabilized by SLBP. That physical arrangement means a conventional flox allele risks disturbing neighboring histone genes through promoter and enhancer sharing, and it also means the protein output is fully redundant with the other H3.1 genes. Practical designs are therefore either a precise dominant point-mutant knockin at this locus, which reports on tail modification biology, or CRISPR multiplex deletion across several cluster members for dosage studies. Choose a Cre active in cycling cells and validate that neighboring histone gene expression remains intact after targeting.',
  Hist1h4a:
    'Hist1h4a, ortholog of human HIST1H4A, encodes canonical histone H4, a 102 residue protein whose sequence is invariant between mouse and human and identical across every gene in the replication-dependent cluster. Two copies of H4 pair with two of H3 to form the tetramer that nucleates the nucleosome, and its unstructured amino-terminal tail carries lysines 5, 8, 12, 16, and 20 that constitute one of the densest regulatory surfaces in chromatin. Expression is confined to S phase, with a stem-loop terminated transcript bound by SLBP and processed by the U7 small nuclear ribonucleoprotein rather than polyadenylated. Because the protein is absolutely conserved, humanization has no meaning here, and because many genes encode it, single-locus deletion is silent. Meaningful alleles are dominant tail substitutions introduced as conditional knockins, or multiplexed cluster deletions for dosage work, matched to a Cre active in proliferating tissue.',
  Hist1h4b:
    'Newly translated histone H4 from Hist1h4b, ortholog of human HIST1H4B, is diacetylated at lysines 5 and 12 by the HAT1 with RBBP7 complex in the cytoplasm, a modification signature that marks the predeposition pool, assists NASP-mediated folding with H3, and accompanies nuclear import before ASF1 hands the dimer to CAF-1 for replication-coupled assembly. These acetyl groups are removed by HDAC1 and HDAC2 containing complexes shortly after deposition as chromatin matures. The gene shares all canonical cluster features, including S phase restricted transcription and a stem-loop terminated, non-polyadenylated message. Since the encoded protein is identical to that of every other H4 gene, deletion at this locus is fully compensated and produces no measurable chromatin change, and species conservation makes humanization moot. Design instead around conditional knockin of lysine to arginine or glutamine substitutions to test predeposition acetylation directly, using an inducible Cre in a cycling lineage.',
  Hist1h4c:
    'Acetylation of lysine 16 on the histone H4 tail encoded by Hist1h4c, ortholog of human HIST1H4C and one of the most highly expressed histone genes, is deposited by KAT8 within the MSL and NSL complexes and is uniquely potent because that residue makes the internucleosomal contact with the H2A acidic patch. Neutralizing its charge blocks 30 nanometer fiber compaction and higher order folding, and its loss is a common early event in tumor chromatin alongside reduced H4K20 trimethylation. SIRT1 and HDAC complexes reverse the mark, while BRD4 bromodomains read it in combination with neighboring acetyl lysines. Because the cluster encodes identical H4 protein from many loci, single-gene deletion is buffered, and the invariant sequence between species makes humanization pointless. Use a conditional lysine 16 to arginine or glutamine knockin to lock the residue in an unmodifiable or acetyl-mimicking state, and read out compaction and transcriptional output.',
  Hist1h4d:
    'Monomethylation of lysine 20 on histone H4, supplied by cluster genes including Hist1h4d, ortholog of human HIST1H4D, is deposited exclusively by KMT5A during late S phase and mitosis and is tightly cell cycle controlled through CRL4 and APC/C mediated degradation of the enzyme. That mark licenses origin firing by promoting ORC1 recruitment through its BAH domain, and its dysregulation produces rereplication and chromosomal instability. It also serves as the obligatory substrate for conversion to the dimethyl and trimethyl states. The gene follows canonical replication-dependent rules, with a stem-loop terminated transcript and CAF-1 mediated deposition. As every H4 gene in the cluster encodes the same invariant protein, deleting this locus alone changes nothing measurable and humanization is meaningless given complete conservation. Use a conditional lysine 20 to arginine knockin to interrogate licensing and replication control, driven by a Cre active in a proliferating compartment.',
  Hist1h4e:
    'Dimethylated lysine 20 on the histone H4 produced by Hist1h4e, ortholog of human HIST1H4E, is generated by SUV420H1 and SUV420H2 from the KMT5A monomethyl substrate and is the dominant constitutive state across the genome. Its principal function in genome integrity is to serve, together with H2A lysine 15 ubiquitination, as the bivalent signal read by the tandem TUDOR domain of 53BP1, which drives repair pathway choice toward non-homologous end joining and antagonizes BRCA1-dependent resection, making this residue central to PARP inhibitor response biology. The trimethyl state marks pericentromeric heterochromatin. Because the invariant protein is encoded by many cluster genes, a single deletion is compensated and no cross-species epitope difference exists to humanize. Conditional knockin of lysine 20 to arginine is therefore the informative allele for repair pathway studies, ideally combined with Brca1 or Trp53bp1 genetics and a Cre matched to the tumor lineage.',
  Hist1h4f:
    'Arginine 3 of the histone H4 tail encoded by Hist1h4f, ortholog of human HIST1H4F, is a bidirectional switch: PRMT1 deposits asymmetric dimethylation that promotes subsequent acetylation by p300 and transcriptional activation, whereas PRMT5 within the methylosome deposits symmetric dimethylation that recruits repressive readers and silences target genes. The competition between these enzymes makes this residue a node for the arginine methyltransferase inhibitors now in clinical development, particularly in MTAP deleted tumors dependent on PRMT5. Like all cluster members the gene is transcribed only in S phase, yields a stem-loop terminated non-polyadenylated message, and delivers protein through ASF1 to CAF-1. Its product is identical to that of every other H4 gene and to human H4, so neither single-locus knockout nor humanization is informative. Use a conditional arginine 3 to lysine or alanine knockin, paired with a lineage-appropriate Cre, and score methylation state alongside downstream acetylation.',
  Hist1h4g:
    'Bromodomain readers converge on the acetylated tail of histone H4 encoded by Hist1h4g, ortholog of human HIST1H4G. BRD4 and its BET family relatives engage diacetylated lysines 5 and 8 through tandem bromodomains, concentrating at super enhancers where they recruit the positive transcription elongation factor complex to release paused RNA polymerase II at MYC and other oncogenic loci, which is the mechanistic basis for BET inhibitor activity in leukemia and midline carcinoma. Acetylation is written by p300 and CBP and erased by HDAC1 and HDAC2 complexes. The gene is a replication-dependent cluster member producing invariant H4 protein from a stem-loop terminated transcript, so deletion is buffered by identical paralogs and humanization is meaningless given complete conservation across species. Design instead a conditional knockin substituting lysines 5 and 8 to arginine to remove the reader docking site, and score elongation and enhancer occupancy as endpoints.',
  Hist1h4h:
    'The basic patch spanning residues 16 through 23 of the histone H4 tail encoded by Hist1h4h, ortholog of human HIST1H4H, docks into the acidic patch formed by H2A and H2B on the neighboring nucleosome, and that single contact governs chromatin fiber compaction and provides the binding surface exploited by silencing factors, chromatin remodelers, and viral proteins. The same surface is engaged by PRC1 and by numerous nucleosome binding enzymes that require an intact H4 tail for stimulation, which is why charge-neutralizing acetylation at lysine 16 has such outsized structural consequences. The gene follows standard cluster regulation with S phase restricted expression and stem-loop dependent transcript stability. Because its protein is identical to that of every other H4 gene and fully conserved with human H4, only dominant knockin substitutions across the basic patch generate interpretable phenotypes. Combine such an allele with a proliferative Cre and assay higher order chromatin structure directly.',
  Hist1h4i:
    'Chaperone-mediated deposition determines where the histone H4 encoded by Hist1h4i, ortholog of human HIST1H4I, ends up in chromatin. The H3 to H4 dimer is escorted by ASF1A or ASF1B, which blocks premature tetramerization, then transferred to the CAF-1 heterotrimer of CHAF1A, CHAF1B, and RBBP4 for PCNA-coupled assembly behind the replication fork, or to HIRA for replication-independent gap filling with the H3.3 variant. Parental histone recycling through MCM2 and POLE3 with POLE4 preserves marks across the fork and underlies epigenetic inheritance. This locus is a standard replication-dependent cluster gene with an S phase restricted, stem-loop terminated transcript. Its invariant protein product is shared with every other H4 gene and identical to human H4, so single deletion is silent and humanization is not applicable. Use dominant tail knockins to interrogate chaperone recognition, and time Cre activity to an actively cycling population.',
  Hist1h4j:
    'Replication coupling of Hist1h4j, ortholog of human HIST1H4J, is enforced at the level of RNA rather than protein. The transcript carries no poly(A) tail and instead terminates in a stem-loop that the stem-loop binding protein grips, coordinating U7 small nuclear ribonucleoprotein directed cleavage, nuclear export, and translational efficiency, and when replication halts the message is oligouridylated by TUT7 and degraded through the LSM1 to LSM7 and exosome pathways within minutes. Transcription itself is confined to S phase by NPAT phosphorylation downstream of CDK2 with cyclin E at histone locus bodies. The encoded protein is canonical histone H4, invariant across all cluster genes and identical between mouse and human, which removes both single-gene knockout and humanization from the useful design space. Reserve multiplex cluster deletion for histone supply and replication stress endpoints, and use dominant tail substitution knockins for chromatin mark questions.',
  Hist1h4k:
    'Lysine 91 sits at the H3 to H4 tetramer interface of the protein encoded by Hist1h4k, a locus corresponding to the human HIST1H4K designation, and its acetylation by the HAT1 containing complex regulates the assembly and disassembly of the histone core rather than tail signaling, influencing nucleosome stability, chromatin assembly during replication, and sensitivity to DNA damaging agents. Mutation of this residue produces genome instability without altering any tail modification, illustrating that structural surfaces of H4 are separately targetable. The gene is a replication-dependent cluster member with an S phase confined, stem-loop terminated transcript deposited by ASF1 with CAF-1. Its product is identical to that of all other H4 genes and to human H4, so a single knockout is buffered and humanization has no target. Conditional knockin of lysine 91 substitutions is the informative allele, best combined with a proliferative Cre and replication stress or damage sensitivity endpoints.',
  Hist1h4l:
    'Diacetylation at lysines 5 and 12 of nascent histone H4 from Hist1h4l, a locus corresponding to the human HIST1H4L designation, is the conserved hallmark of the soluble predeposition pool, placed by HAT1 with RBBP7 and largely removed after chromatin incorporation, a maturation step that helps distinguish newly assembled from parental nucleosomes and contributes to timing of chromatin restoration behind the fork. Failure to erase these marks alters replication-coupled silencing and heterochromatin re-establishment. The locus behaves like every other member of the array, transcribed only in S phase, terminating in a stem-loop bound by SLBP, and delivering protein through ASF1 to CAF-1. Because the encoded H4 is invariant across the cluster and between species, both single-gene deletion and humanization are uninformative. Build conditional lysine to arginine or glutamine knockins to lock the predeposition state, pair with an inducible Cre in cycling tissue, and score chromatin maturation kinetics.',
  Hist1h4m:
    'Deacetylase complexes act continuously on the histone H4 tail supplied by loci such as Hist1h4m, corresponding to the human HIST1H4M designation. SIN3A with HDAC1 and HDAC2, the NuRD complex, and the NCOR and SMRT corepressors strip acetyl groups from lysines 5, 8, 12, and 16, while SIRT1 and SIRT6 use NAD as cofactor to target lysine 16 specifically, and this turnover, on the order of minutes, sets enhancer and promoter output far more dynamically than methyl marks. Clinical HDAC inhibitors act directly on this balance. The gene itself is a replication-dependent cluster member with an S phase restricted, stem-loop terminated transcript and CAF-1 mediated deposition, and its protein is identical across the family and between mouse and human, so neither knockout nor humanization yields information. Use conditional acetyl-null or acetyl-mimicking knockins with a lineage-matched Cre and read out enhancer acetylation directly.',
  Hist1h4n:
    'Balanced histone H4 supply, to which Hist1h4n, a locus corresponding to the human HIST1H4N designation, contributes, is a determinant of replication fork stability rather than a passive stoichiometric requirement. Undersupply leaves nascent DNA underpackaged, exposing single-stranded regions, slowing forks, and triggering ATR with CHK1 signaling, whereas oversupply generates free histone that is cytotoxic and must be buffered by NASP and ASF1 or cleared by the proteasome. Coordinated S phase transcription at histone locus bodies and rapid stem-loop dependent transcript decay after replication arrest exist precisely to hold that balance. Because the invariant protein is produced by many genes in the cluster and is identical to human H4, single-locus deletion is compensated and humanization is not applicable. Address supply questions with multiplexed deletion across several cluster genes, address mark questions with dominant tail knockins, and in both cases use a Cre restricted to cycling cells.',
  Hist1h4o:
    'Recurrent somatic mutations in replication-dependent histone genes, including loci such as Hist1h4o that correspond to the human HIST1H4O designation, are now well documented in B cell malignancy, where substitutions in histone H4 and the linker histone H1 genes of the same cluster accumulate in follicular lymphoma, diffuse large B cell lymphoma, and chronic lymphocytic leukemia, loosening chromatin, altering heterochromatin distribution, and promoting a stem-like transcriptional state. The gene produces canonical H4 through the standard replication-coupled route, with S phase confined transcription, a stem-loop terminated transcript held by SLBP, and CAF-1 dependent deposition. Since the protein is identical across every cluster member and fully conserved with human H4, deletion at one locus is buffered and humanization has no epitope to transfer. Introduce the patient substitution as a conditional knockin, restrict expression with Cd19-Cre or a germinal center driver, and score chromatin accessibility and lymphomagenesis.',
  Hist1h4p:
    'Engineering at Hist1h4p, a locus corresponding to the human HIST1H4P designation, is constrained by the physical organization of the replication-dependent histone array, where H4 genes are interleaved with H3, H2A, H2B, and H1 genes, often sharing bidirectional promoters and coordinate S phase activation at histone locus bodies, so a conventional flox cassette risks perturbing neighboring histone transcription rather than isolating a single gene. Every gene in the family encodes the same invariant H4 protein, which is also identical to human H4, so single-locus knockout is compensated immediately and humanization transfers nothing. The practical design space is therefore precise dominant point-mutant knockins that report on specific tail or core modifications, or CRISPR multiplex deletion across several family members to test histone dosage and replication stress. Validate that neighboring histone gene expression is unchanged after targeting, and drive any conditional allele with a Cre active in proliferating tissue.',
  Hk1:
    'Hk1 encodes the mouse ortholog of human HK1, the constitutively expressed 100 kDa hexokinase that phosphorylates glucose to glucose-6-phosphate and anchors to the outer mitochondrial membrane through an N-terminal hydrophobic segment engaging VDAC, coupling oxidative phosphorylation derived ATP to the first committed glycolytic step while remaining strongly product inhibited. The gene uses alternative tissue-specific promoters generating erythroid and testis-restricted transcripts, which explains its divergent human phenotypes: recessive alleles cause nonspherocytic hemolytic anemia, whereas particular dominant variants cause hereditary motor and sensory neuropathy or retinitis pigmentosa without hematologic disease. Allele design should follow that promoter logic, using conditional nulls with erythroid or neuronal Cre to test lineage-specific glycolytic dependence and patient variant knockins to model the dominant neuropathy and retinal alleles. Because Hk2 is induced in muscle and tumors, confirm isoform composition before assigning phenotype. Match allele to endpoint, whether reticulocyte survival, retinal electrophysiology, or nerve conduction with axon morphometry.',
  Hk2:
    'Hk2 is the mouse ortholog of human HK2 and encodes the inducible hexokinase of skeletal muscle, heart and adipose tissue, distinguished by two catalytically active halves and by transcriptional induction downstream of insulin, hypoxia through HIF1A, and MYC, which together scale glycolytic entry to demand. Like HK1 it binds VDAC at the outer mitochondrial membrane, an interaction promoted by AKT-dependent phosphorylation that both accelerates glucose phosphorylation and suppresses BAX-dependent apoptosis, giving the protein a survival function alongside catalysis. Tumors frequently depend on this isoform, and Hk2 deletion slows initiation and progression in several models while leaving normal tissues comparatively intact. A conditional null with muscle, adipose or tumor-restricted Cre addresses insulin-stimulated glucose disposal and tumor glycolytic dependence, whereas mitochondrial binding mutant knockins isolate the antiapoptotic role. Since Hk1 remains active in the same tissues, quantify total hexokinase activity, and match allele to clamp studies, fluorodeoxyglucose imaging, or tumor latency endpoints.',
  Hk3:
    'Among the hexokinases, Hk3, ortholog of human HK3, encodes the isoform with the most restricted distribution and a strongly autoinhibitory N-terminal extension, expressed chiefly in myeloid cells where it phosphorylates glucose with high affinity and pronounced substrate inhibition and has been linked to neutrophil granule biology and PPARG-driven expression rather than to bulk glycolytic flux. Its restricted pattern means whole-body glucose homeostasis is unlikely to shift on deletion, and the informative phenotypes are immunometabolic, spanning granulopoiesis, phagocyte oxidative burst and inflammatory responses. Design accordingly, using a constitutive null for first-pass immunophenotyping, a conditional null with Lyz2-Cre or Vav1-Cre to establish myeloid autonomy, and a reporter knockin to map genuine expression, which remains contested across mouse and human myeloid subsets. Hk1 and Hk2 are co-expressed in the same cells and will mask flux changes, so measure isoform-resolved activity. Pair the allele with infection challenge, bone marrow chimera, or single-cell metabolic endpoints rather than glycemic curves.',
  Hkdc1:
    'Hkdc1 encodes the mouse ortholog of human HKDC1, the fifth hexokinase family member, which retains hexokinase domain architecture but exhibits low glucose-phosphorylating activity and is expressed in liver, gut and placenta rather than in classic glycolytic tissues. Human variants near HKDC1 associate with maternal glucose levels during pregnancy and with gestational glucose handling, and mouse work implicates the protein in hepatic glucose tolerance, lipid handling and association with mitochondria and lipid droplets, suggesting a regulatory rather than high-flux catalytic role. Because the physiology is pregnancy and liver centered, allele choice should match: a whole-body null clarifies gestational glucose phenotypes, a hepatocyte conditional null with Alb-Cre separates liver-autonomous effects from placental contributions, and humanized knockins permit interrogation of specific human coding and noncoding variants. Hk1 and Hk2 supply the bulk of hexokinase activity in most tissues, so avoid total activity assays as a readout. Center endpoints on pregnancy glucose tolerance, hepatic lipid quantification and tracer-based flux.',
  Hnrnpa1:
    'Hnrnpa1, the mouse ortholog of human HNRNPA1, encodes heterogeneous nuclear ribonucleoprotein A1, an abundant RNA-binding protein with tandem RRM domains and a carboxy-terminal low-complexity prion-like domain that drives reversible liquid-liquid phase separation. A1 antagonizes SR proteins to control alternative splice site selection, participates in mRNA export and internal ribosome entry site-dependent translation, and shuttles through the M9 signal recognized by transportin-1. Disease mutations in the prion-like domain, notably D262V, accelerate fibrillization and cause multisystem proteinopathy with inclusion body myopathy, Paget disease of bone, and ALS, so knockin alleles preserve the gain-of-toxic-assembly mechanism that deletion cannot reproduce. Because A1 is broadly required for splicing homeostasis, conditional floxed alleles paired with neuron- or muscle-restricted Cre drivers are safer than germline deletion for adult phenotyping. The paralog Hnrnpa1l2 and the related Hnrnpa2b1 overlap substantially in target repertoire, so score splicing outcomes transcriptome-wide instead of assuming loss produces a clean null state.',
  Hnrnpa2b1:
    'Alternative splicing of exon 2 in Hnrnpa2b1, the mouse ortholog of human HNRNPA2B1, produces the A2 and B1 isoforms of a nuclear RNA-binding protein that pairs two RRM domains with a glycine-rich prion-like domain. A2 binds the A2 response element to transport myelin basic protein transcripts along oligodendrocyte processes, functions as a nuclear reader of N6-methyladenosine that shapes splicing and primary microRNA processing, and phase separates into transport granules whose material state is tuned by arginine methylation. Prion-like domain mutations such as D290V steepen the fibrillization trajectory and cause multisystem proteinopathy with ALS, so disease knockins capture the aggregation mechanism that deletion does not. Conditional alleles are preferable given the broad requirement for this protein in splicing and myelination, and pairing with Cnp-Cre or neuronal drivers localizes the phenotype. Hnrnpa1 shares many binding sites, so compound genetics and transcriptome-wide splicing readouts should be planned alongside the primary allele.',
  Hras:
    'Hras, ortholog of human HRAS, encodes a small GTPase that cycles between GDP and GTP states under Sos1-family exchange factors and p120 and Nf1 GAPs, engaging Raf kinases, PI3K, and RalGDS when loaded; its distinguishing feature is the hypervariable carboxy-terminal region, which carries both farnesylation and dual palmitoylation and therefore traffics through the Golgi to cholesterol-rich plasma membrane microdomains rather than the disordered regions favored by Kras. Somatic G12V and Q61L substitutions occur in bladder and head and neck carcinoma, while germline G12S and G13D cause Costello syndrome, giving three distinct allele classes: a Lox-Stop-Lox oncogenic knockin for tumor initiation, an endogenous RASopathy point mutation for developmental and cardiac phenotypes, and humanization for isoform-selective inhibitor testing. Hras nulls are viable because Kras carries the essential load, so single-gene deletion is rarely informative, and compound Hras and Nras alleles combined with tissue-restricted Cre give interpretable results.',
  Htt:
    'Huntington disease work centers on Htt, the mouse ortholog of human HTT, encoding huntingtin, a 350 kDa HEAT-repeat scaffold that organizes vesicular and axonal transport along microtubules through HAP1 and the dynein/dynactin machinery, sustains BDNF transcription by sequestering REST in the cytoplasm, and supports selective autophagy cargo recognition and ciliogenesis. Pathology follows CAG repeat expansion in exon 1 beyond roughly 36 units, generating an elongated polyglutamine tract that drives aggregation, aberrant exon 1 splicing into a highly toxic fragment, and somatic repeat instability in striatal medium spiny neurons through MSH3 and mismatch repair activity. Because complete Htt loss is embryonic lethal near gastrulation, conditional floxed alleles are mandatory for adult loss-of-function and lowering-safety studies, whereas full-length or humanized exon 1 CAG knockins preserve endogenous regulation for instability and biomarker endpoints far better than randomly integrated transgenes. Align allele class with endpoint, pairing neuron-restricted or striatum-restricted Cre drivers with region-specific silencing questions.',
  Idh1:
    'Cytosolic isocitrate dehydrogenase 1, encoded by Idh1 and orthologous to human IDH1, catalyzes the NADP-dependent oxidative decarboxylation of isocitrate to alpha-ketoglutarate in the cytoplasm and peroxisomes, supplying reducing equivalents for lipid synthesis and oxidative defense. Tumor alleles are heterozygous missense substitutions at arginine 132, most often R132H, which convert the enzyme into a neomorph that further reduces alpha-ketoglutarate to the oncometabolite D-2-hydroxyglutarate. Accumulated D-2HG competitively inhibits alpha-ketoglutarate dependent dioxygenases including TET2, the KDM4 and KDM6 demethylases, and prolyl hydroxylases, producing the CpG island hypermethylator phenotype and differentiation block characteristic of low grade glioma, chondrosarcoma, cholangiocarcinoma, and acute myeloid leukemia. Because the retained wild type allele is mechanistically required, the correct model is a conditional Lox-Stop-Lox R132H knockin at the endogenous locus rather than a null. Match Cre timing and lineage to the tumor type and use D-2HG suppression as the pharmacodynamic endpoint.',
  Idh2:
    'Idh2, the mouse ortholog of human IDH2, encodes the mitochondrial NADP-dependent isocitrate dehydrogenase that operates inside the matrix to generate alpha-ketoglutarate and NADPH for glutathione and thioredoxin regeneration, distinguishing it from the NAD-dependent heterotrimeric IDH3 that carries flux through the tricarboxylic acid cycle. Cancer alleles are heterozygous substitutions at arginine 140, most often R140Q in acute myeloid leukemia, and at arginine 172 in leukemia and glioma, each producing the same neomorphic reduction of alpha-ketoglutarate to D-2-hydroxyglutarate that inhibits TET2, the JmjC demethylases, and collagen prolyl hydroxylases, driving DNA and histone hypermethylation with a block in myeloid differentiation. Conditional Lox-Stop-Lox knockin of the specific residue, not deletion, reproduces this biology, and the choice between R140Q and R172K matters because they differ in enzymatic output and inhibitor sensitivity. Use an inducible hematopoietic Cre, and pair with Flt3 or Npm1 alleles when full transformation is the endpoint.',
  Ifna1:
    'Ifna1 sits within a tandem cluster of roughly fourteen intact interferon alpha genes on mouse chromosome 4 and corresponds to human IFNA1, encoding a single helical type I interferon that engages the shared IFNAR1 and IFNAR2 heterodimer, activates JAK1 and TYK2, and assembles the ISGF3 complex of STAT1, STAT2, and IRF9 on interferon stimulated response elements. Subtype identity tunes receptor affinity and therefore the balance of antiviral versus antiproliferative output rather than creating unique signaling, which has a hard consequence for allele design: deleting Ifna1 alone is almost always uninformative because the remaining subtypes are coregulated by IRF7 and compensate fully. Productive designs instead remove the entire cluster, target Ifnar1, or install a reporter at Ifna1 to time and localize subtype induction in vivo. When human interferon pharmacology is the endpoint, species restricted receptor engagement makes humanization of the ligand or receptor pair, not a subtype knockout, the appropriate allele.',
  Ifnb1:
    'Unlike the multigene alpha cluster, Ifnb1 is single copy, which makes this mouse ortholog of human IFNB1 the rate limiting first wave ligand of the type I interferon system. Transcription is driven by IRF3 dimers phosphorylated at Ser386 and Ser396 by TBK1 downstream of cGAS and STING, MAVS, or TRIF, cooperating with NF-kB and ATF2 with c-Jun on the compact enhanceosome, and the resulting autocrine IFNAR signal induces IRF7 to amplify the alpha subtypes. That architecture means a conditional Ifnb1 null truncates the initiating signal without touching amplification, a knockin reporter such as luciferase times and localizes sensing in vivo, and Ifnar1 deletion instead removes all downstream response. Because human IFNB1 does not productively engage murine IFNAR, humanization is required for biologic pharmacology. Cell type assignment matters more here than for most cytokines, since stromal, dendritic, and epithelial sources differ, so pair the flox with lineage restricted Cre drivers.',
  Ifng:
    'Interferon gamma, encoded by Ifng, is the mouse ortholog of human IFNG and the only type II interferon, a homodimeric cytokine that clusters IFNGR1 with IFNGR2, activates JAK1 and JAK2, and drives STAT1 homodimers onto gamma activated sequences to induce CIITA and MHC class II, immunoproteasome subunits, CXCL9 and CXCL10, and nitric oxide synthase in primed macrophages. Its sources are Th1 cells, NK cells, ILC1s, and cytotoxic lymphocytes, and human loss-of-function lesions in this pathway cause Mendelian susceptibility to mycobacterial disease, whereas excess drives hemophagocytic pathology. Allele choices diverge sharply: a conditional null asks whether a given lymphocyte lineage supplies the cytokine, a knockin reporter reads transcription without perturbing it, and humanization supports emapalumab-class neutralization studies. Pair the Ifng flox with Cd4-Cre, Cd8-Cre, or Ncr1-Cre rather than germline deletion when the goal is attributing the cellular source rather than ablating the axis entirely.',
  Igf1:
    'Igf1, the mouse ortholog of human IGF1, encodes insulin-like growth factor 1, a 70 amino acid peptide generated by signal and E-peptide processing that is produced largely by hepatocytes under growth hormone control and locally by mesenchymal tissues, circulating almost entirely bound to IGFBP3 and IGFALS in a ternary complex that sets bioavailability. Signaling proceeds through IGF1R and, at higher concentrations, insulin receptor hybrids, activating IRS1 to PI3K and AKT for anabolic growth and the SHC to ERK arm for proliferation. Mice lacking Igf1 show severe intrauterine and postnatal growth failure with substantial, strain-dependent perinatal lethality, so conditional alleles are usually preferable, with hepatocyte deletion isolating endocrine IGF-1 from local production and muscle or osteoblast deletion testing autocrine requirements. Humanized alleles enable evaluation of IGF-1 replacement biologics and neutralizing antibodies. Choose the allele to fit the endpoint, whether longitudinal body composition and bone morphometry, growth hormone axis feedback, or lifespan and tissue growth trajectories.',
  Igf1r:
    'The mouse Igf1r locus, ortholog of human IGF1R, specifies a disulfide-linked alpha2beta2 receptor tyrosine kinase that binds IGF-1 and IGF-2, autophosphorylates activation loop, juxtamembrane and C-terminal tyrosines, and recruits IRS1, IRS2 and SHC to drive PI3K to AKT and ERK output, and it also forms hybrid receptors with the insulin receptor that blur ligand specificity in tissues expressing both. Null mice are severely growth retarded and die neonatally of respiratory failure, so viable interrogation requires conditional alleles, with muscle, adipose, neuronal or endothelial Cre lines separating growth, metabolic and vascular contributions and inducible Cre avoiding developmental confounds. Kinase-dead and epitope-humanized knockins address different questions, the former testing scaffold versus catalytic function and the latter enabling preclinical evaluation of IGF1R-directed antibodies and inhibitors whose selectivity against the insulin receptor is the key liability. Because Insr forms hybrids and signals to the same effectors, plan compound Igf1r and Insr alleles before interpreting insulin sensitivity endpoints.',
  Igf2:
    'Igf2 is the mouse ortholog of human IGF2 and encodes a fetal growth factor whose expression is paternally monoallelic under control of the H19 imprinting control region through CTCF-dependent enhancer competition, with additional input from intragenic differentially methylated regions. The mature peptide signals through IGF1R and, distinctively, through the insulin receptor A isoform, while IGF2R clears it from circulation, making its dosage unusually sensitive to both imprinting status and receptor stoichiometry. Human loss of imprinting drives Beckwith-Wiedemann overgrowth and Wilms tumor, whereas hypomethylation reduces growth in Silver-Russell syndrome, a bidirectional disease logic that allele design should mirror: a paternal-allele conditional null tests the growth requirement, imprinting control region deletion or targeted methylation alleles model biallelic expression, and humanization supports antibody or ligand trap testing. Because Igf1 covers much of postnatal growth, phenotypes concentrate prenatally. Match allele to embryonic and placental growth measurement, allele-specific expression assays, and tumor incidence.',
  Igf2r:
    'The mouse Igf2r locus, ortholog of human IGF2R, encodes the cation-independent mannose-6-phosphate receptor, a large type I transmembrane protein whose extracytoplasmic repeats bind both mannose-6-phosphate-tagged lysosomal hydrolases, delivered from the trans-Golgi network to endosomes, and IGF-2, which it internalizes for degradation, making it a ligand clearance sink rather than a signaling receptor. In mouse the gene is maternally expressed and imprinted through the intronic Airn noncoding RNA, a regulatory feature absent in humans that must be considered before extrapolating dosage effects. Maternal-allele nulls are lethal with generalized overgrowth and cardiac defects that are rescued by concurrent Igf2 deletion, evidence that the phenotype reflects excess IGF-2 rather than lysosomal misrouting. Conditional alleles therefore matter for postnatal work, while separation-of-function knockins that ablate the IGF-2 binding repeat while preserving hydrolase sorting cleanly split the two activities. Choose endpoints accordingly, including circulating IGF-2, lysosomal enzyme secretion, and cardiac and placental morphometry.',
  Ihh:
    'Ihh, the mouse ortholog of human IHH, encodes Indian hedgehog, a lipid-modified morphogen that undergoes autocatalytic cleavage with cholesterol addition to its signaling fragment and palmitoylation by HHAT before release, then binds PTCH1 to relieve inhibition of SMO and shift ciliary GLI processing from repressor toward activator forms. Prehypertrophic chondrocytes secrete it to induce PTHrP in periarticular cells, and that negative feedback circuit sets the pace of chondrocyte proliferation and the position of the hypertrophic zone, while perichondrial signaling specifies osteoblast progenitors during endochondral ossification. Nulls show severe dwarfism with disorganized growth plates and die around birth, so conditional deletion with Col2a1-Cre or Prx1-Cre is required for postnatal skeletal work. Brachydactyly type A1 missense knockins model altered ligand range rather than absence, and humanization aids pathway inhibitor testing. Shh and Dhh overlap in gut and gonad, so compound alleles matter outside the skeleton.',
  Ikbkb:
    'Ikbkb, the mouse ortholog of human IKBKB, encodes IKK2, the dominant catalytic subunit of the IkB kinase complex, which also contains Chuk-encoded IKK1 and the Ikbkg scaffold; once Tak1 phosphorylates the activation loop at Ser177 and Ser181, IKK2 phosphorylates IkBalpha on Ser32 and Ser36, triggering betaTrCP-dependent ubiquitination and proteasomal destruction and freeing RelA and p50 dimers for nuclear entry. Homozygous deletion causes mid-gestation lethality from TNF-driven hepatocyte apoptosis, which can be rescued on a Tnfr1-deficient background but otherwise mandates conditional alleles, so lineage-restricted deletion with LysM-Cre, Cd19-Cre, or Villin-Cre is the practical route for inflammation and tumor studies. A constitutively active Ser177 and Ser181 to glutamate knockin asks whether canonical NF-kB output alone drives a phenotype, a kinase-dead allele distinguishes catalysis from complex assembly, and humanization supports selective inhibitor pharmacology. Chuk partially compensates, so pair compound alleles with a driver validated in the target compartment.',
  Ikbke:
    'Ikbke encodes IKK epsilon, the mouse ortholog of human IKBKE and the noncanonical IKK family kinase most closely related to TBK1, sharing a kinase domain, ubiquitin-like domain, and scaffold dimerization region. Together with TBK1 it phosphorylates IRF3 on the C-terminal serine cluster to license interferon beta transcription, and it also phosphorylates STAT1 at Ser708 to reshape ISGF3 output and modifies NF-kB regulators including CYLD, which underlies its behavior as an amplified breast cancer oncogene able to substitute for AKT driven survival signaling. Design follows the question directly: a conditional null removes protein and scaffolding together, whereas a kinase-dead knockin distinguishes catalytic activity from complex assembly, the decisive comparison for evaluating small molecule inhibitors. Substantial redundancy with Tbk1 means single deletion blunts rather than abolishes interferon induction, and because Tbk1 nulls die in utero from TNF driven hepatocyte apoptosis, compound experiments require conditional Tbk1 alleles planned in advance.',
  Ikbkg:
    'Encoding NEMO, the regulatory scaffold of the IkB kinase complex, Ikbkg is the mouse ortholog of human IKBKG and is X-linked; through its coiled-coil and leucine zipper UBAN region it reads Met1-linked linear polyubiquitin generated by LUBAC as well as Lys63 chains, and this ubiquitin recognition, rather than any catalytic function, is what juxtaposes and licenses IKK1 and IKK2 activation downstream of TNFR1, IL1R, Toll-like receptors, and antigen receptors. Human hypomorphic alleles cause anhidrotic ectodermal dysplasia with immunodeficiency, whereas amorphic alleles are male lethal and produce incontinentia pigmenti in heterozygous females, a pattern faithfully reproduced in mouse, where hemizygous nulls die in mid-gestation and heterozygous females show mosaic dermatopathy. Conditional deletion is therefore the workhorse design, UBAN point mutants such as the Asp311 substitution isolate ubiquitin sensing from scaffolding, and patient-matched hypomorphs model graded immunodeficiency. There is no paralog to buffer loss, so phenotypes report directly on allele strength and driver efficiency.',
  Il10:
    'Il10 corresponds to human IL10 and encodes a class 2 alpha-helical cytokine that signals as a homodimer through IL10RA paired with the shared IL10RB chain, activating JAK1 and STAT3 to induce SOCS3, suppress MHC class II and costimulation, and shut down interleukin 12 and TNF production in activated macrophages. Because that program enforces mucosal tolerance, germline Il10 nulls develop spontaneous microbiota dependent colitis whose severity tracks with housing and Helicobacter status, mirroring human infantile inflammatory bowel disease caused by IL10, IL10RA, and IL10RB mutations. That biology forces careful design: a conditional null with Foxp3-Cre, Cd19-Cre, or Lyz2-Cre attributes suppression to a defined source, whereas germline loss only demonstrates that the axis exists. Humanization supports testing of engineered interleukin 10 agonists and receptor blocking antibodies whose species selectivity is absolute. Interpretation demands controlled microbiota and littermate comparisons, since cage effects can exceed genotype effects when colitis onset is the readout.',
  Il12a:
    'Il12a, the mouse ortholog of human IL12A, encodes the p35 subunit, and its central design trap is subunit sharing: p35 heterodimerizes with p40 from Il12b to form bioactive interleukin 12, and with EBI3 to form interleukin 35, an inhibitory cytokine of regulatory T and B cells. Interleukin 12 acts through IL-12Rbeta1 and IL-12Rbeta2 to trigger JAK2 and STAT4, imprinting Th1 commitment and interferon gamma production, while interleukin 35 signals through gp130 with IL-12Rbeta2 to activate STAT1 and STAT4 in a suppressive configuration. A germline Il12a null therefore removes a proinflammatory and an anti-inflammatory cytokine simultaneously, so phenotypes read as net effects rather than clean interleukin 12 loss. Dissection requires triangulation across Il12b, Ebi3, and Il12rb2 alleles, plus conditional Il12a deletion with dendritic cell or B cell restricted Cre drivers, and humanization when the endpoint is ustekinumab-class or p35 directed antibody pharmacology.',
  Il12b:
    'The p40 subunit encoded by Il12b, mouse ortholog of human IL12B, is the shared chain of two distinct heterodimeric cytokines, interleukin 12 when paired with p35 and interleukin 23 when paired with p19. Interleukin 12 drives STAT4 dependent Th1 differentiation and interferon gamma, whereas interleukin 23 sustains RORgt dependent Th17 and ILC3 programs with interleukin 17 and interleukin 22 output, so a single Il12b null collapses both axes at once and cannot distinguish them. This is precisely the ambiguity that made p40 blockade with ustekinumab clinically effective yet mechanistically opaque, and why selective p19 blockade later outperformed it in psoriasis. Rational design pairs Il12b alleles with Il12a and Il23a single nulls to partition the two cytokines, uses conditional deletion in dendritic cells or macrophages to identify the producing compartment, and adopts humanization when p40 antibody pharmacology rather than pathway ablation is the endpoint. Homodimeric p40 can also antagonize receptor engagement, complicating partial loss interpretation.',
  Il13:
    'Il13 corresponds to human IL13 and encodes a type 2 cytokine that signals through the type II receptor composed of IL-4Ralpha and IL-13Ralpha1 to activate STAT6, with IL-13Ralpha2 acting as a high-affinity decoy, driving goblet cell metaplasia, smooth muscle hyperresponsiveness, periostin production, and fibroblast activation in airway and skin disease. It sits within the type 2 locus immediately adjacent to Il4 and near Il5 under shared conserved noncoding elements including Rad50 region control sequences, so targeting cassettes and floxed designs must be checked for cis effects on neighboring genes, a frequent source of misattributed phenotypes. Because interleukin 4 and interleukin 13 converge on IL-4Ralpha and STAT6, single nulls routinely show partial phenotypes and compound Il4 with Il13 or Il4ra alleles are needed for full type 2 collapse. Humanization is the correct allele for dupilumab, tralokinumab, and lebrikizumab class pharmacology, while reporter knockins localize the producing Th2, ILC2, or mast cell source.',
  Il17a:
    'Il17a is the mouse ortholog of human IL17A and encodes a cystine-knot cytokine acting as a homodimer, and also as a heterodimer with interleukin 17F, on the IL-17RA and IL-17RC receptor complex, recruiting the adaptor Act1 encoded by Traf3ip2 plus TRAF6 to activate NF-kB, MAPK signaling, and transcript stabilization of CXCL1, CXCL2, CSF3, and antimicrobial peptides in epithelium and stroma. Producers are RORgt dependent Th17 cells, gamma delta T17 cells, ILC3s, and MAIT cells, and human IL17RA or IL17F lesions cause chronic mucocutaneous candidiasis while excess drives psoriasis, the indication where secukinumab and ixekizumab succeeded. Because Il17a and Il17f are adjacent and coregulated, single nulls give partial phenotypes and heterodimer contributions are missed, so compound alleles or receptor deletion are frequently required. Fate mapping alleles such as Il17a-Cre distinguish current from historical expression, and conditional deletion in gamma delta versus CD4 compartments is what actually assigns the pathogenic source.',
  Il17f:
    'Sharing a cystine-knot fold and receptor with interleukin 17A, the product of Il17f, mouse ortholog of human IL17F, signals through IL-17RA and IL-17RC with roughly an order of magnitude lower potency and circulates as a homodimer or as an interleukin 17A and 17F heterodimer, converging on Act1, TRAF6, and NF-kB driven neutrophil chemokine and antimicrobial peptide induction at barrier surfaces. The human S65L variant behaves as a dominant negative and causes chronic mucocutaneous candidiasis, establishing a genuine disease knockin design distinct from a simple null, while murine gut phenotypes indicate nonredundant roles in microbiota containment. Because the adjacent Il17a locus is coregulated and functionally overlapping, an Il17f single null typically produces mild readouts, and compound Il17a with Il17f deletion or Il17ra deletion is required for confident loss-of-function conclusions. Match allele to endpoint: dominant negative knockins for host defense, humanization for bimekizumab-class dual blockade, and lineage restricted Cre for source attribution.',
  Il18:
    'Il18 encodes interleukin 18, the mouse ortholog of human IL18 and an interleukin 1 family member synthesized as an inactive precursor constitutively stockpiled in epithelium, keratinocytes, and macrophages, then cleaved by caspase-1 downstream of NLRP3 or NLRC4 inflammasomes, or by caspase-8, neutrophil proteases, and granzyme B, before release through gasdermin D pores. Mature cytokine engages IL-18R1 with the accessory chain IL18RAP to recruit MyD88 and IRAK4, driving NF-kB and, together with interleukin 12, potent interferon gamma output from Th1, NK, and ILC1 cells, while the secreted decoy interleukin 18 binding protein sets the free ligand concentration and rises in macrophage activation syndrome. Allele design should follow that regulation: a conditional null tests requirement, an uncleavable precursor knockin isolates processing, and humanization supports both neutralizing antibody and decoy-resistant agonist programs. Because Il18 and Il1b share upstream inflammasome machinery, attribute phenotypes with ligand-specific alleles rather than caspase-1 deletion.',
  Il1a:
    'Il1a, mouse ortholog of human IL1A, encodes interleukin 1 alpha, a cytokine whose full-length precursor is already bioactive, carries a nuclear localization sequence, tethers to the plasma membrane, and is released as an alarmin when cells die by necrosis or necroptosis, with calpain dependent processing enhancing potency. This makes its regulation fundamentally different from interleukin 1 beta, which requires inflammasome caspase-1 cleavage, even though both signal through IL-1R1 with IL1RAP to recruit MyD88, IRAK4, and IRAK1 and activate NF-kB and p38. Interleukin 1 alpha therefore dominates sterile injury, ultraviolet damage, and tumor associated inflammation, and its nuclear pool contributes transcriptionally in ways a secretion-focused readout misses. Distinguish these functions with a conditional null, a nuclear localization deficient or membrane-anchored knockin, and humanization for bermekimab-class antibodies. Because Il1b and Il1rn act on the same receptor, compound alleles or Il1r1 deletion are needed to bound total interleukin 1 activity in any model.',
  Il1b:
    'Interleukin 1 beta, encoded by the mouse ortholog of human IL1B, is transcribed as an inactive 31 kDa precursor whose maturation requires cleavage at Asp116 by caspase-1 assembled on NLRP3, NLRC4, AIM2, or pyrin inflammasomes, with caspase-8 and neutrophil elastase providing inflammasome independent routes, and export depends on gasdermin D pores rather than the classical secretory pathway. Mature ligand engages IL-1R1 with IL1RAP, recruits MyD88 and IRAK4, and drives NF-kB dependent fever, neutrophil recruitment, interleukin 6 induction, and Th17 support, the axis blocked clinically by canakinumab and anakinra and hyperactivated in cryopyrin associated periodic syndromes. Allele forks are unusually clean: conditional null for requirement, cleavage-resistant knockin to separate transcription from processing, reporter alleles to time inflammasome activity in vivo, and humanization for antibody pharmacology. Because interleukin 1 alpha signals through the same receptor, attribute phenotypes with Il1a comparison rather than assuming Il1r1 readouts reflect interleukin 1 beta alone.',
  Il1rn:
    'Il1rn corresponds to human IL1RN and encodes the interleukin 1 receptor antagonist, a structural mimic of interleukin 1 that occupies IL-1R1 without recruiting the IL1RAP accessory chain, so no Myddosome forms and signaling is competitively silenced, the mechanism exploited therapeutically by anakinra. The locus produces a secreted isoform plus intracellular variants generated from alternative first exons, so deletion strategies must decide explicitly whether to remove all isoforms or only the secreted pool. Human biallelic loss causes deficiency of the interleukin 1 receptor antagonist, presenting with sterile multifocal osteomyelitis, periostitis, and pustulosis, and mouse nulls develop strain dependent arthritis and aortitis that is prominent on BALB/c and mild on C57BL/6, making background choice part of the experimental design rather than a detail. Use conditional nulls to test local buffering in skin, joint, or gut, isoform-specific knockins to separate secreted from intracellular function, and humanization when antagonist pharmacokinetics is the endpoint.',
  Il2:
    'Il2 is the mouse ortholog of human IL2 and encodes a four alpha helix bundle cytokine that assembles a trimeric receptor of IL-2Ralpha, IL-2Rbeta, and the common gamma chain, activating JAK1 and JAK3 with STAT5 to control regulatory T cell fitness, effector CD8 expansion, and activation induced cell death. Because high-affinity capture depends on constitutive CD25 on regulatory T cells, interleukin 2 availability is a tolerance checkpoint, and germline Il2 or Il2ra nulls develop lethal lymphoproliferation with autoimmune hemolytic anemia and colitis rather than immunodeficiency, a phenotype that constrains any breeding scheme. Allele class should follow the endpoint: conditional deletion in CD4 T cells asks who supplies the cytokine, knockins encoding not-alpha or CD25-biased muteins model low dose interleukin 2 therapy, and humanization supports aldesleukin and engineered agonist pharmacology. Plan drivers early, since Cd4-Cre, Foxp3-Cre, and inducible CreERT2 lines give very different windows on tolerance versus antitumor expansion.',
  Il22:
    'Encoding an interleukin 10 family cytokine, Il22 corresponds to human IL22 and signals through IL-22RA1 paired with the shared IL10RB chain, a receptor configuration restricted to epithelial and hepatocyte compartments, which makes interleukin 22 a lymphocyte to epithelium messenger rather than an immune amplifier. STAT3 activation induces antimicrobial Reg3b and Reg3g, mucins, tight junction components, and hepatocyte acute phase and regenerative programs, while the soluble decoy encoded by Il22ra2 sets bioavailability. Producers include Th17 and Th22 cells, gamma delta T cells, and ILC3s, and the same pathway that protects intestinal stem cells after injury drives keratinocyte hyperproliferation in psoriasis, so context determines whether interleukin 22 is protective or pathogenic. Conditional nulls with Rorc-Cre or Cd4-Cre attribute the source, Il22ra2 alleles test decoy control, and humanization enables agonist as well as neutralizing antibody programs. Microbiota state strongly modifies every readout here, so littermate controlled cohorts and defined flora are essential.',
  Il23a:
    'Il23a, the mouse ortholog of human IL23A, encodes the p19 subunit that heterodimerizes with p40 to form interleukin 23, which signals through IL-23R and IL-12Rbeta1 to activate JAK2 and STAT3, stabilizing the RORgt dependent transcriptional program of Th17 cells, gamma delta T17 cells, and ILC3s and sustaining interleukin 17 and interleukin 22 output. Human genetics validates the axis precisely, since the IL23R R381Q variant is protective in psoriasis, ankylosing spondylitis, and Crohn disease, and selective p19 antibodies including risankizumab and guselkumab outperform p40 blockade in skin disease. Because p19 is unique to interleukin 23 while p40 is shared with interleukin 12, an Il23a null delivers the clean loss of function that an Il12b null cannot, and pairing the two alleles is the standard way to partition Th1 from Th17 contributions. Add conditional deletion in dendritic cells or macrophages to identify the producing compartment, and humanization for p19 antibody pharmacology.',
  Il27:
    'Il27 encodes the p28 subunit, mouse ortholog of human IL27, which pairs with EBI3 to form interleukin 27 and signals through IL-27Ralpha, also called WSX-1, together with gp130 to activate both STAT1 and STAT3. That dual output explains its split personality, with early amplification of Th1 commitment and T-bet alongside potent suppression of Th17 differentiation, induction of interleukin 10 producing Tr1 cells, and upregulation of inhibitory receptors including PD-L1 and TIM-3 on T cells. Two design subtleties matter. EBI3 is shared with interleukin 35, so an Ebi3 null removes two cytokines while an Il27 null removes only p28 containing species, and unpaired p28 can antagonize gp130 signaling, meaning overexpression and deletion are not simple mirror images. Conditional deletion in dendritic cells or macrophages assigns the source, Il27ra alleles test receptor requirement in T cells, and humanization supports antibody pharmacology where the immunosuppressive arm is the therapeutic target.',
  Il4:
    'Il4 is the mouse ortholog of human IL4 and encodes the initiating type 2 cytokine, signaling through the type I receptor of IL-4Ralpha with the common gamma chain on lymphocytes and the type II receptor of IL-4Ralpha with IL-13Ralpha1 on myeloid and stromal cells, converging on STAT6 to induce GATA3, immunoglobulin E class switching, and alternative macrophage activation. Its locus lies adjacent to Il13 and Il5 under shared conserved noncoding regulatory elements, so cassette placement can perturb neighbors and generate phenotypes mistakenly attributed to interleukin 4 alone. Because interleukin 4 and interleukin 13 share IL-4Ralpha and STAT6, single nulls give partial results and compound Il4 with Il13 or Il4ra deletion is required for full type 2 collapse. Bicistronic fluorophore reporter knockins mark competent producers without perturbation, while humanization is the appropriate allele for dupilumab-class receptor blockade, and conditional deletion with Cd4-Cre or ILC2 restricted drivers assigns the cellular source.',
  Il5:
    'Encoding a homodimeric type 2 cytokine, Il5 corresponds to human IL5 and signals through IL-5Ralpha paired with the beta common chain encoded by Csf2rb, shared with interleukin 3 and GM-CSF, activating JAK2 and STAT5 to control eosinophil lineage commitment, marrow release, tissue survival, and B1 cell antibody production. It is the dominant nonredundant eosinophil axis, which is why mepolizumab and reslizumab neutralize the ligand while benralizumab depletes eosinophils by targeting the receptor alpha chain with an afucosylated Fc. The locus sits in the type 2 cluster near Il4 and Il13 under shared regulatory elements, so verify that any targeting cassette does not alter neighboring transcription. Design accordingly: conditional deletion with Cd4-Cre or ILC2 restricted drivers attributes the source, receptor alleles separate development from survival, and humanization supports ligand and receptor antibody pharmacology. Avoid Csf2rb deletion as a proxy, since it also removes interleukin 3 and GM-CSF signaling.',
  Il6:
    'Il6, the mouse ortholog of human IL6, encodes a four-helix bundle cytokine that first binds the nonsignaling Il6ra alpha chain and then recruits two Il6st gp130 molecules to assemble a hexameric complex that activates Jak1 and phosphorylates Stat3, driving Socs3 feedback, hepatic acute phase gene induction, Th17 differentiation with Tgfb, and plasma cell survival. A defining feature is trans-signaling, in which ADAM17-shed soluble Il6ra confers responsiveness on gp130-positive cells lacking the alpha chain, a distinction that shapes allele design: a straight null collapses both arms, an Il6ra conditional or a gp130 chimeric decoy isolates trans-signaling, and humanized IL6 or IL6R knockins are the only credible platform for testing tocilizumab, sarilumab, or siltuximab in vivo. Nulls are viable with blunted acute phase and impaired infection responses, and because Il11, Lif, and Osm also converge on gp130, cytokine-level redundancy should be anticipated when interpreting modest phenotypes.',
  Inha:
    'Inha is the mouse ortholog of human INHA and encodes the inhibin alpha subunit, which dimerizes with the beta A or beta B subunit to form inhibin A or inhibin B, ligands that act as competitive antagonists by capturing ActRIIA and ActRIIB in a nonsignaling complex stabilized by the coreceptor betaglycan, damping activin and BMP-driven SMAD2 and SMAD3 output and providing gonadal feedback suppression of pituitary FSH. Deletion yields a striking tumor phenotype, since nulls develop granulosa and Sertoli cell tumors with essentially complete penetrance, then succumb to a cachexia-like wasting syndrome driven by unopposed circulating activin. Conditional alleles driven by Amhr2-Cre or granulosa-restricted lines are therefore essential to separate the gonadal tumor-suppressor function from systemic activin toxicity, and humanized knockins support inhibin and activin biologic development. No paralogous alpha subunit exists, so single-locus loss is fully interpretable, an unusual advantage within this superfamily.',
  Inhba:
    'The inhibin beta A subunit is encoded by Inhba, the mouse ortholog of human INHBA, which supplies the polypeptide that homodimerizes into activin A, heterodimerizes into activin AB, and pairs with the alpha subunit to form inhibin A. Activin A signals through ActRIIA or ActRIIB with ALK4 to phosphorylate SMAD2 and SMAD3, is neutralized extracellularly by follistatin, and drives mesoderm induction, pituitary FSH synthesis, wound repair, heterotopic ossification, and tumor-associated cachexia. Nulls die shortly after birth with cleft palate, absent whiskers, and incisor defects, so conditional deletion is necessary for adult muscle, immune, and cancer endpoints. Subunit-swap knockins, in which Inhbb coding sequence replaces Inhba, remain the cleanest test of whether phenotypes reflect ligand identity or expression domain, and humanization enables selectivity testing of anti-activin A antibodies. Because Inhbb partially substitutes through shared receptors, plan compound conditional genetics before attributing a phenotype to activin A alone.',
  Inhbb:
    'Activin B, activin AB, and inhibin B all derive from the beta B subunit encoded by Inhbb, the mouse ortholog of human INHBB, which engages ActRIIA or ActRIIB with ALK4 and, distinctively, with ALK7 to activate SMAD2 and SMAD3, a receptor preference that separates activin B pharmacology from activin A. Nulls survive but display defective eyelid closure at birth alongside reproductive, placental, and pancreatic islet abnormalities, while inhibin B serves clinically as a Sertoli cell and ovarian reserve marker. Conditional deletion is the right tool for adult liver regeneration, beta-cell, and hepatic iron questions where the perinatal ocular phenotype would otherwise confound interpretation. Subunit-swap and patient variant knockins test ligand-specific receptor usage, and humanization supports antibody and ligand trap development. Inhba shares receptors and expression domains extensively, so compound Inhba and Inhbb conditional alleles, with a driver validated in the relevant lineage, prevent misreading redundancy as dispensability.',
  Inhbc:
    'Largely confined to hepatocytes, the mouse ortholog of human INHBC, Inhbc, encodes the activin beta C subunit whose homodimer, activin C, signals weakly, and whose principal documented activity is heterodimerization with beta A to divert that subunit away from bioactive activin A, effectively lowering SMAD2 and SMAD3 tone in liver and prostate. Nulls are viable without overt pathology, so the informative designs are combinatorial and gain of function rather than simple deletion: hepatocyte-directed overexpression knockins test the sequestration model directly, and conditional nulls become interpretable mainly under regenerative or injury challenge such as partial hepatectomy or hepatotoxin exposure. Humanized alleles support biochemical dissection of subunit pairing preference. Inhbe lies adjacent and is coexpressed in hepatocytes, so the locus demands care: design floxed alleles that leave neighboring regulatory elements intact, and generate compound Inhbc and Inhbe alleles when metabolic or liver injury readouts are primary.',
  Inhbe:
    'Inhbe is the mouse ortholog of human INHBE and encodes activin E, a hepatokine transcriptionally induced by the integrated stress response through ATF4 and by nutrient excess, which acts on adipocytes through ALK7 with ActRIIA or ActRIIB to phosphorylate SMAD2 and SMAD3 and restrain lipolysis. Human predicted loss-of-function alleles are protective, lowering waist-to-hip ratio and improving hepatic and glycemic measures, which positions the gene as a target where the therapeutic hypothesis is inhibition rather than replacement. That logic favors hepatocyte-restricted conditional nulls to confirm the liver as the obligate source, precise knockins of the human protective variants to test whether they abolish secretion or receptor engagement, and humanized alleles for antibody, siRNA, or antisense pharmacology. Inhbc is an adjacent, coexpressed paralog capable of comparable subunit pairing, so compound alleles and careful floxing that preserves the shared regulatory landscape are needed before adipose lipolysis endpoints are read as definitive.',
  Ins:
    'Insulin biology in mouse is complicated by gene duplication: the locus corresponding to human INS is Ins2, while Ins1 is a rodent-specific retrogene, and both encode preproinsulin that is processed in beta cell secretory granules by Pcsk1 and Pcsk2 with carboxypeptidase E, excising C-peptide to yield mature disulfide-bonded A and B chains stored as zinc hexamers. Dominant misfolding mutations, exemplified by the Akita Ins2 Cys96Tyr allele, block folding, trap proinsulin in the endoplasmic reticulum, and cause beta cell stress and diabetes, the mechanism underlying human mutant INS-gene-induced diabetes of youth and permanent neonatal diabetes. Allele choices therefore diverge sharply: point-mutation knockins model proteotoxic stress, full humanization on an Ins1-null background creates a platform for human insulin quantification and analog pharmacology, and reporter fusions track granule dynamics. The Ins1 and Ins2 duplication is genuine redundancy, so single-gene deletion is insufficient and dosage must be engineered deliberately for metabolic endpoints.',
  Insr:
    'Insr, the mouse ortholog of human INSR, encodes a disulfide-linked receptor tyrosine kinase assembled as an alpha-beta heterotetramer, with L1, L2, and cysteine-rich ligand-binding modules and a kinase domain whose activation loop tyrosines undergo trans-autophosphorylation on insulin binding, creating NPXY docking sites for Irs1 and Irs2 that route signals into PI3K, Akt, and Foxo1 as well as Shc-dependent Erk activation; exon 11 splicing generates IR-A and IR-B isoforms with different affinities and tissue distributions. Homozygous nulls are born grossly normal but die within days from ketoacidosis, mirroring human Donohue syndrome, so tissue-restricted deletion with Alb-Cre, Ckmm-Cre, Adipoq-Cre, or Ins1-Cre is the standard approach for dissecting organ-specific insulin action. Kinase-dead and NPXY-mutant knockins separate catalysis from scaffolding, and humanization supports analog and bispecific antibody testing. Igf1r is a close paralog that forms hybrid receptors and buffers signaling, so compound alleles are often necessary.',
  Irak1:
    'Irak1, the mouse ortholog of human IRAK1 and an X-linked gene adjacent to Mecp2, encodes an interleukin 1 receptor associated kinase with an N-terminal death domain, a ProST region, and a kinase domain that is recruited into the MyD88 and IRAK4 Myddosome after TLR or IL-1R engagement. IRAK4 phosphorylates IRAK1, which then autophosphorylates, undergoes K63 linked ubiquitination, and activates TRAF6, TAK1, and the IKK complex, while in plasmacytoid dendritic cells IRAK1 additionally phosphorylates IRF7 to drive endosomal TLR7 and TLR9 dependent type I interferon. Because IRAK2 provides substantial redundancy for TRAF6 activation, Irak1 nulls show blunted rather than abolished NF-kB responses while the interferon defect is more penetrant, so interpret partial phenotypes accordingly and consider compound Irak2 alleles. Kinase-dead knockins separate catalytic from scaffolding roles, the relevant comparison for degrader versus inhibitor programs, and conditional deletion avoids confounding from this X-linked neighborhood.',
  Irak4:
    'Positioned immediately downstream of MyD88, Irak4 is the mouse ortholog of human IRAK4 and encodes the apical kinase of the Myddosome, using its death domain to assemble a helical oligomer with MyD88 and IRAK1 or IRAK2 and its kinase domain to trigger TRAF6, TAK1, IKK, and MAPK output from all MyD88 coupled TLRs plus IL-1R, IL-18R, and IL-33R. Human IRAK4 deficiency produces narrow but severe susceptibility to pyogenic bacteria that attenuates with age, and MYD88 mutant lymphomas depend on the same complex, providing both loss-of-function and oncology rationales. The decisive allele is the kinase-dead knockin, because it separates catalytic activity from scaffolding and predicts what an active site inhibitor will do, whereas a conditional null predicts the behavior of a heterobifunctional degrader. Add lineage restricted Cre drivers to distinguish myeloid, B cell, and epithelial requirements, and choose humanization when compound selectivity against the human kinase domain is the endpoint.',
  Irf3:
    'Irf3 corresponds to human IRF3 and encodes a constitutively expressed interferon regulatory factor with an N-terminal winged helix DNA binding domain and a C-terminal IRF association domain held autoinhibited until TBK1 or IKK epsilon phosphorylate the serine-rich tail at Ser386 and Ser396 downstream of STING, MAVS, or TRIF. Phosphorylation drives dimerization, nuclear accumulation, CBP and p300 recruitment, and transcription of Ifnb1 with early interferon stimulated genes, while a transcription independent arm, the RLR induced apoptotic pathway, uses BH3 like engagement of BAX to kill infected cells. Allele forks map cleanly onto these functions: conditional nulls test requirement, phosphomimetic constitutively active knockins model chronic interferon tone, and mutations separating transactivation from BAX binding isolate the apoptotic arm. Irf7 substantially overlaps in interferon induction, so compound Irf3 with Irf7 deletion is usually required before output is truly abolished, and STING gain-of-function crosses need conditional alleles to survive breeding.',
  Irf5:
    'Irf5 is the mouse ortholog of human IRF5 and encodes an interferon regulatory factor acting mainly downstream of MyD88 coupled TLR7 and TLR9 signaling, where TRAF6 dependent ubiquitination and IKKbeta mediated phosphorylation drive nuclear translocation and transcription of interleukin 6, interleukin 12, interleukin 23, and TNF, making it a determinant of inflammatory macrophage polarization and plasma cell differentiation rather than of type I interferon amplification. Human IRF5 haplotypes are among the strongest non-HLA risk factors for systemic lupus erythematosus, giving clear rationale for both loss-of-function and expression level alleles. One technical caveat dominates this locus: several widely used Irf5 knockout lines carried a closely linked spontaneous Dock2 mutation that independently distorts lymphocyte development and migration, so new projects should use a freshly targeted conditional allele and genotype Dock2 explicitly. Pair the flox with Lyz2-Cre or Cd19-Cre to separate myeloid from B lineage contributions, and humanize when antibody or degrader pharmacology is the endpoint.',
  Irf7:
    'Serving as the master amplifier of the type I interferon system, Irf7 is the mouse ortholog of human IRF7 and encodes an interferon inducible regulatory factor that closes the positive feedback loop converting the single Ifnb1 first wave into broad interferon alpha subtype expression. In plasmacytoid dendritic cells it is activated MyD88 dependently through IRAK4, IRAK1, and IKKalpha downstream of endosomal TLR7 and TLR9, and in other cells by TBK1, with phosphorylation of the C-terminal serine cluster licensing dimerization and ISRE occupancy. Human IRF7 deficiency causes life threatening influenza with preserved responses to many other pathogens, while elevated interferon tone is central to lupus biology. Because Irf3 initiates and Irf7 amplifies, a single null blunts kinetics rather than abolishing induction, so compound alleles are frequently required. Conditional deletion with plasmacytoid dendritic cell restricted or Itgax-Cre drivers assigns the amplification compartment, and reporter knockins time the feedback loop without perturbing it.',
  Jag1:
    'Jag1 is the mouse ortholog of human JAG1 and encodes a single-pass Notch ligand built from a DSL domain, sixteen EGF-like repeats, and a cysteine-rich region, which engages NOTCH1 through NOTCH4 in trans and requires mechanical force to expose the receptor S2 site for ADAM10, licensing gamma-secretase cleavage and NICD release, with Fringe glycosylation of the receptor tuning Jagged versus Delta-like preference and cis expression acting inhibitory. Heterozygous human loss of function causes Alagille syndrome with bile duct paucity, cardiac outflow defects, butterfly vertebrae, and posterior embryotoxon, while nulls die near E10.5 from failed vascular remodeling. Conditional deletion in portal mesenchyme, endothelium, or arterial mural cells is therefore mandatory, Alagille missense knockins distinguish trafficking-defective from binding-defective ligand, and humanization enables antibody and decoy testing. Jag2, Dll1, and Dll4 supply overlapping ligand activity, and sensitized Notch2 hypomorph backgrounds are often required to reveal biliary phenotypes.',
  Jag2:
    'Jag2, the mouse ortholog of human JAG2, encodes a second Jagged-class Notch ligand and presents a DSL domain with EGF repeats to NOTCH1 through NOTCH3, triggering force-dependent ADAM10 and gamma-secretase processing and NICD-driven transcription with RBPJ and MAML. Its non-redundant requirements concentrate in thymic epithelium and gamma delta T cell development, the limb apical ectodermal ridge, tooth, and secondary palate, and nulls die perinatally with cleft palate, limb syndactyly, and thymic hypoplasia, while biallelic human variants cause a recessive muscular dystrophy tied to satellite cell Notch signaling. Given perinatal lethality, conditional deletion is the practical design for postnatal thymus, muscle regeneration, or skin work, patient missense knockins test whether variants impair surface presentation or receptor binding, and humanization supports antibody pharmacology. Jag1 overlaps substantially in epithelial and vascular contexts, so compound conditional alleles paired with a lineage-validated Cre driver prevent masked phenotypes.',
  Jak1:
    'Jak1, the mouse ortholog of human JAK1, encodes a nonreceptor tyrosine kinase organized into a FERM domain, an SH2-like module, a catalytically inactive pseudokinase that autoinhibits, and the active kinase domain; it docks on box1 and box2 motifs of type I and type II interferon receptors, gp130-family receptors, and gamma-common cytokine receptors, then phosphorylates receptor tails and Stat1, Stat3, and Stat5 to license dimerization and nuclear import. Homozygous nulls die perinatally with failure to nurse and neurological deficits, so conditional deletion is required for immune and tumor studies, while pseudokinase-domain activating knockins found in acute lymphoblastic leukemia test ligand-independent signaling and kinase-dead alleles separate catalysis from receptor scaffolding. Humanization is the design that supports selectivity profiling of JAK1-biased inhibitors, since paralog-specific pharmacology is the central question. Jak2, Jak3, and Tyk2 pair with distinct receptor chains and do not broadly substitute, though shared receptor complexes can blunt single-gene phenotypes.',
  Jak2:
    'Encoding the kinase that pairs with single-chain cytokine receptors, Jak2 is the mouse ortholog of human JAK2 and transduces signals from Epor, Mpl, Ghr, Prlr, and Ifngr, phosphorylating Stat5 in particular; its pseudokinase JH2 domain normally restrains the catalytic domain, and the Val617Phe substitution in that interface produces constitutive, ligand-independent activation that drives polycythemia vera, essential thrombocythemia, and primary myelofibrosis, with exon 12 insertions and deletions giving erythroid-restricted disease. Homozygous nulls die at mid-gestation from absent definitive erythropoiesis, so conditional deletion is mandatory, and the informative activating design is a conditional Val617Phe knockin at the endogenous locus expressed through Vav-Cre or interferon-inducible Mx1-Cre, which reproduces allele-dosage-dependent myeloproliferative phenotypes far more faithfully than transgenic overexpression. Humanization supports type I and type II JAK2 inhibitor pharmacology. Receptor pairing is largely nonredundant, so Jak1 and Tyk2 cannot rescue erythropoiesis; match allele class, dosage, and driver to the hematopoietic endpoint.',
  Jak3:
    'Jak3, the mouse ortholog of human JAK3, encodes a Janus kinase whose expression is largely restricted to hematopoietic cells and which associates exclusively with the Il2rg common gamma chain, making it the obligate partner for interleukin 2, 4, 7, 9, 15, and 21 signaling through Stat5 and Stat6; loss-of-function mutations in humans cause autosomal recessive T-negative, B-positive, NK-negative severe combined immunodeficiency. Homozygous null mice are viable but profoundly lymphopenic with blocked thymopoiesis and absent NK cells, which makes the null a useful chassis for immunodeficient host strains supporting human graft engraftment, often alongside Il2rg or Prkdc alleles. Conditional deletion addresses lineage-autonomous requirements after development, kinase-dead knockins separate catalysis from receptor assembly, and humanization is essential when the question is covalent inhibitor engagement of the JAK3-specific Cys909 residue. No paralog substitutes for gamma-chain coupling, so phenotypes report cleanly; choose allele class according to whether the endpoint is host permissiveness or drug selectivity.',
  Kcnh2:
    'Kcnh2, the mouse ortholog of human KCNH2, encodes Kv11.1 (ERG1), a voltage-gated potassium channel with an amino-terminal PAS domain and a carboxy-terminal cyclic nucleotide-binding homology domain that interact to set unusually slow deactivation alongside very fast, voltage-dependent C-type inactivation. This gating signature makes ERG1 the carrier of the cardiac rapid delayed rectifier that terminates the action potential plateau, and the same channel regulates firing frequency and spike-frequency adaptation in brain, where KCNH2 variants have been tied to schizophrenia-associated isoforms. Loss-of-function KCNH2 mutations cause long QT syndrome type 2 and the promiscuous inner-cavity binding pocket makes ERG1 the central off-target in drug safety testing. Because mouse ventricular repolarization relies less on this current, humanized knockin alleles that replace the pore and cavity residues are usually more informative than deletion for proarrhythmia work, while conditional nulls address neuronal excitability. Kcnh6 and Kcnh7 form heteromeric ERG channels, so subunit composition should be measured directly.',
  Kcnh3:
    'Kcnh3, the mouse ortholog of human KCNH3, encodes Kv12.2 (BEC1 or ELK2 in older nomenclature), a voltage-gated potassium channel of the EAG superfamily that is restricted largely to forebrain, with strong expression in hippocampal CA1 pyramidal neurons, cortex, and olfactory bulb. Kv12.2 activates near resting membrane potential and therefore behaves as a persistent, subthreshold brake on excitability rather than a repolarizing conductance, and its trafficking depends on the accessory protein encoded by Lrrc55 and on PIP2 availability at the cyclic nucleotide-binding homology domain. Deletion lowers spike threshold and renders mice seizure-prone with enhanced hippocampal excitability, whereas overexpression suppresses firing, making the gene a candidate excitability set-point regulator. Conditional nulls localize this effect to defined pyramidal populations, and gating knockins test whether the shifted activation curve, rather than channel number, carries the phenotype. The related Kcnh8 subunit can heteromerize within the Kv12 subfamily, so verify composition before assigning currents.',
  Kcnh5:
    'Encoding Kv10.2 (EAG2), Kcnh5 is the mouse ortholog of human KCNH5 and produces a voltage-gated potassium channel of the EAG family that, unlike its ERG relatives, lacks fast inactivation and instead shows a Cole-Moore shift in which prior hyperpolarization slows activation, a behavior conferred by the amino-terminal PAS domain and intracellular calmodulin binding that inhibits the channel when calcium rises. Kv10.2 is expressed in cortical and hippocampal neurons and at the axon initial segment in some populations, where it shapes repetitive firing and, in cerebellar granule cells, contributes to volume regulation. Recurrent de novo KCNH5 variants at the pore-adjacent Arg327 residue cause developmental and epileptic encephalopathy through gain of function, shifting activation to more negative potentials, so patient-matched knockin alleles capture the disease logic that a null allele cannot. Conditional deletion instead addresses whether the channel is required for normal excitability; pair either allele with cortical Cre drivers and single-cell electrophysiology endpoints.',
  Kcnh6:
    'Kcnh6, the mouse ortholog of human KCNH6, encodes Kv11.2 (ERG2), an ERG-family potassium channel sharing the PAS domain and cyclic nucleotide-binding homology domain architecture that yields slow deactivation coupled to rapid C-type inactivation. ERG2 is expressed in brain, including hypothalamic and brainstem neurons, and in pancreatic islet beta cells, where ERG current contributes to repolarization of the calcium action potentials that pace insulin secretion, so loss-of-function variants have been associated with altered glucose-stimulated insulin release and hyperinsulinemia phenotypes. In neurons ERG2 supports spike-frequency adaptation and limits burst firing. A central design consideration is heteromerization: ERG2 co-assembles with Kv11.1 and Kv11.3 subunits encoded by Kcnh2 and Kcnh7, so single-locus deletion frequently yields residual ERG current, and compound alleles or dominant-negative pore knockins are needed to eliminate it. Choose conditional nulls with islet or neuron-restricted Cre for tissue attribution, and humanized pore knockins when the endpoint is subunit-selective pharmacology rather than gene dosage.',
  Kcnh7:
    'Kcnh7, ortholog of human KCNH7, encodes Kv11.3 (ERG3), the ERG-family potassium channel most abundantly expressed in the central nervous system, where it carries a substantial fraction of neuronal ERG current in cortex, hippocampus, and midbrain. Like other ERG channels it combines slow activation and deactivation with fast inactivation, but ERG3 activates at more negative potentials and contributes a resurgent current during repolarization that shapes interspike interval and spike-frequency adaptation, thereby setting sustained firing rates rather than single-spike waveform. Human KCNH7 variants have been associated with bipolar disorder and psychosis risk, motivating knockin alleles at candidate residues alongside straightforward conditional nulls that test whether removing the dominant neuronal ERG subunit destabilizes firing homeostasis. Because Kcnh2 and Kcnh6 heteromerize with ERG3 and can sustain residual current, plan compound genetics and measure ERG-specific block pharmacologically. Match the allele to whether the endpoint is intrinsic excitability, behavioral state, or drug response.',
  Kcnh8:
    'Kcnh8, the mouse ortholog of human KCNH8, encodes Kv12.1 (ELK1), an EAG-superfamily potassium channel that activates at subthreshold voltages and deactivates slowly, producing a standing outward conductance in neurons rather than a classical repolarizing current. ELK1 is expressed in cortex, hippocampus, and dorsal root ganglia, and its gating includes a prominent voltage-dependent potentiation in which prior depolarization shifts subsequent activation to more negative potentials, effectively giving the channel a short-term memory of recent activity that damps repetitive firing. Regulation runs through the cyclic nucleotide-binding homology domain and PIP2, and the amino-terminal PAS domain controls deactivation rate. Because Kv12.1 sits near resting potential, conditional deletion is the appropriate tool for asking whether it sets excitability thresholds in defined populations, while gating knockins separate channel number from voltage dependence. The paralogs Kcnh3 and Kcnh9 form heteromers within the Kv12 subfamily, so verify subunit composition before attributing residual current to incomplete deletion.',
  Kcnh9:
    'Encoding Kv12.3 (ELK2 or ELK1 depending on nomenclature vintage), Kcnh9 is the mouse ortholog of human KCNH9 and completes the Kv12 subfamily of EAG-superfamily channels, contributing a slowly activating, subthreshold potassium conductance that opposes depolarization near resting membrane potential. Expression is largely neuronal, with signal in cortex, hippocampus, and thalamus, and the channel shares the family architecture of an amino-terminal PAS domain, six transmembrane segments, and a carboxy-terminal cyclic nucleotide-binding homology domain that mediates PIP2 sensitivity and slow deactivation without the fast inactivation that defines ERG channels. Functional characterization of Kv12.3 is thinner than for its relatives, so experiments should be framed to establish requirement rather than assume mechanism: conditional nulls paired with cortical or thalamic Cre drivers and current-clamp readouts of rheobase and adaptation are the primary design. Kcnh3 and Kcnh8 heteromerize with this subunit, so compound alleles are often necessary to unmask a phenotype that single-locus deletion leaves buffered.',
  Kcnj1:
    'Kcnj1, the mouse ortholog of human KCNJ1, encodes ROMK (Kir1.1), an inwardly rectifying potassium channel built from two transmembrane helices flanking a pore loop, assembled as a tetramer, and gated by intracellular pH acting through a conserved lysine in the amino terminus together with PIP2 binding at the cytoplasmic domain. ROMK provides the apical potassium recycling pathway in the thick ascending limb that sustains NKCC2-mediated sodium chloride reabsorption, and it mediates potassium secretion in the cortical collecting duct, placing it downstream of WNK kinase and SGK1 regulation. Loss-of-function mutations cause antenatal Bartter syndrome type 2 with salt wasting and, paradoxically, transient neonatal hyperkalemia, and mouse nulls reproduce polyuria, hydronephrosis, and high perinatal mortality on many backgrounds. Conditional alleles with nephron segment-restricted Cre drivers separate thick ascending limb from collecting duct contributions, while knockins of specific pH-sensing or PIP2-binding residues test gating mechanism, and humanized pore alleles support ROMK inhibitor diuretic programs.',
  Kcnj10:
    'Kcnj10, the mouse ortholog of human KCNJ10, encodes Kir4.1, the principal inwardly rectifying potassium channel of astrocytes, Bergmann glia, oligodendrocytes, and retinal Muller cells, where it clamps the glial membrane near the potassium equilibrium potential and performs spatial buffering of extracellular potassium released during neuronal firing. Kir4.1 functions as a homotetramer or as an obligate partner in Kir4.1/Kir5.1 heteromers with the Kcnj16 product, which confers steep intracellular pH sensitivity, and it also operates in the distal convoluted tubule and stria vascularis, coupling to the sodium pump and to chloride handling. Biallelic human mutations cause SeSAME/EAST syndrome with seizures, ataxia, sensorineural deafness, and renal salt wasting, and constitutive nulls die in the early postnatal period with hypomyelination and severe motor impairment, so glia-restricted conditional deletion using Gfap-Cre or Aldh1l1-CreER is required for adult work. No other glial Kir substitutes effectively, so match allele to whether the endpoint is potassium clearance, seizure threshold, or renal electrolyte handling.',
  Kcnj11:
    'Encoding Kir6.2, Kcnj11 is the mouse ortholog of human KCNJ11 and supplies the pore-forming subunit of the ATP-sensitive potassium channel, an octamer of four Kir6.2 subunits with four sulfonylurea receptor subunits encoded by Abcc8. Intracellular ATP binding to Kir6.2 closes the channel while MgADP acting on the nucleotide-binding domains of SUR1 opens it, making the complex a direct metabolic sensor that couples glucose oxidation to beta cell depolarization and insulin secretion, and that also sets firing in substantia nigra pars reticulata neurons and provides ischemic protection in heart and brain. Activating mutations such as R201H and V59M cause neonatal diabetes with neurological features and respond to sulfonylureas, whereas loss-of-function alleles cause congenital hyperinsulinism, so the allele fork is explicit: gain-of-function knockins model diabetes and drug reversal, conditional nulls model hyperinsulinism and neuronal excitability. Kir6.1 encoded by Kcnj8 covers vascular smooth muscle but does not rescue beta cell channels.',
  Kcnj12:
    'Kcnj12, the mouse ortholog of human KCNJ12, encodes Kir2.2, a strong inward rectifier whose rectification arises from voltage-dependent block of the pore by intracellular magnesium and polyamines binding at a conserved aspartate in the second transmembrane segment and at cytoplasmic domain residues. Kir2.2 requires PIP2 for opening, and the crystal structures of this channel defined the PIP2 binding site for the entire Kir2 family. Functionally it co-assembles with Kir2.1 and Kir2.3 to build the cardiac and neuronal IK1 conductance that stabilizes resting membrane potential and sets the final phase of repolarization, and it is expressed in ventricular myocytes, skeletal muscle, and brain. Because heteromerization with the Kcnj2 and Kcnj4 products is the rule rather than the exception, single-locus nulls are typically viable with modest current reduction, and dominant-negative pore knockins or compound conditional alleles are needed to collapse IK1. Choose conditional deletion with cardiac or neuronal Cre when attributing arrhythmia or excitability phenotypes.',
  Kcnj13:
    'Kcnj13, the mouse ortholog of human KCNJ13, encodes Kir7.1, an atypical inward rectifier with unusually low single-channel conductance and weak dependence on extracellular potassium, properties traced to a methionine at the position occupied by arginine in other Kir channels. Kir7.1 is concentrated at the apical membrane of retinal pigment epithelium, where it colocalizes with the sodium pump and sets subretinal potassium levels, and it is also expressed in choroid plexus, thyroid, and uterine smooth muscle. Human mutations cause snowflake vitreoretinal degeneration through dominant-negative gating changes and Leber congenital amaurosis type 16 through recessive loss of function, giving a clear allele fork between knockin and null. Constitutive mouse nulls die within a day of birth with cleft palate and feeding failure, so retinal pigment epithelium-restricted conditional deletion using Best1-Cre or an inducible driver is required to study photoreceptor survival and electroretinogram c-wave endpoints in adults, and humanized alleles support gene replacement testing.',
  Kcnj14:
    'Encoding Kir2.4, Kcnj14 is the mouse ortholog of human KCNJ14 and produces the most restricted member of the strong inward rectifier Kir2 subfamily, expressed predominantly in retinal neurons, cranial and spinal motor neurons, and some cardiac tissue. Like its relatives it rectifies through voltage-dependent polyamine and magnesium block and requires PIP2 for opening, but Kir2.4 is distinguished by higher sensitivity to extracellular pH within the physiological range and by lower single-channel conductance, features that make it a tunable contributor to resting potential in motor neurons rather than a bulk conductance. It readily co-assembles with Kir2.1, Kir2.2, and Kir2.3 to form heteromeric channels with intermediate properties. Because the encoded subunit is a minority component in most tissues, conditional deletion alone often yields little phenotype, and compound alleles with Kcnj2 or Kcnj12 plus dominant-negative pore knockins are the practical route; select motor neuron or retina-restricted Cre drivers to align the allele with the intended readout.',
  Kcnj15:
    'Kcnj15, the mouse ortholog of human KCNJ15, encodes Kir4.2, an inwardly rectifying potassium channel closely related to Kir4.1 that assembles as a homotetramer or, more commonly in native tissue, as a heteromer with Kir5.1 encoded by Kcnj16, an arrangement that confers steep sensitivity to intracellular pH and carbon dioxide. Kir4.2 is expressed on the basolateral membrane of proximal tubule and other kidney segments, in liver, pancreas, and lung, and in restricted neural populations, where it contributes to potassium recycling that supports electrogenic transport and to acid-base sensing. The gene lies within the Down syndrome critical region on human chromosome 21 and has been linked to glucose handling and diabetic nephropathy risk. Conditional nulls with segment-restricted Cre drivers are the appropriate design for transport phenotypes, while pH-sensing residue knockins test the chemosensory hypothesis directly. Because Kir4.1 covers overlapping territory in some tissues, quantify heteromer composition rather than assuming a clean single-subunit loss.',
  Kcnj16:
    'Kcnj16, the mouse ortholog of human KCNJ16, encodes Kir5.1, a subunit that is electrically silent on its own and functions only by heteromerizing with Kir4.1 or Kir4.2, where it converts a weakly pH-sensitive channel into a steeply pH-sensitive one through a lysine in the second transmembrane domain of its partner and through a Kir5.1-specific carboxy-terminal interface. Kir4.1/Kir5.1 channels operate on the basolateral membrane of the distal convoluted tubule and collecting duct, in astrocytes, in carotid body and brainstem chemosensitive neurons, and in retina, making the subunit a molecular link between carbon dioxide, intracellular pH, and potassium conductance. Null rats and mice show impaired potassium and acid-base handling with hypokalemic alkalosis and altered chemoreflex responses. Because the obligate partnership is with Kcnj10 and Kcnj15 products, deletion of Kcnj16 does not abolish current but shifts pH sensitivity, so design endpoints around gating and transport physiology rather than total conductance, using nephron or glia-restricted Cre.',
  Kcnj2:
    'Kcnj2, the mouse ortholog of human KCNJ2, encodes Kir2.1, the dominant subunit of the strong inward rectifier current IK1 that stabilizes the resting membrane potential of cardiac myocytes, skeletal muscle, and many neurons, and that contributes the terminal phase of cardiac repolarization. Rectification is not intrinsic gating but voltage-dependent block by intracellular magnesium and polyamines at Asp172 and cytoplasmic pore residues, and channel opening requires PIP2, with a Golgi export motif and a PDZ-binding tail controlling trafficking. Loss-of-function and dominant-negative KCNJ2 mutations cause Andersen-Tawil syndrome with periodic paralysis, prolonged QT, and dysmorphic features, whereas gain-of-function alleles cause short QT syndrome type 3, so the design fork is between disease knockin and conditional null. Nulls die neonatally with cleft palate, making cardiac or neuron-restricted conditional deletion necessary for adult work. Kir2.2 and Kir2.3 encoded by Kcnj12 and Kcnj4 heteromerize and blunt single-locus loss, so plan compound genetics for full IK1 collapse.',
  Kcnj3:
    'Encoding GIRK1 (Kir3.1), Kcnj3 is the mouse ortholog of human KCNJ3 and supplies a subunit that cannot form functional homotetramers and instead obligately partners with GIRK2 or GIRK4 to build G protein-gated inwardly rectifying potassium channels. These channels are opened directly by Gbeta gamma dimers released from Gi and Go-coupled receptors, including GABA-B, M2 muscarinic, opioid, adenosine A1, and D2 receptors, with PIP2 and intracellular sodium acting as required cofactors and RGS proteins setting deactivation kinetics. GIRK1-containing channels mediate slow inhibitory postsynaptic currents in hippocampus and cortex and the atrial IKACh that slows heart rate. Because the subunit is obligatorily heteromeric, deletion removes surface channels rather than reducing a parallel conductance, and conditional alleles with forebrain or interneuron Cre drivers cleanly separate central from cardiac phenotypes. Kcnj6 and Kcnj5 products remain partially functional without GIRK1, so quantify residual Gbeta gamma-activated current, and use humanized alleles for GIRK-selective modulator campaigns.',
  Kcnj4:
    'Kcnj4, the mouse ortholog of human KCNJ4, encodes Kir2.3, a strong inward rectifier of the Kir2 family that differs from Kir2.1 and Kir2.2 in having lower single-channel conductance, weaker PIP2 affinity, and pronounced inhibition by intracellular protons, making it the pH-sensitive member of the group. It is enriched in forebrain neurons, particularly in hippocampus and cortex where it contributes to resting conductance and dendritic input resistance, and it is present in atrial myocytes and kidney. Its carboxy-terminal PDZ-binding motif recruits PSD-95 and SAP97, localizing the channel to synaptic and lateral membrane domains. Because Kir2.3 heteromerizes freely with Kir2.1 and Kir2.2 encoded by Kcnj2 and Kcnj12, single-locus nulls are viable and usually show only partial IK1 reduction, so compound conditional alleles or dominant-negative pore knockins are required to unmask function. Align the allele with the endpoint, using forebrain-restricted Cre for excitability studies and pH-sensing residue knockins for gating mechanism.',
  Kcnj5:
    'Kcnj5, the mouse ortholog of human KCNJ5, encodes GIRK4 (Kir3.4), the G protein-gated inward rectifier subunit that partners with GIRK1 to carry the atrial acetylcholine-activated current IKACh downstream of M2 muscarinic receptors, and that also forms channels in adrenal zona glomerulosa, pancreatic islets, and restricted brain regions. Channel opening requires direct Gbeta gamma binding together with PIP2, and GIRK4 uniquely can form functional homotetramers, unlike GIRK1. The dominant disease logic is gain of function: somatic and germline KCNJ5 mutations at Gly151 and Leu168 disrupt the selectivity filter, admit sodium, and depolarize glomerulosa cells, driving aldosterone-producing adenomas and familial hyperaldosteronism type 3. Selectivity-filter knockins therefore model primary aldosteronism directly, while conditional nulls address vagal heart rate control and adrenal potassium handling separately. GIRK1, GIRK2, and GIRK3 encoded by Kcnj3, Kcnj6, and Kcnj9 assemble in overlapping combinations, so define subunit composition electrophysiologically before assigning a phenotype to this locus.',
  Kcnj6:
    'Kcnj6, the mouse ortholog of human KCNJ6, encodes GIRK2 (Kir3.2), the principal neuronal G protein-gated inward rectifier, which forms functional homotetramers as well as heteromers with GIRK1 and GIRK3 and is opened by Gbeta gamma subunits liberated by GABA-B, D2, mu opioid, and other Gi/Go-coupled receptors, with PIP2, intracellular sodium, and alcohol acting at defined cytoplasmic sites. GIRK2 carries the slow inhibitory postsynaptic potential in hippocampal and cortical neurons and sets pacemaking in substantia nigra dopaminergic neurons. The classical weaver mutation, a G156S substitution in the selectivity filter, converts the channel into a nonselective cation conductance and kills cerebellar granule cells and dopaminergic neurons, a gain-of-toxic-function allele that behaves very differently from a null, which is viable with reduced opioid analgesia and increased seizure susceptibility. Choose knockin for the selectivity mechanism, conditional null with Dat-Cre or Gad2-Cre for circuit attribution, and quantify residual GIRK1 or GIRK3-containing current.',
  Kcnq1:
    'Kcnq1, the mouse ortholog of human KCNQ1, encodes Kv7.1, a voltage-gated potassium channel whose gating is transformed by accessory KCNE subunits: with KCNE1 it produces the slowly activating cardiac current IKs that provides repolarization reserve during sympathetic drive, while with KCNE3 it becomes a constitutively open conductance supporting chloride secretion in intestinal and airway epithelium. Activity requires PIP2 and calmodulin bound to the carboxy-terminal helices, and PKA phosphorylation through yotiao (AKAP9) mediates beta-adrenergic augmentation. Loss-of-function mutations cause long QT syndrome type 1 and, when biallelic, Jervell and Lange-Nielsen syndrome with deafness from failed endolymph secretion in the stria vascularis, whereas gain-of-function alleles cause short QT and atrial fibrillation. Mouse nulls are viable but deaf with vestibular dysfunction and gastric hyperplasia, so tissue-restricted conditional deletion separates cardiac, cochlear, and epithelial endpoints, and humanized knockins are preferred when the readout is IKs pharmacology, since murine repolarization depends on different currents.',
  Kcnq2:
    'Encoding Kv7.2, Kcnq2 is the mouse ortholog of human KCNQ2 and supplies the principal subunit of the neuronal M current, a slowly activating, noninactivating potassium conductance that opens near threshold and provides the dominant brake on repetitive firing. Kv7.2 assembles preferentially with Kv7.3, requires PIP2 at a carboxy-terminal site and calmodulin at helices A and B, and is targeted to the axon initial segment and nodes of Ranvier through an ankyrin-G binding motif; muscarinic M1 receptor activation depletes PIP2 and suppresses the current, which is the classical mechanism of cholinergic excitation. Human variants split cleanly into loss-of-function alleles causing benign familial neonatal epilepsy and dominant-negative pore mutations causing developmental and epileptic encephalopathy, so patient knockins are essential where deletion is not. Constitutive nulls die perinatally, mandating floxed alleles with Emx1-Cre or Nex-Cre for adult phenotyping. Kcnq3 and Kcnq5 partially substitute, so measure retigabine-sensitive M current directly.',
  Kcnq3:
    'Kcnq3, the mouse ortholog of human KCNQ3, encodes Kv7.3, the obligatory heteromeric partner that increases M current amplitude tenfold when co-assembled with Kv7.2 or Kv7.5, largely because its carboxy-terminal coiled-coil stabilizes tetramer assembly and its higher PIP2 affinity keeps the channel available at physiological lipid levels. Kv7.3 also carries the alanine at position 315 in the pore that is critical for potassium selectivity and for the action of openers such as retigabine, which binds a conserved tryptophan in S5. Like Kv7.2, the channel is concentrated at the axon initial segment and nodes through ankyrin-G binding, where it sets spike threshold and adaptation. KCNQ3 mutations cause benign familial neonatal epilepsy and, at specific residues, more severe encephalopathy with cortical malformation. Because Kcnq2 and Kcnq5 form the functional partnership, single deletion reduces rather than abolishes M current, so plan compound conditional alleles with forebrain Cre drivers and pair pore knockins with retigabine pharmacology endpoints.',
  Kcnq4:
    'Kcnq4, the mouse ortholog of human KCNQ4, encodes Kv7.4, a voltage-gated potassium channel expressed at the basal membrane of cochlear outer hair cells, in type I vestibular hair cells, in central auditory brainstem nuclei, and in vascular smooth muscle. In outer hair cells Kv7.4 carries IK,n, a conductance active at rest that sets the low resting input resistance and provides the potassium exit pathway required for cell survival after mechanotransduction-driven influx. Dominant KCNQ4 mutations in the pore, notably G285S, act as dominant-negatives and cause DFNA2 progressive high-frequency hearing loss, a mechanism reproduced in knockin mice through slow outer hair cell degeneration, while nulls show a milder, later phenotype, making the knockin the more faithful disease model. Kcnq1, Kcnq2, Kcnq3, and Kcnq5 do not substitute in outer hair cells, so redundancy is limited here. Match the allele to whether the endpoint is auditory brainstem response threshold shift, hair cell survival, or opener pharmacology.',
  Kcnq5:
    'Encoding Kv7.5, Kcnq5 is the mouse ortholog of human KCNQ5 and contributes a slowly activating, noninactivating potassium conductance that co-assembles with Kv7.3 to form a distinct component of the neuronal M current, with particularly strong expression in hippocampal CA3, dentate gyrus, cortical interneurons, auditory brainstem, and in vascular and airway smooth muscle where it sets resting tone. Kv7.5 activates at more negative potentials than Kv7.2-containing channels and is strongly PIP2 dependent and calmodulin regulated, and it is suppressed by Gq-coupled receptor signaling, which converts muscarinic or purinergic input into increased excitability or vasoconstriction. Human KCNQ5 loss-of-function variants cause intellectual disability with or without epilepsy. Nulls are viable, so conditional alleles serve cell-type attribution rather than lethality rescue, and gating knockins test whether the shifted voltage dependence carries the phenotype. Because Kcnq2 and Kcnq3 supply overlapping M current, compound genetics and retigabine-sensitive current measurement should accompany any single-locus interpretation.',
  Kctd12:
    'Kctd12, the mouse ortholog of human KCTD12, encodes an auxiliary subunit of the GABA-B receptor rather than a potassium channel, despite the tetramerization domain that names the family. Four KCTD12 subunits dock onto the carboxy-terminal tail of GABA-B2 and then compete directly with GIRK channels for Gbeta gamma, which accelerates receptor activation kinetics and, distinctively, imposes strong desensitization of the GIRK-mediated slow inhibitory postsynaptic current, a property not shared by the related KCTD8 and KCTD16 subunits. Expression is high in the habenula, where the gene is a canonical marker of lateral habenular subdomains, and in hippocampus, thalamus, and interpeduncular nucleus. Null mice retain GABA-B signaling but lose current desensitization, showing altered anxiety-related and audiogenic responses, so deletion isolates a kinetic rather than an amplitude phenotype. Kctd8 and Kctd16 occupy the same binding site and shift assembly composition when this locus is removed, so plan compound alleles and score GABA-B current kinetics as the primary endpoint.',
  Kctd13:
    'Kctd13, the mouse ortholog of human KCTD13, encodes a BTB domain protein that functions as a substrate adaptor within Cullin3 RING E3 ubiquitin ligase complexes, with its best-defined substrate being RhoA, whose polyubiquitination and degradation link this locus to actin cytoskeletal dynamics, synapse structure, and neuronal migration. The gene lies within the 16p11.2 interval whose recurrent deletion and duplication cause reciprocal head size and body weight phenotypes together with autism and schizophrenia risk, and KCTD13 has been nominated as a principal dosage-sensitive driver of that interval, although later work argues the phenotype is polygenic within the region. Mouse nulls show reduced synaptic transmission with elevated RhoA and altered spine density, without lethality. The design fork is therefore dosage-focused: conditional nulls test cell-autonomous requirement, while conditional overexpression or duplication alleles model the reciprocal copy number state. Kctd10 and Tnfaip1 share Cullin3 adaptor activity toward RhoA, so quantify RhoA levels rather than assuming complete pathway disinhibition.',
  Kctd15:
    'Kctd15, the mouse ortholog of human KCTD15, encodes a BTB and POZ domain protein that oligomerizes into pentamers and acts both as a Cullin3 E3 ligase adaptor and as a direct inhibitor of AP-2 transcription factors, a mechanism first defined in neural crest induction where KCTD15 restricts the crest domain at the neural plate border. In vertebrate development it also modulates Wnt and Nodal signaling, and in the hypothalamus it has been implicated in the melanocortin pathway, consistent with human GWAS signals near KCTD15 for body mass index and obesity risk. Related family members KCTD1 and KCTD15 share the AP-2 inhibitory activity, and the closely related KCTD12 and KCTD17 diverge functionally, so paralog-aware design matters. Conditional nulls with Wnt1-Cre address neural crest derivatives, while hypothalamic or Pomc-restricted deletion addresses energy balance, and Cullin3-binding-deficient knockins separate ligase-dependent from transcription factor-binding functions. Choose the allele that matches whether the endpoint is craniofacial patterning, adiposity, or transcriptional output.',
  Kdm6a:
    'Chromatin models built on Kdm6a, the mouse ortholog of human KDM6A, must contend with a JmjC domain demethylase (UTX) that removes H3K27me2 and H3K27me3 while serving as a stoichiometric subunit of KMT2D and KMT2C COMPASS-like complexes at enhancers. Loss-of-function truncations recur in bladder carcinoma, T-lineage acute leukemia, and multiple myeloma, and germline variants cause Kabuki syndrome, so the disease-relevant lesion is haploinsufficiency or biallelic inactivation rather than gain of catalysis. Allele planning diverges sharply: a conditional null interrogates enhancer decommissioning and differentiation blockade, a demethylase-dead point knockin separates catalytic from scaffolding function, and humanization supports patient variant interpretation. Redundancy is genuinely load bearing here, because the Y-linked paralog Uty provides catalysis-independent scaffold activity and Kdm6b (JMJD3) overlaps substrate specificity, which explains why hemizygous males survive longer than null females. Since the locus is X-linked and escapes inactivation, sex, dosage, and Cre driver choice (Vav1 or Mx1 versus urothelial Upk2) must be fixed before phenotyping.',
  Kit:
    'Kit encodes the mouse ortholog of human KIT, a type III receptor tyrosine kinase with five extracellular immunoglobulin-like domains, an autoinhibitory juxtamembrane segment, and a split kinase domain that dimerizes upon binding stem cell factor (Kitl). Ligand engagement triggers trans-autophosphorylation and recruitment of PI3K, SRC family kinases, and the RAS-ERK cascade, sustaining mast cells, melanoblasts, hematopoietic progenitors, germ cells, and interstitial cells of Cajal. Oncogenic alleles fall into two mechanistic classes: juxtamembrane exon 11 deletions that relieve autoinhibition in gastrointestinal stromal tumor, and activation loop D816V substitutions that confer imatinib resistance in systemic mastocytosis and core binding factor leukemia. Conditional nulls therefore address lineage dependency, whereas knockin of the exact human hotspot codon models spontaneous tumorigenesis and inhibitor pharmacology; complete loss recapitulates the dominant white spotting phenotype with perinatal macrocytic anemia, so hypomorphic or inducible strategies preserve viability. Pair activating knockins with tissue-restricted Cre drivers to localize transformation and obtain clean drug response endpoints.',
  Kmt2a:
    'Trithorax-family biology begins with Kmt2a, the mouse ortholog of human KMT2A (MLL1), whose C-terminal SET domain deposits H3K4 methylation at Hox loci after taspase1 cleavage and reassembly of the N-terminal and C-terminal fragments, with catalysis requiring the WRAD module (WDR5, RBBP5, ASH2L, DPY30) and locus targeting through menin, LEDGF, and CXXC-mediated CpG binding. Leukemogenesis proceeds not by point mutation but by 11q23 translocation, generating in-frame fusions such as MLL-AF9 or MLL-AF4 that retain the CXXC domain, recruit DOT1L and the super elongation complex, and enforce HOXA9 and MEIS1 expression. Allele design splits accordingly: conditional nulls test methyltransferase dependence and hematopoietic stem cell output, SET-dead knockins isolate catalysis, and inducible fusion knockins at the endogenous locus produce latency-appropriate leukemia. Germline nulls are embryonic lethal near midgestation while heterozygotes show skeletal and hematopoietic haploinsufficiency, and the paralog Kmt2b partially overlaps, so compound conditionals with a validated hematopoietic Cre are advisable.',
  Kmt2c:
    'Enhancer methylation studies require Kmt2c, the mouse ortholog of human KMT2C (MLL3), a SET domain monomethyltransferase that, with its close paralog Kmt2d, forms COMPASS-like complexes containing NCOA6, PTIP, PA1, and the demethylase UTX to deposit H3K4me1 and license distal regulatory elements for p53, estrogen receptor, and lineage transcription factor output. Truncating and inactivating missense mutations accumulate across breast carcinoma, bladder cancer, medulloblastoma, and myeloid neoplasms, frequently as 7q deletions in the hematopoietic setting, so the disease-relevant allele is loss of function, often at haploinsufficient dosage, rather than hyperactivity. Model design consequently forks between conditional nulls that expose enhancer decommissioning and differentiation defects, SET-dead knockins that separate catalytic from scaffolding contributions, and humanized alleles for variant classification. Redundancy is real and quantitative, since Kmt2d covers overlapping enhancer sets, so compound conditional genetics should be planned upfront, and endpoint choice, whether tumor latency with a cooperating driver or chromatin profiling, dictates the appropriate Cre.',
  Kmt2d:
    'Among enhancer regulators, Kmt2d is the mouse ortholog of human KMT2D (MLL2 or MLL4) and the dominant H3K4 monomethyltransferase of the COMPASS-like complex, working through NCOA6, PTIP, PA1, RBBP5, ASH2L, and UTX to prime enhancers that drive B cell, cardiac, and neural differentiation programs. Heterozygous truncating variants cause Kabuki syndrome, while somatic nonsense and frameshift mutations dominate follicular lymphoma, diffuse large B cell lymphoma, bladder carcinoma, and lung squamous cancer, implicating enhancer collapse and impaired germinal center exit rather than gain of function. Because germline nulls die in midgestation with cardiac and neural tube defects, conditional nulls remain the practical route for lineage-restricted enhancer studies, whereas SET-dead knockins separate catalysis from scaffolding and humanized alleles support classification of clinical missense variants. The paralog Kmt2c shares substrate and complex membership, so masked phenotypes are a genuine risk; align allele class with endpoint and use germinal center drivers such as Cgamma1-cre for lymphomagenesis.',
  Kras:
    'Kras, the mouse ortholog of human KRAS, encodes the Ras isoform on which most epithelial tumors depend, a GTPase governed by Sos1-mediated exchange and by Nf1 and Rasa1 GAP activity, coupling receptor input to Raf, PI3K, and Ral effectors; unlike Hras it is farnesylated without palmitoylation and carries a polybasic hypervariable region, and alternative fourth-exon splicing produces the 4A and 4B isoforms with different membrane behavior. Codon 12, 13, and 61 substitutions abolish GAP-stimulated hydrolysis, and allele identity matters pharmacologically, since Gly12Cys and Gly12Asp are addressed by chemically distinct inhibitors. Homozygous deletion is embryonic lethal, uniquely among Ras genes, so conditional nulls are required, while Lox-Stop-Lox oncogenic knockins expressed at endogenous levels remain the standard for tumor initiation and humanization enables clinical-compound pharmacokinetic and pharmacodynamic testing. Hras and Nras can substitute developmentally when knocked into the Kras locus, evidence that dosage and localization, not sequence identity, drive the essential requirement.',
  Lag3:
    'Lag3, the mouse ortholog of human LAG3, encodes a CD4 related type I membrane protein with four immunoglobulin superfamily domains, a distinctive extra loop in domain D1 that mediates high-affinity MHC class II binding, and additional reported ligands including fibrinogen like protein 1 and alpha-synuclein fibrils. Inhibitory output depends on the cytoplasmic FSAL motif and a glutamate proline repeat rather than classical ITIMs, and requires cis association with the T cell receptor complex, so LAG-3 dampens signaling by competing for peptide MHC class II and disrupting CD4 dependent assembly rather than by recruiting a canonical phosphatase. Alone, Lag3 nulls show mild phenotypes, but combined loss with Pdcd1 produces rapid lethal autoimmunity including myocarditis on permissive backgrounds, the genetic counterpart of relatlimab plus nivolumab synergy in melanoma. Choose humanization for antibody pharmacology because clinical reagents do not cross-react, and conditional deletion with Cd8-Cre when cell intrinsic exhaustion is the question.',
  Lck:
    'Proximal T cell receptor signaling begins with Lck, the mouse ortholog of human LCK, which encodes a Src-family tyrosine kinase anchored to the inner membrane by amino-terminal myristoylation and palmitoylation, with a unique domain that binds the cytoplasmic tails of Cd4 and Cd8, followed by SH3, SH2, and kinase domains; its activity is set by the balance of activating autophosphorylation at Tyr394 and inhibitory Csk-mediated phosphorylation at Tyr505, which Ptprc and Ptpn22 oppose, and once active it phosphorylates CD3 and zeta-chain ITAMs to recruit and activate Zap70. Nulls are viable but show a severe block at the beta-selection checkpoint, so germline deletion is tractable while conditional alleles isolate peripheral T cell requirements from thymic development. A Tyr505 to phenylalanine knockin creates a gain-of-function receptor-proximal kinase, and analog-sensitive gatekeeper mutants permit acute chemical-genetic inhibition on signaling timescales. Fyn substantially compensates, and only Lck and Fyn compound animals fully ablate proximal TCR signaling.',
  Ldha:
    'Ldha encodes the mouse ortholog of human LDHA, the M subunit of lactate dehydrogenase, which assembles into homotetramers and hybrid tetramers with LDHB and preferentially reduces pyruvate to lactate while regenerating cytosolic NAD+, sustaining glycolysis when oxidative capacity or oxygen delivery is limiting. Transcription is driven by HIF1A and MYC, making the gene a canonical Warburg effector, and human LDHA deficiency causes glycogen storage disease type XI with exertional myoglobinuria and a blunted rise in blood lactate during ischemic exercise testing. Allele options map to distinct questions: a conditional null with Ckmm-Cre or a tumor-restricted Cre tests glycolytic dependence and lactate export, patient missense knockins reproduce partial deficiency and exercise-triggered rhabdomyolysis, and humanization supports LDHA inhibitor pharmacology. Because Ldhb is co-expressed and forms hybrid tetramers retaining activity, isoform-resolved zymography is required before attributing changes to LDHA. Match allele to endpoint, whether lactate flux and NAD+ to NADH ratio, tumor growth, or ischemic exercise physiology.',
  Ldhb:
    'Human LDHB has as its mouse ortholog Ldhb, encoding the H subunit of lactate dehydrogenase, which forms tetramers with a lower Km for lactate and is inhibited by high pyruvate, biasing flux toward lactate oxidation and NADH generation in heart, red muscle and other oxidative tissues where imported lactate serves as fuel within the cell to cell lactate shuttle. This directional preference makes the isoform central to lactate consumption rather than production, and its loss shifts tissues toward pyruvate reduction and lactate accumulation; LDHB has also been implicated in lysosomal acidification and autophagy and is silenced by promoter methylation in several tumors. A conditional null with Myh6-Cre or Ckmm-Cre tests reliance on lactate oxidation under workload, whereas humanized knockins support isoform-selective inhibitor programs where sparing LDHA is the goal. Ldha co-expression yields hybrid tetramers retaining bidirectional activity, so quantify isoenzyme patterns. Align allele with arteriovenous lactate difference, lactate tracing, stress echocardiography and autophagic flux endpoints.',
  Ldhc:
    'Ldhc, ortholog of human LDHC, encodes lactate dehydrogenase C4, a germ cell-restricted isozyme expressed from meiosis onward in spermatocytes and retained in mature spermatozoa, where it operates in the cytosol and the sperm mitochondrial compartment and supports the glycolytic ATP supply required for hyperactivated motility and capacitation. Unlike the somatic isoforms it shows broader substrate tolerance, and its restricted expression makes it both a nonhormonal male contraceptive target and a cancer-testis antigen aberrantly expressed in tumors, the basis for vaccine and T cell receptor approaches. Because the null is viable and the phenotype is fertility limited, a constitutive knockout is the appropriate first allele, with reported subfertility from impaired motility and reduced fertilization, while humanized knockins are preferable when the goal is epitope-matched immunotherapy or contraceptive inhibitor testing. Ldha is present in germ cells and partially covers pyruvate reduction. Endpoints should include sperm motility and ATP content, in vitro fertilization rates, and litter size.',
  Ldhd:
    'Distinct from the cytosolic L-lactate dehydrogenases, Ldhd is the mouse ortholog of human LDHD and encodes a mitochondrial FAD-dependent D-lactate dehydrogenase that oxidizes D-lactate to pyruvate and feeds electrons into the respiratory chain, clearing the D-enantiomer generated by the methylglyoxal detoxification route and by gut microbiota. Loss of function in humans causes D-lactic aciduria, and hypomorphic alleles have been associated with elevated urinary D-lactate and, in some reports, with gout through effects on organic acid handling, a phenotypic spectrum entirely distinct from the exercise intolerance of LDHA deficiency. Since no paralog performs this reaction, a constitutive null is informative and viable, providing a clean model of D-lactate accumulation, while conditional alleles with Alb-Cre or intestinal epithelial Cre distinguish hepatic clearance from gut-derived load. Humanized knockins suit human variant validation. Match allele to endpoint, using stereospecific D-lactate and L-lactate quantification, methylglyoxal adduct measurement, microbiome manipulation, and respirometry with D-lactate as substrate.',
  Ldlr:
    'Ldlr, the mouse ortholog of human LDLR, encodes the cell surface receptor that clears apoB-containing lipoproteins, built from seven class A cysteine-rich ligand-binding repeats, EGF-A and EGF-B modules flanking a beta-propeller that mediates acid-dependent ligand release, an O-linked sugar domain, and a cytoplasmic NPXY motif read by Ldlrap1 for clathrin-mediated internalization; Pcsk9 binding to EGF-A diverts the receptor to lysosomal degradation instead of recycling, and Mylip ubiquitination provides a sterol-responsive degradation route. Loss-of-function alleles cause familial hypercholesterolemia, and null mice are viable but develop hypercholesterolemia and atherosclerosis on Western diet, making them a standard cardiovascular platform. Allele choice follows the question: a null for plaque biology, patient point mutations for class-specific trafficking defects, and full humanization when the endpoint is PCSK9 antibody efficacy, siRNA silencing, or base editing of the human sequence. Combining with Apoe or Apobec1 alleles tunes lipoprotein profiles toward human-like distributions.',
  Lefty1:
    'Lefty1 is the mouse ortholog of human LEFTY1 and encodes a divergent, proteolytically processed TGF-beta family protein that functions not as a receptor agonist but as a diffusible Nodal antagonist, binding Nodal and its EGF-CFC coreceptor Cryptic to block productive ActRIIB and ALK4 assembly and SMAD2 phosphorylation. Its expression at the prospective floor plate and ventral midline creates the barrier that prevents left-determining signals from crossing to the right side, so nulls show bilateral Nodal, Lefty2, and Pitx2 expression with left pulmonary isomerism and related laterality defects. Design choices follow that logic: conditional or germline nulls address barrier function, deletion of the asymmetric enhancer isolates transcriptional input from coding loss, and humanization supports biochemical antagonist assays. Lefty2 sits in tandem at the same locus and shares antagonist activity, so compound alleles must be engineered in cis on one chromosome, a constraint worth planning before any single-locus targeting begins.',
  Lefty2:
    'Serving as the diffusible inhibitor arm of the left-right circuit, Lefty2 is the mouse ortholog of human LEFTY2 and encodes a secreted, cleaved TGF-beta family protein that captures Nodal and the EGF-CFC coreceptors Cripto and Cryptic, preventing ActRIIB and ALK4 engagement and limiting SMAD2 and SMAD3 output. Because Nodal induces Lefty2 in left lateral plate mesoderm, the pair constitutes a self-regulating activator with a long-range inhibitor that positions the Pitx2 domain and fixes situs. Loss causes embryonic lethality from excess Nodal signaling with expanded mesendoderm, and human variants appear in heterotaxy and complex cardiac malformation. Consequently, conditional and hypomorphic alleles are preferable to germline nulls for laterality work, deletion of the asymmetric enhancer separates Nodal-dependent induction from constitutive expression, and dosage-sensitive knockins probe inhibitor range. Lefty1 is tandemly linked and functionally overlapping, so compound alleles require cis engineering rather than conventional intercrossing.',
  Lepr:
    'Lepr, ortholog of human LEPR, encodes the leptin receptor, a class I cytokine receptor expressed as several splice isoforms of which only the long form carries the full intracellular Box1 and Box2 motifs needed to activate Jak2 and the downstream tyrosines that recruit SHP2 and ERK, STAT5, and STAT3 to drive Pomc and Agrp transcription in hypothalamic neurons. This isoform structure is the crux of allele design, since the classic db mutation is a splicing defect that eliminates the signaling isoform while leaving short forms intact, and single tyrosine knockins that block STAT3 recruitment reproduce obesity without the full null phenotype, cleanly separating individual signaling arms. Conditional deletion with neuron-subtype Cre drivers assigns energy balance and glucose control to defined populations, and Lepr-Cre is itself a knockin requiring dosage controls. Match alleles to endpoints spanning body composition, food intake, hepatic glucose production, and phosphorylated STAT3 immunostaining.',
  Lrp5:
    'Lrp5, the mouse ortholog of human LRP5, encodes a single-pass LDL receptor-related Wnt co-receptor whose extracellular region comprises four beta-propeller and EGF module pairs; upon Wnt binding it is brought together with Frizzled, and CK1gamma and Gsk3 phosphorylation of reiterated PPPSPXS motifs in its cytoplasmic tail creates the Axin docking site that disables the beta-catenin destruction complex. The first propeller is the binding surface for the antagonists Dkk1 and Sost, which explains why the Gly171Val high bone mass substitution acts by escaping sclerostin inhibition rather than by increasing intrinsic activity, while loss-of-function alleles cause osteoporosis-pseudoglioma syndrome and familial exudative vitreoretinopathy. Nulls are viable with low bone mass and persistent hyaloid vasculature, so germline and conditional alleles are both practical, and the high bone mass knockin or a humanized propeller is the correct design for sclerostin antibody and Dkk1 blockade studies. Lrp6 overlaps functionally, so compound alleles reveal masked skeletal phenotypes.',
  Lrp6:
    'Sharing architecture with Lrp5, Lrp6 is the mouse ortholog of human LRP6 and encodes the more broadly required Wnt co-receptor, using its four beta-propeller and EGF repeat modules to engage Wnt ligands alongside Frizzled and its PPPSPXS-containing tail to recruit Axin after CK1gamma and Gsk3 phosphorylation, thereby stabilizing beta-catenin; Dkk1 and Sost bind the amino-terminal propellers, and Mesd chaperones folding during biosynthesis. Homozygous nulls die at or before birth with caudal truncation, neural tube closure defects, and limb abnormalities that phenocopy combined Wnt deficiencies, while the hypomorphic ringelschwanz allele survives with axial skeletal defects, so conditional deletion is the practical route for postnatal bone, metabolic, and tumor studies. Phosphomimetic tail knockins ask whether constitutive Axin capture drives signaling, antagonist-resistant propeller mutants test the Dkk1 axis genetically, and humanization supports antibody development. Because Lrp5 partially compensates in bone, plan compound conditional genetics with a skeletal or intestinal driver.',
  Lrrk2:
    'Lrrk2, the mouse ortholog of human LRRK2, encodes a large multidomain protein combining armadillo, ankyrin, and leucine-rich repeats with a ROC GTPase domain, a COR linker, a serine/threonine kinase domain, and a WD40 tail, functioning as a dimeric kinase recruited to damaged or stressed membranes. Its validated substrates are a subset of Rab GTPases, including Rab8a, Rab10, and Rab29, phosphorylated at a conserved threonine in the switch II motif, which blocks GDI binding and reroutes membrane trafficking, ciliogenesis, and lysosomal repair. The G2019S mutation in the kinase domain and R1441C/G in the ROC domain increase Rab10 phosphorylation and cause autosomal dominant Parkinson disease, so knockin alleles, not deletion, reproduce the disease mechanism, while nulls are viable but develop kidney and lung lamellar body pathology that constrains interpretation and mirrors the on-target liability of kinase inhibitors. Kinase-dead knockins separate scaffolding from catalysis; use phospho-Rab10 as the pharmacodynamic endpoint.',
  Map2k1:
    'Map2k1, the mouse ortholog of human MAP2K1, encodes MEK1, a dual-specificity kinase that phosphorylates the Thr and Tyr residues of the ERK activation loop TEY motif and is itself activated by Raf phosphorylation of Ser218 and Ser222; it carries an amino-terminal negative regulatory segment, a docking site for ERK, and a proline-rich insert that mediates Ksr scaffold assembly, and ERK-mediated feedback phosphorylation of Thr292 dampens output. Germline nulls die at mid-gestation from placental labyrinth failure, so conditional alleles are needed for tissue work, while allele class maps cleanly onto distinct questions: constitutively active Ser218 and Ser222 to aspartate knockins test whether MEK output suffices for transformation, RASopathy substitutions model cardiofaciocutaneous syndrome, and inhibitor-resistant mutations validate on-target drug action in vivo. Map2k2-encoded MEK2 overlaps substantially and its null is viable, so compound conditional deletion is frequently required, and a lineage driver with confirmed excision efficiency is as important as the flox design.',
  Map2k2:
    'Encoding MEK2, Map2k2 is the mouse ortholog of human MAP2K2 and functions as the second dual-specificity kinase of the Raf to ERK module, phosphorylating the TEY activation motif of Erk1 and Erk2 after Raf-mediated modification of its own activation loop serines; it differs from MEK1 in lacking the Thr292 ERK feedback site and in weaker Ksr scaffold association, which gives it distinct kinetics and dimerization behavior within heterodimeric MEK1 and MEK2 complexes. Homozygous nulls are viable and fertile because MEK1 compensates, so this locus is most informative in compound genetics or as a background on which MEK1 dosage is titrated, and Map2k1 with Map2k2 double conditional animals reveal requirements invisible in either single mutant. Cardiofaciocutaneous syndrome substitutions provide developmental gain-of-function alleles, while resistance mutations distinguish on-target from off-target inhibitor effects. Match allele class to endpoint, and confirm that the chosen Cre deletes efficiently in the compartment where MEK dosage is being tested.',
  Mapk1:
    'Mapk1, the mouse ortholog of human MAPK1, encodes ERK2, the more abundant of the two classical extracellular signal-regulated kinases, activated by MEK1 and MEK2 phosphorylation of the Thr and Tyr residues in its TEY motif and directing substrate choice through a common docking groove and an F-site that recognize DEF and D-domain motifs in Rsk kinases, Elk1, Fos, and Myc, where it phosphorylates Ser62 to stabilize the protein; Dusp6 and Spry proteins impose negative feedback. Homozygous nulls die in early gestation from trophoblast and placental failure, so conditional alleles are required, and allele class separates questions cleanly: floxed deletion tests tissue dependence, an analog-sensitive gatekeeper mutant enables acute kinase inhibition without adaptive rewiring, and knock-in reporters such as kinase translocation constructs quantify signaling dynamics rather than presence. Mapk3-encoded ERK1 is a genuine paralog whose null is viable, and total ERK dosage rather than isoform identity governs most phenotypes, so plan compound alleles accordingly.',
  Mapk14:
    'Mapk14, the mouse ortholog of human MAPK14, encodes p38alpha, a stress-activated MAP kinase phosphorylated on the Thr and Tyr residues of its TGY motif by Map2k3 and Map2k6 downstream of Tak1, Ask1, and Map3k7 in response to inflammatory cytokines, osmotic stress, and DNA damage; its substrates include Mapkapk2, Mknk1, Atf2, Mef2c, and Tp53, and it governs Tnf and Il1b mRNA stability through the MK2 and tristetraprolin axis. A Thr106 gatekeeper residue defines the ATP pocket exploited by pyridinylimidazole inhibitors, which is why a Thr106Met knockin creating a drug-resistant kinase remains the most rigorous in vivo test of on-target inhibitor action. Homozygous nulls die at mid-gestation from placental defects that tetraploid complementation rescues, so conditional deletion is standard for immune and cardiac studies. Mapk11, Mapk12, and Mapk13 encode the other p38 isoforms with partially shared substrates, so compound alleles and a validated lineage driver protect against masked phenotypes.',
  Mapk3:
    'Mapk3, the mouse ortholog of human MAPK3, encodes ERK1, which shares activation by MEK1 and MEK2 through its TEY motif, the same D-domain and DEF-site substrate recognition surfaces, and essentially the same catalytic preferences as ERK2, differing mainly in an amino-terminal extension that slows its nuclear shuttling and in lower expression in most tissues. Homozygous nulls are viable and fertile with modest thymocyte maturation and adipogenic phenotypes, consistent with ERK2 supplying the bulk of pathway flux, which makes this locus most useful for dosage experiments rather than for asking whether ERK activity is required. Informative designs therefore include a straightforward null on sensitized backgrounds, conditional deletion combined with Mapk1 floxed alleles to titrate total ERK output, and isoform-swap knockins that place ERK1 coding sequence at the Mapk1 locus to test whether the two proteins are functionally interchangeable. Interpretation depends on quantifying phospho-ERK dosage, so pair allele choice with a driver validated for complete excision.',
  Mapk8:
    'Encoding JNK1, Mapk8 is the mouse ortholog of human MAPK8 and is activated by Map2k4 and Map2k7 phosphorylation of its TPY motif downstream of Map3k proteins responding to cytokines, ultraviolet irradiation, and endoplasmic reticulum stress, with Jip scaffolds organizing the module; substrates include Jun at Ser63 and Ser73, Atf2, Jund, Bcl2l11, and Irs1 at Ser307, linking stress signaling to apoptosis, transformation, and insulin resistance, while alternative splicing generates alpha and beta isoforms with distinct substrate docking. Homozygous nulls are viable and metabolically protected on high fat diet, whereas Mapk8 with Mapk9 double nulls die in mid-gestation from dysregulated neural apoptosis, which is the clearest evidence that JNK1 and JNK2 are genuinely redundant and that single-gene results must be interpreted cautiously. Conditional alleles isolate tissue-autonomous metabolic roles, analog-sensitive mutants allow acute inhibition, and compound conditional genetics with a lineage-specific driver is usually necessary for developmental questions.',
  Mapt:
    'Mapt, the mouse ortholog of human MAPT, encodes tau, a natively unfolded microtubule-associated protein whose carboxy-terminal repeat domain binds along the microtubule lattice to promote assembly and regulate axonal transport, while its projection domain and extensive phosphorylation by GSK3 beta, CDK5, and MARK kinases control detachment and aggregation propensity. A decisive species difference drives model design: adult mouse brain expresses almost exclusively four-repeat tau, whereas human brain expresses balanced three-repeat and four-repeat isoforms generated by exon 10 splicing, so intronic and exonic FTDP-17 mutations that shift isoform ratio cannot be modeled on the mouse locus and require humanized MAPT knockin alleles carrying the full genomic region. Coding mutations such as P301S and P301L instead drive filament formation and are commonly modeled by knockin or transgene. Nulls are viable with mild phenotypes because Map1b and Map2 compensate, so deletion answers requirement while humanized or aggregation-prone knockins answer tauopathy mechanism and antibody or antisense oligonucleotide response.',
  Matr3:
    'Matr3, the mouse ortholog of human MATR3, encodes matrin-3, an inner nuclear matrix protein with two RNA recognition motifs, two zinc finger domains, a bipartite nuclear localization signal, and a nuclear export signal, functioning in alternative splicing, nuclear retention of hyperedited RNAs, chromatin organization at matrix attachment regions, and transcription-coupled RNA stability. Matrin-3 binds pyrimidine-rich intronic sequences and physically associates with TDP-43, placing it in the same RNA processing network that fails in amyotrophic lateral sclerosis. The S85C mutation, together with F115C and P154S, causes autosomal dominant ALS with distal myopathy through altered protein stability, mislocalization, and gain of toxic function rather than simple loss, which makes patient knockin alleles the design of record; conditional nulls instead ask whether the protein is required in motor neurons or muscle, since matrin-3 is broadly essential and constitutive deletion is poorly tolerated. Pair knockins with Chat-Cre or muscle drivers as needed, and score splicing, TDP-43 localization, and neuromuscular junction integrity.',
  Med12:
    'Med12 encodes the mouse ortholog of human MED12, a subunit of the Mediator kinase module that, together with MED13, cyclin C, and CDK8 or CDK19, docks onto core Mediator to gate RNA polymerase II preinitiation complex activity and to relay Wnt, Notch, and nuclear receptor signals. Recurrent missense and in-frame indel mutations clustered in exons 1 and 2, notably at codon 44, define the overwhelming majority of uterine leiomyomas and also arise in fibroepithelial breast lesions, acting by disrupting kinase module coupling and cyclin C dependent CDK8 stimulation rather than by simple loss. Distinct germline missense variants cause X-linked intellectual disability syndromes including the Opitz-Kaveggia and Lujan phenotypes. Because germline deletion is early embryonic lethal, conditional nulls address transcriptional dependency in defined lineages while precise hotspot knockins are required for leiomyoma modeling and CDK8 inhibitor testing. The paralog Med12l overlaps partially in neural tissue, and X-linkage means sex and Cre selection (for example Amhr2-cre for myometrium) must be predefined.',
  Men1:
    'Endocrine tumor suppression centers on Men1, the mouse ortholog of human MEN1, encoding menin, a nuclear scaffold with no intrinsic enzymatic activity that binds the N-terminal fragment of KMT2A and KMT2B to direct H3K4 trimethylation at targets including Cdkn2c and Cdkn1b, while also restraining JUND-dependent transcription and engaging the SMAD3 and beta-catenin axes. Germline heterozygous loss-of-function alleles followed by somatic second hits produce multiple endocrine neoplasia type 1, with parathyroid hyperplasia, gastroenteropancreatic neuroendocrine tumors, and anterior pituitary adenomas, a textbook two-hit mechanism. Homozygous germline deletion is embryonic lethal in midgestation, so heterozygotes supply spontaneous multiendocrine tumor cohorts while conditional nulls driven by Rip-cre, Pdx1-cre, or Gcg-cre restrict loss to beta or alpha cells, shortening latency with clean cell of origin attribution. Because menin also physically gates MLL fusion oncoprotein chromatin occupancy, menin-MLL inhibitor pharmacology is best interrogated with humanized or interface point mutant alleles rather than nulls.',
  Met:
    'Receptor tyrosine kinase MET, encoded in mouse by Met, is the single-pass receptor for hepatocyte growth factor, comprising a SEMA domain, PSI and IPT repeats, and a cytoplasmic kinase domain whose phosphorylated Y1349 and Y1356 residues recruit GAB1 and GRB2 to activate RAS-ERK, PI3K-AKT, and STAT3, driving epithelial morphogenesis, hepatocyte survival, and myoblast migration. Oncogenic activation occurs through amplification, exon 14 skipping that removes the CBL-binding juxtamembrane degron and stabilizes the receptor, kinase domain germline mutations such as M1250T in hereditary papillary renal carcinoma, and TPR-MET rearrangement. Germline nulls die near midgestation from placental and hepatic failure, so conditional deletion is required for regeneration and tumor dependency studies, while exon 14 skipping or kinase domain knockins model ligand-independent signaling and inhibitor response. Since HGF binding is species selective, humanized MET or ligand-humanized alleles are essential for antibody and antibody-drug conjugate testing; pair these with epithelial Cre lines matched to the intended tumor lineage.',
  Mlh1:
    'Mlh1, the mouse ortholog of human MLH1, encodes the obligate partner of the MutL family, dimerizing with Pms2 to form MutLalpha, and less commonly with Mlh3 or Pms1; recruited by mismatch-bound MutSalpha, the complex uses ATP binding and the latent Pms2 endonuclease to nick the nascent strand, licensing Exo1-mediated excision and resynthesis, and it separately cooperates with Mlh3 to resolve meiotic recombination intermediates into crossovers. Germline loss causes Lynch syndrome with microsatellite instability, and somatic promoter hypermethylation silences it in sporadic colorectal and endometrial cancer. Homozygous nulls are viable but cancer-prone and sterile from meiotic failure, so conditional alleles are the way to study tissue-restricted repair loss without confounding infertility. Endonuclease-dead and dimerization-selective knockins separate repair from crossover functions, while humanization enables functional classification of variants of uncertain significance. Mlh3 and Pms1 partially cover meiotic roles but cannot substitute for MutLalpha in repair, so compensation is limited.',
  Mlkl:
    'Mlkl encodes mixed lineage kinase domain like protein, the mouse ortholog of human MLKL and the terminal executioner of necroptosis, built from an N-terminal four helix bundle killer domain, a brace region, and a catalytically dead pseudokinase domain that serves as a molecular latch. RIPK3 phosphorylates the activation loop at Ser345 in mouse, releasing the bundle to oligomerize, bind phosphatidylinositol phosphates, and permeabilize the plasma membrane, and the equivalent human activation sites and conformational requirements differ enough that murine and human proteins are not interchangeable for inhibitor testing. Nulls are viable and fertile and rescue the embryonic lethality of Casp8 or Fadd deletion, whereas phosphomimetic constitutively active knockins are lethal, so inducible expression is mandatory for gain-of-function work. Because species divergence is the central obstacle, humanized MLKL knockins are the informative allele for translational pharmacology, while conditional nulls with tissue restricted Cre lines partition necroptosis in ischemia, colitis, and kidney injury.',
  Mllt3:
    'Mllt3 is the mouse ortholog of human MLLT3 (AF9), a YEATS domain reader of acetylated and crotonylated histone H3 lysines that nucleates the super elongation complex with AFF1, AFF4, ENL, and the positive transcription elongation factor P-TEFb, and independently binds DOT1L to license H3K79 methylation and productive elongation. Its principal oncogenic role is as the 3 prime partner in t(9;11) MLL-AF9 fusions, where retained AF9 DOT1L and AF4 interaction surfaces convert KMT2A into a processive elongation driver at HOXA9 and MEIS1, establishing self-renewing myeloid leukemia. Beyond fusion biology, AF9 supports hematopoietic stem cell self-renewal, so a conditional null asks whether normal progenitors depend on the wild-type protein, whereas an inducible fusion knockin at the endogenous locus asks how the chimera transforms. The paralog Mllt1 (ENL) occupies the same complex and buffers loss, so compound conditionals with a Vav1 or Mx1 Cre driver yield interpretable elongation phenotypes.',
  Mlst8:
    'Mlst8, the mouse ortholog of human MLST8, encodes GbetaL, a seven-bladed WD40 propeller that docks against the mTOR kinase domain and is shared by both mTOR complexes, stabilizing the catalytic core and, importantly, being far more critical for mTORC2 integrity and Rictor association than for mTORC1 assembly or Raptor-dependent phosphorylation of Rps6kb1 and Eif4ebp1. Consistent with that asymmetry, homozygous nulls die in mid-gestation and phenocopy Rictor deficiency, with intact mTORC1 signaling but abolished Akt Ser473 phosphorylation, which makes this locus uniquely valuable for genetically separating the two complexes. Conditional deletion therefore asks a specific question about mTORC2 output in a given lineage, and comparing it directly against Rptor and Rictor floxed alleles in the same driver background is the design that resolves complex-specific biology, while interface point mutants test whether Rictor binding alone accounts for the phenotype. No paralog exists to buffer loss, so readouts report allele strength and Cre efficiency directly.',
  Mmp1:
    'Human MMP1 encodes interstitial collagenase 1, and the first design fact to confront is that rodents lack a single direct ortholog, since mouse collagenase 1 activity is distributed between Mmp1a and Mmp1b, with Mmp1a serving as the functional counterpart while expression patterns diverge substantially from human. The enzyme is secreted as a zymogen kept latent by a cysteine switch in the propeptide, activated by MMP3, plasmin, or MMP10, restrained by TIMP1 and TIMP2, and cleaves the triple helix of type I, II, and III collagen at a single locus, in addition to processing protease activated receptor 1 and several chemokines. Because of that divergence, epitope-matched knockin of human MMP1 is the informative allele for inhibitor and biomarker work, while Mmp1a conditional nulls address collagenolysis in tumor invasion and lung remodeling. Extensive overlap with Mmp8, Mmp13, and Mmp14 collagenase activity means single-locus deletion routinely underestimates matrix turnover.',
  Mmp12:
    'Mmp12 is the mouse ortholog of human MMP12 and encodes macrophage metalloelastase, a secreted zinc endopeptidase produced almost exclusively by macrophages, with a propeptide cysteine switch, a catalytic domain, and a hemopexin-like domain that undergoes autolytic removal, and with unusually potent activity against elastin as well as fibronectin, laminin, and type IV collagen. Its causal role in emphysema is well established, since Mmp12 nulls resist cigarette smoke induced airspace enlargement and show reduced macrophage recruitment, and the enzyme also contributes to aneurysm formation and to generation of matrikine chemoattractants. Beyond the extracellular compartment it accumulates intracellularly in macrophages where it participates in bacterial killing, a function that secretion-focused assays miss. Conditional deletion with Lyz2-Cre or Cx3cr1-CreER confirms the myeloid source, catalytically dead knockins separate proteolysis from scaffolding, and humanization supports selective inhibitor programs. Compensation by Mmp2, Mmp9, and neutrophil elastase means combined alleles are often needed for full elastolytic loss.',
  Mmp13:
    'Encoding collagenase 3, Mmp13 is the mouse ortholog of human MMP13 and the principal rodent interstitial collagenase, secreted as a zymogen activated by MMP2, MMP14, or plasmin and inhibited by TIMPs, with a catalytic domain that cleaves type I, II, and III collagen and a hemopexin domain that also permits degradation of aggrecan fragments, fibronectin, and perlecan. Transcription is driven by RUNX2, interleukin 1 beta, and MAPK signaling, and the enzyme is the dominant proteolytic driver of osteoarthritic cartilage loss as well as a required participant in growth plate remodeling and endochondral ossification, where compound loss with Mmp9 produces severe skeletal phenotypes. Design should therefore favor conditional deletion, using Col2a1-CreER or Acan-CreER for cartilage and osteoblast drivers for bone, rather than germline nulls that confound development with disease. Catalytically inactive knockins separate proteolysis from other functions, and humanization supports selective inhibitor testing where MMP1 cross-reactivity is the liability.',
  Mmp14:
    'Mmp14 corresponds to human MMP14 and encodes MT1-MMP, the membrane anchored metalloproteinase that concentrates proteolysis at the cell surface through a transmembrane segment and short cytoplasmic tail directing it into invadopodia and controlling internalization and recycling. It cleaves type I, II, and III collagen directly, sheds CD44 and syndecan, and serves as the physiologic activator of pro-MMP2 using TIMP2 as a bridging cofactor, making it the apex node of pericellular matrix turnover. Germline nulls are severely affected, with dwarfism, craniofacial and skeletal dysplasia, fibrosis, and death by weaning, mirroring human MMP14 lesions that cause multicentric osteolysis nodulosis and arthropathy, so viability alone dictates conditional design. Use floxed alleles with endothelial, fibroblast, chondrocyte, or tumor cell restricted Cre lines to separate developmental from disease contributions, catalytically dead knockins to isolate proteolysis from receptor shedding, and humanization when antibody selectivity against the human catalytic cleft is the endpoint.',
  Mmp2:
    'Mmp2 is the mouse ortholog of human MMP2 and encodes gelatinase A, distinguished from most family members by three fibronectin type II repeats inserted in the catalytic domain that confer high-affinity binding to gelatin, collagen, and elastin, and by an activation route requiring cell surface MMP14 with TIMP2 acting as a bridging cofactor rather than soluble proteolysis. Principal substrates include type IV collagen of basement membranes plus laminin, fibronectin, and latent TGF beta binding proteins, placing it centrally in angiogenic sprouting, tumor cell intravasation, and cardiac remodeling. Human biallelic MMP2 mutations cause multicentric osteolysis nodulosis and arthropathy, giving a defined disease knockin option, whereas mouse nulls are viable with modest growth retardation and reduced neovascularization. Overlapping gelatinolysis by Mmp9 means single deletion often looks mild, so plan compound alleles when basement membrane integrity is the readout, and use endothelial or fibroblast restricted Cre lines for source assignment.',
  Mmp3:
    'Encoding stromelysin 1, Mmp3 is the mouse ortholog of human MMP3 and a secreted zinc endopeptidase with unusually broad substrate range, cleaving aggrecan core protein, laminin, fibronectin, nidogen, and type IV and IX collagen, and, importantly, acting as a physiologic activator of pro-MMP1, pro-MMP9, and pro-MMP13, which places it upstream in proteolytic cascades rather than only at the substrate face. Latency is maintained by the propeptide cysteine switch and released by plasmin or other proteases, with TIMP1 as dominant inhibitor, and expression is driven in synovial fibroblasts and chondrocytes by interleukin 1 beta and TNF, which is why Mmp3 nulls show altered severity in collagen induced arthritis and impaired contact hypersensitivity. Because deletion removes an activator as well as an enzyme, phenotypes are frequently indirect, so catalytically dead knockins and compound alleles with Mmp13 clarify causality, while fibroblast or chondrocyte restricted conditional deletion matches allele to endpoint.',
  Mmp7:
    'Mmp7 is the mouse ortholog of human MMP7 and encodes matrilysin, the smallest matrix metalloproteinase, notable for lacking the hemopexin-like C-terminal domain entirely and for epithelial rather than stromal expression, most prominently in intestinal Paneth cells, airway epithelium, and glandular ducts. Beyond degrading fibronectin, laminin, and proteoglycans, its physiologically decisive activities are proteolytic maturation events: activation of pro-alpha defensins into bactericidal cryptdins in mouse small intestine, shedding of the E-cadherin ectodomain, release of soluble Fas ligand, and processing of syndecan bound chemokines. Mmp7 nulls consequently show impaired mucosal antimicrobial defense and altered wound repair rather than gross matrix failure, and the enzyme is an established progression biomarker in idiopathic pulmonary fibrosis. Match allele to question: conditional deletion with Vil1-Cre or Sftpc-CreER assigns the epithelial compartment, catalytically inactive knockins separate substrate processing from binding, and humanization is warranted where inhibitor selectivity or biomarker translation is the endpoint.',
  Mmp9:
    'Encoding gelatinase B, Mmp9 corresponds to human MMP9 and is distinguished by a fibronectin type II insert that grips gelatin and by a heavily O-glycosylated linker preceding the hemopexin domain, which mediates association with TIMP1 and with neutrophil specific storage that allows immediate release from preformed tertiary granules without new transcription. Substrates include type IV and V collagen, elastin, and several chemokines, and its best validated in vivo function is liberating matrix sequestered VEGF to trigger the angiogenic switch, a role established genetically in islet tumorigenesis models. Nulls are viable with delayed growth plate ossification and reduced neutrophil dependent tissue injury, and compensation by Mmp2 means gelatinolytic phenotypes often require both alleles. Because bone marrow derived cells supply most of the enzyme, conditional deletion or reciprocal marrow transplantation is what separates hematopoietic from stromal sources, catalytically dead knockins isolate proteolysis, and humanization supports selective inhibitor programs where broad spectrum compounds failed.',
  Mpo:
    'Mpo, the mouse ortholog of human MPO, encodes myeloperoxidase, the dominant protein of neutrophil azurophilic granules, synthesized as a glycosylated precursor and processed into a disulfide linked homodimer of heavy and light chains each holding a covalently bound heme. Using hydrogen peroxide generated by NADPH oxidase, it oxidizes chloride to hypochlorous acid and tyrosine to reactive radicals, producing the 3-chlorotyrosine footprint of oxidative host defense and contributing to neutrophil extracellular trap formation and lipoprotein modification in atherosclerosis. Two translational asymmetries shape design. Human MPO deficiency is comparatively common yet clinically mild, while myeloperoxidase is the principal autoantigen of ANCA associated microscopic polyangiitis, and mouse neutrophils carry substantially less enzyme than human cells, which blunts murine oxidative readouts. Nulls suit host defense and vasculitis initiation questions, catalytically inactive knockins separate enzymatic from antigenic roles, and humanization is the appropriate allele for autoantibody epitope mapping and inhibitor programs.',
  Mrc1:
    'Mrc1 corresponds to human MRC1 and encodes the mannose receptor CD206, a type I transmembrane endocytic lectin built from an N-terminal cysteine-rich domain that binds sulfated sugars, a fibronectin type II domain that binds collagen, and eight C-type lectin-like domains of which only a subset ligates terminal mannose, fucose, and N-acetylglucosamine in a calcium dependent manner. It functions constitutively in clathrin mediated uptake and lysosomal delivery, clearing circulating lysosomal hydrolases, thyroglobulin, and collagen fragments and shuttling glycosylated antigen for presentation, and it is expressed by tissue macrophages, lymphatic and hepatic sinusoidal endothelium, and tumor associated macrophages. Nulls are viable with elevated serum lysosomal enzymes, so the interesting alleles are usually reporter or Cre knockins for tracking and manipulating alternatively activated macrophages. Note that endothelial expression makes CD206 an imperfect macrophage restricted driver, and that Mrc2 and scavenger receptors share collagen internalization, so single deletion underestimates clearance.',
  Ms4a1:
    'Ms4a1, ortholog of human MS4A1, encodes CD20, a four-pass transmembrane member of the MS4A family with no identified natural ligand that associates with the B cell receptor complex and modulates store-operated calcium entry, appearing from the late pre-B stage through memory B cells and disappearing upon plasma cell differentiation. The decisive design consideration is that the null is largely uninformative, since knockout mice retain near-normal B cell development with only subtle calcium signaling changes, while the clinically meaningful biology lives entirely in the large extracellular loop that rituximab, ofatumumab and obinutuzumab recognize and that differs between mouse and human. Epitope-matched humanized CD20 knockins are therefore mandatory for studying depletion kinetics, complement-dependent cytotoxicity, antibody-dependent phagocytosis and Fc receptor engagement. Related MS4A family members are co-expressed and may buffer signaling contributions. Read out B cell depletion depth and duration across tissues, complement consumption, and recovery from bone marrow progenitors.',
  Msh2:
    'Msh2, the mouse ortholog of human MSH2, encodes the common subunit of both mismatch recognition complexes, pairing with Msh6 to form MutSalpha for base-base mispairs and small insertion or deletion loops and with Msh3 to form MutSbeta for larger loops; mismatch binding stimulates its Walker-motif ATPase, converting the heterodimer into a sliding clamp that recruits MutLalpha and licenses strand-specific excision, and the same machinery drives triplet repeat expansion and mediates the cytotoxicity of methylating agents. Germline biallelic loss causes constitutional mismatch repair deficiency and monoallelic loss causes Lynch syndrome, with microsatellite instability and hypermutation that confer immune checkpoint sensitivity. Nulls are viable, lymphoma-prone, and tolerant of temozolomide, so germline alleles are usable, while conditional deletion restricts hypermutation to a lineage of interest. ATPase separation-of-function knockins uncouple repair from damage signaling, and humanization supports variant classification. Msh6 and Msh3 are partners rather than substitutes, so no compensation rescues Msh2 loss.',
  Msh6:
    'Msh6, the mouse ortholog of human MSH6, encodes the Msh2 partner that completes MutSalpha, contributing the conserved Phe-X-Glu mismatch-reading motif that stacks against the mispaired base and an amino-terminal PWWP domain that binds H3K36me3, thereby coupling mismatch repair to actively transcribed, replication-timed chromatin; it also participates in somatic hypermutation and in class switch recombination fidelity in B cells. Human MSH6 mutations produce an attenuated Lynch phenotype skewed toward endometrial cancer with weaker microsatellite instability, and mouse nulls are viable and tumor-prone with a correspondingly milder instability signature, because Msh3-containing MutSbeta still handles insertion and deletion loops. That partial coverage is a genuine redundancy caveat: Msh6 with Msh3 compound animals are needed to reproduce full MutS deficiency. Allele choices include a null for tumor predisposition, a PWWP-deficient knockin to test chromatin targeting independently of catalysis, conditional alleles for lineage-restricted hypermutation, and humanization for variant of uncertain significance testing.',
  Mthfr:
    'Mthfr, the mouse ortholog of human MTHFR, encodes a FAD-dependent, NADPH-linked reductase that converts 5,10-methylenetetrahydrofolate to 5-methyltetrahydrofolate, the committed and effectively irreversible step that channels one-carbon units away from thymidylate and purine synthesis toward methionine synthase-mediated remethylation of homocysteine and thus toward S-adenosylmethionine production; the enzyme is allosterically inhibited by SAM through a carboxy-terminal regulatory domain, providing feedback control over methylation capacity. The common human C677T polymorphism produces a thermolabile Ala222Val protein with reduced FAD affinity and elevated homocysteine, especially under low folate intake. Homozygous nulls are viable but show hyperhomocysteinemia, altered DNA methylation, and developmental defects, so a humanized Ala222Val knockin is the design that models the common variant, whereas a null models severe deficiency and neural tube phenotypes. Because Bhmt provides a betaine-dependent remethylation bypass, dietary folate, choline, and betaine content must be specified as deliberately as the allele itself.',
  Mtor:
    'Mtor, the mouse ortholog of human MTOR, encodes a phosphatidylinositol kinase-related serine and threonine kinase with HEAT repeats, FAT, FRB, kinase, and FATC domains that nucleates two distinct complexes: mTORC1, containing Raptor and Mlst8, is recruited to lysosomes by Rag GTPases in response to amino acids and activated by Rheb-GTP under growth factor and energy input, phosphorylating Rps6kb1 and Eif4ebp1 to drive translation while suppressing Ulk1-dependent autophagy; mTORC2, containing Rictor, Mapkap1, and Mlst8, phosphorylates Akt at Ser473. Rapamycin acts allosterically by bridging Fkbp12 to the FRB domain, inhibiting mTORC1 acutely and mTORC2 only chronically. Homozygous deletion is lethal shortly after implantation, so conditional alleles are required, and the rapamycin-resistant Ser2035Thr knockin remains the definitive genetic test of on-target drug action. Kinase-dead and activating knockins separate scaffolding from catalysis, while Rptor and Rictor floxed alleles resolve complex-specific questions that Mtor deletion cannot.',
  Myc:
    'Myc, the mouse ortholog of human MYC, encodes a basic helix-loop-helix leucine zipper transcription factor that heterodimerizes with Max to occupy E-box CACGTG elements, recruiting Trrap, Gcn5, and P-TEFb to release paused RNA polymerase II and thereby amplifying the existing transcriptional program rather than imposing a single target signature; it also represses through Miz1. Protein stability is governed by a phosphodegron in which Erk-driven Ser62 phosphorylation primes Gsk3-mediated Thr58 phosphorylation, creating the Fbxw7 recognition site, while Aurora kinase A binding and Usp28 oppose turnover. Homozygous nulls die at mid-gestation, so conditional deletion is required, and allele class maps to distinct questions: a Thr58Ala knockin isolates degradation control, tetracycline-regulated or Lox-Stop-Lox overexpression tests reversibility and tumor maintenance, and humanization supports epitope-dependent reagents. Mycn and Mycl are paralogs with restricted expression that can substitute when knocked into the Myc locus, so dosage and driver choice determine the phenotype observed.',
  Mycl:
    'Mycl, the mouse ortholog of human MYCL, encodes L-Myc, a basic helix-loop-helix leucine zipper protein that dimerizes with Max and binds the same E-box elements as c-Myc but carries a weaker transactivation domain and, notably, lacks the canonical Thr58 and Ser62 phosphodegron architecture that governs c-Myc turnover, giving it different stability and a reduced capacity to induce apoptosis or replication stress. It defines a subset of small cell lung cancer distinct from MYC and MYCN-driven tumors, participates in the MYCL to NUTM1 fusion of NUT carcinoma, and is a selective dependency of Irf8-dependent conventional type 1 dendritic cells. Homozygous nulls are viable, which makes conditional overexpression from a Lox-Stop-Lox or Rosa26 allele the more informative design for asking whether L-Myc output initiates neuroendocrine transformation, while a conditional null addresses dendritic cell function. Myc and Mycn overlap in target occupancy, so paralog dosage should be measured when interpreting modest loss-of-function phenotypes.',
  Mycn:
    'Encoding N-Myc, Mycn is the mouse ortholog of human MYCN and produces a basic helix-loop-helix leucine zipper factor that heterodimerizes with Max, occupies E-box elements, and drives ribosome biogenesis and cell cycle programs in neural crest, neuroblast, and cerebellar progenitors; like c-Myc it carries the Thr58 and Ser62 phosphodegron read by Fbxw7, but Aurora kinase A binding stabilizes the protein against that pathway, which is the mechanistic basis for Aurora A inhibitor strategies in MYCN-amplified disease. Genomic amplification defines high-risk neuroblastoma and also occurs in medulloblastoma and neuroendocrine prostate cancer. Homozygous nulls die in mid-gestation with neural, cardiac, and lung defects, so conditional deletion is required for progenitor studies, whereas lineage-restricted overexpression modeled on tyrosine hydroxylase promoter-driven designs remains the standard tumor-initiating allele, and a Thr58Ala knockin isolates degron control from expression level. Myc can substitute at the endogenous locus, so paralog dosage and driver specificity govern the phenotype.',
  Myd88:
    'Myd88, the mouse ortholog of human MYD88, encodes the universal TIR domain adaptor for every Toll-like receptor except TLR3 and for IL-1R, IL-18R, and IL-33R, using its death domain to nucleate a helical Myddosome with IRAK4 and IRAK1 or IRAK2 that activates TRAF6, TAK1, IKK, and MAPK signaling. Human MYD88 deficiency yields severe pyogenic bacterial infection with otherwise intact immunity, while the recurrent L265P substitution in the TIR domain drives spontaneous Myddosome assembly and constitutive NF-kB in Waldenstrom macroglobulinemia and activated B cell diffuse large B cell lymphoma, cooperating with CD79B in a B cell receptor associated supercomplex. This split biology dictates the allele fork precisely: a conditional null tests requirement for innate sensing, and an L265P knockin, ideally Cd19-Cre or Aicda-Cre restricted and inducible, models the lymphoma. Since germline null phenotypes are strongly microbiota dependent, use littermate controls and defined flora rather than cross-facility comparisons.',
  Myh6:
    'Myh6, the mouse ortholog of human MYH6, encodes alpha myosin heavy chain, the fast ATPase cardiac motor whose isoform biology carries a species caveat that shapes every study: alpha predominates in the adult mouse ventricle whereas the human ventricle runs mainly on beta myosin from MYH7, so contractile kinetics and the pathological switch from alpha toward beta during hypertrophy and failure do not map directly onto patients. Human MYH6 variants cause atrial septal defects and cardiomyopathy, arguing for patient-specific knockins over deletion when modeling disease. A further practical warning applies because the Myh6 promoter drives the widely used alpha-MHC-Cre and MerCreMer cardiac lines, and tamoxifen-treated MerCreMer animals develop transient cardiomyopathy on their own, so Cre-only tamoxifen-treated controls are non-negotiable. Conditional alleles paired with echocardiography, sarcomere shortening in isolated myocytes, fetal gene program transcripts, and myosin ATPase measurements match allele class to a mechanistic endpoint.',
  Myh7:
    'Beta myosin heavy chain is encoded by Myh7, ortholog of human MYH7, a slow ATPase motor whose head domain hydrolyzes ATP to drive actin filament sliding and whose rod mediates thick filament assembly, including the folded interacting heads motif that sets the super-relaxed state and therefore baseline energy consumption. Species context governs interpretation, since beta myosin dominates the human ventricle while the adult mouse ventricle runs mainly on alpha myosin from Myh6, so a mouse null is comparatively uninformative and reinduction of Myh7 is read as a marker of the fetal gene program in stress. Human missense variants cause hypertrophic and dilated cardiomyopathy through altered super-relaxed state occupancy, which is precisely the target of mavacamten, making patient-specific knockins or humanized alleles the correct instruments rather than deletion. Match alleles to endpoints including echocardiographic wall thickness, myofibrillar ATPase and loaded shortening, single-molecule motility, and myocardial disarray on histology.',
  Ndufa1:
    'Ndufa1 encodes the mouse ortholog of human NDUFA1, the small hydrophobic MWFE accessory subunit of complex I that sits in the membrane arm adjacent to the mtDNA-encoded ND subunits and is required for assembly and stability of the proton-pumping segment rather than for redox chemistry itself. The gene is X-linked, and hemizygous human missense variants cause isolated complex I deficiency presenting as Leigh syndrome, encephalomyopathy or myoclonic epilepsy, with severity tracking the degree of residual holoenzyme assembly. That mutational spectrum argues that patient variant knockins, which preserve partial assembly, are more informative than a null for modeling disease course, while a conditional null with Nes-Cre or Camk2a-Cre defines the neuronal threshold for complex I loss and its consequences for NAD+ recycling and reverse electron transport ROS. No paralog substitutes for this subunit, so residual respiration reflects assembly intermediates. Choose endpoints including BN-PAGE with in-gel activity, rotenone-sensitive respirometry, brain lactate imaging, and rotarod performance.',
  Ndufa10:
    'The 42 kDa accessory subunit of complex I is encoded by Ndufa10, ortholog of human NDUFA10, a peripheral protein with a deoxyribonucleoside kinase-like fold that associates with the membrane arm near ND1 and the quinone-binding region and is required for stable incorporation of the Q module into the mature holoenzyme. Human recessive variants cause isolated complex I deficiency with Leigh syndrome and, in some families, hypertrophic cardiomyopathy, and cell studies show that loss destabilizes assembly intermediates rather than merely slowing turnover. That assembly-centric mechanism favors patient missense knockins for graded disease modeling, whereas a conditional null with neuronal or cardiomyocyte Cre establishes lineage-specific thresholds and permits inducible deletion in adults to bypass developmental compensation. Because complex I accessory subunits are single copy with no paralogous backup, residual activity reflects partial assembly. Match allele to endpoints that read assembly and function separately, including BN-PAGE with in-gel NADH dehydrogenase activity, permeabilized fiber respirometry, echocardiography, and brainstem lesion imaging.',
  Ndufa11:
    'Ndufa11 is the mouse ortholog of human NDUFA11 and encodes the B14.7 subunit, an integral membrane accessory component of complex I whose fold resembles the Tim17 and Tim22 family of translocase subunits, positioned in the distal membrane arm where it stabilizes the ND module and has been linked to transitions between assembly intermediates. Biallelic human variants produce isolated complex I deficiency with fatal infantile encephalocardiomyopathy or Leigh-like disease, and knockdown destabilizes the membrane arm while sparing the peripheral arm, a signature useful for interpreting mouse phenotypes. For that reason a knockin of the specific patient allele under study is often the most faithful model, while a conditional null answers the separate question of how much complex I a given tissue requires, with inducible deletion in adult heart or brain avoiding embryonic confounds. No compensating paralog exists for this subunit. Endpoints should include complex I assembly profiling, ND subunit immunoblotting, membrane potential measurement, cardiac function, and neurobehavioral testing.',
  Ndufa12:
    'Final maturation of complex I depends on Ndufa12, the mouse ortholog of human NDUFA12, which encodes the B17.2 subunit added late to the N module of complex I, capping the peripheral arm once the FMN and iron-sulfur chain are in place, and it must be distinguished from its paralogous assembly chaperone NDUFAF2, formerly B17.2L, which transiently occupies the same site during biogenesis. Human NDUFA12 loss causes Leigh syndrome and optic atrophy with isolated complex I deficiency, and cells lacking it retain a nearly complete but functionally impaired enzyme, indicating a role in the terminal capping step and in stabilizing electron flow toward quinone. This makes a null allele genuinely informative, since the resulting phenotype is a misfinished rather than absent complex, while patient knockins allow allele-specific severity comparisons. The NDUFAF2 relationship is the real caution here, since retained chaperone occupancy can blunt phenotypes. Align allele with endpoints including in-gel activity, NDUFAF2 retention assays, retinal ganglion cell counts, and brainstem lesion progression.',
  Ndufa13:
    'Ndufa13, the mouse ortholog of human NDUFA13, encodes GRIM-19, a membrane arm subunit essential for complex I assembly that additionally functions as a negative regulator of STAT3, binding it and restraining transcriptional output, which gives the locus a dual identity spanning bioenergetics and growth signaling. Recessive human variants cause complex I deficiency with encephalopathy and hypertrophic cardiomyopathy, whereas reduced expression in thyroid and other tumors correlates with STAT3 activation. Germline deletion is not survivable, so conditional alleles are required, and the choice of Cre determines which identity is interrogated: cardiomyocyte or neuronal deletion for bioenergetic failure, epithelial or immune deletion for STAT3-dependent phenotypes. Separation-of-function knockins that disrupt the STAT3 interaction surface while preserving assembly competence are the only clean way to distinguish the two roles and are the design most often needed. No paralog replaces this subunit. Match allele to endpoint, whether assembly and respirometry, STAT3 phosphorylation with target gene panels, cardiac hypertrophy, or tumor incidence.',
  Ndufa2:
    'Ndufa2 is the mouse ortholog of human NDUFA2 and encodes the B8 subunit, a small thioredoxin-like fold protein bound to the peripheral N module of complex I near the NDUFS1 iron-sulfur chain, where it stabilizes the NADH-oxidizing arm rather than participating directly in electron transfer. Homozygous human missense variants cause isolated complex I deficiency presenting as Leigh syndrome with hypertrophic cardiomyopathy, and patient fibroblasts show reduced holoenzyme with preserved subassemblies. Because human disease arises from hypomorphic missense rather than complete loss, knocking in the specific patient substitution yields a more interpretable model than a null, whereas a conditional null establishes the lower bound of complex I requirement in a chosen lineage, with tamoxifen-inducible Cre useful for adult-onset modeling. As with other single-copy accessory subunits, no paralog compensates. Choose endpoints that resolve assembly from catalysis, including BN-PAGE, complex I specific activity, NAD+ to NADH ratio, cardiac imaging, and metabolomic signatures of reductive stress.',
  Ndufa3:
    'Human NDUFA3 corresponds to mouse Ndufa3, encoding the small B9 subunit that inserts into the membrane arm of complex I close to the mtDNA-encoded ND1 subunit, where it participates in the earliest membrane arm assembly module and helps stabilize the region forming the quinone-binding interface. Compared with better characterized accessory subunits, human pathogenic variants are rare, so its biology rests largely on assembly studies showing that loss impairs formation of the ND1-containing intermediate and lowers mature holoenzyme, producing an isolated complex I defect without affecting other respiratory complexes. Given this, a constitutive or conditional null is the informative first allele, and inducible deletion in adult tissues distinguishes developmental from maintenance requirements, while a humanized knockin becomes valuable when candidate variants of uncertain significance need functional adjudication. No paralogous subunit substitutes. Pair the allele with endpoints tracking assembly intermediates by BN-PAGE and complexome profiling, alongside rotenone-sensitive oxygen consumption, ATP synthesis rates, and tissue markers of energetic stress.',
  Ndufa4:
    'Despite its name, Ndufa4, the mouse ortholog of human NDUFA4, encodes a subunit reassigned from complex I to complex IV, where it binds the cytochrome c oxidase monomer and prevents dimerization, acting as a bona fide fourteenth COX subunit that modulates catalytic efficiency. Human biallelic NDUFA4 variants cause Leigh syndrome with isolated complex IV deficiency, consistent with that reassignment and providing a rare case in which the gene name actively misdirects experimental design. Allele planning should therefore be built around complex IV endpoints, with a conditional null using neuronal or cardiac Cre to test tissue thresholds for COX activity and patient variant knockins to model the hypomorphic human state. Importantly, the paralog Ndufa4l2 is induced by HIF1A in hypoxic and tumor tissue and substitutes at the same site with altered kinetics, so compound or hypoxia-controlled designs are necessary to avoid masked phenotypes. Match allele to COX histochemistry, monomer to dimer ratios, respirometry, or Leigh-like lesion imaging.',
  Ndufa5:
    'Ndufa5 encodes the mouse ortholog of human NDUFA5, the B13 accessory subunit that binds the peripheral, matrix-exposed arm of complex I within the Q module, contacting the core subunits forming the quinone reduction chamber and contributing to stability of the hydrophilic arm rather than to redox catalysis. Human variants have been reported in complex I deficiency, and mouse knockdown or conditional loss reduces complex I amount with a mild phenotype in some tissues and severe encephalopathy in others, illustrating steep tissue-specific thresholds. The informative design is therefore a conditional null paired with several Cre drivers to map those thresholds, ideally including an inducible line to separate developmental from adult requirements, while a humanized knockin serves variant adjudication. No paralog substitutes, so residual respiration reflects incomplete recombination or stable assembly intermediates rather than compensation. Choose endpoints including complexome profiling, rotenone-sensitive respirometry in permeabilized tissue, hippocampal and cerebellar histology, and behavioral testing for progressive neurological decline.',
  Ndufa6:
    'The mouse Ndufa6 gene, ortholog of human NDUFA6, encodes the B14 subunit, a LYR-motif protein of complex I that pairs with the acyl carrier protein NDUFAB1 on the matrix face of the membrane arm and stabilizes the quinone-binding site through contacts that tune catalytic turnover, linking mitochondrial fatty acid synthesis and lipoylation status to complex I function. Structural and yeast work show that losing the LYR subunit specifically impairs quinone reduction while leaving much of the holoenzyme intact, and human variants cause complex I deficiency, so the resulting enzyme is kinetically crippled rather than absent. That distinction favors point mutant knockins at the NDUFAB1 interface for mechanistic work and conditional nulls for tissue threshold mapping. Because NDUFAB1 also partners the paralogous LYR subunit NDUFB9, interpret acyl carrier protein-dependent phenotypes with both subunits in view. Match allele to endpoint, using quinone site kinetics, in-gel complex I activity, lipoylated protein immunoblots, and organ-level respirometry.',
  Ndufa7:
    'Ndufa7 is the mouse ortholog of human NDUFA7 and encodes the B14.5a subunit, an accessory protein attached to the N module of complex I on the matrix side, incorporated during late assembly of the NADH-oxidizing arm and contributing to holoenzyme stability; the subunit carries post-translational modification and appears to influence assembly efficiency more than catalytic rate. Reported human variants associate with complex I deficiency and neurodevelopmental presentations, but the allelic series is small, so mouse genetics is currently the primary source of physiological information. A conditional null is therefore the first-choice allele, deployed with neuronal Cre for encephalopathy endpoints and with an inducible driver to test maintenance requirements in mature tissue, while humanized knockins become the appropriate tool once specific variants of uncertain significance require functional testing. No paralog compensates for its loss. Align allele with endpoints including complexome profiling of N module intermediates, NADH dehydrogenase activity, brain lactate quantification, and longitudinal motor phenotyping.',
  Ndufa8:
    'Redox-gated import governs Ndufa8, the mouse ortholog of human NDUFA8, which encodes the PGIV subunit, an intermembrane space-facing accessory protein of complex I distinguished by twin CX9C motifs that must be oxidized by the MIA40 and CHCHD4 disulfide relay for stable import and folding, coupling its biogenesis to intermembrane space redox state. Biallelic human variants cause isolated complex I deficiency with Leigh-like encephalopathy and cardiomyopathy, and loss destabilizes the membrane arm. That import requirement creates a distinctive allele opportunity: cysteine substitution knockins test relay dependence directly, whereas a conditional null with neuronal or cardiomyocyte Cre measures tissue-specific complex I thresholds and a humanized allele supports variant adjudication. Note that NDUFB7 and NDUFB10 share the same CHCH import logic, so relay perturbations affect several subunits and effects should not be assigned to one without controls. Choose endpoints reading import and assembly separately, including redox-state gels, BN-PAGE intermediates, respirometry, and cardiac and neurological phenotyping.',
  Ndufa9:
    'Ndufa9, ortholog of human NDUFA9, encodes the 39 kDa accessory subunit of complex I, a short-chain dehydrogenase and reductase family fold that binds NADPH as a structural cofactor and packs against the core subunits forming the quinone chamber, stabilizing the junction between peripheral and membrane arms during assembly. Human biallelic variants cause severe neonatal lactic acidosis, Leigh syndrome or fatal infantile cardiomyopathy, and cell models show loss of holoenzyme with accumulation of Q module intermediates, indicating an assembly rather than catalytic mechanism. Because the human alleles are largely hypomorphic missense affecting NADPH binding or protein stability, knocking in the specific residue changes gives a graded, interpretable model, whereas a conditional null establishes maximal tissue dependence and is best deployed with inducible Cre in heart or brain. No paralogous subunit compensates. Match allele to endpoint, using complexome profiling, NADPH binding assays on purified enzyme, respirometry, blood and cerebrospinal fluid lactate, and cardiac imaging.',
  Ndufb1:
    'Human NDUFB1 has as its mouse ortholog Ndufb1, encoding MNLL, one of the smallest complex I subunits, a single-pass membrane protein located in the distal region of the membrane arm where it forms part of the ND module shell surrounding the proton-pumping core subunits ND4 and ND5. Its position implies a role in stabilizing the distal arm and supporting conformational coupling between quinone reduction and proton translocation, and knockdown reduces mature complex I with accumulation of incomplete intermediates. Pathogenic human variants remain scarce, so mouse alleles provide the primary functional evidence, and a conditional null is the pragmatic first design, with inducible deletion distinguishing assembly from maintenance and tissue-specific Cre lines defining thresholds in heart, muscle and brain. No paralog exists to compensate. Pair the allele with endpoints reading distal arm integrity directly, including complexome profiling, in-gel NADH dehydrogenase activity, proton pumping and membrane potential measurement, and ATP synthesis rates in isolated mitochondria.',
  Ndufb10:
    'Ndufb10 is the mouse ortholog of human NDUFB10 and encodes the PDSW subunit of complex I, an intermembrane space-exposed component of the distal membrane arm whose import depends on cysteine oxidation by the CHCHD4 and MIA40 relay, a step that becomes rate limiting under reductive or hypoxic conditions. Human biallelic variants, including one disrupting a relay cysteine, cause complex I deficiency with fatal infantile cardiomyopathy and lactic acidosis, directly connecting import chemistry to disease. Allele planning should exploit this: cysteine knockins isolate the import defect from loss of protein, a conditional null with Myh6-Cre or Ckmm-Cre quantifies cardiac and muscle thresholds, and humanization enables variant adjudication. Because NDUFA8 and NDUFB7 use the same relay, do not attribute relay-wide phenotypes to this subunit without parallel controls. Match the allele to endpoints including redox-resolved import assays, BN-PAGE assembly profiles, respirometry on permeabilized cardiac fibers, echocardiography, and circulating lactate and acylcarnitine profiling.',
  Ndufb11:
    'Ndufb11 encodes the mouse ortholog of human NDUFB11, the ESSS subunit, an X-linked single-pass membrane protein of the distal complex I membrane arm required for ND module assembly and for stability of the mature holoenzyme. The locus carries two distinct human phenotypes: hemizygous missense variants cause isolated complex I deficiency with encephalopathy or histiocytoid cardiomyopathy, while larger deletions in females cause microphthalmia with linear skin defects, a phenotype shared with contiguous HCCS loss, so allele architecture at this locus dictates presentation. Design should reflect that split, using patient missense knockins for bioenergetic disease modeling and defined deletion alleles to interrogate the X-linked developmental syndrome, with X-inactivation mosaicism in females treated as a central design parameter rather than an afterthought. There is no paralogous subunit. Choose endpoints accordingly, including complex I assembly and activity assays, cardiac histology and function, ocular and skin phenotyping, and allele-specific expression analysis to quantify skewing.',
  Ndufb2:
    'The AGGG subunit of complex I is encoded by Ndufb2, ortholog of human NDUFB2, a very small membrane protein positioned on the distal face of the membrane arm within the ND module, where structural studies place it against the ND4 and ND5 proton-pumping subunits and where its loss reduces mature holoenzyme without disturbing complexes II through V. Because reported human pathogenic variants are limited, the physiological requirement in mammals is best established genetically, and a conditional null crossed to tissue-restricted Cre lines is the appropriate primary design, with tamoxifen-inducible deletion separating a developmental assembly requirement from ongoing turnover in mature mitochondria. Humanized knockins remain useful for adjudicating variants of uncertain significance surfaced by clinical sequencing. No paralogous subunit provides backup, so residual activity indicates surviving unrecombined cells or stable intermediates rather than compensation. Match allele to endpoint, using complexome profiling, in-gel activity, rotenone-sensitive respiration in permeabilized fibers, and tissue NAD+ to NADH and lactate measurement.',
  Ndufb3:
    'Ndufb3, the mouse ortholog of human NDUFB3, encodes the B12 subunit of complex I, a small membrane arm protein of the distal ND module whose incorporation is required for full holoenzyme assembly and whose mature form carries histidine hydroxylation, a modification used as a marker of assembly state. Biallelic human variants cause isolated complex I deficiency with a notably variable course, ranging from lethal infantile lactic acidosis to survival with growth restriction and relatively preserved cognition, and residual activity in patient fibroblasts is often temperature sensitive. That variability makes patient-specific knockins substantially more informative than a null, since severity tracks residual assembly, while a conditional null defines the tissue-specific floor of complex I requirement. No paralog substitutes for the subunit. Pair the allele with endpoints capturing the temperature and stress dependence of the human phenotype, including respirometry at permissive and restrictive temperatures, BN-PAGE assembly profiles, growth trajectory measurement, and lactate response to catabolic challenge.',
  Ndufb4:
    'Mouse Ndufb4, ortholog of human NDUFB4, encodes the B15 subunit of complex I, an integral membrane accessory protein of the distal ND module that contacts the proton-pumping core and contributes to membrane arm stability, with complexome studies placing its incorporation in the later stages of biogenesis alongside other B-type subunits. Reduced NDUFB4 has been reported in tumors and in models of mitochondrial dysfunction, and knockdown lowers mature complex I with accumulation of subassemblies rather than causing a diffuse OXPHOS defect. With few defined human pathogenic alleles, mouse genetics carries the burden of proof, so a conditional null is the correct first allele, with inducible deletion in adult heart, muscle or neurons distinguishing assembly from maintenance requirements and mapping tissue thresholds. No paralog compensates for its loss. Align allele with endpoints including BN-PAGE and complexome profiling, in-gel NADH dehydrogenase activity, respirometry on permeabilized tissue, membrane potential measurement, and organ-level functional testing.',
  Ndufb5:
    'Ndufb5 is the mouse ortholog of human NDUFB5 and encodes the SGDH subunit, a single-pass membrane protein of the complex I membrane arm whose transmembrane helix packs within the ND module while its N-terminal region extends into the matrix, positioning it to stabilize the distal arm during assembly. Loss reduces mature complex I and increases the pool of incomplete intermediates, giving an isolated complex I deficiency signature, and reduced expression has been reported in metabolic and neurodegenerative contexts although a defined human allelic series remains limited. Under those conditions a conditional null is the informative design, with tissue-restricted Cre mapping thresholds in high-demand tissues and inducible Cre separating developmental from maintenance requirements, while a humanized knockin supports functional adjudication of newly identified variants. No paralogous subunit substitutes. Match the allele to endpoints distinguishing quantity from quality of enzyme, including complexome profiling, complex I activity normalized to citrate synthase, respirometry, and superoxide production during reverse electron transport.',
  Ndufb6:
    'Human NDUFB6 corresponds to mouse Ndufb6, encoding the B17 subunit, an accessory membrane arm component of complex I added during distal ND module assembly, which has drawn attention because human NDUFB6 expression in skeletal muscle declines with age and is modulated by promoter DNA methylation in an insulin sensitivity dependent manner, linking the locus to type 2 diabetes risk through epigenetic regulation rather than coding mutation. That distinction shapes design: a conditional null with Ckmm-Cre tests whether reduced subunit dosage suffices to impair muscle oxidative capacity and insulin action, whereas a humanized allele carrying the human promoter with its methylation-sensitive elements is the only way to model the regulatory mechanism itself. Hypomorphic or graded-expression alleles may mirror the modest reductions seen in patients better than a complete null. No paralog compensates. Choose endpoints accordingly, including hyperinsulinemic clamp, muscle respirometry and fiber typing, complex I assembly analysis, and promoter methylation correlated with expression and age.',
  Ndufb7:
    'Ndufb7 encodes the mouse ortholog of human NDUFB7, the B18 subunit of complex I, an intermembrane space-facing protein with a twin CX9C motif that requires oxidative folding by the CHCHD4 and MIA40 disulfide relay and sits in the distal membrane arm supporting ND module assembly. Because import and folding are redox coupled, subunit abundance is sensitive to intermembrane space thiol state and to hypoxia, and reported human variants produce isolated complex I deficiency. The clean experimental fork lies between cysteine substitution knockins, which test relay dependence and folding without deleting the protein, and a conditional null, which measures tissue-specific requirement for complex I, with inducible Cre preferable when adult maintenance is the question. NDUFA8 and NDUFB10 use the same relay, so ascribing a phenotype to a single CHCH subunit requires parallel controls. Match allele to endpoints including thiol redox gels, BN-PAGE assembly intermediates, respirometry, and hypoxia challenge with complex I quantification.',
  Ndufb8:
    'Ndufb8, ortholog of human NDUFB8, encodes the ASHI subunit of complex I, a membrane arm accessory protein of the distal ND module whose abundance is unusually informative experimentally, since NDUFB8 immunolabeling paired with SDHA forms the standard quadruple immunofluorescence readout used to detect complex I deficiency in patient and mouse tissue at single-cell resolution. Biallelic human variants cause complex I deficiency with Leigh-like encephalopathy, and loss destabilizes the holoenzyme while subassemblies persist. This dual role as structural subunit and diagnostic marker has a practical consequence: any allele that removes or alters the epitope invalidates the very assay commonly used to phenotype it, so tagged or humanized knockins must be designed with antibody epitopes deliberately preserved or matched. A conditional null with neuronal or muscle Cre remains the tool for threshold mapping. Align allele with endpoints including quadruple immunofluorescence, BN-PAGE with in-gel activity, respirometry, and neuropathological lesion scoring.',
  Ndufb9:
    'The mouse gene Ndufb9, ortholog of human NDUFB9, encodes the B22 subunit, a LYR-motif accessory protein of complex I that binds the mitochondrial acyl carrier protein NDUFAB1 on the matrix face of the membrane arm, tying complex I assembly to mitochondrial fatty acid synthesis and lipoic acid supply. Human biallelic variants cause complex I deficiency with encephalomyopathy, reduced NDUFB9 has been reported to alter mitochondrial function in tumor models, and structural data show that the LYR and acyl carrier protein pair stabilizes the membrane arm rather than participating in electron transfer. Interface point mutants that disrupt NDUFAB1 binding without removing the protein are therefore the most mechanistically informative allele, with a conditional null reserved for threshold mapping in brain, heart or muscle. Because NDUFA6 is the other NDUFAB1-binding LYR subunit, phenotypes involving acyl carrier protein biology should be interpreted with both in view. Endpoints should include lipoylation immunoblots, complexome profiling, respirometry, and neuromuscular phenotyping.',
  Ndufs1:
    'Ndufs1 is the mouse ortholog of human NDUFS1 and encodes the 75 kDa core subunit of complex I, the largest component of the N module, which carries the N1b, N4 and N5 iron-sulfur clusters relaying electrons from FMN-bound NADH toward the quinone site and thereby forms the entry point of the entire respiratory chain. The subunit is also a caspase-3 substrate during apoptosis, and its cleavage contributes to loss of respiratory function and ROS generation in dying cells, while biallelic human variants cause severe complex I deficiency with Leigh syndrome, leukoencephalopathy and early lethality. Because it is a core catalytic subunit, complete loss is not tolerated, making conditional nulls with tissue-restricted or inducible Cre the practical route and cluster-ligating cysteine knockins the way to dissect electron transfer from assembly. Caspase cleavage resistant knockins address the apoptotic role specifically. Match allele to endpoint, using electron paramagnetic resonance of clusters, reverse electron transport ROS, respirometry, and brain lesion imaging.',
  Ndufs2:
    'Encoding the mouse ortholog of human NDUFS2, Ndufs2 specifies the 49 kDa core subunit that, together with NDUFS7, NDUFS3 and ND1, builds the quinone-binding chamber of complex I, shaping the terminal N2 cluster environment and coupling quinone reduction to the conformational changes that drive proton translocation in the membrane arm. Biallelic human variants cause Leigh syndrome, hypertrophic cardiomyopathy and optic atrophy with isolated complex I deficiency, and structural work shows that Q-site mutations can uncouple electron transfer from pumping rather than simply reducing enzyme amount. That mechanism argues for patient missense knockins when the goal is to model partial, uncoupled activity, and for conditional nulls with cardiomyocyte, neuronal or retinal Cre when the question is tissue tolerance of complex I loss, since a germline null is not viable. No paralog substitutes for a core subunit. Choose endpoints separating coupling from capacity, including proton pumping and membrane potential, quinone site inhibitor sensitivity, respirometry, echocardiography, and retinal ganglion cell quantification.',
  Ndufs3:
    'Complex I assembly begins with the Q module, and Ndufs3, the mouse ortholog of human NDUFS3, encodes one of its core subunits, packing against NDUFS2, NDUFS7 and NDUFS8 to help shape the ubiquinone-binding channel at the junction of the peripheral and membrane arms. Because this subunit nucleates the Q module during stepwise assembly, its loss destabilizes the entire hydrophilic arm rather than producing a partially active enzyme, collapsing NADH:ubiquinone oxidoreductase activity and forcing NADH accumulation that stalls TCA cycle flux. Patient alleles are typically hypomorphic missense changes presenting as Leigh syndrome, so a knockin of the orthologous residue models residual activity far better than deletion, while a floxed conditional null suits tissue-restricted work where constitutive loss is not tolerated. No paralog substitutes for a core subunit, so genetic buffering is not a rescue route. Match the allele to endpoint: knockin for respiratory chain kinetics, conditional null with a neuronal or muscle Cre for tissue-autonomous bioenergetic failure.',
  Ndufs4:
    'Ndufs4, the mouse ortholog of human NDUFS4, encodes an accessory subunit required for final assembly and stabilization of the complex I N module, the flavin-containing NADH oxidation domain, and it is a substrate for PKA-dependent phosphorylation that tunes holoenzyme stability. Loss does not abolish the enzyme outright but leaves a stalled subcomplex lacking NDUFV1, NDUFV2 and NDUFS6, so NADH oxidation fails while membrane arm subunits persist. Constitutive nulls are viable at birth and then develop progressive ataxia, breathing abnormalities and brainstem and cerebellar lesions, giving one of the most faithful Leigh syndrome models available and a proven platform for interventions such as mTOR inhibition or chronic hypoxia. Conditional floxed alleles let the neuron versus glia versus muscle question be separated, since whole-body loss confounds cell-autonomous interpretation. Choose the conditional null with a defined neuronal Cre for lesion mapping, and reserve the germline null for survival and therapeutic response endpoints.',
  Ndufs5:
    'Encoding a small accessory subunit of the complex I ND1 and Q modules, Ndufs5 is the mouse ortholog of human NDUFS5 and carries a twin CX9C motif, meaning the protein is imported through the MIA40 and CHCHD4 disulfide relay of the intermembrane space before docking onto the peripheral arm near the ubiquinone channel. Because this subunit class stabilizes rather than catalyzes, depletion yields partially assembled complex I with reduced steady-state levels and diminished NADH:ubiquinone oxidoreductase flux rather than an outright null enzyme, which is why patient variants segregate with mitochondrial encephalomyopathy of variable severity. A conditional null therefore addresses tissue-specific assembly thresholds, whereas a patient-matched missense knockin preserves the hypomorphic biology driving later onset, and humanization supports reagent development. Since no paralog replaces this subunit, do not expect genetic buffering. Align the allele with the endpoint, using an inducible Cre when adult-onset respiratory decline rather than developmental failure is the readout.',
  Ndufs6:
    'Ndufs6, the mouse ortholog of human NDUFS6, specifies an accessory subunit of the complex I N module that adopts a zinc-binding fold and packs against NDUFV1 and NDUFV2 to lock the NADH-oxidizing flavoprotein head onto the peripheral arm. Reduction of this subunit destabilizes the N module, restricts electron entry at FMN, and raises superoxide production, and hypomorphic gene-trap mice retaining only residual transcript develop progressive dilated cardiomyopathy alongside lactic acidosis, mirroring the fatal neonatal presentations reported for human loss-of-function alleles. That phenotype makes graded expression, not binary deletion, the informative design: a hypomorphic or patient-matched splice-site knockin reproduces dose-dependent cardiac failure, while a floxed conditional null isolates cardiomyocyte-autonomous from systemic effects. There is no redundant paralog for this subunit, so single-locus targeting is sufficient. Pair the conditional allele with a cardiomyocyte Cre when echocardiography and mitochondrial respirometry define the primary readouts.',
  Ndufs7:
    'Ndufs7, ortholog of human NDUFS7, encodes the PSST core subunit of complex I, which coordinates the terminal [4Fe-4S] cluster N2 and, together with NDUFS2, NDUFS8 and NDUFS3, forms the walls of the ubiquinone-binding channel where electron transfer is coupled to proton pumping. Because N2 sits immediately upstream of quinone reduction, missense substitutions near cluster-ligating cysteines slow turnover and uncouple electron flow from proton translocation, generating the Leigh syndrome and isolated complex I deficiency phenotypes seen in patients. Complete loss of a core catalytic subunit is expected to be developmentally catastrophic, so a conditional floxed allele is the practical route to tissue-restricted ablation, while a residue-matched knockin retains partial activity and models the actual clinical hypomorphic state. No paralog substitutes for a core subunit. Select the knockin for redox and proton-pumping kinetics, and the conditional null with a region-specific Cre for neuropathology and lesion progression.',
  Ndufs8:
    'Ndufs8 is the mouse ortholog of human NDUFS8 and encodes the TYKY core subunit, supplying two [4Fe-4S] clusters, N6a and N6b, that form the penultimate relay carrying electrons from the flavin site toward cluster N2 at the quinone-binding pocket of complex I. Disruption of the ferredoxin-like cysteine motifs breaks that wire, so patient missense alleles produce isolated complex I deficiency with Leigh syndrome, leukodystrophy and lactic acidemia while leaving membrane arm assembly comparatively intact. Since the subunit is catalytically essential, plan on conditional targeting: a floxed allele crossed to a tissue Cre distinguishes neuronal from cardiac or hepatic consequences, whereas a knockin of the human-equivalent substitution reproduces graded residual electron transfer and the clinical variability observed. Nothing in the mouse genome compensates for a core iron-sulfur subunit, so single-gene targeting is definitive. Choose alleles according to whether respirometry, ROS output or brainstem histopathology is the endpoint, and validate Cre penetrance directly.',
  Ndufv1:
    'Ndufv1, the mouse ortholog of human NDUFV1, encodes the 51 kDa flavoprotein that binds FMN and the [4Fe-4S] cluster N3 at the tip of the complex I N module, making it the physical entry point where NADH delivers a hydride and electrons begin their traverse toward ubiquinone. That same flavin site is the principal source of superoxide during reverse electron transport, so hypomorphic variants shift both ATP output and mitochondrial ROS, producing Leigh syndrome, leukoencephalopathy with macrocystic degeneration and myoclonic epilepsy in patients. Design accordingly: a conditional null tests the requirement for NADH oxidation in a defined lineage, while a patient-matched missense knockin preserves partial flavin binding and models progressive rather than acute failure. No functional paralog exists at this position. Match the allele to whether respirometry, oxidative damage or white matter pathology is the readout, and use an inducible Cre to bypass developmental compromise when studying adult onset.',
  Ndufv2:
    'The mouse ortholog of human NDUFV2, Ndufv2 encodes the 24 kDa flavoprotein subunit of complex I that coordinates the binuclear [2Fe-2S] cluster N1a adjacent to FMN, positioning it as a redox modulator of flavin-site chemistry and superoxide generation rather than a conductor on the main path to ubiquinone. Loss of this subunit destabilizes the N module and yields assembly intermediates lacking NDUFV1 and NDUFS4, so patient splice and missense alleles present with hypertrophic cardiomyopathy, encephalomyopathy and early lethality. Because germline nulls are expected to be non-viable, floxed conditional alleles are the workable format for asking where NADH oxidation is rate limiting, with cardiac muscle the highest-yield tissue given the human phenotype, while a patient-matched knockin sustains partial assembly and permits longitudinal study. There is no substituting paralog. Pair a cardiomyocyte or neuronal Cre with in-gel complex I activity and supercomplex integrity as primary molecular readouts.',
  Ndufv3:
    'Ndufv3 is the mouse ortholog of human NDUFV3 and encodes an accessory subunit of the complex I N module that exists as two products, a short canonical form and a longer isoform generated by alternative splicing, both docking near the NDUFV1 and NDUFV2 flavoprotein core. Because the long isoform is enriched in heart and other oxidative tissues and appears to tune holoenzyme stability and supercomplex association rather than carry electrons, the underlying biology is one of isoform stoichiometry, not simple catalytic presence or absence. That makes isoform-selective engineering the informative design: an exon-specific deletion removing only the long form tests tissue-specific tuning, a full conditional null tests whether the subunit is required for N module retention at all, and humanization supports isoform-resolved proteomics. No paralog covers this locus. Choose the isoform-selective allele for supercomplex and respirometry endpoints, and pair conditional nulls with cardiac or neuronal Cre lines to interpret tissue specificity.',
  Nf1:
    'Neurofibromin, encoded by mouse Nf1 in orthology with human NF1, is a large cytoplasmic protein whose central GAP-related domain accelerates GTP hydrolysis on RAS, making it the principal brake on RAS-RAF-MEK-ERK and, indirectly, on mTORC1 output; flanking regions mediate SPRED1-dependent membrane recruitment and adenylyl cyclase modulation. Germline heterozygous truncations cause neurofibromatosis type 1, and somatic second hits in Schwann cell precursors, astrocytes, or myeloid progenitors generate plexiform neurofibroma, malignant peripheral nerve sheath tumor, optic pathway glioma, and juvenile myelomonocytic leukemia, while biallelic inactivation also recurs in glioblastoma and melanoma. Because germline nulls die near midgestation from cardiac outflow tract defects, conditional nulls are standard, with Dhh-cre or Krox20-cre for Schwann cell lineages and Gfap-cre for glioma, typically on an Nf1 heterozygous background to reproduce haploinsufficient stroma. Match allele class to endpoint: nulls for tumor initiation and MEK inhibitor response, humanized or specific missense knockins for variant interpretation.',
  Nf2:
    'Merlin, the product of mouse Nf2 and ortholog of human NF2, is a FERM domain cytoskeletal adaptor that couples cortical actin and adherens junctions to growth control, restraining the Hippo pathway by promoting LATS1 and LATS2 activation and YAP or TAZ phosphorylation, and separately entering the nucleus to inhibit the CRL4-DCAF1 E3 ligase. Biallelic inactivation underlies familial and sporadic schwannoma, meningioma, ependymoma, and a large fraction of malignant pleural mesothelioma, with tumorigenesis proceeding through unrestrained YAP-TEAD transcription rather than kinase hyperactivation. Germline nulls fail at gastrulation because of extraembryonic defects, so conditional nulls are mandatory: P0-cre or Postn-cre for Schwann cells, Wt1-cre for mesothelium, each yielding distinct tumor spectra. Compensation is limited, since the ezrin, radixin, and moesin family shares the FERM fold without recapitulating growth suppression. Choose nulls for tumor initiation and TEAD inhibitor sensitivity, and consider humanized alleles where clinical missense variants must be functionally classified.',
  Nfkb1:
    'Nfkb1, the mouse ortholog of human NFKB1, encodes p105, which is co-translationally and post-translationally processed to the p50 DNA-binding subunit; the precursor contains a Rel homology domain plus a carboxy-terminal ankyrin repeat region that functions as its own inhibitor, sequestering RelA and c-Rel until stimulus-dependent IKK phosphorylation and betaTrCP-mediated degradation of the ankyrin segment release active dimers. Because p50 lacks a transactivation domain, p50 homodimers act as repressors at kappaB sites, so the gene contributes both activating and silencing functions, and p105 additionally scaffolds Map3k8 to link NF-kB and Erk signaling. Homozygous nulls are viable with defective B cell responses, impaired isotype switching, and heightened infection susceptibility, making germline alleles tractable. A nonprocessable p105 knockin separates precursor inhibitor function from p50 output, conditional alleles restrict loss to a lineage, and humanization supports reagent matching. Rela, Relb, c-Rel, and Nfkb2 overlap at target promoters, so compound genetics is often necessary.',
  Nfkb2:
    'Nfkb2, the mouse ortholog of human NFKB2, encodes p100, the precursor whose processing to p52 is the committed step of noncanonical NF-kB signaling: engagement of lymphotoxin beta receptor, CD40, BAFF receptor, or RANK stabilizes Map3k14 by relieving Traf3-dependent degradation, and the resulting NIK and IKK1 phosphorylation of carboxy-terminal serines recruits betaTrCP to trim the ankyrin repeats, releasing p52 and RelB dimers that drive chemokine and stromal organizer programs. Human carboxy-terminal truncations cause common variable immunodeficiency and DAVID syndrome by producing unprocessable, dominant-inhibitory p100. Nulls are viable but show disorganized splenic architecture, absent germinal centers, and reduced marginal zone B cells, so germline alleles are usable while conditional deletion isolates stromal from hematopoietic contributions. Allele class matters sharply here: a nonprocessable serine-mutant knockin models dominant human disease, a constitutive p52 knockin models pathway hyperactivation, and Relb compound alleles address partner-specific output.',
  Nfkbia:
    'Nfkbia is the mouse ortholog of human NFKBIA and encodes IkB alpha, whose six ankyrin repeats clamp the nuclear localization sequence of RelA and cRel containing NF-kB dimers, holding them cytoplasmic until IKK beta phosphorylates Ser32 and Ser36, triggering beta-TrCP mediated ubiquitination and proteasomal degradation, and whose own NF-kB driven resynthesis creates the negative feedback that generates oscillatory signaling. Germline nulls die within days of birth with severe dermatitis, granulopoiesis, and runting, making conditional alleles mandatory for adult work, while human heterozygous mutations at Ser32 or Ser36 act as hypermorphs that resist degradation and cause ectodermal dysplasia with immunodeficiency, a phenotype no null reproduces. The design fork is unusually explicit: floxed null for tissue specific NF-kB derepression, S32I or S36A knockin for the human disease and for pathway blockade, and inducible super-repressor expression for acute inhibition. Because Nfkbib and Nfkbie provide partial buffering, expect graded rather than binary loss of control.',
  Nfkbib:
    'Encoding IkB beta, Nfkbib corresponds to human NFKBIB and retains the ankyrin repeat architecture of IkB alpha but differs in the kinetics that matter most, since it is degraded slowly after IKK dependent phosphorylation and resynthesized without strong NF-kB feedback, so it converts transient stimulation into persistent nuclear NF-kB rather than the oscillations imposed by IkB alpha. Newly synthesized hypophosphorylated IkB beta can also chaperone RelA and cRel dimers into the nucleus in a form that binds kB elements while resisting IkB alpha mediated termination, which is how it sustains late phase transcription of Tnf and other secondary response genes in stimulated macrophages. Mouse nulls are viable with selectively reduced TNF production, consistent with a modulatory rather than gatekeeping role. Given real buffering by Nfkbia and Nfkbie, compound conditional alleles are usually necessary to expose kinetic phenotypes, and myeloid restricted Cre drivers are the correct pairing when sustained inflammatory output is the endpoint.',
  Nlgn1:
    'Nlgn1, the mouse ortholog of human NLGN1, encodes neuroligin-1, a postsynaptic cell adhesion molecule with an extracellular cholinesterase-like domain that binds presynaptic neurexins in a calcium-dependent manner and a short cytoplasmic tail whose PDZ-binding motif recruits PSD-95 and whose gephyrin-independent interactions organize the excitatory postsynaptic density. Neuroligin-1 is targeted specifically to glutamatergic synapses by inclusion of splice site B, which biases binding toward beta-neurexins lacking splice site 4, and it preferentially controls NMDA receptor content, so deletion reduces the NMDA to AMPA ratio and impairs long-term potentiation and spatial memory without changing synapse number substantially. The protein is also shed by matrix metalloproteinase 9 in an activity-dependent manner, a step required for plasticity. Conditional nulls with region-restricted Cre drivers assign these effects to defined circuits, while splice site or PDZ motif knockins separate adhesion from scaffolding. Nlgn2 and Nlgn3 occupy distinct synapse classes and only partially buffer loss, so measure receptor composition directly.',
  Nlgn2:
    'Encoding neuroligin-2, Nlgn2 is the mouse ortholog of human NLGN2 and is the only neuroligin restricted to inhibitory synapses, where its extracellular cholinesterase-like domain engages neurexins and MDGA1 while its cytoplasmic tail binds gephyrin and activates collybistin, converting an autoinhibited guanine nucleotide exchange factor into an active one that drives PIP3-dependent gephyrin clustering and GABA-A receptor accumulation. This makes neuroligin-2 the assembly hub that specifies the inhibitory postsynaptic apparatus rather than a generic adhesion molecule. Nulls are viable but show reduced inhibitory transmission, anxiety-like behavior, and altered excitation to inhibition balance, and human NLGN2 variants are associated with schizophrenia and autism spectrum phenotypes. The allele fork is therefore between conditional deletion, which tests circuit-specific requirement for inhibitory synapse assembly using Gad2-Cre or Pvalb-Cre, and collybistin-binding or MDGA-interface knockins, which dissect the mechanism. Nlgn1 and Nlgn3 cannot substitute at inhibitory contacts, so compensation is limited and phenotypes are typically penetrant.',
  Nlgn3:
    'Nlgn3, the mouse ortholog of X-linked human NLGN3, encodes neuroligin-3, the only neuroligin found at both excitatory and inhibitory synapses, where its cholinesterase-like ectodomain binds neurexins and its cytoplasmic tail couples to PSD-95 or gephyrin scaffolds depending on synapse class. Neuroligin-3 is also required for tonic endocannabinoid signaling at hippocampal inhibitory synapses, and its ectodomain is cleaved by ADAM10 in an activity-dependent manner, with the shed fragment acting as a mitogen for glioma cells, a striking non-synaptic function. The autism-associated R451C substitution in the cholinesterase-like domain causes protein retention in the endoplasmic reticulum yet behaves as a gain of function in vivo, increasing inhibitory transmission and producing social behavior deficits, whereas the null shows a distinct and partly opposite profile, so knockin and deletion answer genuinely different questions. Because Nlgn1 and Nlgn2 occupy overlapping synapse classes, conditional alleles paired with cell-type Cre drivers and synapse-resolved recordings are the appropriate design.',
  Nlgn4x:
    'Nlgn4x labels the mouse counterpart of human NLGN4X, the X-linked neuroligin most strongly implicated in autism spectrum disorder and intellectual disability through nonsense, frameshift, and missense mutations such as R87W and D396X that disrupt folding and surface delivery. A species caveat dominates model design here: the mouse gene, often annotated Nlgn4 or Nlgn4-like, shares only roughly sixty percent amino acid identity with human NLGN4X, maps to a different chromosomal context, and shows a divergent expression pattern, so the mouse protein is a poor proxy for human biology. Where studied, the mouse protein localizes to glycinergic and GABAergic synapses, notably in retina and brainstem, and nulls show reduced social interaction and altered vocalization. Consequently full-locus humanization that replaces the coding region with human NLGN4X, rather than conditional deletion of the divergent mouse gene, is the design that supports patient variant knockin, antibody work, and interpretation of behavioral endpoints against human genetics.',
  Nlgn4y:
    'Human NLGN4Y is the Y-linked paralog of NLGN4X, arising from the ancestral gene pair on the sex chromosomes and retained in the male-specific region, and Nlgn4y in mouse annotation reflects that relationship rather than a functionally equivalent locus, since rodents lack a true one-to-one ortholog and the mouse Y-linked gene content diverges sharply from human. In humans the protein is expressed at low levels in brain and, because of amino acid substitutions relative to NLGN4X, shows impaired surface trafficking and reduced ability to induce synapse formation, which has been proposed to leave males without a functional backup when NLGN4X is mutated, contributing to the male bias of associated autism phenotypes. Given this, deletion of the mouse locus is unlikely to be informative, and humanization that introduces the human NLGN4Y coding sequence alongside a humanized NLGN4X allele is the design that actually tests the failed-compensation hypothesis, with synapse induction and social behavior as the matched endpoints.',
  Nlrp1:
    'Human NLRP1 encodes a keratinocyte and epithelial inflammasome sensor with a pyrin domain, NACHT, leucine rich repeats, a function to find domain, and a C-terminal CARD, activated by a degradation based mechanism in which autoproteolysis within the FIIND generates a noncovalently held CT fragment that is liberated when the N-terminal portion is ubiquitinated and destroyed, freeing CARD filaments to recruit ASC and caspase-1. Triggers include DPP9 displacement by Val-boroPro, ZAKalpha and p38 signaling after ribotoxic or ultraviolet stress, and direct cleavage by enteroviral 3C proteases, and gain-of-function variants cause multiple self healing palmoplantar carcinoma and NLRP1 associated autoinflammation with arthritis and dyskeratosis. Mouse biology diverges genuinely, since the Nlrp1a, Nlrp1b, and Nlrp1c paralogs differ in domain composition and strain polymorphism, with Nlrp1b cleaved by anthrax lethal factor. Humanization of the locus is therefore the informative allele for translational work, while paralog specific conditional nulls address murine pathway questions.',
  Nlrp3:
    'Nlrp3 is the mouse ortholog of human NLRP3 and encodes a pyrin domain, NACHT, leucine rich repeat sensor that assembles the best characterized inflammasome, licensed by deubiquitination through BRCC3, phosphorylation changes at serine and tyrosine residues, and NEK7 binding, then recruited to phosphatidylinositol 4-phosphate rich dispersed trans-Golgi membranes where it nucleates ASC filaments and activates caspase-1 to mature interleukin 1 beta and interleukin 18 and cleave gasdermin D. Activation is indirect, reading potassium efflux, lysosomal damage, and mitochondrial stress rather than a defined ligand, and gain-of-function mutations cause cryopyrin associated periodic syndromes, with knockin alleles such as R258W reproducing human R260W disease. Design accordingly: conditional nulls test requirement, inducible periodic syndrome knockins are essential because constitutive activation is lethal in neonates, and humanization supports MCC950-class inhibitor programs. Because Nlrp1b, Nlrc4, Aim2, and pyrin drive caspase-1 independently, attribute phenotypes with sensor specific alleles rather than Casp1 deletion.',
  Nodal:
    'Nodal, the mouse ortholog of human NODAL, encodes a TGF-beta superfamily ligand unique in requiring an EGF-CFC coreceptor, Cripto or Cryptic, to assemble ActRIIA or ActRIIB with ALK4 and phosphorylate SMAD2 and SMAD3 for transcription with SMAD4, FOXH1, and MIXL1, and whose signaling range is set by convertase processing through Furin and PACE4 and by the antagonists Lefty1, Lefty2, and Cerberus. It drives primitive streak formation, mesendoderm specification, node function, and left-right asymmetry through an autoregulatory asymmetric enhancer, and human variants cause heterotaxy with transposition of the great arteries. Nulls arrest before streak formation, so conditional and hypomorphic alleles, or deletion of the asymmetric enhancer alone, are the only informative routes to later requirements. Gdf1 is not a spare copy but an obligate heterodimer partner for long-range signaling, so compound Gdf1 genetics and precisely timed Cre induction determine whether results are interpretable.',
  Nog:
    'Nog, the mouse ortholog of human NOG, encodes noggin, a secreted cysteine-knot dimer that neutralizes BMP2, BMP4, BMP7, and GDF5 by occluding both the type I and type II receptor epitopes on the ligand, thereby setting BMP tone in the node, notochord, somites, and prospective joint interzones. Nulls die perinatally with failed neural tube closure, absent joint interzones, and widespread skeletal fusion, whereas human heterozygous mutations produce proximal symphalangism, multiple synostoses syndrome, and stapes ankylosis, a dosage logic that argues for hypomorphic and patient missense knockins alongside conditional nulls. Joint-restricted deletion using Gdf5-Cre or limb mesenchyme drivers isolates articular maintenance from neural tube requirements, and humanization enables testing of antibodies and engineered BMP variants designed to evade noggin capture. Grem1, Grem2, and chordin overlap as extracellular BMP antagonists in several of these tissues, so compound alleles are advisable when SMAD output is the direct readout.',
  Notch1:
    'Notch1, the mouse ortholog of human NOTCH1, encodes a single-pass receptor whose EGF-like repeats 11 and 12 bind Dll and Jag ligands, with Fringe-mediated O-fucose elongation tuning ligand preference; furin cleavage at S1 generates a heterodimer held together by the negative regulatory region, and mechanical pulling by an endocytosing ligand exposes S2 for Adam10, after which gamma-secretase cleaves at S3 to release the intracellular domain, which enters the nucleus, displaces corepressors from Rbpj, and recruits Maml to activate Hes and Myc, until a carboxy-terminal PEST degron directs Fbxw7-dependent turnover. Human T-cell leukemia mutations cluster in the negative regulatory region and PEST, while loss underlies Adams-Oliver syndrome and bicuspid aortic valve. Homozygous nulls die near E10.5 with somitogenesis and vascular defects, so conditional alleles are standard, and Lox-Stop-Lox intracellular domain knockins, patient-matched PEST truncations, and humanized negative regulatory regions for antibody testing answer separate questions. Notch2 partially compensates, so plan compound genetics.',
  Notch2:
    'Ligand-dependent proteolysis governs Notch2, the mouse ortholog of human NOTCH2, which encodes a receptor with the same modular architecture as Notch1, using EGF repeats for Dll and Jag engagement, a negative regulatory region stabilized by S1 furin processing, sequential Adam10 and gamma-secretase cleavage, and an intracellular domain that partners with Rbpj and Maml before PEST-directed degradation. Its human genetics run in both directions: haploinsufficiency and hypomorphic alleles cause Alagille syndrome with bile duct paucity, whereas PEST-truncating mutations that stabilize the intracellular domain cause Hajdu-Cheney syndrome with acro-osteolysis, and NOTCH2 lesions recur in marginal zone lymphoma. Homozygous nulls die in mid-gestation, while the hypomorphic allele survives with cardiac, renal, and hepatic defects, so conditional deletion is the standard route for biliary, splenic, and skeletal studies. A PEST truncation knockin models gain-of-function bone disease, and receptor-specific humanization supports paralog-selective antibodies. Notch1 overlaps in liver and B cell compartments, making Notch1 and Notch2 compound alleles necessary for full penetrance.',
  Notch3:
    'Notch3, the mouse ortholog of human NOTCH3, encodes a receptor with a shorter extracellular region than Notch1 and expression concentrated in vascular smooth muscle and pericytes, where canonical Adam10 and gamma-secretase processing releases an intracellular domain that acts through Rbpj and Maml to drive Heyl and mural cell maturation. Its disease logic is distinctive and not simple loss of function: CADASIL arises from cysteine-altering substitutions within EGF repeats that promote ectodomain multimerization and granular osmiophilic material deposition in arteriolar walls, a proteinopathy mechanism, whereas PEST-truncating alleles that stabilize signaling cause lateral meningocele syndrome. Homozygous nulls are viable with immature, poorly differentiated arterial smooth muscle and impaired myogenic responses, so germline alleles are usable, but the informative CADASIL model requires a patient-matched cysteine substitution knockin, ideally in a humanized EGF repeat context, rather than deletion. Notch1 contributes to mural cell biology, so compound alleles and a smooth muscle driver refine interpretation.',
  Notch4:
    'Encoding the most divergent family member, Notch4 is the mouse ortholog of human NOTCH4 and produces a receptor with markedly fewer EGF repeats, endothelium-restricted expression, and weaker transactivation than Notch1, still relying on Adam and gamma-secretase processing to liberate an intracellular domain that engages Rbpj and Maml. The locus is historically important as int3, where MMTV proviral insertion truncates the extracellular region and yields a constitutively active intracellular fragment that drives mammary tumors, which established that ligand-independent Notch signaling is transforming. Homozygous nulls are viable and fertile with normal vasculature, and combining them with Notch1 deficiency does not markedly worsen the Notch1 phenotype, so loss-of-function alleles at this locus are of limited value on their own. The productive designs are therefore gain-of-function: endothelial-restricted intracellular domain expression to test arteriovenous malformation and tumor angiogenesis phenotypes, paired with a validated Cdh5-CreER driver so activation timing is controlled rather than constitutive.',
  Npm1:
    'Npm1 encodes the mouse ortholog of human NPM1, a pentameric nucleolar phosphoprotein that shuttles between nucleolus, nucleoplasm, and cytoplasm, chaperoning ribosomal proteins and histones, controlling ribosome biogenesis, and stabilizing ARF and p53 through nucleolar sequestration. The defining leukemogenic lesion is not loss but a frameshift in the terminal exon, most often the type A tetranucleotide duplication at W288, which ablates the C-terminal tryptophans and creates a new leucine-rich nuclear export signal, producing cytoplasmic NPM1c, sustained HOX program expression, and XPO1 dependence in acute myeloid leukemia. Because homozygous deletion is embryonic lethal with hematopoietic and midline defects while heterozygotes show genomic instability, design is explicit: humanized exon 12 frameshift knockins interrogate NPM1c leukemia and menin or exportin inhibitor response, whereas conditional nulls test nucleolar stress and ribosome biogenesis dependence. Paralogs Npm2 and Npm3 do not substitute functionally, and a cooperating Flt3 internal tandem duplication allele markedly shortens latency.',
  Nras:
    'Nras, the mouse ortholog of human NRAS, encodes the Ras isoform whose hypervariable carboxy terminus carries farnesylation plus a single palmitoylation site, directing rapid cycling between Golgi and plasma membrane and giving it signaling output distinct from Kras and Hras despite an identical G domain governed by Sos-family exchange factors and Nf1 and Rasa1 GAPs. Codon 61 substitutions, particularly Gln61Arg and Gln61Lys, dominate cutaneous melanoma, Gly12Asp and Gly13Asp occur in acute myeloid and juvenile myelomonocytic leukemia, and germline substitutions cause a Noonan syndrome variant, so allele class is dictated by disease context rather than convenience. Homozygous nulls are viable with subtle immune phenotypes because Kras carries the essential developmental load, which means conditional deletion is informative only in sensitized or compound settings. Lox-Stop-Lox codon 61 knockins expressed at endogenous levels remain the standard for melanoma and leukemia initiation, and pairing them with Tyr-CreER or Vav-Cre determines the lineage and latency observed.',
  Nrg1:
    'Nrg1, the mouse ortholog of human NRG1, encodes neuregulin 1, a family of EGF-domain ligands generated from a single locus through multiple promoters and splice choices that yield type I and type II isoforms with immunoglobulin-like amino termini, type III isoforms with a cysteine-rich transmembrane region that signal juxtacrine, and alpha or beta EGF variants with different receptor affinity. Most isoforms are made as transmembrane precursors cleaved by Bace1 and Adam17 to release the EGF domain, which binds Erbb3 or Erbb4 and drives heterodimerization with Erbb2 to activate PI3K and Erk. Homozygous nulls die at mid-gestation from failed cardiac trabeculation, so isoform-specific conditional exon targeting is the design that isolates type III-dependent Schwann cell myelination or type I-dependent cardiac and interneuron phenotypes. Human NRG1 fusions in lung adenocarcinoma justify fusion knockins, and Nrg2, Nrg3, and Nrg4 provide overlapping Erbb ligands that can mask single-gene loss.',
  Nrg2:
    'As the mouse ortholog of human NRG2, Nrg2 encodes a neuregulin with an immunoglobulin-like domain, a glycosylated spacer, and an EGF-like domain that binds Erbb4 with high affinity and Erbb3 more weakly, driving heterodimerization with Erbb2 and downstream PI3K and Erk activation; unlike Nrg1 it is expressed most prominently in cerebellar and hippocampal neurogenic zones, in dopaminergic midbrain neurons, and in developing kidney and heart, and the pro-protein requires proteolytic shedding to release soluble ligand. Homozygous nulls survive but show reduced body size, delayed reproductive development, altered dopaminergic and GABAergic signaling, and behavioral phenotypes relevant to Erbb4-dependent circuit assembly, so germline alleles are workable while conditional deletion separates neuronal from peripheral contributions. Isoform-specific targeting distinguishes membrane-tethered from shed activity, and EGF-domain point mutants test receptor preference genetically. Because Nrg1 and Nrg3 supply overlapping Erbb4 ligand activity, compound alleles are frequently required before circuit-level phenotypes become penetrant.',
  Nrg3:
    'Nrg3, the mouse ortholog of human NRG3, encodes a neuregulin whose EGF-like domain binds Erbb4 essentially exclusively, with no appreciable affinity for Erbb3, giving it unusually selective receptor specificity within the family; it is expressed predominantly in central nervous system neurons, where it acts as a membrane-tethered and shed ligand controlling cortical interneuron migration, axonal outgrowth, and Erbb4-dependent GABAergic synapse formation on parvalbumin interneurons. The spontaneous mouse kyphoscoliosis allele disrupts Nrg3 and produces neuromuscular and skeletal deformity, while human NRG3 variants are associated with schizophrenia and attention deficit phenotypes, and elevated NRG3 expression correlates with cortical dysfunction. Nulls are viable with behavioral and circuit abnormalities, so germline deletion is tractable and conditional alleles restrict loss to specific neuronal populations after migration is complete. EGF-domain substitutions that abolish Erbb4 binding separate ligand activity from structural roles, and because Nrg1 and Nrg2 also engage Erbb4, compound alleles clarify masked synaptic phenotypes.',
  Nrxn1:
    'Presynaptic adhesion in the mouse is organized by Nrxn1, ortholog of human NRXN1, which uses two promoters to produce long alpha-neurexin isoforms (six LNS domains interleaved with EGF repeats) and short beta-neurexins sharing a single transmembrane segment and a cytoplasmic tail that recruits CASK and Mint. Extensive alternative splicing at sites 1 through 6, particularly splice site 4, dictates trans-synaptic partner choice among neuroligins, LRRTMs, cerebellin-GluD complexes, and dystroglycan, thereby tuning calcium channel coupling and release probability. Human deletions and rare truncating variants segregate with autism, schizophrenia, and Pitt-Hopkins-like syndrome 2. Allele choice follows directly: conditional deletion of alpha-specific exons isolates presynaptic calcium coupling, splice-locked knockins interrogate isoform logic, and humanized cassettes support variant modeling. Because Nrxn2 and Nrxn3 substantially compensate, single-locus nulls are frequently silent, so plan triple conditional genetics with defined Cre drivers and match allele class to synaptic physiology endpoints.',
  Nrxn2:
    'Although often treated as the minor paralog, Nrxn2 encodes the mouse ortholog of human NRXN2, an alpha and beta neurexin pair whose extracellular LNS and EGF modules bind neuroligins, LRRTMs, and cerebellin adaptors to align presynaptic release machinery with postsynaptic receptor fields. Its cytoplasmic tail terminates in a PDZ-binding motif engaging CASK, linking the adhesion complex to voltage-gated calcium channels and the active zone. Truncating NRXN2 variants have been reported in autism and schizophrenia pedigrees, and alpha-Nrxn2 null mice show altered social behavior and anxiety with region-specific transmission deficits. Design decisions therefore split between conditional alpha-specific exon removal, beta-selective ablation, splice site 4 fixed knockins, and humanization for variant testing. Given strong functional overlap with Nrxn1 and Nrxn3, compound conditional alleles are usually required to unmask phenotypes, and pairing them with an interneuron or projection-specific Cre determines whether readouts are electrophysiological, behavioral, or ultrastructural.',
  Nrxn3:
    'Splice isoform diversity is greatest at Nrxn3, the mouse ortholog of human NRXN3, where alpha and beta transcripts plus heavy alternative splicing, including a site 4 insert and 3-prime terminal variants that generate secreted forms, control postsynaptic partner selection and AMPA receptor abundance. Nrxn3 supports presynaptic release at hippocampal inhibitory synapses and regulates AMPA receptor trafficking in olfactory bulb and dentate gyrus, while human NRXN3 deletions and intronic variants associate with autism, addiction phenotypes, and obesity. Allele design should distinguish complete conditional null, isoform-restricted deletion of alpha-specific exons, splice-locked knockins that fix site 4 inclusion, and epitope humanization for reagent validation. Redundancy with Nrxn1 and Nrxn2 is genuine and well documented, so single knockouts frequently yield subtle phenotypes; combining conditional triple alleles with a defined Cre and matching them to release probability, receptor content, or circuit behavior endpoints is essential.',
  Ntrk1:
    'TrkA, encoded by mouse Ntrk1 in orthology with human NTRK1, is a receptor tyrosine kinase with leucine-rich repeats and immunoglobulin-like C2 modules that binds nerve growth factor, dimerizes, and signals through SHC, FRS2, phospholipase C gamma, and the RAS-ERK and PI3K-AKT cascades to specify survival of nociceptive sensory and sympathetic neurons. Biallelic loss-of-function variants cause congenital insensitivity to pain with anhidrosis, whereas oncogenic activation occurs through in-frame fusions such as LMNA-NTRK1 and TPM3-NTRK1 that dimerize constitutively via partner coiled coils, defining a tumor-agnostic indication for larotrectinib and entrectinib along with solvent front resistance at G595. Design therefore separates three questions: nulls for sensory neuron development and pain phenotypes, inducible fusion knockins for oncogenic dependency and inhibitor pharmacology, and humanized kinase domains for potency and resistance profiling. Germline nulls survive to birth but die early with severe sensory ganglion loss, so tissue-restricted deletion is preferable, and Ntrk2 and Ntrk3 bind distinct neurotrophins without compensating.',
  Ntrk2:
    'Mouse Ntrk2, ortholog of human NTRK2, encodes TrkB, the high affinity receptor for brain-derived neurotrophic factor and neurotrophin 4, whose ligand-induced dimerization activates SHC-RAS-ERK, PI3K-AKT, and phospholipase C gamma 1 signaling to control neuronal survival, dendritic arborization, synaptic potentiation, and hypothalamic energy balance. Alternative splicing generates the kinase-dead TrkB.T1 isoform, which acts as a dominant negative ligand sink and predominates in glia, an isoform architecture that targeting vectors must respect. Human loss-of-function variants produce hyperphagic obesity with developmental delay, while NTRK2 fusions occur in pilocytic astrocytoma and glioblastoma. Germline nulls die within days of birth with severe sensory and motor deficits, so conditional deletion using Camk2a-cre, Nes-cre, or Sim1-cre is required for adult circuit and metabolic endpoints, and isoform-selective alleles are needed to separate full length from truncated receptor function. Ntrk1 and Ntrk3 bind different neurotrophins and do not rescue, so match allele class to whether the question is circuit signaling, obesity, or fusion-driven glioma.',
  Ntrk3:
    'Ntrk3 is the mouse ortholog of human NTRK3 and encodes TrkC, the cognate receptor for neurotrophin 3, which dimerizes through its immunoglobulin-like C2 domain and activates RAS-ERK, PI3K-AKT, and phospholipase C gamma cascades required for group Ia proprioceptive afferents, muscle spindle formation, and cardiac and enteric development. Its oncogenic relevance is dominated by the ETV6-NTRK3 fusion, in which the ETV6 sterile alpha motif enforces ligand-independent dimerization; this rearrangement defines infantile fibrosarcoma, congenital mesoblastic nephroma, secretory carcinoma of breast and salivary gland, and a subset of thyroid carcinoma, and it responds to TRK-selective inhibitors until solvent front substitutions emerge. Model design therefore diverges between conditional nulls, which address proprioceptive and cardiac developmental biology since germline loss is perinatal lethal, and inducible fusion knockins that generate the actual tumor histologies for pharmacology. Because Ntrk1 and Ntrk2 respond to different neurotrophins, functional rescue is minimal; select Cre drivers matched to mesenchymal or secretory epithelial cell of origin.',
  Optn:
    'Optineurin, encoded by mouse Optn and orthologous to human OPTN, is a coiled-coil autophagy receptor carrying an LC3-interacting region, a UBAN motif that binds linear M1-linked polyubiquitin, and a C-terminal zinc finger. TBK1 phosphorylates optineurin at Ser177 and adjacent residues to enhance LC3 binding and ubiquitin affinity, driving mitophagy downstream of PINK1 and parkin, xenophagy of cytosolic bacteria, and clearance of aggregated protein, while the UBAN domain simultaneously restrains NF-kappaB signaling. Disease logic is allele-specific: E50K acts as a dominant gain of function in normal-tension glaucoma, whereas E478G and truncating alleles cause ALS by abolishing ubiquitin binding. Model designs therefore fork between conditional null, UBAN point knockins such as D477N, phosphomimetic or phosphodead Ser177 variants, and humanization. Because Sqstm1, Nbr1, Tax1bp1, and Calcoco2 provide overlapping receptor activity, expect buffered clearance phenotypes and pair conditional alleles with motor neuron or microglial Cre drivers.',
  Palb2:
    'Palb2, the mouse ortholog of human PALB2, encodes the physical bridge of the BRCA network: an N-terminal coiled coil engages BRCA1, while the C-terminal seven-bladed WD40 propeller docks BRCA2 and RAD51, delivering the recombinase to resected DNA ends, with a chromatin-association motif binding MRG15 and nucleosomes to license homologous recombination in transcribed regions. Biallelic loss causes Fanconi anemia subtype N, whereas monoallelic truncation confers high breast, ovarian and pancreatic risk through somatic second hits. Constitutive deletion is embryonic lethal, so tissue-restricted conditional nulls paired with mammary or pancreatic Cre drivers remain the only route to adult tumor phenotypes, while patient-matched truncating or WD40 missense knockins address separation-of-function and variant reclassification questions a clean null cannot. Allele choice should therefore track endpoint: conditional null for tumor latency and PARP inhibitor synthetic lethality, knockin for variant pathogenicity, humanized locus for clinical candidate pharmacology.',
  Pank2:
    'Coenzyme A biosynthesis begins with Pank2, the mouse ortholog of human PANK2, which encodes the mitochondrially targeted pantothenate kinase isoform that phosphorylates vitamin B5 in the committed, rate-limiting step and is allosterically inhibited by acetyl-CoA and other acyl-CoA thioesters. Loss of function causes pantothenate kinase-associated neurodegeneration, a childhood NBIA subtype featuring globus pallidus iron accumulation, dystonia, and the eye-of-the-tiger MRI sign, attributed to phosphopantothenate and CoA shortage with secondary lipid and cysteine dysregulation. Critically, conventional Pank2 knockout mice are viable and do not reproduce basal ganglia degeneration, showing instead retinal degeneration and azoospermia, so designs must consider patient missense knockins, combined Pank1 or Pank3 deficiency, or dietary and ketogenic challenge to sensitize the phenotype. Genuine paralog redundancy among Pank1, Pank2, and Pank3 is the central obstacle, so choose compound alleles when the endpoint is CoA flux, iron deposition, or motor decline.',
  Park7:
    'Park7 encodes DJ-1, the mouse ortholog of human PARK7, a small ThiJ/PfpI-fold homodimer functioning as a redox sensor and protein deglycase that removes glycation adducts from cysteine, arginine, and lysine residues and from nucleotides, and as a holdase chaperone suppressing alpha-synuclein aggregation. Its reactive Cys106 undergoes graded oxidation to sulfinic acid, promoting mitochondrial localization, stabilization of NRF2 by antagonizing KEAP1, and modulation of PTEN and ASK1 signaling, whereas hyperoxidation to sulfonic acid inactivates the protein. Recessive PARK7 mutations such as L166P destabilize the dimer and cause early onset parkinsonism. Because global Park7 nulls remain viable with only mild nigrostriatal dopamine release deficits and no overt degeneration, allele planning should weigh conditional null against C106 redox-dead knockins, patient missense alleles, or humanization, and should anticipate additive designs with Pink1 and Prkn when dopaminergic loss rather than oxidative stress signaling is the endpoint.',
  Pck1:
    'Pck1 encodes cytosolic phosphoenolpyruvate carboxykinase, the mouse ortholog of human PCK1, which commits mitochondrially derived oxaloacetate to phosphoenolpyruvate in a GTP-dependent decarboxylation that sets the flux ceiling for hepatic and renal gluconeogenesis and for adipose glyceroneogenesis. Transcription rather than allostery dominates its control: glucagon acting through cAMP and CREB, the glucocorticoid receptor, FOXO1 and PGC-1 alpha drive the promoter, while insulin signaling through AKT suppresses it, making the locus a canonical readout of fasting and insulin resistance. Whole-body deletion is neonatally lethal with massive hepatic steatosis, so albumin-Cre or adipocyte-restricted conditional nulls are required to separate liver from adipose contributions, and promoter-replacement or inducible overexpression alleles test whether transcriptional derepression alone raises glucose output. The mitochondrial paralog Pck2 supplies partial cataplerotic flux but does not rescue cytosolic gluconeogenesis, so compound designs are advisable when quantifying whole-body glucose production.',
  Pck2:
    'Mitochondrial cataplerosis runs through Pck2, the mouse ortholog of human PCK2, which encodes the matrix isoform of phosphoenolpyruvate carboxykinase and catalyzes the GTP-dependent decarboxylation and phosphorylation of oxaloacetate to phosphoenolpyruvate inside the matrix, providing a cataplerotic exit from the TCA cycle that is constitutively expressed rather than hormonally cycled like the cytosolic PCK1 enzyme. Under glucose limitation, this flux routes glutamine-derived oxaloacetate into phosphoenolpyruvate for serine, glycerol and nucleotide biosynthesis, a route repeatedly implicated in tumor survival during nutrient stress and in ATF4-driven integrated stress transcription. The design fork is clear: a conditional null defines where mitochondrial cataplerosis is required without confounding by whole-body metabolic adaptation, while humanization supports inhibitor pharmacology, since selectivity against PCK1 is the central medicinal chemistry problem. Genuine redundancy with cytosolic Pck1 exists in gluconeogenic tissue, so consider compound alleles. Match the allele to isotope tracing flux, tumor growth or systemic glucose handling endpoints.',
  Pcsk9:
    'Pcsk9, ortholog of human PCSK9, encodes a secreted proprotein convertase that abandons catalysis after autoproteolysis: the cleaved prodomain remains lodged in the active site, and the mature protein instead acts as a chaperone, its catalytic domain gripping the EGF-A repeat of the LDL receptor at the hepatocyte surface and rerouting the complex from recycling endosome to lysosome, lowering surface receptor density and raising plasma LDL cholesterol. Human genetics supplies both directions, with gain-of-function alleles such as D374Y causing autosomal dominant hypercholesterolemia and loss-of-function alleles such as Y142X and R46L conferring lifelong protection. Because monoclonal antibodies and siRNA therapeutics recognize human sequence, locus humanization is usually the decisive design for pharmacology, whereas hepatic conditional nulls and D374Y knockins address receptor trafficking and lesion burden. Nulls are viable and hypocholesterolemic, so lethality is no constraint; pair alleles with Ldlr or Apoe backgrounds suited to the atherosclerosis endpoint.',
  Pdcd1:
    'Pdcd1 encodes PD-1, mouse ortholog of human PDCD1, a single immunoglobulin variable domain inhibitory receptor whose cytoplasmic tail carries an ITIM and, functionally more important, an ITSM that recruits SHP2 to dephosphorylate proximal signaling components, with CD28 rather than the T cell receptor established as the preferred substrate, so PD-1 acts primarily by disabling costimulation. Ligands PD-L1 and PD-L2 are induced by interferon gamma, coupling target cell sensing of inflammation to lymphocyte restraint, and sustained expression marks exhausted CD8 T cells in chronic infection and tumors. Germline nulls develop late, strain dependent autoimmunity, lupus-like nephritis on C57BL/6 and dilated cardiomyopathy on BALB/c, so background must be stated explicitly. Because pembrolizumab and nivolumab do not bind murine PD-1, epitope-matched humanization is mandatory for clinical antibody testing, while conditional nulls with Cd8-Cre address cell intrinsic exhaustion and compound Ctla4 or Lag3 alleles reproduce combination checkpoint synergy.',
  Pdcd1lg2:
    'Pdcd1lg2, the mouse ortholog of human PDCD1LG2, encodes PD-L2 (B7-DC), a type I transmembrane protein whose IgV and IgC2 ectodomains engage PD-1 with roughly three-fold higher affinity than PD-L1 while also binding the repulsive guidance molecule RGMB on lung interstitial macrophages. Expression is largely restricted to dendritic cells, macrophages, and germinal center B cells and is driven by IL-4 and STAT6 rather than by the interferon gamma axis that dominates Cd274 induction, so PD-L2 shapes type 2 and tissue-resident tolerance more than interferon-driven adaptive resistance. Allele choice follows directly: conditional nulls isolate the ligand contribution of a defined myeloid or dendritic compartment, whereas ectodomain humanization is required whenever a candidate antibody or PD-1 fusion fails to cross-react with mouse protein. Because Cd274 covers much of the same receptor, single knockouts frequently look silent, so plan Cd274 compound genetics and pair the allele with tumor rejection, exhaustion reversal, or airway inflammation endpoints.',
  Pdgfra:
    'Pdgfra encodes the mouse ortholog of human PDGFRA, a class III receptor tyrosine kinase that binds PDGF-A, PDGF-C, and PDGF-B as homodimers or as heterodimers with PDGFRB, then autophosphorylates to engage PI3K, phospholipase C gamma, SHP2, and RAS-ERK, directing cranial and cardiac neural crest, oligodendrocyte precursor, and gastrointestinal mesenchymal development. Oncogenic activation takes several distinct forms: activation loop D842V and juxtamembrane mutations in KIT wild-type gastrointestinal stromal tumor, which resist imatinib but respond to avapritinib, FIP1L1-PDGFRA fusions in hypereosinophilic myeloid neoplasms, and amplification in diffuse midline glioma. Germline nulls die in midgestation with craniofacial and cardiac defects, exactly as in the classic Patch deletion, so hotspot knockins should be conditional or inducible, and conditional nulls serve adult mesenchymal and oligodendrocyte questions. The paralog Pdgfrb heterodimerizes and shares ligands, so single-locus deletion can be buffered in perivascular compartments; choose Cre drivers by lineage and read out tumor latency or inhibitor response.',
  Pdgfrb:
    'Signaling in the mural cell compartment depends on Pdgfrb, the mouse ortholog of human PDGFRB, a class III receptor tyrosine kinase activated by PDGF-B and PDGF-D that recruits PI3K, SHP2, and RAS-ERK effectors and is indispensable for pericyte and vascular smooth muscle recruitment to developing endothelium. Human disease spans both directions of dosage: gain-of-function substitutions in infantile myofibromatosis and Kosaki overgrowth syndrome, COL1A1-PDGFB rearrangement in dermatofibrosarcoma protuberans, ETV6-PDGFRB fusions in eosinophilia-associated myeloid neoplasms, and loss-of-function alleles causing primary familial brain calcification with blood brain barrier failure. Germline nulls die perinatally from pericyte deficiency, glomerular defects, and hemorrhage, so conditional deletion with Pdgfrb-cre, Cspg4-cre, or Myh11-cre is required for adult vascular and fibrosis endpoints, while precise activating knockins reproduce myofibromatosis and inhibitor sensitivity. Pdgfra shares ligands and can heterodimerize, so compound alleles clarify mesenchymal redundancy; match allele class to whether the readout is barrier integrity, fibrosis, or tumor response.',
  Pdha1:
    'Pdha1, the mouse ortholog of human PDHA1, encodes the E1 alpha subunit of the pyruvate dehydrogenase complex, which pairs with E1 beta in an alpha2beta2 heterotetramer, binds thiamine pyrophosphate, and performs the decarboxylation of pyruvate that commits carbon to acetyl-CoA and the TCA cycle. Regulation runs through three serine residues on this subunit that are phosphorylated by the PDK kinases and reversed by PDP phosphatases, making the protein the direct node where nutrient state gates glycolytic carbon entry into oxidative metabolism. The gene is X-linked, and PDHA1 deficiency is the commonest cause of congenital lactic acidosis, hemizygous in males and mosaic in heterozygous females, an architecture that should shape design: conditional floxed alleles permit tissue-restricted loss without the confound of random X inactivation, while patient-matched knockins retain residual activity for dichloroacetate or ketogenic diet studies. No paralog compensates. Select neuronal or hepatic Cre drivers according to neuropathology or systemic lactate endpoints.',
  Pdhb:
    'Pdhb, ortholog of human PDHB, encodes the E1 beta subunit that partners with E1 alpha to build the alpha2beta2 pyruvate dehydrogenase E1 heterotetramer, contributing to the thiamine pyrophosphate binding pocket and to the interface that docks E1 onto the E2 dihydrolipoamide acetyltransferase core. Unlike the X-linked alpha subunit, this gene is autosomal, so patients present with recessive pyruvate dehydrogenase deficiency, lactic acidosis and neurodevelopmental impairment while carriers remain unaffected, a distinction that makes recessive knockin modeling straightforward and interpretable. Because complete blockade of pyruvate flux into acetyl-CoA is expected to be developmentally lethal, plan conditional floxed alleles for tissue-restricted ablation and reserve patient-matched missense knockins for modeling partial activity and testing thiamine or dichloroacetate responsiveness. No paralogous subunit substitutes at this position. Match the allele to endpoint, using neuronal Cre drivers for Leigh-like pathology and muscle or liver drivers for substrate oxidation and lactate handling.',
  Pdhx:
    'Pdhx is the mouse ortholog of human PDHX and encodes E3BP, the dihydrolipoamide dehydrogenase binding protein, a structural component of the pyruvate dehydrogenase complex that occupies positions within the E2 inner core and supplies the lipoyl and binding domains that tether the E3 flavoprotein to the assembly. Without E3BP, E3 is not recruited, so reoxidation of the lipoamide swinging arm stalls and the whole complex loses activity even though E1 and E2 remain intact, which is why PDHX mutations cause recessive pyruvate dehydrogenase deficiency with lactic acidosis, Leigh-like lesions and, in some patients, comparatively longer survival than E1 alpha disease. The allele fork follows that structural logic: a conditional null tests where complex assembly is limiting, whereas a truncating patient-matched knockin preserves partial incorporation and models residual flux. No paralog performs this tethering role. Select the conditional allele with neuronal or hepatic Cre when lesion progression or lactate clearance defines the endpoint.',
  Pdk1:
    'Nomenclature deserves care here: Pdk1 and human PDK1 denote pyruvate dehydrogenase kinase isozyme 1, a mitochondrial matrix kinase distinct from the PI3K effector Pdpk1. The enzyme phosphorylates serine residues on the E1 alpha subunit of the pyruvate dehydrogenase complex, principally site 1, inactivating the complex and blocking pyruvate entry into the TCA cycle, thereby diverting carbon toward lactate. It is allosterically inhibited by pyruvate and by dichloroacetate and induced transcriptionally by HIF1 alpha, placing it at the switch that installs aerobic glycolysis in hypoxic and tumor tissue. Conditional nulls crossed to cardiomyocyte or tumor-restricted Cre drivers test whether relieving pyruvate dehydrogenase inhibition reverses the glycolytic phenotype, while kinase-dead or hypoxia-response-element mutant knockins isolate catalysis from induction. Because Pdk2, Pdk3 and Pdk4 phosphorylate overlapping sites with different tissue distributions and strong fasting induction, single-isoform deletion frequently yields a masked metabolic phenotype and compound alleles should be planned early.',
  Pdk2:
    'Encoding pyruvate dehydrogenase kinase isozyme 2, Pdk2 is the mouse ortholog of human PDK2 and phosphorylates serine residues on the E1 alpha subunit to switch off the pyruvate dehydrogenase complex, acting as a direct brake on glycolytic carbon entry into the TCA cycle. This isoform is the most broadly expressed of the four, the most sensitive to inhibition by pyruvate and by dichloroacetate, and is stimulated by elevated acetyl-CoA to CoA and NADH to NAD ratios, so it enforces the classic fatty acid to glucose oxidation switch in heart, muscle and liver. Design choices split cleanly: a conditional null asks where tonic PDH suppression is required and typically increases glucose oxidation, while humanization enables testing of dichloroacetate analogs and newer inhibitors against the human pharmacophore. Real redundancy exists across Pdk1, Pdk3 and Pdk4, so plan compound conditional genetics before interpreting a single knockout. Choose the allele by flux tracing, insulin sensitivity or drug response endpoints.',
  Pdk3:
    'Pdk3, the mouse ortholog of human PDK3, encodes the pyruvate dehydrogenase kinase isoform with the highest intrinsic specific activity toward E1 alpha and the strongest dependence on binding the lipoyl-bearing L2 domain of the E2 core for full activation, a property that renders it comparatively resistant to feedback inhibition by pyruvate. That biochemistry carries clinical weight, since the gene is X-linked and gain-of-function missense variants strengthening L2 binding cause X-linked Charcot-Marie-Tooth neuropathy type 6 through chronic PDH hyperphosphorylation and suppressed oxidative flux. The design fork is therefore unusual for this family: a hyperactivating patient-matched knockin, not a null, reproduces the human disease, while a conditional null answers the separate question of where this isoform normally restrains PDH. Because Pdk1, Pdk2 and Pdk4 overlap substantially, a single knockout is easily buffered and compound alleles should be planned. Match allele to endpoint, pairing peripheral nerve analysis with the knockin and flux measurements with the null.',
  Pdk4:
    'As the mouse ortholog of human PDK4, Pdk4 encodes the pyruvate dehydrogenase kinase isoform whose control is overwhelmingly transcriptional, induced by fasting, glucocorticoids, PPAR alpha and PPAR delta, FOXO1 and estrogen-related receptors, and repressed by insulin, so its abundance tracks nutrient state rather than acute allosteric input. By phosphorylating E1 alpha during starvation, high fat feeding or diabetes, it conserves pyruvate and lactate for gluconeogenesis while forcing muscle and heart onto fatty acid oxidation, and sustained induction contributes to the metabolic inflexibility seen in insulin resistance and heart failure. That regulatory logic favors a floxed conditional null with muscle, cardiac or hepatic Cre drivers to localize where induction drives glucose oxidation suppression, and a humanized allele where inhibitor pharmacology is the goal. Overlap with Pdk1, Pdk2 and Pdk3 is genuine, so compound conditionals prevent misreading a buffered phenotype. Align the allele with clamp studies, substrate tracing or cardiac efficiency endpoints.',
  Pfkl:
    'Pfkl is the mouse ortholog of human PFKL and encodes the liver-type subunit of phosphofructokinase 1, the tetrameric enzyme that commits glucose to glycolysis by phosphorylating fructose 6-phosphate to fructose 1,6-bisphosphate, the step under the strongest allosteric control by ATP, citrate, AMP and fructose 2,6-bisphosphate. The L subunit assembles into homotetramers and into hybrid tetramers with the M and P subunits, and the resulting isozyme composition sets tissue-specific sensitivity to those effectors, with the liver-enriched form tuned for gluconeogenic and lipogenic crosstalk. Because the human gene sits on chromosome 21, dosage effects have also been examined in trisomy contexts. Conditional nulls localize where L subunit content limits glycolytic flux, while humanization supports allosteric modulator screening. Since Pfkm and Pfkp form functional tetramers in overlapping tissues, single-locus deletion is frequently buffered and compound conditional alleles are advisable. Match allele class to isotope flux, hepatic glucose output or tumor glycolysis endpoints.',
  Pfkm:
    'Skeletal muscle glycolytic capacity rests on Pfkm, the mouse ortholog of human PFKM, which encodes the muscle subunit of phosphofructokinase 1 and dominates the tetramer in that tissue, where it catalyzes the committed, effectively irreversible ATP-dependent phosphorylation of fructose 6-phosphate and integrates AMP, ATP, citrate and fructose 2,6-bisphosphate signals into glycolytic rate. Recessive loss causes Tarui disease, glycogen storage disease type VII, in which exercise intolerance, cramps, myoglobinuria and compensated hemolysis follow from blocked muscle glycolysis, with the erythrocyte phenotype partial rather than complete because red cells contain M and L hybrid tetramers. Model design follows that tissue logic: a germline or muscle-restricted conditional null reproduces the metabolic myopathy, while patient-matched missense or splice knockins model residual activity and milder late-onset forms. Redundancy with Pfkl and Pfkp is real outside muscle. Choose the allele by endpoint, whether exercise challenge, glycogen accumulation, phosphorus magnetic resonance spectroscopy or hemolytic indices are the primary measures.',
  Pfkp:
    'Pfkp, the mouse ortholog of human PFKP, encodes the platelet-type phosphofructokinase 1 subunit, which assembles into tetramers with the L and M subunits and catalyzes the rate-committing conversion of fructose 6-phosphate to fructose 1,6-bisphosphate under allosteric control by ATP, citrate and fructose 2,6-bisphosphate. This isoform is the one most often upregulated in tumors and activated immune cells, where growth factor signaling through EGFR and AKT drives post-translational modification and membrane recruitment that raise glycolytic flux, and where ubiquitin-dependent degradation limits aerobic glycolysis. That biology makes conditional nulls the tool for asking whether tumor or immune cell glycolysis actually depends on this subunit in vivo, while humanization supports isoform-selective inhibitor work. Compensation by Pfkl and Pfkm within the shared tetramer pool is substantial, so plan compound conditional alleles rather than expecting a clean single-locus phenotype. Match the allele to lactate output, tumor growth or T cell effector function endpoints.',
  Pgk1:
    'Pgk1 is the mouse ortholog of human PGK1 and encodes phosphoglycerate kinase 1, the enzyme that transfers the high-energy phosphate of 1,3-bisphosphoglycerate to ADP, generating the first net ATP of glycolysis and yielding 3-phosphoglycerate that also feeds the serine biosynthesis branch. The gene is X-linked and ubiquitously expressed, and the protein moonlights beyond canonical glycolysis, acting as a disulfide reductase that liberates angiostatin from plasmin and, in some settings, entering mitochondria to phosphorylate pyruvate dehydrogenase kinase 1. Recessive human deficiency produces hemolytic anemia, myopathy and neurological disease with hemizygous male presentation. Because complete loss removes a non-redundant ATP-generating step, conditional floxed alleles are the practical format, with patient-matched knockins preserving residual activity for erythroid and muscle phenotyping. The testis-restricted paralog Pgk2 exists but does not cover somatic tissue. Match the allele to endpoint, using erythroid, muscle or neural Cre drivers as the biology dictates.',
  Pik3ca:
    'Pik3ca, the mouse ortholog of PIK3CA, encodes p110 alpha, the class IA PI3K catalytic subunit that heterodimerizes with p85 regulatory subunits and phosphorylates PIP2 to PIP3 downstream of receptor tyrosine kinases and RAS, nucleating PDPK1 and AKT recruitment at the membrane. Oncogenic substitutions cluster in two structural classes with distinct mechanisms: helical domain changes E542K and E545K relieve the p85 nSH2 inhibitory contact, whereas the kinase domain change H1047R alters the membrane-binding interface, and the same alleles cause PIK3CA-related overgrowth spectrum when mosaic. Cre-activated latent knockins such as a lox-stop-lox H1047R allele are therefore standard for modeling dose and timing of activation, kinase-dead knockins isolate lipid kinase output from scaffolding, and conditional nulls test tissue dependence, since germline deletion is embryonic lethal at midgestation. Because p110 beta sustains PIP3 in some lineages, interpret isoform-selective inhibitor studies against compound Pik3ca and Pik3cb genetics.',
  Pik3cb:
    'Encoding p110 beta, Pik3cb is the ortholog of human PIK3CB and is unique among class IA catalytic subunits in receiving direct input from G protein coupled receptors through G beta gamma and from RAC1 and CDC42, in addition to canonical p85 mediated recruitment by phosphotyrosine. That wiring makes it the principal PIP3 source in PTEN-deficient prostate and other tumors and a driver of integrin dependent platelet activation and arterial thrombosis. Germline deletion is embryonic lethal, so conditional nulls are the practical tool, and a kinase-dead knockin is especially informative because p110 beta retains kinase-independent scaffolding roles in clathrin-mediated endocytosis and nuclear DNA replication that a null would conflate with catalytic loss. Given the reciprocal dependence between p110 alpha and p110 beta after isoform-selective inhibition, endpoint dictates design: pair conditional Pik3cb loss with Pten deletion for tumor latency, and choose kinase-dead alleles when the question is catalysis versus scaffold.',
  Pik3cd:
    'Expression of p110 delta, encoded by Pik3cd and orthologous to human PIK3CD, is largely restricted to leukocytes, where it couples the B cell receptor, T cell receptor and cytokine receptors through p85 to PIP3 production, AKT activation and FOXO1 inactivation, controlling B cell development, class switch recombination, T cell differentiation and neutrophil chemotaxis. Human gain-of-function substitutions, notably E1021K in the carboxy-terminal kinase domain, cause activated PI3K delta syndrome with senescent effector T cells, lymphoproliferation and impaired humoral immunity, while biallelic loss produces primary immunodeficiency. Two complementary alleles dominate the field: the catalytically inactive D910A knockin, which preserves protein and complex stoichiometry while abolishing lipid kinase output, and Cre-dependent E1021K knockins that reproduce the hyperactive human state in a lineage-restricted manner. Because germline deletion is viable, lethality is not limiting, and endpoints such as germinal center formation and idelalisib response map cleanly onto the chosen allele class.',
  Pik3r1:
    'Three regulatory proteins, p85 alpha, p55 alpha and p50 alpha, arise from Pik3r1, the ortholog of human PIK3R1, through alternative promoters, and each contributes an inter-SH2 coiled coil that stabilizes p110 alongside nSH2 and cSH2 domains that clamp the catalytic subunit until phosphotyrosine binding relieves inhibition. This dual role explains why the locus behaves as both a positive requirement and a brake: exon 11 splice-site mutations generate the p65 truncation seen in immunodeficiency, R649W in the cSH2 causes SHORT syndrome with insulin resistance, and somatic truncations act as tumor suppressor events in endometrial cancer. Whole-body deletion is neonatally lethal with hypoglycemia, whereas ablation of the p85 alpha isoform alone is viable and insulin hypersensitive, a distinction that should dictate whether promoter-specific or pan-locus conditional alleles are built. Pik3r2 and Pik3r3 partially substitute, so quantify residual regulatory subunit stoichiometry before attributing a phenotype to Pik3r1 loss.',
  Pink1:
    'Mitochondrial quality control initiates with Pink1, the mouse ortholog of human PINK1, encoding a serine/threonine kinase whose N-terminal targeting sequence normally drives import, MPP and PARL cleavage, and rapid N-end rule degradation. On depolarized mitochondria import arrests, PINK1 accumulates on the TOM complex, autophosphorylates, and phosphorylates ubiquitin at Ser65 plus the parkin ubiquitin-like domain, relieving parkin autoinhibition and nucleating a feed-forward mitophagy cascade that recruits optineurin and NDP52. Recessive loss of function causes early onset Parkinson disease, while kinase-dead and targeting-sequence variants define distinct failure modes. Allele choice follows the question: conditional null for tissue-restricted mitophagy failure, kinase-dead knockin to separate scaffolding from catalysis, and humanized alleles for kinase-activator compound testing. Note that murine Pink1 nulls show respiration and striatal dopamine release deficits without frank nigral degeneration, so pair alleles with mitophagy reporters such as mito-QC or exogenous stressors when neurodegeneration is the endpoint.',
  Pklr:
    'Two tissue-specific promoters drive Pklr, the mouse ortholog of human PKLR, producing the liver and erythrocyte pyruvate kinase isozymes that catalyze the final, effectively irreversible step of glycolysis, transferring phosphate from phosphoenolpyruvate to ADP under strong allosteric activation by fructose 1,6-bisphosphate and inhibition by ATP and alanine, with the hepatic form additionally suppressed by glucagon-driven phosphorylation. Recessive loss-of-function alleles cause pyruvate kinase deficiency, the commonest enzymatic cause of hereditary nonspherocytic hemolytic anemia, in which ATP depletion in mature erythrocytes that lack mitochondria drives membrane failure and 2,3-bisphosphoglycerate accumulation. Design follows the tissue split: patient-matched missense knockins reproduce the unstable, allosterically impaired enzyme and are the correct substrate for testing activators of the mitapivat class, while conditional nulls separate hepatic from erythroid consequences. The paralogous Pkm locus serves other tissues but does not rescue red cells. Match allele class to hematologic or hepatic glucose endpoints.',
  Pkm:
    'Pkm, the mouse ortholog of human PKM, encodes pyruvate kinase M and is regulated principally by mutually exclusive splicing of exon 9 versus exon 10, controlled by PTBP1 and by hnRNPA1 and hnRNPA2, yielding either the constitutively active PKM1 tetramer typical of differentiated tissue or PKM2, whose tetramer to dimer equilibrium responds to fructose 1,6-bisphosphate, serine, phosphotyrosine peptides and acetylation. The low-activity PKM2 dimer throttles the terminal glycolytic step, backing upstream intermediates into biosynthetic branches and underpinning the Warburg phenotype, with additional nuclear functions reported. Consequently, isoform-selective engineering matters more than deletion: exon-specific alleles that force PKM1 or PKM2 expression test the splicing hypothesis directly, while conditional nulls address whether the locus is required at all in a given lineage. The Pklr paralog covers liver and erythroid tissue only. Match the allele to lactate flux, biosynthetic tracing or tumor initiation endpoints with tissue-matched Cre drivers.',
  Pla2g6:
    'Membrane phospholipid remodeling depends on Pla2g6, the mouse ortholog of human PLA2G6, encoding calcium-independent phospholipase A2 beta, an ankyrin repeat containing enzyme with a canonical GXSXG lipase motif that hydrolyzes the sn-2 acyl chain of glycerophospholipids to release fatty acids and lysophospholipids. This activity governs membrane fatty acid remodeling, mitochondrial and ER membrane integrity, store-operated calcium signaling, and arachidonate supply. Recessive mutations cause infantile neuroaxonal dystrophy, atypical neuroaxonal dystrophy, and PARK14 dystonia-parkinsonism, with axonal spheroids, tubulovesicular membrane accumulation, and variable brain iron deposition. Usefully, Pla2g6 knockout and patient-type missense knockin mice do develop progressive spheroid pathology and motor decline, making constitutive null a legitimate starting allele, while catalytically dead knockins separate loss of hydrolase activity from dominant-negative effects. Conditional alleles crossed to neuronal or dopaminergic Cre lines are preferable when regional axonal degeneration rather than systemic lipid change is the endpoint.',
  Plat:
    'Plat is the mouse ortholog of human PLAT and encodes tissue-type plasminogen activator, a serine protease built from finger, EGF, two kringle, and catalytic domains that cleaves plasminogen at the Arg-Val activation bond, with fibrin acting as a template that accelerates catalysis several hundred fold. Activity is restrained by PAI-1 (Serpine1) and neuroserpin, circulating enzyme is cleared through LRP1, and in brain tPA additionally processes proBDNF and the NMDA receptor NR1 subunit, linking it to excitotoxicity and barrier opening. Because nulls are viable with only mild fibrin persistence, informative designs combine conditional deletion (endothelial, hepatocyte, or neuronal) with a thrombotic or injury challenge, whereas catalytically dead knockins separate proteolysis from receptor-mediated actions. Plau provides substantial redundancy, so compound Plat Plau animals are needed to expose the full fibrinolytic deficit, and allele class should track the endpoint, whether clot lysis, wound repair, or infarct volume.',
  Plau:
    'Encoding urokinase-type plasminogen activator, Plau is the mouse ortholog of human PLAU and produces a single-chain zymogen that binds its GPI-anchored receptor uPAR (Plaur) through an N-terminal growth factor domain, is activated by plasmin or cathepsin cleavage, and then generates plasmin at the cell surface rather than in the fluid phase. This pericellular proteolysis drives matrix degradation, latent TGF-beta and pro-MMP activation, macrophage and smooth muscle migration, and integrin plus vitronectin dependent signaling that persists even when catalysis is blocked. Consequently a conditional null tests requirement in myeloid, endothelial, or tumor compartments, an active-site knockin separates proteolysis from uPAR occupancy, and humanization of the growth factor domain is necessary for antibodies or ATF fusions that ignore mouse protein. Plat and plasma kallikrein compensate in the fluid phase, so pair Plau alleles with invasion, fibrosis, or fibrinolysis endpoints and a validated lineage Cre.',
  Plg:
    'Plg, the mouse ortholog of human PLG, encodes plasminogen, a zymogen whose five kringle domains carry lysine binding sites that dock fibrin, cell surface receptors such as Plg-RKT and annexin A2, and carboxy-terminal lysines exposed on partially degraded substrates. Cleavage by tPA or uPA converts closed, activation-resistant Glu-plasminogen into plasmin, which degrades fibrin, activates MMPs, cleaves complement C3 and C5, and liberates matrix-sequestered growth factors, while alpha 2 antiplasmin terminates the reaction. Homozygous nulls survive but develop widespread fibrin deposition, rectal prolapse, delayed wound closure, and growth failure, so complete deletion is informative yet phenotypically dominant, and conditional hepatic deletion or hypomorphic knockins give graded fibrinolytic capacity. Humanized kringle knockins matter for tranexamic acid, plasminogen replacement, or kringle-directed biologics. Match allele to readout, whether clot lysis kinetics, ligneous conjunctivitis, or complement-dependent inflammation.',
  Pmaip1:
    'Pmaip1, the mouse ortholog of human PMAIP1, encodes NOXA, a short BH3-only protein induced transcriptionally by p53, HIF1A, and ATF4 during genotoxic, hypoxic, and integrated stress responses, and it binds selectively to MCL1 and A1 rather than to BCL2 or BCL-XL. By occupying these labile guardians and promoting MCL1 turnover through MULE-dependent ubiquitination, NOXA lowers the apoptotic threshold and liberates BAK and BAX for mitochondrial outer membrane permeabilization, which explains why NOXA levels predict sensitivity to proteasome inhibitors, CDK9 blockade, and venetoclax combinations. Conditional nulls therefore test survival requirements in a defined lineage, whereas knockins that ablate the BH3 helix or stabilize the protein against degradation distinguish loss of function from persistent priming. Redundancy is genuine, since Bbc3 (PUMA), Bcl2l11 (BIM), and Bid overlap, so compound alleles are often required. Anchor allele choice to thymocyte deletion, lymphoma latency, or BH3 mimetic pharmacodynamics.',
  Pml:
    'Pml encodes the mouse ortholog of human PML (TRIM19), a RBCC tripartite motif protein whose coiled coil and SUMO to SIM interactions polymerize into PML nuclear bodies that concentrate p53, CBP, HIPK2, DAXX, and SP100 to coordinate apoptosis, senescence, antiviral responses, and stem cell quiescence. Its cardinal oncogenic role is as the 5 prime partner in t(15;17) PML-RARA, the driver of acute promyelocytic leukemia, where the fusion oligomerizes through the PML coiled coil, converts retinoic acid receptor alpha into a constitutive repressor of myeloid differentiation genes, and is uniquely susceptible to all-trans retinoic acid and to arsenic trioxide, which binds PML cysteines and triggers SUMO-dependent RNF4 degradation. Germline nulls are viable but tumor prone with impaired senescence, so conditional nulls address tumor suppressor and stem cell questions, whereas cathepsin G promoter driven or inducible PML-RARA knockins generate authentic promyelocytic leukemia. Because arsenic targeting depends on precise cysteine and SUMO site context, humanized PML alleles suit pharmacology endpoints.',
  Pms2:
    'As the endonuclease-bearing partner of MLH1 in the MutL alpha heterodimer, Pms2 (ortholog of human PMS2) executes the incision step of mismatch repair, using a conserved metal-binding endonuclease motif whose latent nickase activity is licensed by PCNA and RFC to introduce strand-discrimination nicks that direct EXO1 excision of the error-containing nascent strand. Biallelic germline loss causes constitutional mismatch repair deficiency with childhood brain tumors and hematologic malignancy, while monoallelic loss produces Lynch syndrome with microsatellite instability and a hypermutated, immunotherapy-responsive tumor genome. Null mice are viable but cancer prone and male infertile, so conditional alleles matter mainly for lineage-specific tumor initiation, whereas an endonuclease-dead knockin cleanly separates catalytic repair from the damage signaling and apoptotic functions of MutL alpha. Note that MLH1 also partners MLH3 and PMS1 in MutL gamma and MutL beta, so meiotic and somatic repair endpoints should not be treated as interchangeable.',
  Pparg:
    'Adipocyte identity depends on Pparg, the mouse ortholog of PPARG, a ligand-activated nuclear receptor that heterodimerizes with RXR alpha and occupies PPRE elements through tandem zinc fingers, while its ligand-binding domain accommodates fatty acid derivatives and thiazolidinediones and exchanges NCoR corepressor for coactivators upon agonist binding. Insulin sensitization additionally depends on blocking CDK5 and ERK phosphorylation of Ser273, which reprograms rather than simply activates the receptor. The PPARG2 isoform, carrying an extra amino-terminal segment from an upstream promoter, is adipose-restricted, so isoform-specific alleles ask different questions than pan-locus deletion. Germline null is embryonic lethal from placental vascular failure, making adipocyte, macrophage or intestinal conditional nulls mandatory, while dominant-negative knockins such as P467L reproduce familial partial lipodystrophy and Ser273 phospho-dead alleles isolate the antidiabetic mechanism. Ppara and Ppard bind overlapping ligands but cannot restore adipogenesis, so compensation is confined to lipid oxidation endpoints.',
  Ppargc1a:
    'PGC-1 alpha, encoded by Ppargc1a and orthologous to human PPARGC1A, is not a DNA-binding factor but an inducible coactivator that uses N-terminal LXXLL motifs to dock NRF1, ERR alpha, PPARs, MEF2C and nuclear hormone receptors, then recruits SRC-1, CBP and p300 plus the mediator complex to drive mitochondrial biogenesis through TFAM and oxidative gene programs. Activity is set post-translationally by AMPK phosphorylation and SIRT1-dependent deacetylation, integrating energy charge with NAD+ status, and by alternative promoter usage that yields exercise-induced amino-terminal isoforms with distinct stability. Because germline nulls are viable but show hepatic, cardiac and behavioral abnormalities, the informative designs are tissue-restricted conditional nulls in muscle, heart or brown fat and inducible overexpression alleles testing sufficiency for fiber-type switching. Ppargc1b and Pprc1 overlap partially, and combined muscle deletion produces far stronger mitochondrial phenotypes, so plan compound genetics when quantifying respiratory capacity.',
  Prkaa1:
    'Prkaa1 encodes AMPK alpha1, one of two catalytic subunits orthologous to human PRKAA1, comprising an amino-terminal kinase domain, an autoinhibitory sequence and a carboxy-terminal region that tethers the beta and gamma subunits. Activation requires Thr172 phosphorylation by LKB1 or, upon calcium flux, by CaMKK2, and is sustained allosterically when adenine nucleotide occupancy of the gamma subunit protects that site from phosphatases; downstream, the kinase phosphorylates ACC1 Ser79, TSC2, RAPTOR Ser792 and ULK1 to suppress anabolism and license autophagy. Alpha1 predominates in most tissues except skeletal muscle and liver, where alpha2 dominates, so single deletion often yields a partial phenotype and compound Prkaa1 and Prkaa2 alleles are usually necessary; combined deletion is embryonically lethal, making conditional pairs the practical route. Thr172 phospho-dead knockins separate upstream kinase input from intrinsic catalysis, which matters when interpreting metformin and direct activator studies.',
  Prkaa2:
    'Skeletal muscle, liver and the nuclear compartment rely disproportionately on AMPK alpha2, the catalytic subunit encoded by Prkaa2 and orthologous to human PRKAA2, which shares the Thr172 activation loop and LKB1 and CaMKK2 inputs with alpha1 but carries a nuclear localization signal and a distinct autoinhibitory region that tune its response to contraction and fasting. Constitutive nulls are viable yet glucose intolerant with reduced exercise-stimulated glucose uptake and blunted AICAR responses, evidence that alpha1 covers part but not all of the requirement. Design accordingly: muscle or hepatocyte conditional nulls isolate tissue-autonomous metabolic control, a dominant-negative K45R allele interrogates acute pathway suppression, and truncated constitutively active knockins test sufficiency for mitochondrial biogenesis. Because alpha1 and alpha2 heterotrimers differ mainly in subcellular distribution rather than substrate preference, quantify residual Thr172 and ACC phosphorylation before assigning any phenotype to Prkaa2 alone.',
  Prkab1:
    'The beta1 subunit, encoded by Prkab1 (human PRKAB1), is the scaffold that binds AMPK alpha and gamma subunits and positions the complex physiologically, using amino-terminal myristoylation at Gly2 for membrane and lysosomal association and a central carbohydrate-binding module that docks glycogen and dampens activity when glycogen stores are replete. Beta1 also completes the allosteric drug and metabolite site formed with the alpha subunit kinase domain, where Ser108 autophosphorylation is required for activation by A-769662, salicylate and clinical direct activators. Beta1 predominates in liver while beta2 dominates skeletal muscle, so hepatocyte-restricted conditional deletion is the informative design for glucose output and lipogenesis endpoints, whereas a Ser108 to alanine knockin cleanly distinguishes pharmacological activation from adenine nucleotide-driven activation. Because beta2 substitutes during trimer assembly, single deletion often preserves total AMPK activity, and combined beta1 and beta2 loss is required to abolish signaling in most tissues.',
  Prkab2:
    'Prkab2 encodes AMPK beta2, orthologous to human PRKAB2, a regulatory subunit that assembles obligate heterotrimers with an alpha catalytic and a gamma nucleotide-sensing subunit, contributing both the bridging module and a carbohydrate-binding domain with higher glycogen affinity than beta1, which localizes the kinase to glycogen particles in skeletal muscle and heart. This distribution makes beta2 the dominant scaffold for contraction and ischemia-driven AMPK signaling and for the muscle response to AICAR and exercise, and it accounts for reduced total muscle AMPK activity in beta2 null animals despite intact beta1. Conditional deletion in muscle or cardiomyocytes therefore addresses substrate delivery and glucose uptake, while a carbohydrate-binding module mutant separates glycogen tethering from trimer assembly, a distinction no null can make. Because beta1 partially replaces beta2 in trimer formation, plan compound Prkab1 and Prkab2 conditional genetics before attributing a metabolic phenotype to loss of one beta isoform.',
  Prkag1:
    'Nucleotide sensing in AMPK resides in the gamma subunit, and Prkag1, the ortholog of human PRKAG1, encodes the ubiquitously expressed gamma1 isoform built from four cystathionine beta-synthase domains arranged as two Bateman modules that create four adenine nucleotide sites: one permanently occupied by AMP, one nonfunctional, and two that exchange AMP, ADP and ATP to convert energy charge into conformational change. AMP or ADP binding promotes Thr172 phosphorylation by LKB1, blocks its dephosphorylation, and allosterically stimulates catalysis, so gamma1 rather than the catalytic subunit sets the sensitivity threshold. Useful alleles include conditional nulls to test trimer availability and CBS-site knockins such as the activating R70Q substitution or nucleotide-binding-dead variants, which uncouple energy sensing from kinase competence in a way pharmacology cannot. Because gamma2 and gamma3 form functional trimers in heart and muscle respectively, interpret gamma1 loss against measured isoform stoichiometry in the target tissue.',
  Prkag2:
    'Cardiac energy sensing depends heavily on Prkag2, ortholog of human PRKAG2, which encodes the gamma2 AMPK subunit distinguished by a long amino-terminal extension upstream of its four cystathionine beta-synthase domains, the modules that bind AMP, ADP and ATP and thereby set Thr172 phosphorylation and allosteric activation of the alpha subunit. Human missense mutations in the CBS repeats, classically R302Q and N488I, impair nucleotide binding and produce PRKAG2 cardiac syndrome, a glycogen storage cardiomyopathy with ventricular pre-excitation, conduction disease and hypertrophy rather than a simple loss of kinase output. Modeling that disease requires knockin of the specific human substitution, ideally Cre-inducible for adult-onset expression, because constitutive transgenic overexpression exaggerates glycogen accumulation and confounds electrophysiologic endpoints. Conditional nulls answer a different question, namely the requirement for gamma2-containing trimers in ischemic tolerance, and should be interpreted against gamma1 expression, which persists and supports baseline AMPK activity.',
  Prkn:
    'Parkin, the product of mouse Prkn and ortholog of human PRKN, is an RBR-class E3 ubiquitin ligase built from a ubiquitin-like domain followed by RING0, RING1, IBR, and RING2 modules that hold the catalytic Cys431 in an autoinhibited conformation. Binding of PINK1-generated phospho-Ser65 ubiquitin plus phosphorylation of the parkin Ubl domain releases autoinhibition, allowing thioester transfer and amplification of ubiquitin chains on outer membrane substrates including MFN1, MFN2, and MIRO, committing damaged mitochondria to mitophagy. Recessive exon deletions and missense alleles cause juvenile parkinsonism without Lewy pathology. Because Prkn nulls are viable and lack nigral cell loss, informative designs include conditional null combined with mitochondrial stress, catalytically dead C431S knockins that separate ligase activity from scaffolding, constitutively active W403A-type alleles, and humanization for activator screening. Match allele class to endpoint using dopaminergic Cre drivers and mitophagy reporters rather than expecting spontaneous degeneration.',
  Proc:
    'Encoding protein C, Proc is the mouse ortholog of human PROC and yields a vitamin K dependent zymogen with a Gla domain, two EGF modules, and a chymotrypsin-like protease domain that is activated when thrombin, presented by endothelial thrombomodulin and concentrated by EPCR, removes the activation peptide. Activated protein C then uses protein S as cofactor to proteolyze factors Va and VIIIa, shutting down thrombin amplification, and separately signals through EPCR-dependent PAR1 cleavage to stabilize endothelial barrier function and dampen NF-kB driven cytokine output. Complete deficiency in mice is perinatal lethal from consumptive coagulopathy, so severe models rely on hypomorphic alleles giving a few percent of normal activity, hepatocyte-restricted conditional deletion with Alb-Cre, or signaling-selective knockins that retain cytoprotection without anticoagulant function. Select by endpoint, whether microvascular thrombosis, sepsis survival, or permeability, since the anticoagulant and cytoprotective arms segregate genetically.',
  Pros1:
    'Pros1, the mouse ortholog of human PROS1, encodes protein S, a vitamin K dependent plasma glycoprotein with a Gla domain, thrombin-sensitive region, four EGF repeats, and a sex hormone binding globulin-like module that both accelerates activated protein C mediated inactivation of factors Va and VIIIa and serves, independently of coagulation, as an agonist for the TAM receptors MERTK, TYRO3, and AXL. Because the Gla domain binds phosphatidylserine, protein S bridges apoptotic cells to phagocyte TAM receptors, driving efferocytosis and restraining innate activation, while the SHBG region sequesters C4b-binding protein. Homozygous nulls die in utero or perinatally from fulminant coagulopathy with hemorrhage and thrombosis, making conditional deletion (hepatocyte, endothelial, or myeloid) the practical route, with humanized knockins reserved for protein S directed biologics. Gas6 partially covers TAM ligation but not anticoagulation, so add Gas6 alleles and target retinal phagocytosis, thrombin generation, or neuroinflammation endpoints.',
  Prr5:
    'Protor-1, the product of Prr5 and ortholog of human PRR5, is an accessory subunit of mTOR complex 2 that binds the complex through RICTOR rather than mTOR itself and is dispensable for complex assembly, distinguishing it from RICTOR and mSIN1, whose loss dissolves mTORC2 entirely. Its documented function is substrate-selective: Protor-1 deficiency reduces mTORC2-dependent hydrophobic motif phosphorylation and activation of SGK1 in kidney while leaving AKT Ser473 phosphorylation largely intact, making the locus a rare tool for dissociating branches of mTORC2 output. Null animals are viable and grossly normal, so constitutive deletion is acceptable and conditional alleles are needed only for lineage-specific renal or metabolic questions. The paralog Prr5l encodes Protor-2 and occupies the same RICTOR interface, so compound deletion is advisable when total SGK1 signaling is the endpoint; match allele choice to whether the question concerns complex integrity or substrate steering.',
  Psen1:
    'Gamma-secretase catalysis resides in Psen1, the mouse ortholog of human PSEN1, whose nine-transmembrane product is endoproteolyzed into N-terminal and C-terminal fragments contributing the catalytic aspartates in TM6 and TM7 to a complex containing nicastrin, APH1, and PEN2. This intramembrane aspartyl protease processively trims the APP C99 stub to generate amyloid beta peptides of varying length and cleaves Notch1, ErbB4, N-cadherin, and other type I substrates. Dominant PSEN1 mutations, the commonest cause of autosomal dominant early onset Alzheimer disease, reduce processivity and raise the Abeta42 to Abeta40 ratio rather than simply abolishing activity. Constitutive Psen1 knockout is perinatal lethal with severe somite and skeletal defects from Notch failure, so conditional null alleles are required for adult brain work, while patient missense knockins such as M146V or L166P model the disease mechanism directly. Choose humanized alleles for gamma-secretase modulator testing and pair conditionals with forebrain Cre drivers.',
  Psen2:
    'Second catalytic subunit of gamma-secretase, Psen2 is the mouse ortholog of human PSEN2 and assembles with nicastrin, APH1, and PEN2 into complexes localizing preferentially to late endosomes and lysosomes rather than the plasma membrane, giving PSEN2-containing gamma-secretase a distinct intracellular substrate pool and a documented role in mitochondria-associated ER membrane calcium handling. Rare dominant PSEN2 mutations, including N141I, cause early onset Alzheimer disease by shifting cleavage toward longer amyloid beta species. Unlike Psen1, Psen2 knockout mice are viable and fertile with only mild age-dependent pulmonary fibrosis, which makes constitutive null tractable, whereas Psen1 and Psen2 double nulls phenocopy severe Notch deficiency and die embryonically. Genuine redundancy with Psen1 therefore dictates a compound conditional strategy whenever total gamma-secretase output is the endpoint. Use patient knockins for amyloid ratio questions, conditional double alleles for substrate accumulation studies, and humanization when modulator pharmacology is the goal.',
  Ptch1:
    'Ptch1, the mouse ortholog of PTCH1, encodes a twelve-pass transmembrane receptor of the RND permease superfamily that, in the absence of ligand, catalytically restrains Smoothened by moving sterols away from the primary cilium, thereby suppressing GLI processing and pathway output. Sonic hedgehog binding, assisted by GAS1, CDON and BOC, triggers PTCH1 internalization and degradation, releasing SMO and converting GLI3 from repressor to activator. Loss of function underlies Gorlin syndrome, sporadic basal cell carcinoma and SHH-subgroup medulloblastoma, so heterozygous and conditional null alleles are the standard tumor initiation tools, while lacZ knockin reporters read pathway activity directly and remain widely used gradient readouts. Homozygous germline deletion is embryonic lethal with an open neural tube from constitutive pathway activation, mandating conditional strategies with lineage-appropriate Cre drivers. Ptch2 provides only partial repression, so compound loss sharpens tumor penetrance, particularly when modeling acquired vismodegib resistance.',
  Ptch2:
    'Sharing overall topology with PTCH1, the protein encoded by Ptch2 (human PTCH2) is a twelve-pass sterol transporter-like Hedgehog receptor that binds SHH and represses Smoothened, but with lower repressive capacity, an expression pattern enriched in skin, testis and hair follicle, and its own status as a direct GLI target, which makes it a feedback node rather than the principal ligand sink. Null animals are viable without spontaneous pathway activation, and that fact is itself the design constraint: single-locus deletion is best deployed on sensitized backgrounds rather than alone. Practical strategies therefore favor conditional nulls combined with Ptch1 heterozygosity or conditional Ptch1 loss, where compound animals show accelerated basal cell carcinoma and medulloblastoma penetrance that neither genotype produces efficiently. Reporter knockins remain useful for mapping where feedback repression operates. Match allele class to endpoint: compound conditional loss for tumor latency, single conditional loss for tissue-autonomous questions in epidermis or germline.',
  Pten:
    'Antagonism of PI3K signaling is the defining activity of Pten, ortholog of human PTEN, whose phosphatase domain dephosphorylates the 3 position of PIP3 to regenerate PIP2, collapsing PDPK1 and AKT recruitment, while its C2 domain mediates membrane binding and a carboxy-terminal tail with a PDZ-binding motif and phosphorylation cluster controls stability and the open versus closed conformation. Protein phosphatase and nuclear scaffolding activities are separable from lipid phosphatase activity, which is why the G129E lipid-dead and C124S catalytically dead knockins remain more informative than a null for mechanism. Germline deletion is embryonic lethal, and heterozygotes develop a broad tumor spectrum reflecting exquisite dose sensitivity, so conditional nulls and hypomorphic alleles that titrate expression mirror PTEN hamartoma tumor syndrome better than complete loss. Choose accordingly: conditional null with a prostate, mammary or neural Cre driver for tumor latency, missense knockin for variant interpretation and inhibitor pharmacology.',
  Pycard:
    'Pycard, the mouse ortholog of human PYCARD, encodes ASC, a bipartite adaptor whose pyrin domain nucleates prion-like filaments with activated sensors including NLRP3, NLRC4, AIM2, and pyrin, while its CARD recruits and clusters pro-caspase-1 into the dense speck where proximity-induced autoproteolysis occurs. Mature caspase-1 then processes IL-1 beta and IL-18 and cleaves gasdermin D to open plasma membrane pores, and ASC specks released from dying cells continue to mature cytokines extracellularly, making ASC a signaling node rather than a passive linker. Nulls are viable and fertile, so straight deletion cleanly reports inflammasome dependence, conditional alleles assign requirement to macrophages, neutrophils, or epithelium, and phosphosite or filament-disrupting knockins separate speck assembly from caspase recruitment. Certain NLRC4 and NLRP1 responses proceed with reduced ASC dependence, so match the allele to endpoints such as IL-1 beta release, pyroptosis kinetics, or gout and peritonitis models.',
  Rad51:
    'Strand invasion during homologous recombination is executed by RAD51, and Rad51 is the mouse ortholog of human RAD51, encoding the RecA-family recombinase that displaces RPA from resected single-stranded DNA with BRCA2 BRC repeat assistance, polymerizes into an ATP-dependent helical nucleoprotein filament, searches the sister chromatid for homology and catalyzes D-loop formation. Beyond recombination, RAD51 coats and protects stalled replication forks from MRE11 and DNA2 degradation, a function genetically separable from strand exchange. Germline deletion causes very early embryonic lethality that Trp53 loss only partially delays, so conditional nulls with inducible Cre are essential for adult analysis, while dominant-negative Walker motif mutants such as K133R or K133A permit acute, reversible interference with filament turnover. Because the paralogs RAD51B, RAD51C, RAD51D, XRCC2 and XRCC3 act as mediators rather than substitutes, they cannot rescue loss; match allele class to whether the endpoint is repair capacity, fork protection or chemosensitivity.',
  Rad52:
    'Rad52, ortholog of human RAD52, encodes a single-stranded DNA annealing protein that assembles into undecameric rings, binds RPA-coated single-stranded DNA and catalyzes complementary strand annealing, driving single-strand annealing repair and break-induced replication as well as second-end capture during homologous recombination. Unlike its budding yeast counterpart it is not the principal RAD51 mediator in mammals, a role BRCA2 fulfills, and this is precisely why the mouse null is viable and nearly phenotypically silent with only modest recombination defects. That redundancy is the central design consideration: informative models place conditional or constitutive Rad52 loss on Brca1, Brca2 or Palb2 deficient backgrounds, where RAD52 becomes a synthetic lethal dependency and a validated small molecule target. Structure-guided knockins that disrupt the annealing groove or the RPA interaction while preserving ring assembly separate mechanism from protein abundance. Select by endpoint: compound conditional genetics for synthetic lethality, point knockins for target validation.',
  Raf1:
    'Encoding CRAF, Raf1 is the mouse ortholog of human RAF1 and produces a serine and threonine kinase held autoinhibited by 14-3-3 binding at phospho-Ser259 and by its cysteine-rich domain until RAS-GTP engages the RAS-binding domain at the membrane, after which SHOC2 and PP1 dephosphorylation, Ser338 phosphorylation and side-to-side dimerization with BRAF generate an active kinase that phosphorylates MEK1 and MEK2. Germline Noonan syndrome substitutions such as S257L and S259F disrupt the 14-3-3 brake and cause hypertrophic cardiomyopathy, providing a knockin design distinct from a null, and kinase-independent functions in ASK1 and ROK alpha regulation argue for kinase-dead knockins alongside deletion. Constitutive deletion is embryonic lethal with widespread apoptosis on most backgrounds, so conditional nulls are needed for adult work. Araf and Braf occupy the same dimer interface and partially compensate, so interpret single-locus loss against dimerization-competent paralog expression in the target tissue.',
  Rara:
    'Rara is the mouse ortholog of human RARA and encodes retinoic acid receptor alpha, a nuclear receptor with AF-1, zinc finger DNA-binding, and ligand-binding domains that heterodimerizes with RXR on direct-repeat retinoic acid response elements, holds targets repressed through NCoR, SMRT, and HDAC complexes when unliganded, and switches to p300 and NCOA coactivators upon all-trans retinoic acid binding. The dominant disease logic is fusion driven, since PML-RARA in acute promyelocytic leukemia converts the receptor into a constitutive repressor that blocks myeloid maturation and is resolved pharmacologically by retinoid-induced degradation. Accordingly, allele choice diverges sharply between conditional nulls for tissue retinoid requirements, dominant-negative or PML-RARA knockins for leukemia modeling, and humanized ligand-binding domains for agonist and degrader pharmacology. Rarb and Rarg compensate extensively, and only compound receptor alleles reproduce full vitamin A deficiency phenotypes, so plan multi-locus conditional genetics with an inducible driver from the outset.',
  Rb1:
    'The prototypic tumor suppressor Rb1, ortholog of human RB1, encodes a pocket protein whose A and B domains form a cleft that binds the transactivation domain of E2F1 through E2F3 and, through a separate LXCXE-binding groove, recruits histone deacetylases and chromatin modifiers as well as viral oncoproteins including E7 and large T antigen. Sequential phosphorylation by cyclin D with CDK4 or CDK6 and then cyclin E with CDK2 releases E2F and licenses S phase entry, the axis targeted by palbociclib, and biallelic loss causes retinoblastoma and is pervasive in small cell lung cancer. Germline deletion is embryonic lethal from placental and erythroid defects, so conditional nulls are standard, and phosphorylation site or LXCXE-cleft knockins separate CDK regulation from chromatin recruitment. Critically, the paralogs Rbl1 and Rbl2 compensate robustly in mouse retina and elsewhere, so compound conditional genetics is usually required to reproduce the human tumor spectrum.',
  Rela:
    'Rela encodes p65, the ortholog of human RELA and the principal transactivating subunit of canonical NF-kappaB, which dimerizes with p50 through its Rel homology domain, is retained in the cytoplasm by IkappaB alpha, and enters the nucleus after IKK beta phosphorylates IkappaB alpha and triggers its ubiquitin-dependent degradation, with Ser536 and Ser276 phosphorylation and p300 acetylation tuning output at kappaB elements. Germline deletion is embryonic lethal at midgestation from TNF-driven hepatocyte apoptosis, a lethality rescued by concurrent Tnfrsf1a deficiency, which is a useful genetic maneuver but shifts the inflammatory baseline. Conditional nulls with hepatocyte, myeloid or intestinal epithelial Cre drivers are therefore standard for inflammation and tumor promotion endpoints, while phospho-site or transactivation domain knockins separate nuclear entry from cofactor recruitment. Rel and Relb do not substitute for p65 in canonical target induction, so compensation is limited and single-locus phenotypes are usually interpretable.',
  Relb:
    'Non-canonical NF-kappaB signaling runs through Relb, the mouse ortholog of RELB, whose product pairs almost exclusively with p52 generated by NIK and IKK alpha dependent processing of the NFKB2 p100 precursor, a slow, protein-synthesis-dependent arm activated by lymphotoxin beta receptor, CD40, BAFF receptor and RANK rather than by TNF. RELB and p52 dimers drive lymphoid organogenesis, follicular and conventional dendritic cell maturation, and thymic medullary epithelial development including Aire expression, and RELB also forms inhibited complexes with p100 that sequester it until processing occurs. Constitutive nulls are viable but develop multiorgan inflammation, splenomegaly and disorganized secondary lymphoid architecture, so conditional alleles are chiefly useful for separating stromal from hematopoietic contributions. Because p100 acts as an inhibitor as well as a precursor, pair Relb alleles with Nfkb2 processing-dead knockins when the endpoint is pathway logic rather than simple loss of the transactivator.',
  Ret:
    'Rearranged during transfection kinase, encoded by mouse Ret and orthologous to human RET, is a single-pass receptor tyrosine kinase with four cadherin-like domains and a calcium-binding cysteine-rich region that is activated by GDNF family ligands presented through GFRA1 to GFRA4 co-receptors, triggering phospholipase C gamma, RAS-ERK, and PI3K-AKT signaling essential for enteric neural crest colonization and kidney branching morphogenesis. The mutational logic is strikingly bidirectional: cysteine-rich domain substitutions such as C634R cause multiple endocrine neoplasia type 2A, activation loop M918T causes MEN2B with aggressive medullary thyroid carcinoma, CCDC6-RET and KIF5B-RET fusions drive papillary thyroid and lung adenocarcinoma, and loss-of-function alleles cause Hirschsprung disease. Germline nulls die perinatally with renal agenesis and intestinal aganglionosis, so conditional nulls suit developmental questions while precise hotspot or fusion knockins model tumorigenesis and selpercatinib or pralsetinib response, including resistance substitutions. Match allele to endpoint and use lineage-restricted Cre drivers for thyroid or pulmonary readouts.',
  Rheb:
    'Rheb, ortholog of human RHEB, encodes a farnesylated small GTPase that anchors to lysosomal membranes through its carboxy-terminal CAAX motif and, in the GTP-bound state, binds the mTOR kinase domain directly to relieve an inhibitory conformation and switch on mTORC1 phosphorylation of S6K1 and 4E-BP1. Its intrinsic hydrolysis rate is low, so pathway control is exerted almost entirely by the TSC1, TSC2 and TBC1D7 complex acting as a GTPase-activating protein, which explains why tuberous sclerosis mutations produce constitutive RHEB-GTP and rapamycin-sensitive overgrowth, and why activating substitutions such as Y35N behave as oncogenic drivers. Germline deletion is embryonic lethal, making conditional nulls the practical design for organ growth studies, while Cre-inducible Y35N knockins test sufficiency for mTORC1 activation without disturbing amino acid input through the Rag GTPases. The paralog Rhebl1 has restricted expression and does not broadly compensate, so single-locus phenotypes are generally interpretable.',
  Rictor:
    'Defining mTOR complex 2, Rictor is the ortholog of human RICTOR and encodes a large scaffold that, with mSIN1 and mLST8, confers substrate specificity for the hydrophobic motifs of AKT Ser473, SGK1 and conventional PKC isoforms, alongside a turn motif phosphorylation that stabilizes nascent AGC kinases. Unlike mTORC1, the complex resists acute rapamycin but is disassembled by prolonged exposure, which makes genetic ablation the only clean way to separate mTORC2 from pharmacologically confounded mTORC1 readouts. Germline deletion is embryonic lethal at midgestation, so conditional nulls with tissue-restricted Cre drivers are required, and running matched Rptor conditional cohorts is the standard way to attribute a phenotype to one complex rather than to the kinase itself. No paralog substitutes, though the accessory subunits Protor-1 and Protor-2 tune substrate selection, so interpret residual SGK1 signaling carefully when the endpoint is renal sodium handling or metabolic control.',
  Ripk1:
    'Ripk1 is the mouse ortholog of human RIPK1 and encodes a kinase whose N-terminal catalytic domain, ubiquitin-modified intermediate region, RHIM, and C-terminal death domain let it act as both scaffold and executioner downstream of TNFR1, TLR3, TLR4, and ZBP1. Within complex I, cIAP and LUBAC dependent ubiquitination of RIPK1 supports NF-kB and MAPK output, whereas loss of that modification allows cytosolic complex II formation, where autophosphorylated RIPK1 engages RIPK3 for necroptosis or FADD and caspase-8 for apoptosis, with caspase-8 cleavage at Asp325 serving as a brake. Nulls die perinatally from systemic inflammation, so the informative alleles are viable kinase-dead D138N knockins that isolate scaffold from catalytic function, RHIM mutants, cleavage-resistant D325A alleles, and tissue-restricted conditional deletion. Choose by endpoint, whether epidermal or intestinal inflammation, sepsis survival, or RIPK1 inhibitor pharmacodynamics, and validate the Cre driver carefully.',
  Ripk3:
    'Serving as the mouse ortholog of human RIPK3, Ripk3 encodes the obligate necroptosis kinase that oligomerizes with RIPK1, ZBP1, or TRIF through RHIM-mediated amyloid-like interactions and then phosphorylates MLKL at Thr231 and Ser345, triggering conformational change, membrane targeting, and lytic death with DAMP release. Kinase activity also supports inflammasome activation and cytokine transcription in some myeloid settings, so the protein is not purely a death switch. Genetically, nulls are viable and fertile and give clean epistasis, but kinase-dead D161N knockins are embryonic lethal because the inactive protein still assembles with RIPK1 and drives caspase-8 apoptosis, a contrast that is itself informative. Because caspase-8 restrains this axis, compound Casp8 or Mlkl alleles are frequently required for interpretation, and conditional deletion assigns requirement to intestinal epithelium, keratinocytes, or macrophages. Align allele class with ischemic injury, viral clearance, or MLKL phosphorylation endpoints.',
  Ros1:
    'Ros1 is the mouse ortholog of human ROS1 and encodes an orphan receptor tyrosine kinase, structurally related to Drosophila Sevenless, with an unusually large extracellular region of fibronectin type III and glycine-rich repeats and no validated mammalian ligand; physiologically it drives differentiation of the epididymal initial segment, and germline nulls are viable although males are infertile. Its clinical importance is entirely rearrangement driven, with CD74-ROS1, EZR-ROS1, SLC34A2-ROS1, and SDC4-ROS1 fusions retaining an intact kinase domain while the partner supplies dimerization or membrane anchoring, activating SHP2, RAS-ERK, PI3K, and STAT3 in lung adenocarcinoma, inflammatory myofibroblastic tumor, glioblastoma, and cholangiocarcinoma. Because there is no loss-of-function disease worth modeling, the informative alleles are inducible fusion knockins or humanized kinase domain replacements that support crizotinib, entrectinib, and repotrectinib pharmacology and reproduce G2032R solvent front resistance. Pair fusion expression with alveolar type II drivers such as Sftpc-creER for histologically appropriate lung tumors.',
  Rps6kb1:
    'S6 kinase 1, encoded by Rps6kb1 and orthologous to human RPS6KB1, is an AGC kinase recruited to mTORC1 through a TOS motif that binds RAPTOR, then activated by mTOR phosphorylation of the Thr389 hydrophobic motif followed by PDPK1 phosphorylation of Thr229 in the activation loop. Its substrates include ribosomal protein S6, eIF4B, PDCD4, eEF2 kinase and IRS-1, the last constituting the negative feedback loop that limits PI3K signaling and underlies paradoxical insulin sensitization by rapamycin. Nulls are viable but small with hypoinsulinemia and reduced beta cell size, so conditional alleles matter mainly for tissue-autonomous growth questions, while a Thr389 phospho-dead knockin isolates mTORC1 input from PDPK1 input in a way inhibitors cannot. Because Rps6kb2 phosphorylates overlapping substrates and is upregulated after Rps6kb1 loss, compound alleles or an Rps6 phospho-dead knockin should be planned when translation output is the endpoint.',
  Rps6kb2:
    'Rps6kb2 encodes S6 kinase 2, the ortholog of human RPS6KB2, an AGC kinase that shares the TOS motif, RAPTOR docking and mTORC1-dependent hydrophobic motif phosphorylation with S6K1 but carries a carboxy-terminal nuclear localization signal, lacks the amino-terminal extension that targets S6K1 to the nucleolus, and accounts for a substantial fraction of ribosomal protein S6 phosphorylation in many tissues. Single deletion produces essentially no growth phenotype and is accompanied by increased S6K1 activity, a compensatory relationship that is the central design consideration here, since combined Rps6kb1 and Rps6kb2 deletion causes perinatal lethality and abolishes S6 phosphorylation. Practical strategies therefore use conditional alleles at both loci with a common Cre driver, or an Rps6 serine to alanine knockin when the question concerns S6 phosphorylation rather than kinase identity. Reserve single-locus nulls for pharmacological specificity controls when validating pan-S6K inhibitors in a defined tissue.',
  Rptor:
    'Raptor, encoded by Rptor and orthologous to human RPTOR, is the substrate-presenting scaffold of mTOR complex 1, recognizing TOS motifs in S6K1, 4E-BP1 and other clients, tethering the complex to the lysosomal surface through the Rag GTPase heterodimer and Ragulator during amino acid sufficiency, and providing the surface required for FKBP12-rapamycin inhibition. It is also the node where catabolic input converges, since AMPK phosphorylation at Ser792 creates 14-3-3 binding sites that suppress mTORC1 independently of RHEB. Germline deletion is early embryonic lethal, so conditional nulls with muscle, cardiac, hepatic or immune Cre drivers are the standard tool for testing complex-specific requirements, and matched Rictor conditional cohorts distinguish mTORC1 from mTORC2 contributions. A Ser792 phospho-dead knockin isolates AMPK control from nutrient control, which is the appropriate allele when the endpoint is metabolic stress rather than growth factor signaling.',
  Runx1:
    'Definitive hematopoiesis requires Runx1, the mouse ortholog of human RUNX1 (AML1), a Runt domain transcription factor that heterodimerizes with CBFB to raise DNA affinity at core enhancer TGTGGT motifs and recruits either coactivators such as CBP or corepressors including NCOR-HDAC and GFI1 machinery, governing endothelial to hematopoietic transition, megakaryocyte maturation, and lymphoid development. Disease alleles are mechanistically diverse: germline heterozygous mutations cause familial platelet disorder with predisposition to myeloid malignancy, somatic point mutations cluster in the Runt domain in myelodysplastic syndrome and acute myeloid leukemia, and translocations generate RUNX1-RUNX1T1 or ETV6-RUNX1 chimeras that convert the factor into a dominant repressor. Because germline nulls die around midgestation lacking definitive hematopoietic stem cells, conditional nulls with Vav1-cre or Mx1-cre are essential, while knockin of Runt domain point mutants or endogenous fusion alleles addresses dominant negative mechanism. Paralogs Runx2 and Runx3 share CBFB and DNA motifs, so lineage compensation should be tested explicitly.',
  Runx1t1:
    'Corepressor function is the province of Runx1t1, the mouse ortholog of human RUNX1T1 (ETO or MTG8), a nuclear protein organized into TAFH, nervy homology, and C-terminal zinc finger modules that lacks DNA binding capacity and instead scaffolds NCOR1, SMRT, HDAC1 through HDAC3, and SIN3 machinery onto sequence-specific partners. Its central oncogenic role is as the 3 prime partner of t(8;21), where RUNX1-RUNX1T1 retains the Runt domain but replaces the RUNX1 activation domain with ETO repressor surfaces, hijacking CBFB-dependent enhancers to block myeloid differentiation; the truncated AE9a variant alone is leukemogenic in mice, whereas the full length fusion requires cooperating lesions such as Kit mutation. Design decisions therefore separate conditional nulls, which probe corepressor requirements in gut and neural development where germline loss is perinatal lethal, from inducible endogenous fusion knockins for leukemia and HDAC inhibitor endpoints. Genuine redundancy exists with paralogs Cbfa2t2 and Cbfa2t3, so compound conditional genetics prevents masked phenotypes.',
  Rxra:
    'Rxra, the mouse ortholog of human RXRA, encodes retinoid X receptor alpha, the obligate heterodimer partner for RAR, PPAR, LXR, FXR, VDR, and NR4A receptors, which makes its deletion a simultaneous collapse of multiple nuclear receptor axes rather than a single pathway lesion. As the permissive partner it contributes DNA binding at direct repeats and coregulator recruitment, and it is the pharmacological target of rexinoids such as bexarotene. Germline nulls die in mid to late gestation with myocardial thinning, ventricular hypoplasia, and placental defects, so conditional alleles with Alb-Cre, K14-Cre, LysM-Cre, or Mx1-Cre are essential to reach adult metabolic, epidermal, and myeloid endpoints. Point knockins that selectively disable ligand binding or the heterodimer interface separate structural partnering from ligand-dependent activation, and humanized ligand-binding domains support rexinoid pharmacology. Rxrb and Rxrg substitute in several tissues, so compound conditional deletion is often required before assigning a phenotype to Rxra.',
  S100a12:
    'S100a12 is a special case among immune loci, because the human gene S100A12 encodes calgranulin C (EN-RAGE) yet mice carry no functional ortholog, the sequence having been lost from the syntenic S100 cluster, so there is no endogenous mouse gene to delete. The human protein is a calcium and zinc binding EF-hand dimer released abundantly by activated neutrophils that signals through RAGE and TLR4 to drive mast cell activation, monocyte recruitment, and endothelial adhesion molecule expression, which is why serum and fecal levels track Kawasaki disease, inflammatory bowel disease, and vasculitis activity. Modeling therefore requires knockin of the human coding sequence at a defined locus or expression from a neutrophil-restricted regulatory region, with a zinc-binding-deficient variant as the matched control. Because Ager and Tlr4 also transduce S100A8 and S100A9 signals, combine humanized alleles with those genotypes and with neutrophil influx or RAGE blockade endpoints.',
  S100a8:
    'S100a8, the mouse ortholog of human S100A8, encodes MRP8 (calgranulin A), a small EF-hand protein that heterodimerizes obligately with S100A9 to form calprotectin, the dominant cytosolic cargo of neutrophils and inflammatory monocytes. Released calprotectin chelates zinc and manganese to starve bacteria and fungi, engages TLR4 and RAGE to amplify NF-kB driven cytokine output and endothelial activation, and promotes myeloid-derived suppressor cell accumulation in tumors, while intracellularly the complex supports NADPH oxidase assembly and tubulin dynamics. Notably, germline S100a8 disruption has been reported as early embryonic lethal with resorption, whereas S100a9 nulls are viable and lack detectable S100A8 protein because the partner is unstable alone, so conditional or myeloid-restricted deletion is the safer design. Zinc-binding or dimer-interface knockins separate nutritional immunity from receptor signaling. Fit alleles to bacterial clearance, arthritis severity, or calprotectin biomarker endpoints.',
  S100a9:
    'Encoding MRP14 (calgranulin B), S100a9 is the mouse ortholog of human S100A9 and pairs with S100A8 through a hydrophobic interface to build the calprotectin heterodimer, then assembles into calcium-dependent tetramers that are the receptor-active species for TLR4 and RAGE. The protein carries a C-terminal extension with an additional metal site and a phosphorylation-regulated segment, and it directs the complex to membranes and to the NADPH oxidase during neutrophil activation, while extracellular tetramers drive chemotaxis, beta 2 integrin affinity maturation, and metal sequestration that restricts microbial growth. Nulls are viable but lose S100A8 protein as well, which confounds subunit-specific conclusions and argues for tetramerization-deficient or metal-site knockins alongside myeloid conditional alleles. Because mice lack S100a12, calgranulin biology cannot be fully reconstructed without human transgenes. Match the allele to endpoints such as sepsis mortality, autoimmune arthritis, or tumor myeloid suppression.',
  Scn1a:
    'Interneuron excitability in mouse depends on Scn1a, ortholog of human SCN1A, encoding the Nav1.1 pore-forming alpha subunit assembled from four homologous domains, each contributing six transmembrane segments with an S4 voltage sensor and a re-entrant P loop, plus the DIII to DIV linker carrying the IFM fast inactivation particle. Nav1.1 is enriched in the axon initial segment of parvalbumin and somatostatin interneurons, so haploinsufficiency preferentially silences inhibition and produces the disinhibition seen in Dravet syndrome, while milder missense alleles cause GEFS+ and specific gain of function variants cause familial hemiplegic migraine 3. Allele class maps precisely onto question: heterozygous conditional null models Dravet dosage, patient knockins such as R1648H or A1783V test channel biophysics, and humanized alleles enable antisense or gene therapy testing. Homozygous nulls die by roughly postnatal day 15 and seizure severity is strongly background dependent, so fix strain and choose interneuron-restricted Cre carefully.',
  Scn1b:
    'Beyond the pore, Scn1b encodes the mouse ortholog of human SCN1B, a single-pass immunoglobulin domain beta subunit that noncovalently associates with sodium channel alpha subunits, modulates gating kinetics and voltage dependence, promotes surface trafficking, and acts as a homophilic adhesion molecule at nodes of Ranvier and the axon initial segment, interacting with contactin, neurofascin, and ankyrin. Its ectodomain is a substrate for BACE1 and gamma-secretase, releasing an intracellular fragment with transcriptional activity. Biallelic SCN1B loss causes developmental and epileptic encephalopathy 52, while heterozygous variants produce GEFS+ and cardiac conduction or Brugada phenotypes. Scn1b null mice are informative because they display spontaneous seizures, ataxia, and death around weaning, so lethality timing constrains study windows and argues for conditional alleles when adult circuits are the target. Patient missense knockins separate adhesion from gating, and cell-type-restricted Cre choice determines whether neuronal or cardiac endpoints dominate.',
  Scn2a:
    'Axon initial segment excitability in immature and unmyelinated excitatory neurons is set by Scn2a, the mouse ortholog of human SCN2A, encoding Nav1.2, a four-domain alpha subunit whose S4 sensors, IFM inactivation motif, and ankyrin-G binding motif in the DII to DIII linker determine localization and firing. Developmentally Nav1.2 dominates the proximal segment early and is progressively replaced distally by Nav1.6, while retaining roles in dendritic backpropagation and plasticity. The genotype-phenotype logic is unusually clean: gain of function variants produce early infantile epileptic encephalopathy responsive to sodium channel blockers, whereas loss of function alleles cause autism and intellectual disability with later-onset or absent seizures. Designs therefore split between heterozygous conditional null for the haploinsufficiency arm and defined missense knockins for the gain of function arm, with humanization enabling antisense upregulation strategies. Homozygous nulls die perinatally from hypoxia, so heterozygous or conditional approaches are mandatory.',
  Scn2b:
    'Disulfide-linked to the sodium channel alpha subunit, the product of mouse Scn2b, ortholog of human SCN2B, is a covalently attached immunoglobulin fold beta subunit that increases channel surface density, shifts inactivation voltage dependence, and contributes extracellular matrix and adhesion interactions at the node. Like beta1, beta2 is sequentially cleaved by BACE1 and gamma-secretase, coupling amyloidogenic processing to sodium current density. Human SCN2B variants associate with Brugada syndrome, atrial fibrillation, and epilepsy. Scn2b null mice are viable and fertile but show reduced sodium current density, lowered seizure threshold, altered nociception, and cardiac conduction abnormalities, so a constitutive null is a reasonable first allele. Where finer dissection is needed, floxed alleles crossed to neuronal or cardiomyocyte Cre lines separate central from cardiac contributions. Because Scn1b, Scn3b, and Scn4b provide partially overlapping modulation, compound alleles are advisable when total beta subunit function rather than isoform identity is the endpoint.',
  Scn3b:
    'Among the sodium channel beta subunits, Scn3b encodes the mouse ortholog of human SCN3B, a noncovalently associating immunoglobulin domain protein that modulates Nav alpha subunit gating by shifting steady-state inactivation, accelerating recovery from inactivation, and enhancing surface trafficking, with prominent expression in heart, dorsal root ganglia, and brain. It is also a p53 target gene and a substrate for BACE1 and gamma-secretase. Human SCN3B mutations cause Brugada syndrome and have been implicated in atrial fibrillation and sudden death, while the neuronal contribution is less penetrant. Scn3b knockout mice are viable and display arrhythmia susceptibility with modest neuronal excitability changes, so constitutive null is tractable and conditional alleles serve mainly to separate cardiac from neural contributions. Because Scn1b, Scn2b, and Scn4b overlap functionally, expect compensation and plan compound alleles. Use patient missense knockins when trafficking defects rather than complete absence are the mechanism under test.',
  Scn8a:
    'Resurgent sodium current and high-frequency repetitive firing depend on Scn8a, the mouse ortholog of human SCN8A, encoding Nav1.6, the alpha subunit concentrated at nodes of Ranvier and the distal axon initial segment where its low activation threshold and persistent current component drive action potential initiation. Nav1.6 behavior is shaped by beta4 subunit open-channel block that generates resurgent current, and by FGF14 and ankyrin-G interactions. Gain of function missense variants such as R1872W and N1768D cause developmental and epileptic encephalopathy 13, whereas loss of function alleles produce intellectual disability, ataxia, and movement disorder, a duality that dictates allele design. Conditional null alleles model haploinsufficiency and can be restricted to excitatory neurons or Purkinje cells, patient knockins model epileptogenic gain of function, and humanized alleles support antisense knockdown testing. Homozygous nulls, exemplified by the classic med mutant, develop progressive paralysis and die by weaning, so heterozygous or conditional strategies are required.',
  Scn9a:
    'Nociceptor threshold setting is the province of Scn9a, the mouse ortholog of human SCN9A, encoding Nav1.7, a tetrodotoxin-sensitive alpha subunit expressed in dorsal root and trigeminal ganglion neurons and sympathetic neurons, where slow closed-state inactivation lets it amplify subthreshold depolarizations and act as a threshold channel. Human genetics is unusually decisive: biallelic loss of function produces congenital insensitivity to pain with anosmia, while gain of function missense alleles cause inherited erythromelalgia (hyperpolarized activation) and paroxysmal extreme pain disorder (impaired fast inactivation). Global Scn9a nulls die shortly after birth, so conditional alleles crossed to Advillin-Cre, Nav1.8-Cre, or Wnt1-Cre are standard for adult pain phenotyping, while patient knockins such as I848T model gain of function pharmacology and humanized alleles enable selective blocker and antibody testing. Compensation from Scn10a and Scn11a within the same neurons is real, so match allele class to behavioral or electrophysiological endpoints accordingly.',
  Sdha:
    'Sdha is the mouse ortholog of human SDHA and encodes the flavoprotein catalytic subunit of succinate dehydrogenase, the only enzyme shared by the TCA cycle and the electron transport chain, which oxidizes succinate to fumarate using a covalently bound FAD attached through a histidyl linkage installed by the SDHAF2 flavinylation factor. Electrons pass from FAD into the iron-sulfur relay of SDHB and onward to ubiquinone at the membrane anchor formed by SDHC and SDHD. Biallelic hypomorphic alleles cause Leigh syndrome and cardiomyopathy, whereas heterozygous germline loss with a somatic second hit predisposes to paraganglioma, gastrointestinal stromal tumor and renal tumors through succinate accumulation that inhibits alpha-ketoglutarate-dependent dioxygenases. Design accordingly: patient-matched knockins model the recessive bioenergetic disease, while conditional nulls in chromaffin or neural crest lineages model the tumor suppressor arm. No paralog substitutes. Match allele to succinate to fumarate ratio, DNA hypermethylation or pseudohypoxic HIF signaling endpoints.',
  Sdhaf1:
    'Encoding a LYR-motif assembly factor for succinate dehydrogenase, Sdhaf1 is the mouse ortholog of human SDHAF1 and works with the HSC20 and HSPA9 chaperone system to deliver and insert iron-sulfur clusters into the SDHB subunit, a step that must precede docking of SDHB onto the flavinylated SDHA protomer. Because the factor acts catalytically rather than structurally, its loss leaves SDHA intact but yields unstable, cluster-deficient SDHB and an assembly-incompetent complex II, and human biallelic mutations produce infantile leukoencephalopathy with brain succinate accumulation detectable by magnetic resonance spectroscopy. The allele fork follows: patient-matched missense knockins recapitulate the hypomorphic white matter disease and permit longitudinal spectroscopy, whereas a conditional null asks where complex II assembly is rate limiting in specific lineages. Partial functional overlap with Sdhaf3 in iron-sulfur maturation is documented, so consider compound alleles. Align allele class with in-gel complex II activity, succinate levels or myelin histopathology endpoints.',
  Sdhaf2:
    'Sdhaf2, the mouse ortholog of human SDHAF2 and also known as SDH5, encodes the assembly factor that catalyzes covalent attachment of FAD to a conserved histidine of the SDHA flavoprotein, a prerequisite for succinate oxidation and for productive assembly of the complex II holoenzyme. Without flavinylation, SDHA remains catalytically dead and the enzyme fails to form, uncoupling the TCA cycle from ubiquinone reduction and driving succinate accumulation. In humans, germline mutation causes hereditary paraganglioma type 2 with a striking parent-of-origin pattern in which disease manifests almost exclusively upon paternal transmission, a feature that must be built into breeding design rather than assumed. Conditional nulls in neural crest or chromaffin lineages therefore model the tumor predisposition arm, while patient-matched knockins address partial flavinylation and residual complex II activity. The other assembly factors, SDHAF1, SDHAF3 and SDHAF4, act at distinct steps and do not substitute. Match allele to succinate ratio, HIF signaling or tumor incidence endpoints.',
  Sdhaf3:
    'Sdhaf3, ortholog of human SDHAF3, encodes a LYR-motif mitochondrial assembly factor that cooperates with SDHAF1 in maturing and protecting the iron-sulfur clusters of the SDHB subunit during complex II biogenesis, shielding nascent clusters from oxidative damage before SDHB joins the flavinylated SDHA protomer. Loss lowers assembled complex II, raises succinate and increases sensitivity to oxidative stress, phenotypes first mapped in yeast and Drosophila and subsequently linked to reduced succinate dehydrogenase activity in mammalian systems, with rare human variants proposed to contribute to paraganglioma risk. Because the factor is transient and catalytic, a conditional null is the informative allele for asking where assembly capacity limits complex II in vivo, while humanization supports biochemical reconstitution and testing of variants of uncertain significance. Functional overlap with Sdhaf1 in cluster delivery is genuine, so a compound conditional design avoids masked phenotypes. Choose blue native in-gel activity, succinate to fumarate ratio and oxidative stress markers as endpoints.',
  Sdhaf4:
    'Sdhaf4 is the mouse ortholog of human SDHAF4 and encodes a small assembly factor for succinate dehydrogenase that binds the SDHA flavoprotein after covalent FAD attachment, chaperoning it toward productive association with SDHB while preventing the free flavinylated subunit from generating superoxide through futile succinate oxidation. Loss therefore produces a dual defect, reduced assembled complex II plus elevated reactive oxygen species from unpartnered SDHA, a phenotype demonstrated in yeast and Drosophila models with locomotor impairment and shortened lifespan, and human biallelic variants have been associated with mitochondrial disease. The allele fork is straightforward: a conditional null tests where chaperone capacity limits complex II assembly and whether the ROS arm or the bioenergetic arm dominates in a given tissue, while humanization supports variant functional testing. The other SDH assembly factors act at separate steps and do not cover this role. Select drivers and endpoints together, pairing neuronal or muscle Cre lines with respirometry and superoxide readouts.',
  Sdhb:
    'Sdhb, the mouse ortholog of human SDHB, encodes the iron-sulfur subunit of complex II, carrying the [2Fe-2S], [4Fe-4S] and [3Fe-4S] clusters that form the electron relay from the FAD of SDHA to the ubiquinone site created by SDHC and SDHD. Germline loss-of-function alleles combined with somatic loss of the wild-type copy define one of the strongest tumor suppressor mechanisms in paraganglioma, pheochromocytoma, gastrointestinal stromal tumor and renal cell carcinoma, and carriers show a notably high rate of metastatic disease. The mechanism is metabolite driven: accumulated succinate competitively inhibits alpha-ketoglutarate-dependent dioxygenases including TET demethylases, KDM histone demethylases and PHD prolyl hydroxylases, producing a hypermethylator phenotype and pseudohypoxic HIF stabilization. Conditional nulls in chromaffin or neural crest lineages are therefore the tumor-relevant design, while knockins model hypomorphic bioenergetic disease. No paralog substitutes. Match the allele to methylome, HIF target or tumor latency endpoints and validate lineage-specific Cre expression.',
  Sdhc:
    'The larger of the two integral membrane subunits of complex II is specified by Sdhc, the mouse ortholog of human SDHC, which together with SDHD coordinates a single heme b and forms the ubiquinone-binding pocket that accepts electrons emerging from the [3Fe-4S] cluster of SDHB, thereby anchoring the soluble catalytic dimer to the inner membrane. Mutations that distort this pocket both block succinate-driven quinone reduction and promote electron leak, and germline loss causes hereditary paraganglioma type 3 as well as succinate dehydrogenase deficient gastrointestinal stromal tumor, acting through succinate accumulation and consequent inhibition of alpha-ketoglutarate-dependent dioxygenases. Model design should separate the tumor suppressor question from the bioenergetic one: conditional nulls in neural crest or chromaffin lineages address the former, while patient-matched missense knockins retaining partial quinone binding address respiratory capacity and ROS. Neither SDHD nor the assembly factors compensate for this subunit. Match allele class to succinate to fumarate ratio, hypermethylation and tumor incidence endpoints.',
  Sdhd:
    'Sdhd is the mouse ortholog of human SDHD and encodes the small membrane anchor subunit of complex II that partners with SDHC to coordinate the heme b group and complete the ubiquinone-binding site through which electrons leave the SDHB iron-sulfur relay. Germline mutation causes hereditary paraganglioma type 1, and the phenotype shows a well-documented parent-of-origin effect in which tumors arise almost exclusively after paternal transmission, so breeding scheme and allele inheritance must be designed explicitly rather than treated as incidental. Mechanistically, succinate accumulation inhibits alpha-ketoglutarate-dependent dioxygenases, stabilizing HIF and reshaping the methylome to produce pseudohypoxic, hypermethylated tumors. Conditional nulls restricted to chromaffin cells or carotid body lineages therefore model tumorigenesis, while patient-matched knockins address partial complex II activity and oxygen sensing. No other subunit substitutes for the anchor function. Match the allele to carotid body hyperplasia, catecholamine output, HIF target expression or tumor latency endpoints.',
  Serpinc1:
    'Serpinc1, the mouse ortholog of human SERPINC1, encodes antithrombin, the principal plasma serpin that neutralizes thrombin, factor Xa, and factor IXa by presenting an Arg-Ser reactive center loop that is captured as a covalent acyl-enzyme complex. Heparin and endothelial heparan sulfate bind the D-helix, inducing an allosteric shift and template bridging that accelerates thrombin inhibition several thousand fold, the mechanistic basis of heparin therapy and the site disrupted in human heparin binding site variants. Complete deficiency is embryonic lethal at midgestation with fibrin deposition in myocardium and liver, so viable models use hypomorphic knockins, human deficiency-mimicking point mutations, or hepatocyte-restricted deletion driven by Alb-Cre or AAV-Cre. Humanized alleles are essential for testing antithrombin-lowering agents developed for hemophilia rebalancing. Match allele class to endpoint, whether spontaneous venous thrombosis, thrombin generation assays, or bleeding correction in a factor-deficient background.',
  Serpind1:
    'Serpind1 is the mouse ortholog of human SERPIND1 and encodes heparin cofactor II, a plasma serpin that inhibits thrombin through a Leu-Ser reactive center and is accelerated up to a thousand fold by dermatan sulfate, which binds a basic surface and releases an acidic N-terminal extension that then engages thrombin anion-binding exosite II. This dermatan sulfate dependence localizes activity to the subendothelial matrix rather than the luminal heparan sulfate compartment served by antithrombin, giving heparin cofactor II a distinct role after vessel injury. Nulls are viable and fertile with normal baseline hemostasis but show accelerated thrombus formation after photochemical or ferric chloride carotid injury, so germline deletion is informative while hepatocyte conditional alleles pin the source. Glycosaminoglycan-binding or reactive center loop knockins separate cofactor dependence from intrinsic inhibition. Since Serpinc1 dominates fluid-phase thrombin control, interpret accordingly and align alleles with arterial injury or restenosis endpoints.',
  Serpine1:
    'Encoding plasminogen activator inhibitor 1, Serpine1 is the mouse ortholog of human SERPINE1 and produces a metastable serpin that forms covalent complexes with tPA and uPA, then spontaneously relaxes into an inactive latent conformation within one to two hours unless bound by vitronectin, which stabilizes the active form in matrix and platelets. Transcription is driven by TGF-beta and SMAD3, hypoxia through HIF1A, and senescence programs, placing PAI-1 at the intersection of fibrinolytic shutdown, fibrosis, adipose remodeling, and cellular senescence, and human loss of function causes a bleeding diathesis with accelerated clot lysis. Nulls are viable with mild hyperfibrinolysis, so germline deletion is tractable, conditional alleles assign the source to hepatocytes, adipocytes, endothelium, or platelets, and vitronectin-binding or reactive center loop knockins dissociate protease inhibition from adhesion effects. Select by endpoint, whether pulmonary or renal fibrosis, clot lysis time, or metabolic and lifespan readouts.',
  Serpinf1:
    'Serpinf1, the mouse ortholog of human SERPINF1, encodes pigment epithelium derived factor, a non-inhibitory serpin whose reactive center loop is proteolytically nonfunctional and which instead uses an asymmetric charge distribution to bind collagen I and glycosaminoglycans on one face and laminin receptor plus PNPLA2 on the other. Through those interactions PEDF acts as a potent endogenous antiangiogenic and neurotrophic factor, inducing endothelial FAS dependent apoptosis and dampening VEGF signaling, while in bone it is required for osteoid mineralization, so recessive human loss of function causes osteogenesis imperfecta type VI with normal collagen but defective matrix mineralization. Nulls are viable and reproduce low bone mass with increased retinal and pancreatic vascularity, making germline deletion useful, while receptor-binding-domain knockins separate antiangiogenic from lipase-modulating and neurotrophic activities and conditional alleles isolate retinal pigment epithelium or osteoblast sources. Anchor the allele to choroidal neovascularization, bone mineral density, or photoreceptor survival endpoints.',
  Serpinf2:
    'Serpinf2 is the mouse ortholog of human SERPINF2 and encodes alpha 2 antiplasmin, the fastest known plasmin inhibitor, which uses a reactive center loop to form a covalent complex with the plasmin active site while two flanking extensions dictate physiology: an N-terminal glutamine that factor XIIIa crosslinks onto fibrin alpha chains, and a C-terminal lysine-rich tail that docks plasminogen kringles and delivers the inhibitor to the clot surface. This architecture makes alpha 2 antiplasmin the dominant brake on fibrinolysis, and human deficiency produces delayed bleeding after trauma or surgery despite normal coagulation screens. Nulls are viable and fertile with markedly enhanced endogenous clot lysis, so germline deletion is a clean gain-of-fibrinolysis tool, while crosslinking-site or C-terminal truncation knockins separate fibrin anchoring and plasminogen binding from intrinsic inhibition and hepatocyte conditional alleles define the plasma source. Match alleles to pulmonary embolism resolution, rebleeding, or antifibrinolytic drug endpoints.',
  Serping1:
    'Serping1, the mouse ortholog of human SERPING1, encodes C1 inhibitor, a heavily glycosylated serpin with a long mucin-like N-terminal domain that inactivates C1r and C1s in the classical pathway, MASP1 and MASP2 in the lectin pathway, and, critically for disease, plasma kallikrein and factor XIIa in the contact system. Loss of one functional allele produces hereditary angioedema type I through low protein levels and type II through dysfunctional reactive center loop variants, and in both cases unrestrained kallikrein liberates bradykinin from high molecular weight kininogen to cause bradykinin B2 receptor dependent vascular leak. Because heterozygous insufficiency drives the human phenotype, heterozygous or hypomorphic knockins recapitulate disease better than complete nulls, which are viable but display constitutive leak, and humanized alleles are needed to test C1 inhibitor concentrates or kallikrein-directed antibodies. Compensation by other serpins is limited, so use extravasation, plasma kallikrein activity, or complement consumption endpoints.',
  Setd2:
    'Setd2 encodes the mouse ortholog of human SETD2, the sole methyltransferase that trimethylates histone H3 lysine 36 in mammals, coupling to transcription through an SRI domain that docks on the phosphorylated C-terminal domain of elongating RNA polymerase II and thereby governing co-transcriptional splicing, MSH6-dependent mismatch repair recruitment, homologous recombination, and suppression of cryptic intragenic initiation; it additionally methylates alpha tubulin K40 during mitosis. Truncating mutations are enriched in clear cell renal carcinoma, where 3p loss removes SETD2 together with VHL, BAP1, and PBRM1, and also recur in leukemia, glioma, and pediatric high grade astrocytoma, making loss of function with H3K36me3 depletion the defining event. Germline nulls die in midgestation from vascular remodeling failure, so conditional nulls are required, ideally with Pax8-cre or Ksp-cadherin-cre plus concurrent Vhl deletion to reconstruct renal tumor genetics. Catalytically dead SET knockins separate methyltransferase output from scaffold roles, and no paralog restores H3K36me3, so single-locus deletion is interpretable.',
  Setx:
    'Co-transcriptional R-loop resolution requires Setx, the mouse ortholog of human SETX, encoding senataxin, a large superfamily 1 helicase with a C-terminal DNA and RNA helicase domain and an N-terminal protein interaction region contacting RNA polymerase II, the RNA exosome, and DNA damage response factors. Senataxin unwinds RNA:DNA hybrids at transcription termination sites and at collisions between transcription and replication, limiting genome instability and supporting antisense transcript degradation and meiotic sex chromosome inactivation. Disease logic splits cleanly: recessive loss of function causes ataxia with oculomotor apraxia type 2, while dominant L389S and R2136H alleles cause juvenile ALS4 through an apparent gain or change of function. Allele design must therefore separate conditional null from dominant point knockins, since these model different diseases. Note that Setx null males are sterile with meiotic arrest, so conditional deletion with a neuronal Cre is preferable when motor neuron or cerebellar endpoints are the focus.',
  Sf3b1:
    'Splicing fidelity depends on Sf3b1, the mouse ortholog of human SF3B1, the largest subunit of the SF3b module of the U2 small nuclear ribonucleoprotein, built from twenty HEAT repeats that clamp the pre-messenger RNA branch point adenosine and stabilize U2 snRNA duplex formation during A complex assembly, with PHF5A and SF3B3 completing the pocket targeted by pladienolide and related modulators. Cancer-associated mutations are heterozygous, mutually exclusive missense changes, chiefly K700E in myelodysplastic syndrome with ring sideroblasts and in chronic lymphocytic leukemia, and R625 substitutions in uveal melanoma, acting as change of function by promoting cryptic 3 prime splice site selection and nonsense-mediated decay of transcripts such as Abcb7 and Map3k7. Consequently, conditional heterozygous hotspot knockins are the only faithful design, since homozygous mutant and null alleles are lethal, and induction with Mx1-cre or Vav1-cre reproduces dysplastic erythropoiesis. Match allele class to endpoint, whether mis-splicing catalogs, sideroblastic phenotype, or spliceosome modulator sensitivity.',
  Shank1:
    'Postsynaptic density scaffolding at excitatory synapses depends on Shank1, the mouse ortholog of human SHANK1, a master scaffold containing ankyrin repeats, an SH3 domain, a PDZ domain that binds GKAP/SAPAP and thereby couples to PSD-95 and NMDA receptors, a proline-rich region engaging Homer and cortactin, and a C-terminal SAM domain that polymerizes into zinc-dependent sheets forming the PSD lattice. Through Homer it links metabotropic glutamate receptors to IP3 receptors, and through cortactin it links to actin and spine morphology. SHANK1 deletions associate with autism spectrum disorder, generally with milder cognitive impact than SHANK3. Shank1 nulls are viable with smaller spines, thinner postsynaptic densities, reduced basal transmission, and altered learning, so constitutive null is workable while conditional alleles allow cell-type dissection. Because Shank2 and Shank3 share domain architecture and partially overlap, compound alleles may be needed when total scaffold capacity rather than isoform-specific function is the endpoint.',
  Shank2:
    'Within the SHANK scaffold family, Shank2 encodes the mouse ortholog of human SHANK2, also called ProSAP1, organizing the postsynaptic density through ankyrin repeats, SH3, PDZ, proline-rich Homer and cortactin binding segments, and a zinc-sensitive SAM domain, with multiple internal promoters generating isoforms differing in N-terminal content and synaptic targeting. SHANK2 couples GKAP/SAPAP and PSD-95 to actin regulators, controlling AMPA and NMDA receptor content, spine maturation, and mGluR coupling. Heterozygous deletions and truncating SHANK2 variants cause autism and intellectual disability, and exon-specific mouse mutants recapitulate hyperactivity, repetitive grooming, and social deficits with NMDA receptor hypofunction or hyperfunction depending on which exons are removed. That exon dependence is the key design point: choose deleted exons to match the human variant, and separate conditional null from patient missense knockins. Given real overlap with Shank1 and Shank3, plan compound conditional genetics and pair Cre drivers to striatal or cortical endpoints.',
  Shank3:
    'Deletion of Shank3, the mouse ortholog of human SHANK3, is the principal genetic driver of Phelan-McDermid syndrome arising from 22q13.3 loss, and the gene encodes the most abundant SHANK scaffold in striatal and cortical postsynaptic densities, with ankyrin repeats, SH3, a PDZ domain binding GKAP/SAPAP, proline-rich Homer and cortactin sites, and a SAM domain that polymerizes the PSD lattice. Multiple intragenic promoters and extensive alternative splicing generate isoforms with distinct localization, which is why different exon-specific mouse lines produce divergent synaptic and behavioral phenotypes. Haploinsufficiency reduces AMPA and NMDA receptor content, impairs corticostriatal transmission, and produces repetitive grooming and social deficits. Allele planning must specify exact exons, choosing conditional null for reversibility studies, isoform-selective deletion matched to patient breakpoints, truncating knockins, or humanization for oligonucleotide and gene therapy testing. Partial redundancy with Shank1 and Shank2 argues for compound alleles when total scaffold capacity is the endpoint.',
  Shc1:
    'Three isoforms, p46, p52 and p66, arise from Shc1, the ortholog of human SHC1, through alternative translation initiation and promoter use; all share a phosphotyrosine-binding domain and an SH2 domain that engage NPXY motifs on activated receptor tyrosine kinases, plus a CH1 region whose Tyr239, Tyr240 and Tyr317 phosphorylation recruits GRB2 and SOS1 to load RAS and activate ERK. The p66 isoform is functionally distinct, carrying a CH2 extension whose Ser36 phosphorylation under oxidative stress promotes mitochondrial translocation, cytochrome c oxidation and hydrogen peroxide generation, linking the locus to oxidative stress resistance and lifespan. Because pan-locus deletion is embryonic lethal with cardiovascular defects, adult questions require conditional nulls, whereas isoform-selective p66 knockouts are viable and are the correct allele for aging and redox endpoints. The paralogs Shc2, Shc3 and Shc4 have restricted neural and muscle expression and do not broadly compensate, so tissue context should guide interpretation.',
  Shh:
    'Shh is the mouse ortholog of human SHH and encodes Sonic hedgehog, which autoprocesses to attach cholesterol to the carboxy terminus of its signaling fragment and receives palmitate at Cys24 from HHAT, then depends on DISP1 and SCUBE2 for release before binding PTCH1 with the coreceptors CDON, BOC, and GAS1 to relieve SMO inhibition and shift ciliary GLI processing from GLI3 repressor toward activator forms. It patterns the ventral neural tube as floor plate signal and specifies digit identity from the zone of polarizing activity, and human mutations cause holoprosencephaly type 3 while pathway-activating PTCH1 and SMO lesions drive basal cell carcinoma and medulloblastoma. Nulls die with cyclopia and severe midline defects, so conditional deletion, holoprosencephaly missense knockins, and ZRS limb enhancer alleles each answer distinct questions. Ihh and Dhh overlap in gut and gonad, and Shh-Cre lines double as lineage drivers worth validating before use.',
  Sigmar1:
    'At mitochondria-associated ER membranes, the product of mouse Sigmar1, ortholog of human SIGMAR1, functions as a ligand-operated chaperone rather than a classical receptor, forming an ER membrane protein that associates with BiP and, upon agonist binding or calcium depletion, dissociates to stabilize IP3 receptor type 3 and sustain calcium transfer from ER to mitochondria. Sigma-1 receptor also chaperones ion channels, modulates the unfolded protein response through IRE1, and translocates to the nuclear envelope and plasma membrane. Recessive E102Q causes juvenile ALS16 and other variants cause distal hereditary motor neuropathy, with loss of contact site integrity, calcium dysregulation, and impaired autophagic flux as proposed mechanisms. Because Sigmar1 knockout mice are viable with late-onset motor deficits, both conditional null and patient knockin alleles are practical, and humanization is attractive given active agonist pharmacology such as pridopidine. Select motor neuron Cre drivers when contact site integrity and neuromuscular junction endpoints matter.',
  Sirpa:
    'Encoding signal regulatory protein alpha (CD172a), Sirpa is the mouse ortholog of human SIRPA and presents three extracellular immunoglobulin domains, of which the polymorphic IgV domain binds CD47, plus a cytoplasmic tail with two ITIMs that recruit SHP-1 and SHP-2 to block phagocytic cup maturation and myosin IIA accumulation in macrophages, neutrophils, and dendritic cells. This CD47 to SIRPA axis is the dominant myeloid checkpoint that tumors exploit, and it is under strong species constraint because mouse SIRPA binds human CD47 poorly, which is exactly why humanized IgV knockin strains greatly improve human hematopoietic engraftment in immunodeficient hosts. Design forks sharply: conditional nulls or cytoplasmic truncations test ITIM-dependent inhibition in a defined myeloid lineage, whereas full ectodomain humanization is mandatory for anti-SIRPA or CD47 blocking antibodies and xenograft work. Related Sirpb1 and Sirpg do not restore inhibitory signaling, so target red cell clearance, antibody-dependent phagocytosis, or engraftment endpoints.',
  Sirt1:
    'Sirt1, ortholog of human SIRT1, encodes an NAD+ dependent class III deacetylase whose catalytic core couples removal of acetyl groups to cleavage of NAD+ into nicotinamide and 2-O-acetyl-ADP-ribose, making activity a direct function of cellular NAD+ and a target of nicotinamide product inhibition. Substrates include p53 Lys382, FOXO factors, PGC-1 alpha, NF-kappaB p65 Lys310 and histone H4 Lys16, placing the enzyme at the intersection of stress response, mitochondrial biogenesis and inflammatory transcription, and it is allosterically activated by resveratrol-class compounds through an amino-terminal domain in a substrate-dependent manner. Germline deletion causes substantial perinatal lethality with developmental eye and cardiac defects on most backgrounds, favoring conditional nulls, while catalytically dead histidine to tyrosine knockins distinguish deacetylase activity from scaffolding. Because the allosteric activator site is itself the pharmacological question, activator-insensitive point knockins are often more informative than deletion when validating small molecule mechanism.',
  Slc17a6:
    'Vesicular glutamate loading in subcortical circuits is carried out by Slc17a6, the mouse ortholog of human SLC17A6, encoding VGLUT2, a twelve-transmembrane SLC17 family transporter that uses the vacuolar ATPase-generated proton electrochemical gradient, predominantly its membrane potential component, to concentrate glutamate into synaptic vesicles, with biphasic allosteric chloride dependence and a distinct phosphate transport activity. VGLUT2 dominates thalamus, hypothalamus, brainstem, and spinal cord and marks glutamatergic identity in dopaminergic and other neuromodulatory neurons that co-release glutamate. Constitutive nulls die at birth from respiratory failure, so conditional floxed alleles are the standard tool, widely used to remove glutamate co-release from specific populations with Cre lines such as Slc6a3-Cre or Th-Cre. Knockin reporter or Cre-expressing alleles at the locus are equally common for circuit access. Because Slc17a7 and Slc17a8 occupy largely non-overlapping territories, true compensation is limited; match allele to identity, co-release, or quantal size endpoints.',
  Slc17a7:
    'Cortical and hippocampal glutamatergic terminals depend on Slc17a7, the mouse ortholog of human SLC17A7, encoding VGLUT1, the SLC17 family vesicular transporter that fills synaptic vesicles using the proton motive force generated by the vacuolar ATPase and that additionally recruits endophilin A1 through its C-terminal polyproline region to slow vesicle endocytosis and shape release probability during sustained activity. VGLUT1 defines telencephalic excitatory identity and is developmentally exchanged for VGLUT2 at many synapses. Homozygous nulls survive birth but decline sharply after the third postnatal week with blindness, ataxia, and death, reflecting that developmental switch, so conditional alleles are strongly preferred for adult circuit work. Knockin Cre or reporter alleles at the locus provide clean access to cortical excitatory populations. Because VGLUT2 partially substitutes at a subset of synapses during early development, interpret quantal size and vesicle filling phenotypes with that transient overlap in mind and select region-specific Cre drivers accordingly.',
  Slc17a8:
    'Restricted but functionally distinctive, Slc17a8 encodes the mouse ortholog of human SLC17A8, VGLUT3, an SLC17 vesicular glutamate transporter expressed not in canonical glutamatergic neurons but in cholinergic striatal interneurons, serotonergic raphe neurons, a subset of GABAergic cortical interneurons, cochlear inner hair cells, and some dorsal root ganglion neurons, where it enables glutamate co-release and vesicular synergy that enhances loading of the primary transmitter. Dominant SLC17A8 variants cause autosomal dominant nonsyndromic deafness DFNA25, and knockout mice are profoundly deaf from failed inner hair cell transmission while also showing altered anxiety, cocaine response, and audiogenic seizure susceptibility. Because the null is viable, constitutive deletion is feasible, but conditional alleles are preferred when separating cochlear from central contributions, and knockin Cre alleles give access to co-releasing populations. Redundancy with Slc17a6 and Slc17a7 is minimal in these cell types, so match allele class directly to auditory, striatal, or serotonergic endpoints.',
  Slc1a2:
    'Astrocytic clearance of synaptic glutamate is dominated by Slc1a2, the mouse ortholog of human SLC1A2, encoding GLT-1, also called EAAT2, a trimeric secondary active transporter in which each protomer combines a rigid scaffold domain with an elevator-like transport domain that carries glutamate across the membrane coupled to three sodium ions and one proton inward and one potassium ion outward, alongside an uncoupled chloride conductance. GLT-1 accounts for most forebrain glutamate uptake, its downregulation is a consistent feature of ALS and epilepsy, and dominant SLC1A2 variants cause developmental and epileptic encephalopathy 41. Global knockout mice develop lethal spontaneous seizures within weeks, so astrocyte-conditional deletion using GFAP-CreERT2 or Aldh1l1-CreERT2 is the practical route for adult studies. Neuronal GLT-1 exists but is minor, and compensation by Slc1a3 is partial at best; select patient missense knockins when dominant-negative trafficking rather than absence is the mechanism under test.',
  Slc1a3:
    'GLAST, encoded by mouse Slc1a3 and orthologous to human SLC1A3, is the EAAT1 glutamate transporter enriched in Bergmann glia, retinal Muller cells, cochlear supporting cells, and cortical astrocytes, operating as a trimeric elevator transporter that couples glutamate influx to three sodium ions and one proton with potassium countertransport plus an anion conductance contributing to glial membrane behavior. Dominant missense variants, notably P290R, cause episodic ataxia type 6 by combining reduced uptake with an enhanced anion current, a mechanism that a simple null cannot reproduce. Slc1a3 knockout mice are viable but show cerebellar motor incoordination, heightened susceptibility to excitotoxic injury, and retinal dysfunction. Allele choice therefore forks between conditional null for regional uptake capacity questions and patient knockins for the dominant channelopathy mechanism. Because Slc1a2 carries most forebrain uptake, cerebellar and retinal endpoints are the most informative, and inducible glial CreERT2 drivers avoid developmental confounds.',
  Slc6a1:
    'GABA reuptake at cortical synapses is mediated by Slc6a1, the mouse ortholog of human SLC6A1, encoding GAT-1, a twelve-transmembrane sodium and chloride dependent symporter of the SLC6 family with the LeuT fold, expressed on GABAergic axon terminals and on astrocytes, where it terminates phasic inhibition and constrains ambient GABA and tonic conductance. It is the pharmacological target of tiagabine. Heterozygous SLC6A1 missense and truncating variants cause myoclonic atonic epilepsy, absence seizures, autism, and intellectual disability, and importantly many missense alleles act through misfolding and ER retention rather than pure haploinsufficiency, which strongly favors patient knockin over simple null when mechanism is the question. Slc6a1 knockout mice are viable with tremor, ataxia, elevated tonic inhibition, and altered seizure susceptibility. Use conditional alleles with neuronal versus astrocytic Cre drivers to separate the two GAT-1 pools, and humanized alleles when chaperone or oligonucleotide therapeutics are tested.',
  Slc6a2:
    'Noradrenergic signaling is terminated by Slc6a2, the mouse ortholog of human SLC6A2, encoding the norepinephrine transporter, an SLC6 family sodium and chloride coupled symporter with the LeuT twelve-transmembrane fold that clears released norepinephrine into presynaptic terminals of locus coeruleus and sympathetic neurons and also transports dopamine in cortical regions where dopamine transporter expression is low. NET is the principal target of desipramine, reboxetine, and atomoxetine and a component of cocaine and amphetamine action, and the A457P variant causes orthostatic intolerance through dominant-negative loss of transport. Slc6a2 knockout mice are viable, displaying elevated extracellular norepinephrine, prolonged clearance, altered stress and antidepressant responses, and reduced psychostimulant sensitivity, so constitutive null is a valid baseline. Humanized knockin alleles are particularly valuable because rodent and human transporters differ in inhibitor affinity, making them correct for pharmacology, while conditional alleles paired with Dbh-Cre isolate central from peripheral sympathetic contributions.',
  Slc6a3:
    'Dopamine clearance depends on Slc6a3, the mouse ortholog of human SLC6A3, encoding the dopamine transporter, an SLC6 sodium and chloride coupled symporter with LeuT architecture concentrated on midbrain dopaminergic terminals in striatum, where it sets extracellular dopamine lifetime, supports vesicular refilling, serves as the primary molecular target of cocaine, amphetamine, and methylphenidate, and provides the route of MPP+ entry that confers selective nigral vulnerability. Biallelic loss of function causes dopamine transporter deficiency syndrome with infantile parkinsonism-dystonia, and common variation has been linked to ADHD phenotypes. Slc6a3 knockout mice are viable but hyperdopaminergic, hyperactive, growth retarded, and insensitive to cocaine reward, and the locus is also the standard site for DAT-Cre and DAT-CreERT2 knockin drivers, which must be chosen carefully because some cassettes reduce transporter expression. Match allele class to endpoint, using patient missense knockins for trafficking-defect mechanisms and humanization for inhibitor pharmacology.',
  Slc6a4:
    'Serotonin reuptake is executed by Slc6a4, the mouse ortholog of human SLC6A4, encoding SERT, an SLC6 family sodium and chloride dependent symporter with a twelve-transmembrane LeuT fold, a central substrate site, and an allosteric vestibular site, expressed on raphe serotonergic terminals as well as platelets, gut, and transiently on developing thalamocortical and sensory neurons. SERT is the direct target of SSRIs, MDMA, and cocaine, and it is regulated by PKC-dependent internalization, p38 MAPK phosphorylation, and syntaxin 1A interaction. Human variation includes the 5-HTTLPR promoter polymorphism and rare coding variants such as I425V. Slc6a4 knockout mice are viable with elevated extracellular serotonin, blunted 5-HT1A autoreceptor function, anxiety-like behavior, and abnormal barrel cortex patterning, making the null informative but developmentally confounded. Conditional alleles with tamoxifen-inducible Pet1-CreERT2 separate adult from developmental roles, and humanized alleles are preferred for SSRI pharmacology and promoter variant modeling.',
  Smad1:
    'Bone morphogenetic protein signaling is transduced by Smad1, the mouse ortholog of SMAD1, a receptor-regulated SMAD whose MH1 domain binds GC-rich BMP response elements and whose MH2 domain is phosphorylated at a carboxy-terminal SSVS motif by the type I receptors ALK1, ALK2, ALK3 and ALK6, after which it trimerizes with SMAD4 and enters the nucleus. Signal duration is set in the linker region, where CDK8 and CDK9 prime and GSK3 extends phosphorylation to recruit the ubiquitin ligase SMURF1, terminating output. Germline deletion is embryonic lethal from allantois and chorioallantoic fusion failure, so conditional nulls with endothelial, chondrocyte or germ cell drivers are required for postnatal questions, and linker phospho-dead knockins uniquely test signal duration. Smad5 and Smad9 are genuinely redundant BMP effectors, so compound conditional alleles are usually necessary before concluding that a BMP-dependent process is Smad1 dependent.',
  Smad2:
    'Smad2, ortholog of human SMAD2, encodes a receptor-regulated SMAD for the TGF beta, activin and Nodal branch, phosphorylated on its carboxy-terminal SSMS motif by the type I receptors ALK4, ALK5 and ALK7 and then partnered with SMAD4. Its distinguishing feature is exon 3, a thirty-residue insert in the MH1 domain that blocks direct DNA contact, so the full-length protein acts through partners such as FOXH1, whereas the naturally occurring exon 3 deleted isoform binds SMAD-binding elements much like SMAD3. Germline deletion is early embryonic lethal with failure of egg cylinder patterning and mesoderm formation, mandating conditional nulls for adult fibrosis, immune or tumor endpoints. Exon 3 deletion knockins and carboxy-terminal phospho-dead alleles separate DNA binding mode from receptor input. Because Smad3 shares receptor input and SMAD4 partnership while binding DNA directly, phenotypes attributed to Smad2 should be tested against compound Smad2 and Smad3 genetics.',
  Smad3:
    'Lacking the exon 3 insert that keeps SMAD2 off DNA, the protein encoded by Smad3 (human SMAD3) binds CAGAC SMAD-binding elements directly through its MH1 domain after ALK5 phosphorylates its carboxy-terminal SSVS motif, then trimerizes with SMAD4 and cooperates with AP-1, TCF and FOXO factors to drive collagen, Serpine1 and Foxp3 transcription. This direct DNA engagement makes it the dominant effector for TGF beta driven fibrosis, epithelial to mesenchymal transition and induced regulatory T cell generation. Human loss-of-function mutations cause aneurysm-osteoarthritis syndrome, a Loeys-Dietz variant, providing a knockin rationale distinct from deletion. Constitutive nulls are viable with immune dysregulation, colorectal tumors and protection from experimental fibrosis, so conditional alleles are needed chiefly to separate stromal, epithelial and T cell compartments. Given that Smad2 and Smad3 diverge in DNA binding rather than receptor use, allele selection should follow whether the endpoint is transcriptional output or receptor-proximal signaling.',
  Smad4:
    'Every branch of the TGF beta superfamily converges on Smad4 (ortholog of human SMAD4), the sole common mediator SMAD, which trimerizes through its MH2 domain with two receptor-phosphorylated SMADs, either SMAD2 and SMAD3 downstream of TGF beta and activin or SMAD1, SMAD5 and SMAD9 downstream of BMP, and supplies nuclear export control plus the transcriptional activation surface for the complex. Because it is shared, deletion collapses both branches at once, which is informative for tumor suppression but confounds branch attribution. Germline loss is early embryonic lethal at gastrulation, and somatic inactivation defines juvenile polyposis and is a canonical event in pancreatic ductal adenocarcinoma, where conditional nulls combined with Kras G12D and Trp53 alleles reproduce the human progression sequence. When the question is branch-specific, receptor-SMAD conditional alleles are preferable to Smad4 deletion, and MH2 interface knockins test complex assembly without abolishing protein expression.',
  Smad5:
    'Smad5, the mouse ortholog of SMAD5, encodes a BMP receptor-regulated SMAD phosphorylated at its carboxy-terminal SSVS motif by ALK1, ALK2, ALK3 and ALK6, after which it assembles heterotrimers with SMAD4 and occupies GC-rich BMP response elements, with linker phosphorylation by GSK3 and MAPK recruiting SMURF ligases to terminate signaling. Germline deletion is embryonic lethal at midgestation with defective yolk sac and amnion angiogenesis, cardiac looping abnormalities and primordial germ cell deficits, so conditional alleles with endothelial or hepatocyte Cre drivers are necessary for postnatal analysis, particularly for hepcidin regulation and iron homeostasis where BMP6 and ALK3 input converge. Redundancy here is genuine and quantitative: Smad1 and Smad9 use the same phosphoacceptor motif and the same response elements, and compound Smad1 and Smad5 deletion produces far more severe phenotypes, so plan double conditional genetics before attributing a BMP phenotype to this locus alone.',
  Smad9:
    'Encoding SMAD8, also designated SMAD9, Smad9 is the mouse ortholog of human SMAD9 and completes the BMP receptor-regulated SMAD trio, carrying the same MH1 DNA-binding and MH2 trimerization architecture and the carboxy-terminal SSVS phosphoacceptor recognized by ALK1 and ALK2, though it is expressed more narrowly and is particularly relevant in pulmonary endothelium downstream of BMP9 and BMP10 signaling through the ALK1, BMPR2 and endoglin receptor complex. Human loss-of-function variants are a recognized cause of heritable pulmonary arterial hypertension, supplying a clear knockin rationale, and null mice are viable with pulmonary vascular abnormalities rather than embryonic lethality, so constitutive deletion is a workable starting point with endothelial conditional alleles reserved for cell autonomy. Because Smad1 and Smad5 share receptors, motif and response elements, single-locus deletion usually yields mild phenotypes, and compound alleles or a sensitized Bmpr2 heterozygous background are advisable for penetrant vascular endpoints.',
  Smarca4:
    'Smarca4 is the mouse ortholog of human SMARCA4 and encodes BRG1, one of two mutually exclusive ATPase motors of the BAF, PBAF, and non-canonical BAF chromatin remodeling complexes, using HSA, ATPase, and bromodomain modules together with SMARCB1, ARID1A, and DPF subunits to slide nucleosomes and maintain enhancer accessibility for lineage transcription factors. Inactivating mutations define small cell carcinoma of the ovary hypercalcemic type and thoracic SMARCA4-deficient undifferentiated tumor, and recur in lung adenocarcinoma, medulloblastoma, and Burkitt lymphoma, while distinct germline missense variants cause Coffin-Siris syndrome, so both null and hypomorphic allele classes are biologically legitimate. Germline deletion is lethal at the peri-implantation stage, making conditional nulls mandatory for tissue studies; ATPase-dead knockins separate remodeling from scaffolding, and humanized alleles serve variant classification. The paralog Smarca2 (BRM) substitutes in many contexts and underlies the well-documented synthetic lethal dependency of BRG1-deficient cells, so compound conditional design and inducible Cre timing are central to interpretation.',
  Smarcb1:
    'Loss of Smarcb1, the mouse ortholog of human SMARCB1 (SNF5, INI1, BAF47), removes a core non-catalytic subunit of the BAF chromatin remodeling complex that stabilizes the ATPase module on nucleosomes and directs residual complexes toward typical enhancers, so its absence redistributes SMARCA4 to super-enhancers and creates a striking dependence on PRC2 and EZH2 activity. Biallelic inactivation, frequently 22q11 deletion plus a truncating hit, defines rhabdoid tumor of kidney, atypical teratoid rhabdoid tumor, epithelioid sarcoma, and renal medullary carcinoma, and germline heterozygosity produces rhabdoid tumor predisposition syndrome, making this one of the most genomically simple pediatric cancers. Homozygous germline deletion is lethal shortly after implantation, whereas conditional nulls yield rhabdoid or lymphoid tumors with very short latency, itself a practical design constraint. No paralog compensates, unlike the SMARCA4 and SMARCA2 pair, so single-locus conditional deletion is interpretable; select inducible Cre timing and lineage to control histology and EZH2 inhibitor endpoints.',
  Smo:
    'Smo, the ortholog of human SMO, encodes a class F G protein coupled receptor with a seven-transmembrane bundle plus an extracellular cysteine-rich domain that binds cholesterol, the activating sterol whose access is restricted by PTCH1 until Hedgehog engagement. Activation drives SMO accumulation in the primary cilium, phosphorylation by GRK2 and CK1, suppression of PKA-dependent GLI3 processing and release of GLI2 activator. Oncogenic substitutions such as the SmoM2 allele and the vismodegib resistance mutation D473H make Cre-inducible knockins, particularly the lox-stop-lox SmoM2 allele, the standard tools for driving pathway activation in a defined lineage and for modeling acquired inhibitor resistance. Germline deletion is embryonic lethal with cardiac and left to right asymmetry defects, so conditional nulls are required to test ligand dependence in adult tissues. Match allele class to question: activating knockin for tumor initiation and drug resistance, conditional null for pathway requirement and ciliary trafficking.',
  Snca:
    'Alpha-synuclein, encoded by mouse Snca and orthologous to human SNCA, is a 140 residue intrinsically disordered presynaptic protein with an amphipathic N-terminal region of imperfect KTKEGV repeats that folds into a helix on acidic membranes, a hydrophobic NAC segment driving amyloid assembly, and an acidic C-terminal tail mediating calcium and chaperone interactions. Physiologically it chaperones SNARE complex assembly through VAMP2 binding and modulates synaptic vesicle clustering; pathologically it forms Lewy body fibrils and propagates in a prion-like manner. Dominant missense alleles A53T, A30P, and E46K plus SNCA locus duplication and triplication cause Parkinson disease, establishing dosage as a driver. Critically, mouse Snca natively encodes threonine at position 53, so humanized knockin alleles are the correct choice for aggregation and antibody studies rather than relying on murine sequence. Redundancy with Sncb and Sncg is real, so pair conditional nulls with compound alleles when synaptic function is the endpoint.',
  Sod1:
    'Cytosolic superoxide detoxification is carried out by Sod1, the mouse ortholog of human SOD1, encoding copper and zinc superoxide dismutase, a beta-barrel homodimer stabilized by an intrasubunit Cys57 to Cys146 disulfide and metallated by the copper chaperone CCS, which dismutates superoxide to hydrogen peroxide and oxygen in cytosol and mitochondrial intermembrane space. More than 180 dominant SOD1 mutations, including G93A, G85R, and A4V, cause ALS1 through gain of toxic function involving misfolding, aberrant metal handling, and aggregation rather than loss of dismutase activity, a distinction confirmed because Sod1 knockout mice do not develop motor neuron disease but instead show distal axonopathy, hearing loss, muscle atrophy, and oxidative damage. Allele design therefore favors patient missense knockins at the endogenous locus over overexpression transgenes when physiologic dosage matters, with humanized alleles required for tofersen-class antisense oligonucleotide testing and conditional nulls reserved for cell-autonomy questions.',
  Sos1:
    'Sos1, ortholog of human SOS1, encodes the principal guanine nucleotide exchange factor for RAS, using a CDC25 homology domain and an adjacent REM domain to catalyze nucleotide release, an allosteric RAS-GTP binding site that generates positive feedback, and DH and PH domains that confer RAC exchange activity. Basal output is restrained by an amino-terminal histone fold and a carboxy-terminal proline-rich tail that binds GRB2 SH3 domains, coupling exchange to receptor tyrosine kinase phosphotyrosine. Germline gain-of-function substitutions relieve that autoinhibition and cause Noonan syndrome, so patient knockins address developmental and cardiac endpoints, while conditional nulls test the requirement for wild-type RAS loading in tumors treated with SOS1 inhibitors or with KRAS G12C inhibitors that depend on nucleotide cycling. Constitutive deletion is embryonic lethal from placental failure, whereas the paralog Sos2 supports adult viability and compensates partially, making compound Sos1 and Sos2 alleles the informative dependency design.',
  Sost:
    'Sost is the mouse ortholog of human SOST and encodes sclerostin, an osteocyte-derived, secreted cysteine-knot protein of the DAN family that binds the first beta-propeller of LRP5 and LRP6, using LRP4 as a presenting platform, to block Wnt, Frizzled, and LRP coreceptor assembly and suppress beta-catenin signaling in osteoblasts, with a secondary reported BMP-antagonist activity. Mechanical loading downregulates it, and human loss of function causes sclerosteosis or, through deletion of the ECR5 enhancer roughly 35 kilobases downstream, van Buchem disease, both high bone mass conditions that validated antibody blockade. This makes the allele fork unusually crisp: osteocyte-restricted conditional nulls using Dmp1-Cre test cell of origin and adult loading responses, ECR5 enhancer deletion models the human regulatory disease, and humanizing the LRP-binding loop enables direct antibody pharmacology. Sostdc1 shares the same LRP-binding mode, so consider compound alleles when dental or renal endpoints accompany skeletal readouts.',
  Spg11:
    'Spatacsin, encoded by mouse Spg11 and orthologous to human SPG11, is a large multipass membrane-associated protein acting with spastizin and the adaptor protein complex AP-5 to drive autophagic lysosome reformation, the process that regenerates functional lysosomes from autolysosomes after autophagic flux. Loss of spatacsin causes accumulation of undegraded material, notably gangliosides, within enlarged lysosomes. Biallelic SPG11 mutations produce the commonest form of autosomal recessive hereditary spastic paraplegia with thin corpus callosum, and also juvenile ALS5 and Charcot-Marie-Tooth type 2X, indicating broad motor axon vulnerability. Usefully, Spg11 knockout mice reproduce the disease with progressive motor deficits, cortical and cerebellar neuron loss, thin corpus callosum, and lysosomal storage, so constitutive null is a legitimate model. Conditional alleles remain useful for cell-autonomy questions in neurons versus glia. Functional partnership rather than redundancy with Zfyve26 means double mutants inform pathway epistasis, not hidden phenotype rescue.',
  Spg15:
    'Working in the same pathway as spatacsin, mouse Spg15, also annotated Zfyve26, encodes spastizin, the ortholog of human ZFYVE26, a large protein with a FYVE domain binding phosphatidylinositol 3-phosphate on endosomal membranes and a leucine zipper region mediating association with the AP-5 adaptor complex and with Beclin 1 and VPS34 autophagy initiation machinery. Spastizin is required for autophagosome maturation and autophagic lysosome reformation, and its loss produces enlarged lysosomes filled with undegraded substrates. Biallelic mutations cause SPG15, hereditary spastic paraplegia with thin corpus callosum, cognitive decline, and Kjellin retinopathy, clinically overlapping SPG11. Null mice recapitulate progressive motor impairment, Purkinje and cortical neuron loss, and lysosomal storage, so the constitutive null is productive, while conditional alleles address neuronal versus glial cell autonomy. Because Spg11 and Ap5z1 act within the same complex, expect epistasis rather than compensation and match allele class to lysosomal or axonal endpoints.',
  Sqstm1:
    'p62, the product of mouse Sqstm1 and ortholog of human SQSTM1, is a multidomain signaling adaptor and selective autophagy receptor built from an N-terminal PB1 domain that self-oligomerizes and binds NBR1 and atypical PKCs, a ZZ zinc finger, a TRAF6 binding region, an LC3-interacting region, a KEAP1-interacting region, and a C-terminal UBA domain that captures ubiquitinated cargo. By bridging polyubiquitinated substrates to LC3 on the phagophore, p62 drives aggrephagy and mitophagy, while sequestering KEAP1 to activate NRF2 antioxidant transcription and scaffolding NF-kappaB signaling. SQSTM1 mutations, mostly clustered in the UBA domain, cause Paget disease of bone, ALS with frontotemporal dementia, and distal myopathy. Constitutive knockout mice are viable but develop mature-onset obesity, insulin resistance, and age-dependent neurodegeneration, so metabolic confounds argue for conditional deletion with neuronal or microglial Cre drivers, while UBA or LIR point knockins cleanly separate cargo binding from NRF2 and NF-kappaB functions.',
  Src:
    'Prototype of the SRC family, Src is the mouse ortholog of human SRC and encodes a myristoylated non-receptor tyrosine kinase organized as SH3, SH2 and kinase domains with a carboxy-terminal regulatory tail whose Tyr527 is phosphorylated by CSK to lock an autoinhibited conformation; displacement of that intramolecular clamp by phosphotyrosine ligands or by PTP1B dephosphorylation permits Tyr416 autophosphorylation and full activity downstream of integrins, FAK, EGFR and other receptors. Null mice are viable but osteopetrotic from defective osteoclast ruffled border formation, a phenotype rescued by kinase-dead SRC, which established that scaffolding is separable from catalysis and makes kinase-dead knockins uniquely informative here. Fyn and Yes occupy overlapping substrate space and compensate substantially, with triple deletion perinatally lethal, so compound conditional genetics is essential for signaling endpoints. Reserve conditional nulls for tissue-autonomous adhesion and metastasis questions and use analog-sensitive gatekeeper knockins for chemical genetic specificity.',
  Srebf1:
    'Srebf1, ortholog of human SREBF1, encodes membrane-bound basic helix-loop-helix leucine zipper transcription factors, SREBP-1a and the liver and adipose enriched SREBP-1c, produced from alternative promoters and first exons. Both are synthesized as endoplasmic reticulum precursors held by SCAP and, when sterols are abundant, retained through INSIG binding; sterol depletion permits COPII transport to the Golgi, sequential cleavage by S1P and S2P, and release of the nuclear form that occupies sterol response elements to drive Acaca, Fasn, Scd1 and Elovl6. SREBP-1c is additionally induced by insulin through AKT and by LXR agonism, making the locus the transcriptional hub of de novo lipogenesis. Hepatocyte or adipocyte conditional nulls address tissue-autonomous lipogenesis, while nuclear-form transgenes test sufficiency without processing control. Srebf2 partially substitutes at shared promoters, so measure both nuclear forms before attributing altered fatty acid synthesis to Srebf1 alone.',
  Srebf2:
    'Cholesterol homeostasis is governed largely by Srebf2, the ortholog of human SREBF2, whose SREBP-2 precursor resides in the endoplasmic reticulum bound to SCAP, is retained by INSIG when sterol levels are high, and upon sterol depletion travels to the Golgi for S1P and S2P cleavage that liberates a basic helix-loop-helix leucine zipper fragment driving Hmgcr, Hmgcs1, Ldlr and Pcsk9 transcription. The gene also hosts miR-33a within an intron, coordinating cholesterol synthesis with repression of Abca1-dependent efflux, a coupling that a naive coding knockout would disrupt inadvertently. Germline deletion is largely embryonic lethal, so hepatocyte or macrophage conditional nulls are the practical design, and intron-preserving strategies or separate miR-33a alleles are essential when efflux is an endpoint. Cleavage-resistant or constitutive nuclear-form knockins test whether sterol sensing rather than transcriptional capacity is limiting, and Srebf1 compensates only partially at shared sterol response elements.',
  Srsf2:
    'Srsf2 encodes the mouse ortholog of human SRSF2 (SC35), a serine and arginine rich splicing factor with a single RNA recognition motif and a phosphorylated RS domain that binds exonic splice enhancers, recruits U1 and U2 snRNP to nascent transcripts, and also couples to transcriptional elongation and R loop resolution. The recurrent P95H, P95L, and P95R substitutions in myelodysplastic syndrome, chronic myelomonocytic leukemia, and secondary acute myeloid leukemia are heterozygous and mutually exclusive with SF3B1 and U2AF1 lesions, acting by shifting exonic enhancer preference from GGNG to CCNG motifs, which drives poison exon inclusion in Ezh2 and aberrant splicing of Bcor rather than simple loss of activity. Model design therefore requires conditional heterozygous P95H knockins, since homozygous mutant and null alleles are not tolerated in hematopoietic cells, with Mx1-cre or Vav1-cre induction to capture dysplasia and clonal advantage. Align allele choice with endpoint, whether splicing catalogs, competitive transplantation, or PRMT5 and spliceosome inhibitor sensitivity.',
  Stat1:
    'Stat1 encodes the ortholog of human STAT1, a latent cytoplasmic transcription factor recruited through its SH2 domain to phosphotyrosine docking sites on activated cytokine receptors, phosphorylated at Tyr701 by JAK1 and JAK2, and then assembled either as the homodimeric GAF complex that binds GAS elements downstream of interferon gamma or, with STAT2 and IRF9, as ISGF3 which binds interferon stimulated response elements downstream of type I interferon. Ser727 phosphorylation in the transactivation domain provides a second, JAK-independent input required for full activity. Human loss-of-function alleles cause mycobacterial and viral susceptibility while gain-of-function alleles cause chronic mucocutaneous candidiasis, so knockins of specific coiled-coil or DNA-binding domain substitutions answer questions deletion cannot. Nulls are viable but profoundly infection susceptible and tumor prone, making constitutive alleles usable, with conditional nulls reserved for separating hematopoietic from stromal interferon responses in tumor immunology.',
  Stat3:
    'Signaling from gp130-family cytokines, notably IL-6, IL-11, IL-10 and LIF, converges on Stat3, the ortholog of human STAT3, whose SH2 domain docks phosphorylated receptor tyrosines, is phosphorylated at Tyr705 by JAK1, dimerizes, and drives Socs3, Bcl3 and Myc transcription, with Ser727 phosphorylation and a separate mitochondrial pool supporting electron transport chain activity independently of transcription. Dominant-negative DNA-binding and SH2 domain mutations cause autosomal dominant hyper-IgE syndrome, whereas somatic activating mutations occur in large granular lymphocytic leukemia and germline gain-of-function alleles cause early-onset multiorgan autoimmunity, so patient-matched knockins interrogate mechanisms opposite in sign. Germline deletion is early embryonic lethal, making conditional nulls mandatory for essentially all adult work, and Ser727 phospho-dead knockins isolate the mitochondrial function. Match allele to endpoint: conditional null for tissue requirement, activating knockin for lymphoproliferation and JAK inhibitor response.',
  Stat5a:
    'Stat5a is the mouse ortholog of human STAT5A and lies in a tandem duplication with Stat5b, an arrangement that dictates targeting strategy since the two genes are separated by only a few kilobases and share more than ninety percent identity. The protein is recruited by its SH2 domain to phosphotyrosines on prolactin, growth hormone, erythropoietin and common gamma chain cytokine receptors, phosphorylated by JAK2 or JAK1 at a carboxy-terminal tyrosine, then dimerizes or tetramerizes on GAS elements to drive Cish, Bcl2l1 and casein gene transcription. Selective loss produces failed mammary lobuloalveolar development with largely preserved body growth, the reciprocal of Stat5b deletion. Because paralog compensation is substantial, rigorous work generally uses floxed alleles spanning both genes with lineage-restricted Cre drivers, or tetramerization-deficient amino-terminal domain knockins when the question is target gene selectivity rather than total signaling capacity.',
  Stat5b:
    'Encoded within the same tandem locus as Stat5a, Stat5b is the ortholog of human STAT5B and transduces growth hormone receptor signaling through JAK2, binding GAS elements to induce Igf1, Socs2 and Igfals and thereby setting somatic growth, while also mediating IL-2 receptor signaling required for regulatory T cell Foxp3 expression and NK cell homeostasis. Human loss-of-function mutations produce growth hormone insensitivity with severe short stature accompanied by immune dysregulation and eczema, whereas activating substitutions such as N642H drive T cell and NK cell leukemias, giving two knockin designs with opposite biology. Selective deletion in mouse abolishes male-pattern hepatic gene expression and reduces body growth. Given the extreme sequence identity and physical linkage with Stat5a, distinguish single-gene from dual-locus floxed alleles at the design stage, and pair conditional deletion with a hematopoietic or hepatocyte Cre driver matched to the intended endpoint.',
  Stat6:
    'Stat6, ortholog of human STAT6, encodes the transcription factor that converts type 2 cytokine input into gene expression, recruited by its SH2 domain to Jak-phosphorylated tyrosines on the shared Il4ra chain downstream of both the type I IL-4 receptor and the type II IL-4 and IL-13 receptor, then dimerizing and binding TTCNNNNGAA response elements to drive Gata3, Ccl26, Arg1 and immunoglobulin class switching to IgE. Because a single factor integrates two cytokines through one shared chain, a null collapses the entire axis and cannot distinguish IL-4 from IL-13 contributions, which is the principal design pitfall. Conditional deletion in T cells, B cells, macrophages or epithelium assigns allergic phenotypes to a compartment, while receptor-level alleles or blocking reagents separate the two ligands, and humanized alleles support dupilumab-class pharmacology directed at IL-4R alpha. Read out airway eosinophilia, serum IgE, alternative macrophage activation markers, and goblet cell metaplasia.',
  Stk11:
    'Metabolic tumor suppression runs through Stk11, the mouse ortholog of human STK11 (LKB1), a serine and threonine kinase that must complex with the pseudokinase STRADA and the scaffold CAB39 to adopt an active conformation, whereupon it phosphorylates the activation loop threonine of AMPK alpha subunits and of twelve related kinases including the SIK, NUAK, MARK, and BRSK families, linking energy stress to mTORC1 restraint, epithelial polarity, and CRTC-dependent transcription. Germline heterozygous inactivation causes Peutz-Jeghers syndrome with hamartomatous polyposis, and somatic biallelic loss co-occurs with KRAS mutation in lung adenocarcinoma, producing immunologically cold, STING-silenced tumors whose SIK dependence and serine metabolism define distinct vulnerabilities. Germline nulls die in midgestation from vascular and placental defects, so conditional nulls combined with Kras LSL-G12D and viral Cre delivery are the workhorse design, while kinase-dead or Peutz-Jeghers missense knockins separate catalytic from scaffolding function. Choose allele class by endpoint: polyposis, tumor immunophenotype, or metabolic inhibitor response.',
  Syngap1:
    'Synaptic Ras GTPase-activating protein, encoded by mouse Syngap1 and orthologous to human SYNGAP1, is among the most abundant postsynaptic density proteins, containing a pleckstrin homology domain, a C2 domain, a RasGAP catalytic domain active on both Ras and Rap, and a C-terminal PDZ-binding motif anchoring it to PSD-95. By restraining Ras-ERK signaling it limits AMPA receptor insertion and spine maturation, and its rapid NMDA receptor-driven phosphorylation and dispersal from the density is a required step in long-term potentiation. Alternative C-terminal isoforms alpha1, alpha2, beta, and gamma exert opposing effects on synaptic strength. Heterozygous de novo truncating variants cause SYNGAP1-related intellectual disability with epilepsy and autism, and homozygous null mice die within days of birth, so heterozygous or conditional alleles are mandatory. Choose conditional null for reversibility and cell-autonomy studies with excitatory or interneuron Cre drivers, isoform-specific alleles for the C-terminal question, and humanization for oligonucleotide upregulation testing.',
  Tab1:
    'Tab1, the mouse ortholog of human TAB1, encodes TGF-beta activated kinase 1 binding protein 1, an inactive pseudophosphatase whose N-terminal PP2C-like fold is catalytically dead but whose C-terminal peptide docks into the TAK1 (Map3k7) kinase domain and allosterically drives TAK1 autophosphorylation, making TAB1 a constitutive activator rather than a signal-dependent adaptor. Independently, TAB1 binds p38 alpha and enables TAK1-independent p38 autoactivation during ischemia and osmotic stress, a route relevant to cardiac injury. Germline deletion is embryonic lethal near midgestation with cardiovascular and lung dysmorphogenesis, so conditional alleles are the practical route, while knockins deleting only the TAK1-binding peptide or the p38 docking motif cleanly separate the two functions, an experiment a null cannot perform. Tab2 and Tab3 are true paralogs for ubiquitin-dependent TAK1 activation but do not substitute for this allosteric mechanism. Match alleles to innate cytokine output, cardiac hypertrophy, or epithelial survival endpoints with a validated Cre.',
  Tab2:
    'Tab2 is the mouse ortholog of human TAB2 and encodes an adaptor that couples receptor-proximal ubiquitin signals to TAK1 activation, using a C-terminal NZF domain to read K63-linked polyubiquitin chains and an N-terminal CUE domain plus a TAK1-binding region to bring the kinase into TRAF6 and TRAF2 assembled complexes downstream of IL-1R, TLRs, TNFR1, and RANK. Ubiquitin engagement induces clustering and TAK1 trans-autophosphorylation, licensing IKK and MAPK activation, and human TAB2 haploinsufficiency causes congenital heart disease and dilated cardiomyopathy. Germline nulls die at midgestation from TNF-driven hepatocyte apoptosis, so viable modeling requires conditional deletion or NZF-domain knockins that abolish ubiquitin reading while preserving scaffolding. Redundancy with Tab3 is substantial and compensatory upregulation is documented, so single deletion often looks mild and compound Tab2 Tab3 conditional genetics is the honest design. Pair alleles with NF-kB reporter output, cardiac remodeling, or intestinal epithelial survival endpoints.',
  Tab3:
    'Functioning as the paralog that explains many negative results at the Tab2 locus, Tab3 is the mouse ortholog of human TAB3 and encodes an NZF-containing adaptor that likewise binds K63-linked polyubiquitin and the TAK1 kinase domain to support IL-1, TNF, and TLR driven TAK1 activation, with preferences dictated by receptor context and cell type rather than by a wholly distinct mechanism. Its NZF domain reads ubiquitin chains through a different surface than TAB2, and the two proteins occupy TAK1 in mutually exclusive complexes, which is why acute loss of one is buffered. Germline nulls are viable and largely unremarkable, so informative designs are compound conditional alleles with Tab2, or NZF-inactivating knockins that separate ubiquitin recognition from TAK1 binding within an otherwise intact complex. Given genuine redundancy, never treat a single Tab3 knockout as a TAK1 pathway test, and anchor compound genetics to cytokine transcription, hepatocyte survival, or tumor NF-kB endpoints using validated Cre lines.',
  Tardbp:
    'Nuclear TDP-43, encoded by mouse Tardbp and orthologous to human TARDBP, is a heterogeneous nuclear ribonucleoprotein with two RRM domains binding UG-rich RNA and a C-terminal glycine-rich prion-like low complexity domain mediating phase separation and protein interaction. It represses cryptic exon inclusion in transcripts such as STMN2 and UNC13A, regulates splicing and mRNA stability, and autoregulates its own abundance by binding its 3-prime untranslated region. In ALS and frontotemporal lobar degeneration, TDP-43 mislocalizes from the nucleus and forms hyperphosphorylated, ubiquitinated cytoplasmic inclusions, and rare dominant mutations cluster in the low complexity domain, including M337V, A315T, and Q331K. Because Tardbp null embryos die around implantation and overexpression is independently toxic, endogenous locus knockins and conditional alleles are strongly preferred over transgenes. Match design to question, using nuclear localization signal mutants for mislocalization, patient missense knockins for aggregation, and humanized alleles when cryptic exon readouts require human sequence context.',
  Tbk1:
    'Tbk1, the mouse ortholog of human TBK1, encodes a serine threonine kinase of the IKK family with kinase, ubiquitin-like, and scaffold dimerization domains that phosphorylates STING at Ser366 and IRF3 at Ser396 to drive type I interferon transcription downstream of cGAS, RIG-I through MAVS, and TLR3 through TRIF, and separately phosphorylates the autophagy receptors OPTN and SQSTM1 to license selective mitophagy and xenophagy. Human haploinsufficiency and loss of function mutations cause amyotrophic lateral sclerosis and frontotemporal dementia, while excess interferon output underlies its interest in autoinflammation. Germline nulls die at midgestation from TNF-dependent hepatic apoptosis, a lethality rescued on a Tnfrsf1a-null background, so practical alleles include kinase-dead knockins, phosphosite mutants, conditional deletion, and truncating patient variants. Ikbke partially covers interferon induction in myeloid cells, so compound genetics may be required, and allele choice should track interferon output, mitophagy flux, or motor neuron phenotypes.',
  Tert:
    'Tert encodes the mouse ortholog of human TERT, the catalytic reverse transcriptase subunit of telomerase, which assembles with the noncoding RNA template Terc plus dyskerin, NOP10, NHP2, and GAR1 and is recruited to chromosome ends by TPP1 to add telomere repeats, using an N-terminal essential domain, an RNA binding domain, and a canonical reverse transcriptase fold. Human cancer activates TERT chiefly through recurrent promoter mutations at positions 124 and 146 upstream of the start codon, which create de novo GABP ETS binding sites and reactivate transcription in melanoma, glioblastoma, bladder cancer, and hepatocellular carcinoma, whereas germline loss-of-function alleles cause dyskeratosis congenita, aplastic anemia, and pulmonary fibrosis. A critical species caveat governs design: laboratory mice carry very long telomeres and tolerate Tert deletion for several generations, so nulls model attrition only after successive intercrossing or on a Terc-deficient background. Promoter-humanized or hTERT knockin alleles are therefore the appropriate choice for promoter mutation biology and telomerase-directed therapeutics.',
  Tet2:
    'Tet2 is the mouse ortholog of human TET2 and encodes an iron and 2-oxoglutarate dependent dioxygenase that oxidizes 5-methylcytosine to 5-hydroxymethylcytosine and further products, initiating active and passive demethylation at enhancers; unlike Tet1 and Tet3 it lacks a CXXC domain and instead relies on partners such as IDAX, WT1, and EBF1 for locus targeting. Truncating and catalytic domain missense mutations make TET2 one of the most frequent drivers of clonal hematopoiesis and of myelodysplastic syndrome, chronic myelomonocytic leukemia, and angioimmunoblastic T cell lymphoma, and its activity is phenocopied by IDH1 or IDH2 neomorphic mutations through 2-hydroxyglutarate inhibition while being stimulated by ascorbate. Germline nulls are viable with progressive hematopoietic stem cell expansion, myeloid bias, and long tumor latency, so conditional nulls with Vav1-cre or Mx1-cre plus a cooperating Flt3 internal tandem duplication or Jak2 V617F allele sharpen the phenotype. Paralogs Tet1 and Tet3 partially buffer hydroxymethylation, making compound conditional alleles worthwhile.',
  Tgfb1:
    'Tgfb1 is the mouse ortholog of human TGFB1 and encodes the prototypical isoform, secreted as a latent complex in which the mature disulfide-linked dimer is shielded noncovalently by its latency-associated peptide and tethered to LTBP1 or LTBP3 in matrix, or to GARP on regulatory T cells. Activation is mechanical and proteolytic, requiring integrin alpha v beta 6 or alpha v beta 8 traction, plasmin, or thrombospondin 1, after which TGFBR2 recruits ALK5 to phosphorylate SMAD2 and SMAD3. Roughly half of nulls die in utero from yolk sac vasculogenesis failure and survivors succumb to multiorgan autoimmune inflammation within weeks unless crossed onto immunodeficient backgrounds, while human loss of function causes very early onset inflammatory bowel disease and latency peptide mutations cause Camurati-Engelmann disease. Immune-restricted conditional nulls, activation-site knockins, and humanized alleles for antibody testing answer distinct questions, with Tgfb2 and Tgfb3 sharing receptors.',
  Tgfb2:
    'Among the three ligand isoforms, Tgfb2, the mouse ortholog of human TGFB2, has the lowest intrinsic affinity for TGFBR2 and therefore depends on the coreceptor betaglycan to present ligand efficiently for ALK5 recruitment and SMAD2 and SMAD3 phosphorylation, a biochemical distinction that predicts why its in vivo requirements barely overlap with Tgfb1. Nulls die perinatally with cardiac outflow tract and aortic arch malformation, craniofacial and eye defects, and inner ear anomalies, while human heterozygous loss of function causes Loeys-Dietz syndrome type 4 with thoracic aortic aneurysm, and elevated aqueous humor ligand features in glaucoma. Consequently, neural crest and endothelial conditional nulls using Wnt1-Cre or Tie2-Cre isolate lineage requirements, haploinsufficient and patient missense knockins reproduce the aneurysm paradox in which reduced ligand yields increased downstream signaling, and humanization enables isoform-selective antibody testing. Tgfb1 and Tgfb3 share receptors yet compensate only partially, so isoform-specific alleles remain necessary rather than interchangeable.',
  Tgfb3:
    'Tgfb3 is the mouse ortholog of human TGFB3 and encodes the isoform with the highest intrinsic affinity for TGFBR2, capable of forming heterodimers with TGFB1 and concentrated in the medial edge epithelium of the fusing palatal shelves, where it drives the SMAD2 and SMAD3 program required for epithelial seam breakdown. Nulls develop cleft palate with an essentially normal craniofacial skeleton plus delayed lung maturation, a strikingly restricted phenotype, and human variants cause Loeys-Dietz syndrome type 5 and arrhythmogenic right ventricular cardiomyopathy type 1, while the isoform has long been pursued for scarless wound repair. Epithelial conditional deletion using K14-Cre separates palatal seam requirements from mesenchymal signaling, patient knockins address aortic and myocardial disease mechanism, and humanization supports isoform-selective pharmacology. Although Tgfb1 and Tgfb2 use the same receptor pair, their nonoverlapping null phenotypes show compensation is limited in vivo, so treat isoform identity as functionally meaningful.',
  Tgfbr1:
    'Tgfbr1 encodes ALK5, ortholog of human TGFBR1, a type I serine and threonine kinase receptor recruited into a heterotetramer by ligand-bound TGFBR2, which transphosphorylates the glycine and serine rich GS box; FKBP12 occupies that box in the basal state to prevent leaky activation, and once released the kinase phosphorylates SMAD2 and SMAD3 at their carboxy-terminal motifs while also engaging TRAF6, TAK1 and p38 for non-SMAD output. Heterozygous kinase domain mutations cause Loeys-Dietz syndrome with aortic aneurysm, so patient knockins address vascular biology that deletion does not. Germline deletion is embryonic lethal from yolk sac vasculogenesis failure, mandating conditional nulls for fibrosis, immune tolerance and tumor microenvironment studies, while a constitutively active T204D knockin driven from a lox-stop-lox cassette tests sufficiency. Because ALK1 and ALK2 transduce distinct ligand subsets, do not assume ALK5 loss removes all superfamily input from a tissue.',
  Tgfbr2:
    'Tgfbr2, the mouse ortholog of human TGFBR2, encodes the constitutively active type II serine/threonine kinase receptor that captures TGFB1, TGFB2, and TGFB3 and transphosphorylates the GS domain of the type I receptor ALK5 (Tgfbr1), licensing phosphorylation of the SMAD2 and SMAD3 carboxy-terminal SSXS motifs and SMAD4-dependent nuclear transcription. Human disease logic splits cleanly: biallelic frameshifts in the polyadenine BAT-RII tract drive microsatellite-unstable carcinomas, whereas heterozygous kinase-domain missense alleles cause Loeys-Dietz syndrome with paradoxically elevated SMAD2 output in aortic wall. Straight germline deletion is lethal near E10.5 from failed yolk sac vasculogenesis and hematopoiesis, so epithelial, fibroblast, or T cell questions require a floxed kinase-domain allele driven by a validated lineage Cre. Because ligand redundancy across three TGFB isoforms and intact activin and BMP arms (Acvr2a, Acvr2b, Bmpr2) preserve parallel SMAD1/5/8 flux, receptor deletion silences only the SMAD2/3 branch; reserve epitope humanization for ligand trap and antibody pharmacology.',
  Tia1:
    'Stress granule nucleation depends on Tia1, the mouse ortholog of human TIA1, encoding a nucleocytoplasmic RNA binding protein with three RRM domains and a C-terminal prion-like low complexity domain that drives liquid-liquid phase separation. TIA1 binds U-rich sequences to promote alternative splicing and, upon eIF2alpha phosphorylation during integrated stress response activation, recruits stalled preinitiation complexes into cytoplasmic stress granules while repressing translation of specific transcripts. Missense mutations within the low complexity domain, notably P362L and E384K, alter granule dynamics and delay disassembly, causing Welander distal myopathy and contributing to ALS and frontotemporal dementia with TDP-43 pathology. Allele logic follows: patient missense knockins at the endogenous locus model altered phase behavior, whereas conditional null tests granule-independent splicing roles. Tia1 nulls show partial embryonic lethality with viable survivors, and the paralog Tial1 provides genuine functional overlap, so compound alleles are advisable when granule assembly itself is the endpoint.',
  Ticam1:
    'Encoding the adaptor TRIF, Ticam1 is the mouse ortholog of human TICAM1 and supplies the MyD88-independent arm of Toll-like receptor signaling, using a central TIR domain to engage TLR3 directly and TLR4 through TRAM (Ticam2) after endosomal internalization, an N-terminal region that recruits TRAF3 with the TBK1 and IKK epsilon complex for IRF3-driven type I interferon, and a C-terminal RHIM that binds RIPK1 and RIPK3 to trigger NF-kB, apoptosis, or necroptosis depending on caspase-8 availability. The classic Lps2 frameshift allele established that TRIF loss abolishes poly(I:C) responses and the late-phase LPS interferon response while sparing early MyD88 signaling. Nulls are viable, so germline deletion is tractable, whereas RHIM or TRAF-binding knockins separate interferon induction from death signaling and Myd88 compound alleles are needed because both adaptors serve TLR4. Fit alleles to interferon beta induction, endotoxin tolerance, or virus-induced tissue damage endpoints.',
  Tigit:
    'Tigit is the mouse ortholog of human TIGIT and encodes a single IgV domain inhibitory receptor bearing an ITIM and an ITT-like motif that is induced on activated and exhausted CD8 T cells, follicular helper cells, regulatory T cells, and NK cells, where it binds CD155 (Pvr) with high affinity and CD112 (Pvrl2) more weakly. Because CD226 engages the same ligands as a costimulatory receptor, TIGIT acts partly by outcompeting CD226 and disrupting its homodimerization, while cis interactions and Treg-intrinsic signaling shape ligand availability and IL-10 output. Design consequences are concrete: germline or conditional nulls test cell-intrinsic inhibition, ITIM or ITT-like knockins separate signaling from ligand sequestration, and ectodomain humanization is required whenever a clinical antibody with defined Fc effector function is evaluated, since Fc-dependent Treg depletion is a leading proposed mechanism. Cd96 and Cd226 modulate the same axis, so plan compound alleles with tumor control or Pdcd1 combination endpoints.',
  Timp1:
    'Timp1, the mouse ortholog of human TIMP1, encodes tissue inhibitor of metalloproteinases 1, a glycoprotein whose N-terminal domain inserts a Cys1-containing wedge into the MMP active site so that the alpha amino group and carbonyl chelate the catalytic zinc, giving broad inhibition of soluble MMPs including MMP1, MMP3, and MMP9 but notably weak activity against MT1-MMP (Mmp14). Independently of protease inhibition, TIMP1 signals as a cytokine through CD63 and integrin beta 1, activating FAK, PI3K, and ERK to promote survival, and it shapes hepatic stellate cell and neutrophil behavior during fibrosis and metastatic niche formation. Nulls are viable, so germline deletion works, while conditional alleles resolve stromal versus hepatic sources and Cys1 or CD63-binding knockins separate inhibitory from signaling functions, an essential control given the dual activity. Timp2, Timp3, and Timp4 overlap on shared targets, so consider compound genetics and follow fibrosis, metastasis, or gelatinase endpoints.',
  Timp2:
    'Distinctive among the family, Timp2 is the mouse ortholog of human TIMP2 and encodes the only member that efficiently blocks MT1-MMP (Mmp14) while paradoxically being required for pro-MMP2 activation, because its C-terminal domain tethers pro-MMP2 to MT1-MMP on the cell surface so that a neighboring uninhibited MT1-MMP molecule performs the activating cleavage. The N-terminal domain provides canonical zinc chelation through its Cys1 start, and TIMP2 additionally signals through integrin alpha 3 beta 1 and SHP-1 to suppress VEGFR2 phosphorylation, giving MMP-independent antiangiogenic activity. Nulls are viable with loss of MMP2 activation and altered angiogenesis, so germline deletion is informative but conflates inhibitory and activating roles, which argues for C-terminal or Cys1 knockins that separate them plus conditional alleles for stromal versus endothelial sources. Timp3 and Timp4 partly overlap on MT1-MMP, so plan compound genetics and align alleles with collagen invasion, corneal neovascularization, or MMP2 zymography endpoints.',
  Timp3:
    'Timp3 is the mouse ortholog of human TIMP3 and encodes the only family member sequestered in extracellular matrix through sulfated glycosaminoglycan binding via its C-terminal domain, and the only one that potently inhibits ADAM17 (TACE), ADAM10, ADAM12, and the aggrecanases ADAMTS4 and ADAMTS5 in addition to classical MMPs. Because ADAM17 sheds TNF, TGF-alpha, IL-6 receptor, and Notch ligands, TIMP3 sets the tone of ectodomain shedding rather than only matrix turnover, and human C-terminal mutations cause Sorsby fundus dystrophy by promoting TIMP3 aggregation and dysregulated VEGF handling in Bruch membrane. Nulls are viable but develop air space enlargement, cardiac dilation, accelerated cartilage degradation, and enhanced TNF shedding, so germline deletion is tractable, while matrix-binding or Sorsby point knockins model dominant human disease and conditional alleles isolate chondrocyte, myeloid, or retinal pigment epithelium sources. Timp1, Timp2, and Timp4 do not substitute for ADAM17 inhibition, so target shedding, osteoarthritis, or neovascularization endpoints.',
  Timp4:
    'Timp4, the mouse ortholog of human TIMP4, encodes the most restricted family member, expressed predominantly in heart, brain, adipose tissue, and platelets, where its N-terminal Cys1 wedge chelates the catalytic zinc of MMP1, MMP2, MMP7, MMP9, and MT1-MMP, and its C-terminal domain binds pro-MMP2 in a manner analogous to but weaker than TIMP2. Platelet-derived TIMP4 modulates aggregation and local matrix remodeling at sites of injury, and cardiac TIMP4 loss shifts the protease inhibitor balance during pressure overload and infarction, linking the gene to adverse remodeling rather than to developmental patterning. Nulls are viable and fertile with essentially normal baseline morphology, so germline deletion is a low-risk starting point but usually needs a stress challenge to reveal phenotype, while conditional alleles resolve cardiomyocyte versus fibroblast contributions and domain knockins separate inhibition from pro-MMP2 binding. Given clear redundancy with Timp1, Timp2, and Timp3, plan compound genetics around remodeling, infarct expansion, or adipose fibrosis endpoints.',
  Tlr1:
    'Tlr1 is the mouse ortholog of human TLR1 and encodes a leucine-rich repeat receptor that does not act alone but heterodimerizes with TLR2 at the plasma membrane to sense triacylated bacterial lipopeptides, with the crystallographically defined arrangement placing two lipid chains in the TLR2 pocket and the third in a narrow TLR1 channel, after which paired TIR domains recruit TIRAP and MyD88 to activate IRAK4, IRAK1, TRAF6, and NF-kB. Divergence in the lipid-binding pocket means mouse and human receptors differ in sensitivity to synthetic agonists such as Pam3CSK4 and to mycobacterial lipoproteins, the main argument for ectodomain humanization. Nulls are viable and immunocompetent at baseline, so germline deletion is straightforward, while conditional alleles resolve myeloid versus epithelial sensing. Tlr6 covers diacylated ligands through the same TLR2 partner, so interpret single knockouts cautiously and match alleles to bacterial burden, cytokine induction, or adjuvant response endpoints.',
  Tlr10:
    'Tlr10 presents a species obstacle rather than a straightforward target, because the mouse locus is a pseudogene disrupted by retroviral insertion and produces no functional receptor, whereas human TLR10 encodes an expressed leucine-rich repeat protein that heterodimerizes with TLR2 and, in most reported settings, acts as a negative regulator dampening TLR2-dependent MyD88 recruitment and NF-kB output while shaping IL-1 driven responses in monocytes and B cells. Consequently there is nothing informative to delete in mouse, and modeling requires knockin of the human coding sequence at the syntenic locus or a myeloid-restricted transgene, ideally alongside a TIR-domain mutant control to test whether inhibition requires signaling-competent assembly. Because human TLR10 operates in the context of human TLR1, TLR2, and TLR6, results are most interpretable in strains humanized across that cluster. Fit the design to TLR2 agonist responsiveness, cytokine dampening, or human variant association follow-up endpoints.',
  Tlr2:
    'Encoding a broadly promiscuous pattern recognition receptor, Tlr2 is the mouse ortholog of human TLR2 and uses a horseshoe of leucine-rich repeats with a hydrophobic pocket at the boundary of its central and C-terminal regions to sense bacterial lipoproteins, lipoteichoic acid, peptidoglycan fragments, zymosan, and fungal and parasitic lipids, always as a heterodimer with TLR1 or TLR6 and often assisted by CD14, CD36, or integrin beta 3. Ligand engagement dimerizes the TIR domains, recruits TIRAP and MyD88, and activates IRAK and TRAF6 for NF-kB and MAPK output, with a minor endosomal interferon component. Nulls are viable and highly informative in infection models, so germline deletion is a reasonable default, conditional alleles separate myeloid, epithelial, and astrocyte sensing, and ectodomain humanization supports antagonists that fail to cross-react. Because Tlr1 and Tlr6 partition ligand classes, interpret co-receptor genetics together and target clearance, sterile inflammation, or adjuvant endpoints.',
  Tlr3:
    'Tlr3, the mouse ortholog of human TLR3, encodes the endosomal receptor for double-stranded RNA, binding duplexes of roughly forty five base pairs or longer across two sites on the lateral face of its leucine-rich repeat ectodomain so that two receptors are bridged into a signaling dimer, with acidic pH and UNC93B1-dependent trafficking required for function. Uniquely among Toll-like receptors it signals exclusively through TRIF rather than MyD88, recruiting TRAF3, TBK1, and IKK epsilon to phosphorylate IRF3 for type I interferon and, through RIPK1, driving NF-kB or RHIM-dependent death, and human TLR3 deficiency predisposes specifically to herpes simplex encephalitis. Nulls are viable and immunocompetent outside particular viral challenges, so germline deletion is practical, while conditional alleles resolve neuronal, epithelial, and dendritic cell sensing and humanized ectodomains matter for agonist pharmacology. Since Ddx58 and Ifih1 also sense duplex RNA in cytosol, plan compound genetics around interferon induction or neurotropic infection endpoints.',
  Tlr4:
    'Tlr4 is the mouse ortholog of human TLR4 and encodes the lipopolysaccharide receptor, which requires the accessory protein MD-2 (Ly96) to form a pocket accommodating five of the six lipid A acyl chains while CD14 and LBP deliver ligand, and dimerization then triggers MyD88 and TIRAP signaling at the plasma membrane followed by TRAM and TRIF dependent IRF3 activation after endocytosis. Species specificity is a first-order design issue, since mouse and human MD-2 and TLR4 differ in their response to underacylated lipid A species, so lipid A mimetics, monophosphoryl lipid A adjuvants, and antagonists such as eritoran behave differently, which is why humanized Tlr4 and Ly96 knockins are used for adjuvant and sepsis pharmacology. The spontaneous P712H allele and complete nulls are both viable, so conditional deletion in myeloid, endothelial, or intestinal epithelial compartments is the refinement step, with endotoxin shock, neuropathic pain, or steatohepatitis endpoints dictating allele choice.',
  Tlr5:
    'Serving as the flagellin sensor, Tlr5 is the mouse ortholog of human TLR5 and encodes a cell-surface leucine-rich repeat receptor that recognizes the conserved D1 domain of bacterial flagellin through a lateral surface centered on repeats seven to ten, an interface that also mediates receptor dimerization and subsequent MyD88, IRAK4, and TRAF6 dependent NF-kB activation. Because this epitope is buried in assembled filaments, TLR5 detects monomeric flagellin released by motile bacteria, and signaling in intestinal epithelium and lamina propria dendritic cells controls flagellin-specific IgA, antimicrobial peptide expression, and microbiota composition, with human dominant-negative variants linked to Legionella susceptibility. Nulls are viable but develop altered microbiota, metabolic syndrome features on some backgrounds, and impaired mucosal antibody responses, so germline deletion is informative provided cohousing and microbiome controls are used, while conditional alleles resolve epithelial versus dendritic cell sensing. Align allele choice with colonization, adjuvant, or metabolic endpoints.',
  Tlr6:
    'Tlr6, the mouse ortholog of human TLR6, encodes the partner receptor that redirects TLR2 toward diacylated ligands including mycoplasmal MALP-2, lipoteichoic acid from gram positive organisms, and zymosan components, using a lipid-binding pocket that lacks the narrow channel present in TLR1 and therefore accommodates only two acyl chains. Heterodimer assembly juxtaposes TIR domains for TIRAP and MyD88 recruitment, IRAK4 activation, and TRAF6 dependent NF-kB and MAPK signaling, and TLR6 also cooperates with CD36 in sensing oxidized lipids and amyloid beta during sterile inflammation. Nulls are viable and specifically lose diacyl lipopeptide responsiveness, so germline deletion cleanly parses ligand classes, conditional alleles isolate myeloid or epithelial sensing, and ectodomain humanization is warranted when synthetic agonists are advanced as adjuvants. Tlr1 covers triacylated ligands through the same TLR2 scaffold, so single knockouts underestimate pathway loss and compound Tlr1 Tlr6 genetics should match cytokine, clearance, or atherogenesis endpoints.',
  Tlr7:
    'Tlr7 is the mouse ortholog of human TLR7 and encodes an endosomal receptor that requires UNC93B1 for trafficking and proteolytic maturation, then senses single-stranded RNA degradation products through two cooperating sites, one binding guanosine or synthetic agonists such as imiquimod and R848 and a second binding short uridine-containing oligoribonucleotides, with dimerization driving MyD88, IRAK4, and IRF7 dependent type I interferon in plasmacytoid dendritic cells. Dosage is central to disease logic: the Yaa locus duplication of Tlr7 accelerates murine lupus, human gain of function substitutions such as Y264H that increase guanosine affinity cause childhood systemic lupus erythematosus, and escape from X inactivation raises expression in females. Design accordingly, using conditional nulls to assign requirement to plasmacytoid dendritic cells or B cells, copy-number or point-mutant knockins for gain of function, and humanized alleles for agonist pharmacology. Tlr8 and Tlr9 overlap in nucleic acid sensing, so target autoantibody, interferon signature, or adjuvant endpoints.',
  Tlr8:
    'Tlr8 illustrates why humanization is not optional for nucleic acid sensing pharmacology, since the mouse ortholog of human TLR8 carries a five amino acid deletion in a region required for productive agonist engagement and responds poorly or not at all to imidazoquinolines such as R848 that potently activate the human receptor. Human TLR8 operates in monocytes and myeloid dendritic cells, where it is proteolytically matured in endosomes and senses uridine plus short oligoribonucleotide products of RNase T2 and RNase 2 degradation in two adjacent pockets, driving MyD88 dependent NF-kB with strong IL-12 and TNF output rather than the interferon-dominated program of TLR7. Practical designs therefore favor knockin of the human coding sequence at the endogenous locus with human TLR7 status controlled, while mouse Tlr8 nulls remain useful because they display Tlr7-dependent autoinflammation that reveals a regulatory role. Align alleles with cytokine profiling, adjuvant potency, or autoimmunity endpoints.',
  Tlr9:
    'Recognition of microbial DNA runs through Tlr9, the mouse ortholog of human TLR9, whose endosomal receptor binds unmethylated CpG-containing single-stranded DNA at a site on the concave ectodomain surface while a second pocket engages a free 5 prime xCx dinucleotide, cooperativity that explains why activation is sequence and end dependent and why UNC93B1 trafficking plus cathepsin-mediated cleavage are prerequisites for signaling to MyD88, IRAK4, and IRF7. Species divergence is practical rather than theoretical, since mouse TLR9 prefers GACGTT-containing motifs whereas human TLR9 favors GTCGTT, so CpG oligonucleotide adjuvants and antagonists are not interchangeable and ectodomain humanization is warranted for translational pharmacology. Nulls are viable and, importantly, show worsened lupus in several autoimmune backgrounds despite reduced anti-DNA responses, revealing a regulatory function that complicates simple loss of function logic. Because Tlr7 shares the UNC93B1 and IRF7 axis, plan compound alleles around interferon output, autoantibody specificity, or adjuvant potency.',
  Tnf:
    'Encoded as a type II transmembrane trimer and shed by ADAM17, the product of Tnf (mouse ortholog of human TNF) engages TNFRSF1A and TNFRSF1B to nucleate complex I, in which TRADD, TRAF2, cIAP1/2, LUBAC, and RIPK1 ubiquitin chains recruit TAK1 and IKK for canonical NF-kB and JNK output, while RIPK1 deubiquitination diverts signaling into caspase-8 apoptosis or, when FADD or caspase-8 activity is limiting, RIPK3 and MLKL necroptosis. Allele choice tracks the question precisely: conditional null alleles test cell-intrinsic cytokine sources, the AU-rich element deletion knockin stabilizes transcript and reproduces Crohn-like ileitis and erosive arthritis, uncleavable membrane-only knockins separate juxtacrine from systemic activity, and full humanization is mandatory because infliximab and adalimumab do not recognize mouse TNF. Targeting must avoid disrupting the tightly linked Lta and Ltb loci, whose lymphotoxin products independently sustain lymphoid architecture and can confound readouts of germinal center or Peyer patch phenotypes.',
  Tnfrsf1a:
    'Tnfrsf1a, the mouse ortholog of human TNFRSF1A, encodes TNFR1 (p55), a receptor whose four cysteine-rich extracellular domains bind soluble and membrane TNF and whose cytoplasmic death domain nucleates complex I through TRADD, RIPK1, TRAF2, and cIAP1 and cIAP2, where LUBAC-generated linear ubiquitin recruits TAB and IKK complexes for NF-kB and MAPK output. When ubiquitin editing fails or translation is blocked, RIPK1 disengages into cytosolic complex II, producing caspase-8 apoptosis or RIPK3 and MLKL necroptosis, while ADAM17 shedding generates soluble receptor that buffers ligand, and human cysteine-altering mutations cause TNF receptor associated periodic syndrome through misfolding and retention. Nulls are viable and resistant to endotoxin lethality, so germline deletion is a workhorse, conditional alleles assign requirement to intestinal epithelium, endothelium, or neurons, patient point knockins model autoinflammation, and humanization is needed because etanercept and infliximab engage human ligand. Match alleles to shock, colitis, or demyelination endpoints.',
  Tnfrsf1b:
    'Tnfrsf1b is the mouse ortholog of human TNFRSF1B and encodes TNFR2 (p75), which binds membrane-anchored TNF preferentially and, lacking a death domain, signals instead through TRAF1, TRAF2, and cIAP1 to activate canonical and non-canonical NF-kB, PI3K, and AKT, thereby delivering survival and proliferative rather than cytotoxic instructions. Because TNFR2 sequesters TRAF2 and cIAP away from TNFR1 complexes, it also modulates TNFR1-driven death, and its restricted expression on regulatory T cells, myeloid-derived suppressor cells, endothelium, oligodendrocyte progenitors, and cardiomyocytes underlies interest in agonists for tolerance and repair and antagonists for Treg depletion in tumors. Nulls are viable, so germline deletion is tractable, conditional alleles distinguish Treg-intrinsic costimulation from tissue-protective signaling, and ectodomain humanization is mandatory for agonist or blocking antibodies that fail to cross-react. Since Tnfrsf1a shares the ligand, interpret with compound receptor genetics and align alleles to Treg expansion, graft tolerance, or remyelination endpoints.',
  Tradd:
    'As the mouse ortholog of human TRADD, Tradd encodes the TNFR1-associated death domain protein, the first adaptor recruited to the ligated TNFR1 death domain, using its own C-terminal death domain for receptor binding and an N-terminal TRAF-interacting domain to dock TRAF2, thereby delivering cIAP1 and cIAP2 and enabling the ubiquitin-dependent assembly that drives NF-kB and MAPK activation. In the alternative configuration TRADD nucleates cytosolic complex II with FADD and caspase-8 to execute apoptosis, and it also participates in DR3 and TLR-driven signaling. Nulls are viable and fertile, showing reduced TNF-induced NF-kB and marked resistance to TNF-dependent apoptosis while retaining RIPK1-dependent necroptosis, so germline deletion is an efficient epistasis tool and conditional alleles resolve hepatocyte or intestinal epithelial requirement. Because RIPK1 can be recruited independently of TRADD, compound Ripk1 genetics clarifies the split, and alleles should follow hepatotoxicity, colitis, or death pathway endpoints.',
  Traf2:
    'Traf2, the mouse ortholog of human TRAF2, encodes a RING-domain E3 ubiquitin ligase with an N-terminal RING and five zinc fingers plus a C-terminal TRAF domain that trimerizes and binds receptor tails, and it functions in TNFR1 complex I both by supporting K63-linked and K11-linked ubiquitination and, more importantly, by recruiting cIAP1 and cIAP2 that ubiquitinate RIPK1 to suppress cell death while enabling JNK and NF-kB output. In parallel, a TRAF2, TRAF3, and cIAP complex constitutively degrades NIK (Map3k14), so TRAF2 loss releases non-canonical NF-kB and p52 generation. Germline nulls die perinatally with TNF-driven wasting and are partially rescued on a Tnfrsf1a-null background, so conditional deletion is standard while RING-dead or cIAP-binding knockins separate ligase from adaptor functions. Traf5 provides genuine partial redundancy for TNF-induced NF-kB, so compound alleles matter, and allele choice should track keratinocyte or hepatocyte death, plasma cell accumulation, or NIK stabilization.',
  Traf3:
    'Traf3 is the mouse ortholog of human TRAF3 and encodes a RING E3 that, together with TRAF2 and cIAP1 and cIAP2, forms the destruction complex keeping NIK (Map3k14) at vanishingly low levels, so its loss constitutively activates non-canonical NF-kB and NF-kB2 p100 processing. Beyond that, TRAF3 transduces CD40, BAFF receptor, and lymphotoxin beta receptor signals, and in innate immunity it is recruited to TRIF and MAVS complexes where it is required for TBK1-dependent IRF3 activation and type I interferon induction, giving the protein opposing positive and negative roles by receptor context. Germline nulls die within the first weeks of life with progressive wasting, a phenotype rescued by Nfkb2 or NIK haploinsufficiency, so B cell or T cell conditional deletion is the practical approach and faithfully models the B cell hyperplasia and prolonged survival seen with human TRAF3 deletions in myeloma. Match alleles to plasma cell output, interferon induction, or lymphoproliferation endpoints using validated lineage Cre drivers.',
  Traf5:
    'Traf5, the mouse ortholog of human TRAF5, encodes the closest structural relative of TRAF2, sharing a RING domain, zinc fingers, and a trimerizing TRAF domain, and it is recruited to CD27, CD30, CD40, lymphotoxin beta receptor, and TNFR2 to support NF-kB and JNK activation, in some assays acting interchangeably with TRAF2 while in others tuning IL-6 driven STAT3 signaling and helper T cell differentiation. Because its contribution is largely additive rather than unique, germline nulls are viable and fertile with only subtle defects in CD27 and CD40 driven responses, which is precisely the redundancy trap to plan for: a single Traf5 knockout will usually not report pathway dependence, and compound Traf2 Traf5 conditional genetics is required to expose shared function. RING-dead knockins separate ligase activity from scaffolding within otherwise intact receptor complexes. Fit the allele set to T cell dependent antibody responses, non-canonical NF-kB activity, or airway inflammation endpoints.',
  Traf6:
    'Encoding an essential K63-specific E3 ubiquitin ligase, Traf6 is the mouse ortholog of human TRAF6 and pairs its RING and zinc finger region with the UBC13 and UEV1A conjugating complex to build unanchored and substrate-linked K63 polyubiquitin chains that recruit TAB2 and TAB3 for TAK1 activation and NEMO for IKK activation, placing it immediately downstream of MyD88 and IRAK1 and IRAK4 for TLR and IL-1R signaling and downstream of RANK, CD40, and TGF-beta receptors. Its TRAF domain also autoubiquitinates and oligomerizes, giving threshold-like responses. Germline nulls die perinatally with severe osteopetrosis from failed osteoclast differentiation, absent lymph nodes, and neural tube defects, so conditional deletion is essential, while RING-dead or UBC13-binding knockins distinguish catalytic from scaffolding roles and are far more informative than a null for signaling questions. No paralog substitutes, so single-locus conditional genetics usually suffices. Align alleles to osteoclastogenesis, innate cytokine output, or regulatory T cell development.',
  Trem2:
    'Trem2 is the mouse ortholog of human TREM2 and encodes a single immunoglobulin domain innate receptor on microglia and other myeloid cells that lacks its own signaling motifs and instead pairs with Tyrobp, also called DAP12, to trigger Syk, PI3K and PLC gamma signaling after binding anionic lipids, apolipoprotein E and amyloid beta, licensing the disease-associated microglial state, phagocytosis and plaque compaction. ADAM10 and ADAM17 shed the ectodomain to produce soluble TREM2, an established cerebrospinal fluid biomarker whose signaling role is distinct from the membrane receptor. Allele choice here is unusually consequential because the R47H Alzheimer risk variant introduced into mouse Trem2 created a cryptic splice site that lowered transcript and confounded early reports, so humanized TREM2 knockins carrying the human sequence are required for variant modeling. Conditional nulls with microglia-restricted inducible Cre address adult requirement. Read plaque-associated microglial coverage, transcriptional signatures, and shed ectodomain levels.',
  Trp53:
    'Trp53, the mouse ortholog of human TP53, encodes the tetrameric transcription factor whose central DNA-binding core reads p53 response elements at Cdkn1a, Mdm2, Bbc3, Pmaip1, and Zmat3, coupling ATM and ATR phosphorylation of the amino-terminal transactivation domains to arrest, senescence, and mitochondrial apoptosis while MDM2 and MDM4 impose continuous ubiquitin-dependent turnover. Because most human alleles are missense rather than deleted, the design fork is decisive: conditional or germline nulls model pure suppressor loss and yield thymic lymphoma and sarcoma, whereas structural and contact hotspot knockins such as R172H and R270H (human R175H and R273H) confer dominant-negative and gain-of-function metastatic behavior that a null never reproduces. Lox-stop-lox and restorable alleles interrogate reactivation therapeutics, and humanized TP53 supports MDM2 inhibitor and mutant-reactivator pharmacology. Note that Trp63 and Trp73 share response elements and can buffer apoptotic output, so match allele class to tumor spectrum, latency, and drug response endpoints deliberately.',
  Tsc1:
    'Hamartin, the product of Tsc1 (mouse ortholog of human TSC1), stabilizes tuberin and TBC1D7 within the TSC complex, the RHEB-directed GTPase-activating module that clamps mTORC1 at the lysosomal surface; growth factor signaling through AKT, ERK, and RSK phosphorylates the complex to relieve this restraint, whereas AMPK reinforces it under energy stress. Loss-of-function alleles produce tuberous sclerosis complex with cortical tubers, subependymal giant cell astrocytoma, angiomyolipoma, and pulmonary lymphangioleiomyomatosis, all driven by constitutive S6K1 and 4E-BP1 phosphorylation. Since homozygous deletion is embryonic lethal from liver hypoplasia and neural tube defects, mechanistic work depends on floxed exons combined with Nestin, Emx1, Synapsin, or Pax8 Cre, while heterozygotes serve tumor predisposition studies. Critically, Tsc1 and Tsc2 are obligate partners rather than redundant paralogs, so hamartin loss destabilizes tuberin and no compound genetics can rescue; align allele class with rapamycin sensitivity or seizure and lesion endpoints.',
  Tsc2:
    'Tuberin, encoded by Tsc2 (mouse ortholog of human TSC2), supplies the catalytic GAP domain that hydrolyzes RHEB-GTP on lysosomal membranes, and its loss produces ligand-independent mTORC1 activity, sustained S6K1 and 4E-BP1 phosphorylation, and secondary IRS1 degradation that dampens upstream AKT. Patient alleles range from truncations to GAP-domain missense substitutions and to variants that merely destabilize the hamartin interaction, which is why a disease-specific knockin answers a different question than a conditional null: the former resolves catalytic versus structural failure and genotype-phenotype severity, the latter defines lineage requirements. Homozygous deletion is embryonic lethal by mid-gestation, and heterozygotes develop renal cystadenoma and hepatic hemangioma, echoing the Eker rat. No paralog substitutes for tuberin, since TSC1 and TBC1D7 are stoichiometric partners rather than backups, so pair floxed alleles with kidney, brain, or smooth muscle Cre drivers and read out mTORC1 flux, lesion burden, and rapalog or ATP-competitive inhibitor response.',
  Tyk2:
    'Tyk2, the mouse ortholog of human TYK2, encodes a JAK-family kinase whose FERM and SH2-like modules dock receptor boxes, whose JH2 pseudokinase domain autoinhibits catalysis, and whose kinase domain phosphorylates STAT1, STAT2, STAT3, and STAT4 downstream of IFNAR1, IL12RB1, and IL10RA, placing it at the center of type I interferon, IL-12, IL-23, and IL-10 responses. Human genetics frames the design: complete deficiency causes mycobacterial and viral susceptibility, while the common P1104A hypomorph is protective against psoriasis and inflammatory bowel disease, so a knockin of that exact substitution models allosteric partial inhibition far better than a null does. Kinase-dead alleles further separate catalytic output from scaffolding, and humanized JH2 or full-locus replacement is effectively required for deucravacitinib-class pseudokinase binders that do not engage the mouse domain. JAK1 is an obligate heterodimeric partner, not a redundant substitute, so anticipate compound genetics only when interrogating receptor-specific pairing.',
  U2af1:
    'Recognition of the 3 prime splice site depends on U2af1, the mouse ortholog of human U2AF1, the small subunit of the U2 auxiliary factor heterodimer, which uses two CCCH zinc fingers to contact the invariant AG dinucleotide and flanking nucleotides while its U2AF homology motif binds U2AF2 and licenses U2 snRNP loading at the branch point. Myeloid disease mutations are heterozygous and mutually exclusive with SF3B1 and SRSF2 lesions, with S34F and S34Y altering preference at the position three nucleotides upstream of the AG and Q157P or Q157R altering the position immediately downstream, producing distinct cassette exon and intron retention programs rather than global splicing failure; identical substitutions recur in lung adenocarcinoma. Because complete loss is not tolerated, the correct design is a conditional or doxycycline-inducible heterozygous hotspot knockin at the endogenous locus, induced with Mx1-cre or Vav1-cre to capture dysplastic hematopoiesis. Match allele to endpoint, whether isoform mapping, competitive repopulation, or spliceosome modulator sensitivity.',
  Ubqln2:
    'Ubiquilin-2, encoded by X-linked mouse Ubqln2 and orthologous to human UBQLN2, is a proteasome shuttle factor with an N-terminal ubiquitin-like domain that docks the 26S proteasome, central STI1-like chaperone regions that bind hydrophobic and transmembrane segments, a primate-specific PXX repeat region, and a C-terminal UBA domain that captures polyubiquitinated substrates. It thereby delivers misfolded and ribosome-quality-control substrates for degradation, participates in autophagosome maturation, and undergoes phase separation into stress granules. Dominant mutations concentrated in the PXX repeat, including P497H, P506T, and P525S, cause X-linked ALS and frontotemporal dementia with ubiquilin-2-positive inclusions. Because that repeat region is absent in rodents, humanized knockin alleles are essentially required for faithful variant modeling rather than murine point mutations. Conditional or constitutive nulls remain useful for proteostasis flux questions, and functional overlap with Ubqln1 and Ubqln4 means compound alleles may be needed when total shuttle capacity is the endpoint.',
  Uqcr10:
    'Uqcr10, the mouse ortholog of human UQCR10, encodes a small hydrophobic supernumerary subunit of the cytochrome bc1 complex that contributes to the peripheral scaffold of complex III, the dimeric enzyme that oxidizes ubiquinol at the Qo site, bifurcates electrons to the Rieske protein and to cytochrome b, and reduces cytochrome c while translocating protons through the Q cycle. Subunits of this class carry no redox centers; instead they stabilize the holoenzyme and influence incorporation of catalytic subunits, so depletion lowers assembled complex III and cytochrome c reductase activity without abolishing the catalytic core itself. A conditional null is therefore the informative allele for asking where complex III abundance limits respiration, while humanization supports epitope-matched antibody and proteomic reagents. No paralogous subunit substitutes. Choose Cre drivers matched to oxidative tissues such as heart, muscle or brain, and read out blue native assembly, in-gel activity and coupled respirometry.',
  Uqcr11:
    'Uqcr11, the mouse ortholog of human UQCR11, encodes one of the smallest supernumerary subunits of complex III, a single-pass hydrophobic peptide that packs against the cytochrome b core of the dimeric bc1 enzyme where ubiquinol oxidation at the Qo site drives the bifurcated Q cycle and proton translocation. Because this subunit is structural rather than redox active, reducing it destabilizes the holoenzyme and lowers steady-state ubiquinol to cytochrome c oxidoreductase activity, and such deficits typically manifest in high-demand oxidative tissue rather than uniformly. Given that, a floxed conditional null paired with cardiac, skeletal muscle or neuronal Cre drivers is the practical design for localizing where complex III abundance becomes rate limiting, while humanization supports epitope-matched detection and interaction proteomics. There is no paralog to buffer the loss, so a single-locus allele should give a clean readout. Align allele class with blue native assembly profiling, supercomplex distribution and coupled respirometry endpoints.',
  Uqcrb:
    'As the mouse ortholog of human UQCRB, Uqcrb encodes the ubiquinone-binding subunit of complex III, a supernumerary component that sits adjacent to cytochrome b and contributes to stability of the quinone-binding environment in which ubiquinol oxidation at the Qo site bifurcates electrons to the Rieske iron-sulfur protein and to the low and high potential hemes of cytochrome b. Beyond assembly, this subunit has been tied experimentally to mitochondrial ROS signaling that stabilizes HIF-1 alpha under hypoxia, with small molecules targeting it suppressing angiogenic signaling, while human loss-of-function alleles cause isolated complex III deficiency with hypoglycemia and lactic acidosis. Design should follow the question: a conditional null defines tissue-specific requirements for complex III assembly and oxygen sensing, whereas a patient-matched knockin preserves partial assembly and models the metabolic presentation. No paralog covers this subunit. Pair the allele with respirometry, ROS reporters and HIF target transcript endpoints using hepatic or neuronal Cre drivers.',
  Uqcrc1:
    'Uqcrc1 is the mouse ortholog of human UQCRC1 and encodes core protein 1 of complex III, a large matrix-facing subunit that, with core protein 2, adopts a mitochondrial processing peptidase-like fold and forms the structural platform onto which cytochrome b, cytochrome c1 and the Rieske protein assemble in the dimeric bc1 enzyme. These core subunits carry no redox center but are required for holoenzyme stability and for processing events during maturation of the Rieske subunit presequence, so their reduction destabilizes the entire complex and lowers ubiquinol to cytochrome c oxidoreductase flux. Human variants have been linked to complex III deficiency and, separately, reported in familial parkinsonism with dopaminergic vulnerability, making both a conditional null with dopaminergic Cre drivers and a patient-matched missense knockin defensible depending on whether bioenergetic failure or neurodegeneration is the question. Core protein 2 does not substitute. Select blue native assembly, respirometry and dopaminergic histology as paired endpoints.',
  Uqcrc2:
    'Encoding core protein 2 of the cytochrome bc1 complex, Uqcrc2 is the mouse ortholog of human UQCRC2 and pairs with core protein 1 in a mitochondrial processing peptidase-like heterodimer that projects into the matrix and forms the scaffold stabilizing the catalytic subunits of complex III, including cytochrome b, cytochrome c1 and the Rieske iron-sulfur protein. Loss of this scaffold prevents productive holoenzyme assembly and lowers ubiquinol to cytochrome c oxidoreductase activity, and recessive human mutations cause complex III deficiency presenting with recurrent metabolic crises, hypoglycemia, hyperammonemia and lactic acidosis. Because the phenotype is dose sensitive, a patient-matched missense knockin preserving partial assembly usually models the human disease more faithfully than deletion, while a floxed conditional null establishes where complex III capacity is limiting, with hepatic and neuronal drivers highest yield given the crisis phenotype. Core protein 1 does not compensate. Match allele class to assembly profiling, respirometry, fasting challenge and ammonia and lactate endpoints.',
  Uqcrfs1:
    'Uqcrfs1, the mouse ortholog of human UQCRFS1, encodes the Rieske iron-sulfur protein, the subunit whose mobile extrinsic head carries a [2Fe-2S] cluster and swings between the Qo site of cytochrome b and cytochrome c1, executing the bifurcation that makes the protonmotive Q cycle possible. It is imported with a cleavable presequence, matured with help from the LYRM7 chaperone, and inserted late during complex III biogenesis, so its incorporation is the step that converts a pre-complex into an active enzyme. Loss or destabilization collapses cytochrome c reduction, prolongs Qo-site semiquinone occupancy and raises superoxide output, and reduced dosage has been linked to complex III deficiency and to mitochondrial ROS-dependent signaling. Since a germline null removes an essential catalytic subunit, plan conditional floxed alleles with tissue Cre drivers, reserving knockins for cluster-ligand substitutions that preserve partial activity. No paralog exists. Match allele to respirometry, ROS output and HIF-dependent transcription endpoints.',
  Uqcrh:
    'The hinge protein of complex III is encoded by Uqcrh, the mouse ortholog of human UQCRH, a highly acidic helical subunit that binds cytochrome c1 and organizes the electrostatic interface required for efficient docking and electron transfer to the mobile carrier cytochrome c. Because it governs formation of the productive encounter complex rather than carrying a redox center itself, loss slows the terminal step of the bc1 reaction and destabilizes the cytochrome c1 subcomplex, reducing assembled complex III and coupled respiration, with human deletion alleles reported in complex III deficiency and mouse knockouts showing respiratory chain deficiency with systemic metabolic consequences. Conditional floxed alleles are therefore the tool for asking where cytochrome c docking efficiency limits oxidative phosphorylation, while humanization supports epitope-matched reagents and interface mutagenesis. No paralogous hinge subunit buffers the loss. Align allele class with cytochrome c reductase assays, blue native assembly analysis and coupled respirometry using tissue-appropriate Cre drivers.',
  Uqcrq:
    'Uqcrq, ortholog of human UQCRQ, encodes the small ubiquinone-binding protein subunit of complex III that packs against cytochrome b and helps shape the environment of the quinone sites where the bifurcated Q cycle operates, moving electrons from ubiquinol to the Rieske iron-sulfur protein and to the b hemes. A homozygous missense substitution in this subunit was identified as a cause of severe complex III deficiency with Leigh-like encephalopathy and profound psychomotor impairment, establishing that even a small structural subunit can be rate limiting for holoenzyme function. That makes a patient-matched knockin the most faithful design, since it preserves partial assembly and reproduces graded respiratory chain failure, whereas a floxed conditional null answers the separate question of where complex III abundance constrains oxidative metabolism. No paralogous subunit substitutes at this position. Match allele class to blue native assembly, cytochrome c reductase activity, brain lesion mapping and lactate endpoints using neuronal Cre drivers.',
  Vapb:
    'Endoplasmic reticulum membrane contact sites are organized in part by Vapb, the mouse ortholog of human VAPB, encoding a tail-anchored ER protein whose cytosolic major sperm protein domain binds FFAT motifs in lipid transfer and tethering partners such as OSBP, ORP family proteins, STARD3, and PTPIP51, coupling the ER to mitochondria, endosomes, and the plasma membrane for sterol, phosphatidylserine, and calcium exchange. The dominant P56S mutation misfolds that domain, forming insoluble ER inclusions that sequester wild type VAPB and VAPA, causing ALS8 and late-onset spinal muscular atrophy, while a cleaved fragment can be secreted and act on Eph receptors. Model design should separate P56S knockin at the endogenous locus, which captures the dominant aggregation mechanism, from conditional null, which tests contact site function; note that Vapb nulls are viable with only mild late deficits. Genuine redundancy with Vapa argues for compound alleles when lipid transfer is the endpoint.',
  Vcp:
    'The AAA+ ATPase p97, encoded by mouse Vcp and orthologous to human VCP, is a homohexameric segregase with an N domain plus tandem D1 and D2 ATPase rings that threads ubiquitinated substrates through its central pore, extracting them from membranes, chromatin, and multiprotein complexes. Cofactors assign function: UFD1 and NPL4 direct ER-associated degradation and ribosome quality control, p47 supports membrane fusion, and UBXD1 and others govern lysosomal and mitochondrial quality control plus autophagosome maturation. Dominant missense mutations, mostly at the N to D1 interface such as R155H and R191Q, cause multisystem proteinopathy, namely inclusion body myopathy with Paget disease and frontotemporal dementia, plus ALS14, by increasing ATPase activity and altering cofactor binding rather than ablating function. Constitutive Vcp null is embryonic lethal while heterozygous nulls are largely normal, so patient knockins at the endogenous locus are the correct allele; use conditional alleles with muscle or neuronal Cre for tissue-specific proteostasis endpoints.',
  Vegfa:
    'Vegfa, the mouse ortholog of human VEGFA, encodes the dimeric heparin-binding growth factor spliced into 120, 164, and 188 residue isoforms that differ in exon 6 and 7 matrix retention and signal through KDR (VEGFR2) autophosphorylation to PLCG1, PKC, and ERK, with FLT1 acting as ligand sink and neuropilins as coreceptors during DLL4-Notch-governed tip cell selection. Unusually, this locus is haploinsufficient: even heterozygous deletion is lethal around E11 from failed endothelial assembly, so conditional floxed alleles paired with tightly validated Cdh5, Sox2, or lineage-restricted Cre drivers are mandatory rather than optional, and isoform-restricted knockins expressing only the 120 or 188 form dissect gradient formation from bulk mitogenic dose. Humanization matters because bevacizumab and ranibizumab do not neutralize mouse VEGF-A. Vegfb and Pgf engage FLT1 alone and cannot restore KDR signaling, so map alleles onto oxygen-induced retinopathy, permeability, or tumor angiogenesis endpoints.',
  Vhl:
    'Vhl encodes the mouse ortholog of human VHL, the substrate recognition subunit of a cullin 2 RING E3 ubiquitin ligase that assembles with elongin B, elongin C, CUL2, and RBX1 and binds hydroxylated prolines in the oxygen-dependent degradation domains of HIF1A and HIF2A after prolyl hydroxylase modification, thereby coupling oxygen and 2-oxoglutarate availability to hypoxia inducible factor destruction. Biallelic inactivation, usually 3p25 deletion plus a truncating or missense hit, initiates clear cell renal carcinoma and drives von Hippel-Lindau disease with hemangioblastoma, pheochromocytoma, and pancreatic neuroendocrine tumors, with clear genotype specificity since type 2C alleles retain HIF regulation while losing other functions. Germline nulls die in midgestation from placental vasculogenesis failure, so conditional nulls with Pax8-cre or Ksp-cadherin-cre are standard, generally combined with Pbrm1, Bap1, or Setd2 deletion because Vhl loss alone rarely produces carcinoma in mouse kidney. Choose nulls for HIF2A dependence and belzutifan response, missense knockins for genotype-phenotype dissection.',
  Vps35:
    'Retromer cargo selection depends on Vps35, the mouse ortholog of human VPS35, encoding the alpha-solenoid scaffold that binds VPS26 and VPS29 to form the trimeric cargo recognition complex, which associates with sorting nexins and the WASH complex to retrieve transmembrane cargo, including the cation-independent mannose 6-phosphate receptor, GLUT1, sortilin, and DMT1, from endosomes to the trans-Golgi network and cell surface. The dominant D620N mutation causes late-onset autosomal dominant Parkinson disease PARK17 by impairing WASH complex binding, disrupting endosomal actin dynamics and cargo trafficking, and elevating LRRK2 kinase activity, placing retromer directly upstream of established parkinsonian signaling. Since constitutive Vps35 loss is embryonic lethal, useful designs are the D620N knockin at the endogenous locus for the dominant mechanism, conditional null for retromer collapse in dopaminergic neurons or microglia, and heterozygous null for dosage sensitivity. Match allele class to LRRK2 substrate phosphorylation, cargo mislocalization, or nigrostriatal integrity endpoints.',
  Wnt1:
    'Wnt1 is the mouse ortholog of human WNT1 and encodes the founding Wnt ligand, palmitoleated on a conserved serine by Porcupine and exported through Wntless before engaging Frizzled receptors with LRP5 or LRP6 to inhibit the destruction complex and stabilize beta-catenin. Its critical developmental domain is the midbrain and hindbrain organizer, where it maintains an Engrailed, Pax2, and Fgf8 regulatory loop, and the spontaneous swaying allele plus targeted nulls lose midbrain and cerebellum with perinatal death. Human recessive mutations cause osteogenesis imperfecta type XV and heterozygous variants cause early onset osteoporosis, reflecting an osteoblast-autonomous requirement that germline lethality obscures. Conditional deletion is therefore the route to skeletal work, osteogenesis imperfecta missense knockins test secretion versus receptor engagement, and humanization supports pathway agonist testing. Note that Wnt1-Cre is the canonical neural crest driver, so confirm which allele your colony actually carries before interpreting compound crosses.',
  Wnt10a:
    'Wnt10a, the mouse ortholog of human WNT10A, encodes a canonical Wnt of the ectodermal appendage program and requires Porcupine-mediated lipidation and Wntless-dependent secretion before signaling through Frizzled with LRP6 to stabilize beta-catenin in dental, hair follicle, nail, and sweat gland epithelium. Human biallelic mutations cause odonto-onycho-dermal dysplasia and Schopf-Schulz-Passarge syndrome, while heterozygous variants produce isolated tooth agenesis, and mouse nulls are viable with cusp and root patterning defects and reduced eccrine gland number, an accessible phenotype set for allele comparison. Conditional deletion resolves epithelial versus mesenchymal requirement across successive appendage stages, patient missense knockins distinguish secretion-defective from binding-defective protein, and humanization supports Porcupine inhibitor and agonist pharmacology. Because Wnt10b and Wnt6 are close paralogs and Wnt6 sits immediately adjacent within a shared regulatory landscape, design floxed alleles that spare neighboring enhancers and plan compound genetics for appendage endpoints.',
  Wnt10b:
    'Wnt10b is the mouse ortholog of human WNT10B and encodes a canonical Wnt whose best-defined function is restraining adipogenic commitment, since sustained beta-catenin signaling downstream of Frizzled and LRP5 or LRP6 suppresses PPAR gamma and CEBP alpha induction and holds preadipocytes undifferentiated, while in bone the same ligand supports osteoblastogenesis and trabecular mass. Nulls are viable with reduced trabecular bone and expanded marrow adiposity, and human variants cause split hand foot malformation and tooth agenesis, indicating additional limb and dental appendage roles. Given viability, both conditional deletion and stromal or osteoblast-directed overexpression knockins are practical, the former for cell of origin questions in marrow niches and the latter for testing whether ligand supply alone reallocates lineage output. Humanized alleles support pathway agonist pharmacology. Wnt10a and the adjacent Wnt6 overlap functionally and share regulatory sequence, so preserve neighboring elements when floxing and anticipate compound requirements.',
  Wnt11:
    'Predominantly noncanonical in output, Wnt11 is the mouse ortholog of human WNT11 and signals through Frizzled 7 with the alternative receptors ROR2 and RYK to activate RHOA, ROCK, DAAM1, and JNK, driving planar polarity and calcium-dependent responses rather than beta-catenin stabilization, and it can antagonize canonical output in the same tissue. In the kidney it sits in a reciprocal loop with GDNF and RET in the ureteric bud tip, so nulls show reduced branching, nephron deficit, and renal hypoplasia with perinatal compromise, alongside reported outflow tract and myocardial defects. Ureteric epithelium conditional deletion with Hoxb7-Cre separates tip-autonomous requirement from metanephric mesenchyme signaling, knockins that disrupt ROR2 engagement test receptor selectivity, and humanization supports biochemical assays. Wnt5a supplies overlapping polarity input in most of these tissues, so compound Wnt5a alleles are worth planning before ascribing convergent extension defects to Wnt11 alone.',
  Wnt16:
    'Cortical bone is the compartment where Wnt16, the mouse ortholog of human WNT16, exerts its effect, since this osteoblast-derived Wnt signals through Frizzled with LRP5 or LRP6 and also engages noncanonical routes to suppress osteoclastogenesis both directly, by blunting RANKL-driven differentiation, and indirectly through osteoprotegerin induction. Human variation at the locus is among the strongest determinants of cortical bone mineral density and forearm fracture risk, and nulls are viable with thin, porous cortices and spontaneous fractures despite largely preserved trabecular bone, a compartment-selective phenotype that makes the gene valuable for skeletal fragility work. Osteoblast or osteocyte conditional deletion with Col1a1-Cre or Dmp1-Cre establishes cell of origin, gain-of-function knockins test whether restoring ligand suffices to thicken cortex, and humanization enables pathway agonist pharmacology. Redundancy is limited in the periosteal compartment, which is precisely why single-locus loss gives a clean readout, so cortical geometry and fracture endpoints remain directly interpretable.',
  Wnt2:
    'Wnt2 is the mouse ortholog of human WNT2 and encodes a canonical ligand of splanchnic mesenchyme that stabilizes beta-catenin through Frizzled with LRP6 in lung mesenchyme, where it specifies Nkx2-1 positive respiratory progenitors from foregut endoderm, and in placental and cardiac progenitor populations. The original null was recognized through placental vascular insufficiency with partial perinatal loss, while lung specification appears grossly intact on its own, which is the key design consideration. Mesenchyme-restricted conditional deletion using Dermo1-Cre or Tbx4 enhancer drivers addresses stage-specific requirements once placental confounding is removed, and humanized alleles support agonist and Porcupine inhibitor pharmacology. Redundancy here is not hypothetical, since Wnt2b is coexpressed in the same ventral foregut mesenchyme and only compound Wnt2 and Wnt2b nulls abolish lung specification and produce lung agenesis. Plan the double conditional and a validated mesenchymal driver from the start rather than after a disappointing single-locus result.',
  Wnt2b:
    'Wnt2b is the mouse ortholog of human WNT2B and encodes a canonical Wnt that stabilizes beta-catenin through Frizzled with LRP5 or LRP6 in ventral foregut mesenchyme, retinal ciliary margin progenitors, and the mesenchymal compartment supporting intestinal crypt stem cells. Biallelic human loss of function causes early onset chronic diarrhea with intestinal epithelial failure, establishing a non-redundant requirement in the human gut niche that a mouse single null does not obviously reproduce. Conditional deletion in intestinal subepithelial mesenchyme is therefore the informative design for niche questions, patient nonsense or missense knockins model the human enteropathy directly, and humanization supports agonist and R-spondin combination pharmacology. Wnt2 is coexpressed and functionally overlapping, most clearly in lung specification where only compound loss produces agenesis, so compound conditional alleles with a validated mesenchymal Cre driver belong in the initial plan whenever respiratory or intestinal niche output is the endpoint.',
  Wnt3:
    'Wnt3 is the mouse ortholog of human WNT3 and encodes the canonical ligand that initiates the mouse body axis, acting through Frizzled with LRP5 or LRP6 to stabilize beta-catenin and induce primitive streak formation in the posterior epiblast. Nulls arrest at gastrulation without a streak or mesoderm, an absolute early embryonic lethality that forces conditional and inducible designs for any later question, and human mutations cause tetra-amelia with craniofacial and urogenital malformation, indicating persistent limb induction requirements. Conditional deletion with Sox2-Cre, T-Cre, or tamoxifen-inducible drivers separates epiblast axis initiation from later limb and hair follicle roles, tetra-amelia knockins test whether human variants are secretion defective, and humanization supports pathway agonist testing. Wnt3a cannot substitute at streak initiation despite sharing receptors and acting later in axis elongation, so treat the two as sequential rather than interchangeable and time Cre activity precisely against the streak stage.',
  Wnt3a:
    'Widely supplied as the recombinant canonical ligand of choice, Wnt3a is the mouse ortholog of human WNT3A and stabilizes beta-catenin through Frizzled with LRP6 to maintain the primitive streak after initiation, sustain neuromesodermal progenitors, and drive paraxial mesoderm and somitogenesis, with an additional requirement in hippocampal development alongside LEF1. Nulls truncate the caudal axis with absent tailbud somites and die in late gestation, whereas the spontaneous vestigial tail allele is hypomorphic and survives, providing a natural allelic series that argues for dose-graded engineering rather than a single null. Conditional deletion isolates progenitor pool maintenance from later neural roles, hypomorphic knockins titrate signaling output against segment number, and humanization supports agonist and surrogate ligand testing. Wnt3 overlaps in axis programs and Wnt5a contributes to elongation, so pair conditional alleles with a validated posterior driver and a beta-catenin reporter to quantify actual pathway dose.',
  Wnt4:
    'Wnt4 is the mouse ortholog of human WNT4 and encodes a ligand operating in both canonical and noncanonical modes, whose defining role is enforcing the ovarian program, since with RSPO1 it sustains beta-catenin in the XX gonad to suppress SOX9 and FGF9, while it also drives Mullerian duct development, adrenal cortex organization, and the mesenchymal to epithelial transition of pretubular aggregates in the nephron lineage. Nulls die perinatally with renal agenesis and partial XX masculinization, human loss of function causes SERKAL syndrome with female to male sex reversal plus renal, adrenal, and pulmonary dysgenesis, and heterozygous variants appear in Mullerian aplasia. Conditional deletion with Sf1-Cre for gonad and adrenal or Six2-Cre and Pax2-Cre for nephron progenitors separates these requirements, and SERKAL knockins test residual activity. Wnt9b overlaps in duct elongation, so compound alleles matter when urogenital tract endpoints, rather than gonadal fate, are primary.',
  Wnt5a:
    'Wnt5a, the mouse ortholog of human WNT5A, encodes the prototypical noncanonical Wnt and signals through Frizzled with the alternative receptors ROR2 and RYK to engage VANGL2, Dishevelled, RHOA, ROCK, and JNK, directing planar polarity and convergent extension while frequently antagonizing beta-catenin-dependent transcription in the same tissue. Nulls die perinatally with severe anterior to posterior truncation, shortened limbs and digits, and craniofacial and genital defects, phenocopying the Ror2 mutant and matching human disease, since heterozygous WNT5A mutations cause dominant Robinow syndrome while recessive ROR2 mutations cause the recessive form. Conditional deletion is therefore required for postnatal work in lung, mammary gland, and tumor stroma, patient cysteine substitution knockins test ligand and receptor coupling rather than absence, and humanization supports pathway pharmacology. Wnt11 and Wnt5b provide overlapping polarity input, so compound conditional alleles and a lineage-validated Cre driver protect against under-reading a real requirement.',
  Wnt5b:
    'Wnt5b is the mouse ortholog of human WNT5B and encodes the close paralog of WNT5A, sharing its lipidation and secretion requirements and its preference for noncanonical output through Frizzled with ROR2, activating RHOA, JNK, and calcium-dependent responses in growth plate chondrocytes, adipocyte progenitors, pancreatic islets, and digit mesenchyme. Nulls are grossly normal, which is the central design fact, because the informative experiment is almost never single-locus deletion but compound Wnt5a and Wnt5b genetics, where dosage reduction aggravates chondrocyte column disorganization and limb shortening beyond either single mutant. Accordingly, build a conditional Wnt5b allele intended for use on a Wnt5a-sensitized background, add overexpression knockins to test whether Wnt5b can substitute for Wnt5a when supplied in the correct domain, and humanize the ligand for receptor selectivity pharmacology. Pair these with a chondrocyte or limb mesenchyme driver, since interpretable skeletal endpoints depend on restricting deletion to the relevant lineage.',
  Wnt6:
    'Wnt6 is the mouse ortholog of human WNT6 and encodes a canonical Wnt of epithelial appendage and somite programs, stabilizing beta-catenin through Frizzled with LRP5 or LRP6 in surface ectoderm, where it contributes to dermomyotome specification and myogenic commitment, and in tooth, hair follicle, and placental epithelium. The dominant practical consideration is genomic architecture, since Wnt6 lies immediately adjacent to Wnt10a and the two share regulatory elements, so any targeting strategy must leave neighboring enhancers and the Wnt10a transcription unit intact, otherwise apparent Wnt6 phenotypes reflect collateral regulatory damage. Nulls are viable, so conditional deletion is used mainly to isolate stage-specific ectodermal requirements, reporter or Cre knockins provide lineage access, and humanization supports Porcupine inhibitor pharmacology. Wnt10a and Wnt10b overlap functionally in the same appendage tissues, so compound alleles plus a validated ectodermal driver are appropriate when placode or myogenic endpoints are primary.',
  Wnt7a:
    'Wnt7a is the mouse ortholog of human WNT7A and encodes a canonical Wnt with an unusually well defined patterning role, since dorsal limb ectoderm expression maintains Lmx1b to specify dorsal mesenchyme, so nulls ventralize the dorsal paw and lose dorsal-specific structures, while the same ligand acts through Frizzled 7 and VANGL2 to drive symmetric satellite cell expansion by a planar, mTOR-dependent route, and it directs uterine Hoxa10 and Hoxa11 expression in the female reproductive tract. Human mutations cause Fuhrmann syndrome and the more severe Al-Awadi Raas-Rothschild limb and pelvis hypoplasia, an allelic severity series that motivates precise missense knockins rather than deletion alone. Conditional alleles separate embryonic limb patterning from adult muscle regeneration and endometrial function, and humanization supports agonist and surrogate ligand pharmacology. Wnt7b overlaps substantially in central nervous system angiogenesis and other epithelial contexts, so plan compound conditional genetics for vascular endpoints.',
  Wnt7b:
    'As the close paralog of Wnt7a, Wnt7b is the mouse ortholog of human WNT7B and stabilizes beta-catenin through Frizzled 4 with LRP5 or LRP6 and the endothelial coreceptor module GPR124 and RECK, which is how it and Wnt7a drive central nervous system angiogenesis and blood brain barrier acquisition, while separate requirements exist in lung branching and vascular smooth muscle differentiation, osteoblast function, and placental chorioallantoic attachment. Nulls die in midgestation from placental failure, so conditional deletion is the only practical route to postnatal vascular, skeletal, and pulmonary endpoints, and endothelium-restricted alleles are particularly informative because barrier phenotypes are cell autonomous. Knockins that disrupt GPR124-dependent signaling test coreceptor specificity, and humanization supports surrogate agonist pharmacology aimed at barrier repair. Wnt7a is genuinely redundant here, since only compound Wnt7a and Wnt7b loss abolishes central nervous system angiogenesis, so build the double conditional with a validated endothelial driver.',
  Wnt8a:
    'Transient expression in the primitive streak and posterior epiblast defines Wnt8a, the mouse ortholog of human WNT8A, a canonical Wnt that stabilizes beta-catenin through Frizzled with LRP5 or LRP6 to contribute posteriorizing input to neural plate and mesoderm patterning, a function far more prominent in fish and frog embryos than in mouse. Nulls are viable without overt malformation, which is the essential planning fact, because single-locus deletion is unlikely to yield a phenotype and the productive designs are conditional alleles built for use on sensitized backgrounds together with reporter knockins that map the actual expression window against streak stages. Overexpression or gain-of-function knockins directly test posteriorizing capacity where loss of function is silent. Wnt3a supplies overlapping posterior canonical signaling and Wnt8b overlaps in neural domains, so compound alleles combined with a beta-catenin activity reporter are needed to quantify pathway dose rather than infer it.',
  Wnt8b:
    'Within the anterior neural tube, Wnt8b, the mouse ortholog of human WNT8B, acts as a canonical Wnt, signaling through Frizzled with LRP5 or LRP6 to stabilize beta-catenin in the presumptive diencephalon, the zona limitans intrathalamica region, and the hippocampal primordium, contributing to regional patterning of forebrain progenitor domains. Nulls are grossly normal, so the design logic mirrors other redundant Wnts: conditional alleles are worth generating primarily for use on sensitized backgrounds, reporter or Cre knockins provide access to the specific forebrain progenitor domains that express it, and overexpression knockins test whether ectopic ligand can respecify regional identity where loss of function is silent. Wnt3a is the principal overlapping ligand in hippocampal development and Wnt8a overlaps in posterior neural domains, so compound conditional genetics with an inducible forebrain driver, read against a beta-catenin activity reporter, is the realistic route to an interpretable patterning phenotype.',
  Wnt9a:
    'Wnt9a is the mouse ortholog of human WNT9A and encodes a canonical Wnt that stabilizes beta-catenin through Frizzled with LRP5 or LRP6 and is the principal inducer of synovial joint identity, since ectopic expression converts cartilage toward joint interzone fate while loss permits ectopic chondrogenesis within joints and joint fusion. Beyond the skeleton it acts from stromal niches to support hematopoietic stem cell function and from ureteric epithelium to help initiate the mesenchymal to epithelial transition of nephron progenitors, and nulls die perinatally with renal hypoplasia. Joint-restricted conditional deletion using Gdf5-Cre isolates articular maintenance from renal lethality, gain-of-function knockins test the joint induction model directly, and humanization supports agonist pharmacology, while human WNT9A variants in autopod malformation motivate patient missense alleles. Wnt9b overlaps in kidney and duct programs, so compound conditional alleles are advisable whenever urogenital rather than articular endpoints are primary.',
  Wnt9b:
    'Of the two Wnt9 paralogs, Wnt9b, the mouse ortholog of human WNT9B, dominates the urogenital lineage, stabilizing beta-catenin through Frizzled with LRP5 or LRP6, acting from Wolffian and ureteric epithelium as the inductive signal that triggers ureteric bud outgrowth, nephron progenitor induction, and nephric and Mullerian duct elongation, with additional roles in hepatocyte zonation. Nulls lack kidneys and gonaducts and die at birth, so conditional deletion with Hoxb7-Cre or an inducible ureteric driver is the only practical route to later nephrogenesis and duct questions, and dosage-sensitive hypomorphs are valuable because the ligand behaves as a quantitative inducer. The locus also carries the classic cleft lip modifier on the A/WySn background, so regulatory variant knockins address craniofacial risk separately from coding loss, while humanization supports agonist pharmacology. Wnt9a overlaps in kidney induction, making compound conditional alleles worthwhile before concluding a requirement is Wnt9b specific.',
  Xiap:
    'Xiap is the mouse ortholog of human XIAP and encodes an inhibitor of apoptosis protein with three BIR domains, a ubiquitin-associated region, and a C-terminal RING E3 ligase, in which BIR2 plus its preceding linker occludes the active sites of caspase-3 and caspase-7 while BIR3 binds and holds caspase-9 monomers inactive, and the RING ubiquitinates caspases and other substrates for degradation. SMAC (Diablo) released from mitochondria displaces these interactions through its IAP-binding motif, the principle exploited by SMAC mimetics. Independently of apoptosis, XIAP ubiquitinates RIPK2 to sustain NOD1 and NOD2 driven NF-kB signaling, which is why human loss of function causes X-linked lymphoproliferative syndrome type 2 with hemophagocytic lymphohistiocytosis and Crohn-like disease. Nulls are viable with compensatory Birc2 and Birc3 upregulation, so compound alleles or RING-dead and BIR-selective knockins give sharper answers, and allele choice should follow NOD2 responsiveness, inflammasome activation, or SMAC mimetic sensitivity.',
  Yes1:
    'Membrane-anchored through amino-terminal myristoylation, the Yes1 product (mouse ortholog of human YES1) is a SRC-family tyrosine kinase whose SH3 and SH2 modules enforce an autoinhibited conformation until CSK-placed phosphate on the carboxy-terminal regulatory tyrosine is removed, after which it phosphorylates YAP1 at Y357, occludin and ZO-1 at junctions, and receptor-proximal adaptors to license junctional remodeling and transcriptional coactivation. Focal YES1 amplification in lung, esophageal, and breast carcinoma creates genuine kinase dependency and dasatinib sensitivity, which argues for amplification-mimicking or activating knockins when the question is oncogene addiction, and for conditional or analog-sensitive gatekeeper alleles when the question is acute catalytic requirement in normal epithelium. Compensation here is real and well documented: Src and Fyn overlap extensively with Yes1, single nulls are viable and nearly normal, and only compound Src, Fyn, and Yes1 genetics expose junctional and osteoclast phenotypes, so plan multiplexed floxed alleles alongside your chosen Cre driver.',
  Zbtb16:
    'Zbtb16 is the mouse ortholog of human ZBTB16 (PLZF), a transcriptional repressor combining an N-terminal BTB or POZ dimerization domain with nine C-terminal C2H2 zinc fingers, which recruits NCOR1, SMRT, HDAC, and PRC1 components to target promoters and enforces spermatogonial stem cell self-renewal, innate effector programming of invariant natural killer T cells, and limb and axial skeletal patterning. In oncology it appears as the 5 prime partner of the t(11;17) ZBTB16-RARA fusion in a rare, all-trans retinoic acid resistant variant of acute promyelocytic leukemia, where the BTB domain drives constitutive oligomerization and corepressor recruitment that pharmacologic retinoid concentrations cannot dislodge. Germline nulls are viable, phenocopying the luxoid mutant with limb and vertebral defects and progressive loss of spermatogonial stem cells, so conditional nulls suit adult germline and immune endpoints, whereas inducible fusion knockins address differentiation therapy resistance. No close paralog substitutes for this BTB and zinc finger combination, so single-locus deletion is interpretable with a lineage-matched Cre.',
  Zrsr2:
    'Minor spliceosome function requires Zrsr2, the mouse ortholog of human ZRSR2, a zinc finger and RS domain protein that serves as the U2AF1-like 3 prime splice site recognition factor for the U11 and U12 dependent spliceosome, enabling excision of the roughly seven hundred U12-type introns found in genes such as Mapk1 and Parp1. Loss-of-function mutations and deletions, rather than hotspot missense changes, characterize its role in myelodysplastic syndrome and chronic myelomonocytic leukemia, where the consequence is selective U12-type intron retention and, unusually among spliceosome genes, a strong male predominance because the locus is X-linked and escapes X inactivation. Allele design therefore favors conditional nulls rather than knockins, with Vav1-cre or Mx1-cre induction and explicit attention to sex and dosage. Notably, real redundancy exists in mouse through the intronless autosomal retrogene Zrsr1, whose expression can mask intron retention phenotypes, so compound Zrsr1 and Zrsr2 conditional genetics is advisable before concluding minor spliceosome output is intact.',
};

export const CURATED_INTRO_GENES = new Set(Object.keys(curatedGeneIntros));

export function getCuratedIntro(gene: string): string | undefined {
  return curatedGeneIntros[gene];
}
